R:Segment({id="alliance/02-westfall",title="Westfall",faction="Alliance",min=11,max=17,zone=1436,zoneName="Westfall",next="alliance/03-darkshore"}, function() return {
  {t="Goldshire", lv=11, n="On the road from Stormwind to Westfall, Goldshire is the first stop: Remy \"Two Times\" stands outside the inn, Marshal Dughan beside him. Remy's A Fishy Peril goes straight to Dughan, who then gives Further Concerns; his Report to Gryan Stoutmantle goes with you to Westfall.", f={r={"Dwarf","Gnome"}}, g={{"a",40,m=1429,x=42.1,y=67.3,ml=7},{"t",40,m=1429,x=42.1,y=65.9},{"a",35,m=1429,x=42.1,y=65.9,ml=7},{"a",109,n2="Marshal Dughan: for Gryan Stoutmantle at Sentinel Hill",m=1429,x=42.1,y=65.9,ml=9}}},
  {t="The Tower of Azora", lv=11, n="East along the road past Crystal Lake: Hamish Bergwort and Blixie Fitzwink stand at the foot of the tower.", f={r={"Dwarf","Gnome"}}, g={{"a",91725,m=1429,x=63.2,y=72.6,ml=7},{"a",91723,m=1429,x=65.1,y=69.8,ml=7}}},
  {t="The bridge", lv=11, n="Guard Thomas guards the bridge on the road east; Ormin Pelford stands just across it. His tools and Thomas's Prowlers and bears are south of the bridge, on the way back.", f={r={"Dwarf","Gnome"}}, g={{"t",35,m=1429,x=74,y=72.2},{"a",37,m=1429,x=74,y=72.2,ml=7},{"a",52,m=1429,x=74,y=72.2,ml=7},{"a",91733,m=1429,x=76.5,y=71.9,ml=7}}},
  {t="The Eastvale Logging Camp", lv=11, n="The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it.", f={r={"Dwarf","Gnome"}}, g={{"a",83,n2="Sara Timberlain, inside",m=1429,x=79.5,y=68.8,ml=4},{"a",5545,m=1429,x=81.4,y=66.1,ml=5},{"a",91732,m=1429,x=82.5,y=63.8,ml=6},{"o",5545,i=1,txt="Bundle of Wood x8",m=1429,x=81.6,y=62.6},{"t",5545,m=1429,x=81.4,y=66.1}}},
  {t="A half-eaten body", lv=11, n="It lies by the river north-west of the logging camp.", f={r={"Dwarf","Gnome"}}, g={{"t",37,m=1429,x=72.7,y=60.3},{"a",45,m=1429,x=72.7,y=60.3,ml=7}}},
  {t="Stone Cairn Lake", lv=11, n="Defias Rogue Wizards camp on the shores of Stone Cairn Lake; they drop the Red Linen Bandanas too. Rolf's corpse lies in the murloc village on the north-east shore.", f={r={"Dwarf","Gnome"}}, g={{"o",83,i=1,txt="Red Linen Bandana x6",n2="Red Linen Bandanas",m=1429,x=72.5,y=56.4},{"t",45,m=1429,x=79.8,y=55.5},{"a",71,m=1429,x=79.8,y=55.5,ml=7}}},
  {t="The gnoll camps", lv=11, n="Riverpaw gnolls camp in the hills west of Stone Cairn Lake; the Stolen Enchanting Supplies lie in their camps.", f={r={"Dwarf","Gnome"}}, g={{"o",91725,i=1,txt="Stolen Enchanting Supplies x5",m=1429,x=68.7,y=51.1}}},
  {t="The Jasperlode Mine's entrance", lv=11, f={r={"Dwarf","Gnome"}}, g={{"g",0,txt="Jasperlode Mine",m=1429,x=61.6,y=54.1}}},
  {t="Jasperlode Mine: kill these as you meet them", lv=11, n="The mine is south-west of the gnoll camps. Mining Tools lie near the entrance; Kobold Geomancers hold the tunnels.\nCareful: Mother Fang (7-10), the Mine Spiders (7-9) and Geosculptor Yip (7) are elites deep in the mine: pull the kobolds one at a time near the entrance and back out if an elite comes; they're easier with a friend.", f={r={"Dwarf","Gnome"}}, g={{"o",91732,i=1,txt="Mining Tools x4",m=1429,x=61.6,y=53.3},{"o",91723,i=1,txt="Kill Kobold Geomancer x8",n2="Kobold Geomancer walks around Jasperlode Mine: look inside the circle on the map",m=1429,x=61.3,y=51.7}}},
  {t="The Tower of Azora", lv=11, n="Follow the hills south to the tower.", f={r={"Dwarf","Gnome"}}, g={{"t",91723,m=1429,x=65.1,y=69.8},{"t",91725,m=1429,x=63.2,y=72.6}}},
  {t="Downstream", lv=11, n="East along the road, then into the river south of the bridge: the Waterlogged Saw, Axe and Toolbox lie in it. Prowlers and Young Forest Bears roam its banks.", f={r={"Dwarf","Gnome"}}, g={{"o",91733,i=2,txt="Waterlogged Saw",m=1429,x=74.2,y=76.3},{"o",52,i=1,txt="Kill Prowler x8",m=1429,x=75.5,y=76.5},{"o",52,i=2,txt="Kill Young Forest Bear x5",m=1429,x=73.4,y=80.4},{"o",91733,i=3,txt="Waterlogged Toolbox",m=1429,x=77.3,y=86.7},{"o",91733,i=1,txt="Waterlogged Axe",m=1429,x=76.7,y=82.4}}},
  {t="The bridge", lv=11, f={r={"Dwarf","Gnome"}}, g={{"t",91733,m=1429,x=76.5,y=71.9},{"t",71,m=1429,x=74,y=72.2},{"a",39,m=1429,x=74,y=72.2,ml=7},{"t",52,m=1429,x=74,y=72.2}}},
  {t="The Eastvale Logging Camp", lv=11, f={r={"Dwarf","Gnome"}}, g={{"t",83,n2="Sara Timberlain, inside",m=1429,x=79.5,y=68.8},{"t",91732,m=1429,x=82.5,y=63.8}}},
  {t="Goldshire", lv=11, n="Follow the road west to Goldshire, on the way to Westfall: Marshal Dughan stands outside the inn.", f={r={"Dwarf","Gnome"}}, g={{"t",39,m=1429,x=42.1,y=65.9}}},
  {t="The Jansen Stead", lv=11, n="Follow the road from Elwynn into Westfall: the Furlbrows sit by their burned farm, the first one on the road. Pick up oats from any Sack of Oats you pass on the loop: the rest are gathered in the fields here on the way back.", g={{"a",109,n2="Farmer Furlbrow: Humans may have it already from Deputy Rainer in Elwynn",m=1436,x=60,y=19.4,f={r={"Human","NightElf","Skyborne"}},ml=9}}},
  {t="Westfall", lv=11, f={r={"Dwarf","Gnome","Skyborne"}}, g={{"g",0,txt="The Jansen Stead",m=1436,x=59.9,y=19.4}}},
  {t="The Jansen Stead", lv=11, g={{"a",36,m=1436,x=59.9,y=19.4,ml=9},{"a",184,n2="Only if you looted a Westfall Deed in Elwynn: right-click it",opt=true,ml=8},{"t",184,m=1436,x=60,y=19.4,opt=true},{"a",151,m=1436,x=59.9,y=19.4,ml=9},{"a",64,m=1436,x=60,y=19.4,ml=9}}},
  {t="Saldean's Farm", lv=11, n="South along the road, past the fork. Farmer Saldean stands outside, Salma in the house, Ozwin Ironsprocket in the barn to the west. Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way.", g={{"t",36,n2="Salma Saldean, inside",m=1436,x=56.4,y=30.5},{"a",22,m=1436,x=56.4,y=30.5,ml=9},{"a",38,m=1436,x=56.4,y=30.5,ml=9},{"a",9,m=1436,x=56,y=31.2,ml=8},{"a",92909,m=1436,x=51.5,y=32.3,ml=8}}},
  {t="Goretusk Snouts", lv=11, n="Young Goretusks root in the fields along the road south from Saldean's to Sentinel Hill: take their snouts on the way.", g={{"o",38,i=3,txt="Goretusk Snout x3",m=1436,x=50.4,y=29.4}}},
  {t="Sentinel Hill's tower and Thor", lv=11, n="Gryan Stoutmantle and Captain Danuvin stand at the top of the stone tower, Quartermaster Lewis inside it, Thor the gryphon master on the south side of the hill with Scout Galiaan beside him. Thor gives you Lewis' note for Osric Strang with a free flight to Stormwind: take it now. In Stormwind, Morgan Pestle's shop is in the Trade District by the gryphons, Osric's shop, Limited Immunity, in Old Town; Baros Alexston stands in Cathedral Square on the way back to Dungar Longdrink, the gryphon master.", f={r={"Human"}}, g={{"t",109,m=1436,x=56.3,y=47.5},{"a",12,m=1436,x=56.3,y=47.5,ml=9},{"a",102,m=1436,x=56.4,y=47.6,ml=8},{"a",6181,n2="Quartermaster Lewis, inside",m=1436,x=57,y=47.2,ml=10},{"fp",4,txt="Get the Sentinel Hill flight path (Thor)",m=1436,x=56.5,y=52.6},{"a",153,n2="Scout Galiaan, beside Thor",m=1436,x=54,y=53,ml=10},{"t",6181,m=1436,x=56.5,y=52.6},{"a",6281,n2="Thor: the free flight he offers goes to Stormwind",m=1436,x=56.5,y=52.6,ml=10},{"z",0,txt="Fly to Stormwind",at="Stormwind"}}},
  {t="Osric Strang", lv=11, f={r={"Human"}}, g={{"t",61,n2="Morgan Pestle, Trade District, by the gryphons",m=1453,x=63.2,y=74.4},{"t",6281,n2="Osric Strang, Limited Immunity in Old Town",m=1453,x=77.2,y=61},{"a",6261,m=1453,x=77.2,y=61,ml=10}}},
  {t="Defensive Stance", lv=11, n="Ilsa Corbin trains warriors in Old Town, near Osric's shop; the tram from Ironforge arrives in the Dwarven District, north of it. Harry Burlguard and Bartleby stand together by the Pig and Whistle Tavern there. Bartleby fights you for his mug. If Ilsa doesn't offer A Warrior's Training, go straight to Harry: he gives Bartleby the Drunk without it.", f={c={"WARRIOR"},r={"Human"}}, g={{"a",1638,m=1453,x=80.4,y=59.8,f={r={"Human"}},ml=10},{"t",1638,m=1453,x=77.1,y=53.3,f={r={"Human"}}},{"a",1639,m=1453,x=77.1,y=53.3,f={r={"Human"}},ml=10},{"t",1639,m=1453,x=76.8,y=52.5,f={r={"Human"}}},{"a",1640,m=1453,x=76.8,y=52.5,f={r={"Human"}},ml=10},{"o",1640,i=1,txt="Kill Bartleby",n2="Beat Bartleby",m=1453,x=76.8,y=52.5,f={r={"Human"}}},{"t",1640,m=1453,x=76.8,y=52.5,f={r={"Human"}}},{"a",1665,m=1453,x=76.8,y=52.5,f={r={"Human"}},ml=10},{"t",1665,n2="Harry Burlguard: Defensive Stance",m=1453,x=77.1,y=53.3,f={r={"Human"}}}}},
  {t="Baros Alexston", lv=11, f={r={"Human"}}, g={{"a",399,n2="Baros Alexston, Cathedral Square: his compass is in his old house in Westfall",m=1453,x=57.7,y=47.9,ml=10}}},
  {t="Stormwind City", lv=11, w={{k="onquest",q={94774}}}, f={c={"PRIEST"},r={"Human"}}, g={{"g",0,txt="High Priestess Laurena",m=1453,x=49.5,y=44.6}}},
  {t="High Priestess Laurena", lv=11, n="High Priestess Laurena is in the Cathedral of Light, across Cathedral Square from Baros.", f={c={"PRIEST"},r={"Human"}}, g={{"t",94774,n2="Divine Grace",m=1453,x=49.5,y=44.6,f={r={"Human"}}}}},
  {t="Dungar Longdrink", lv=11, f={r={"Human"}}, g={{"t",6261,n2="Dungar Longdrink, the gryphon master",m=1453,x=71.3,y=72.2},{"a",6285,m=1453,x=71.3,y=72.2,ml=10},{"fp",2,txt="Get the Stormwind flight path (Dungar Longdrink)",m=1453,x=71.3,y=72.2},{"z",0,txt="Fly to Sentinel Hill",at="Sentinel Hill"}}},
  {t="Sentinel Hill", lv=11, n="Gryan Stoutmantle and Captain Danuvin stand at the top of the stone tower. Quartermaster Lewis is in the tower, Scout Galiaan on the south side of the hill, next to the inn and Thor the gryphon master.", g={{"t",109,m=1436,x=56.3,y=47.5,f={r={"Dwarf","Gnome","NightElf","Skyborne"}}},{"a",12,m=1436,x=56.3,y=47.5,ml=9},{"a",102,m=1436,x=56.4,y=47.6,ml=8},{"t",6285,n2="Quartermaster Lewis, inside: back from Stormwind",m=1436,x=57,y=47.2,f={r={"Human"}}},{"fp",4,txt="Get the Sentinel Hill flight path (Thor)",m=1436,x=56.5,y=52.6},{"a",153,m=1436,x=54,y=53,ml=10},{"a",92742,n2="Alba Fairmoon, beside Scout Galiaan",m=1436,x=52.5,y=53,ml=9},{"a",92744,m=1436,x=52.5,y=53,ml=9}}},
  {t="Sentinel Hill", lv=11, w={{k="onquest",q={98021}}}, g={{"t",98021,m=1436,x=56.3,y=47.5,f={r={"Skyborne"}}}}},
  {t="Goretusk Livers as you go", lv=11, n="Goretusks and Young Goretusks root along every leg of this loop: kill the ones you pass for the pie's livers.", al=true, g={{"o",22,i=1,txt="Goretusk Liver x8",m=1436,x=59,y=49.1}}},
  {t="Stringy Vulture Meat as you go", lv=11, n="Fleshrippers circle the fields along this loop: kill the ones you pass for the stew's meat.", al=true, g={{"o",38,i=1,txt="Stringy Vulture Meat x3",n2="Stringy Vulture Meat: Fleshrippers",m=1436,x=59.4,y=52.3}}},
  {t="Red Leather Bandanas as you go", lv=11, n="Every Defias on this loop can drop a Red Leather Bandana: the Trappers and Smugglers, and the guards at Furlbrow's Wardrobe.", al=true, g={{"o",153,i=1,txt="Red Leather Bandana x15",n2="Red Leather Bandanas",m=1436,x=60.6,y=58.2}}},
  {t="Defias Trappers and Smugglers", lv=11, n="North-west from Sentinel Hill toward Molsen Farm: Defias Trappers and Smugglers camp in the fields between them.", g={{"o",12,i=2,txt="Kill Defias Smuggler x15",m=1436,x=51.6,y=46.6},{"o",12,i=1,txt="Kill Defias Trapper x15",m=1436,x=51.4,y=46.8}}},
  {t="Molsen Farm's well", lv=11, g={{"o",92742,i=2,txt="Molsen Farm Water Sample",n2="Fill the vial at the farm's well",m=1436,x=46.1,y=38.2}}},
  {t="Molsen Farm's Harvest Watchers", lv=11, n="Harvest Watchers and Golems work the fields around Molsen Farm; they drop the isosprings, gyrostabilizers, Okra and sometimes a Precessive Autocognition Assembly. Foe Reaper 4000, a level 20 rare, walks here: leave it alone.", g={{"o",9,i=1,txt="Kill Harvest Watcher x20",n2="Harvest Watchers",m=1436,x=45.9,y=36.1},{"o",92909,i=1,txt="Golem Isospring x14",m=1436,x=45.9,y=36.1},{"o",92909,i=2,txt="Harvester Gyrostabilizer x5",m=1436,x=45.9,y=36.1},{"o",38,i=4,txt="Okra x3",m=1436,x=45.9,y=36.1},{"h",255155,txt="Get Precessive Autocognition Assembly",m=1436,x=45.9,y=36.1,n=1,opt=true},{"a",92910,opt=true,ml=8},{"h",814,txt="Get Flask of Oil x5",n2="Flask of Oil: keep five for Captain Grayson at the Westfall Lighthouse, later on the route",m=1436,x=45.9,y=36.1,n=5,opt=true}}},
  {t="The gnoll hills", lv=11, n="North to the hills above Jangolode Mine: Riverpaw Gnolls and Scouts (level 11-13) roam there, east toward the Jansen Stead. The gnolls further south and west are 13-19: stay in the north hills.\nCareful: Gnolls that stand close together tend to join a fight as a group. Pulling one at a time is safer.", g={{"o",102,i=1,txt="Gnoll Paw x8",n2="Gnoll Paws",m=1436,x=44.7,y=14.6}}},
  {t="The Longshore murlocs", lv=11, n="Murloc Coastrunners and Raiders line the north coast from above the mine east toward the Jansen Stead: work along the beach eastward. They flee at low health: pull one at a time.", g={{"o",92744,i=1,txt="Longshore Murloc Gill x7",n2="Longshore Murloc Gills",m=1436,x=42.5,y=10.5},{"o",38,i=2,txt="Murloc Eye x3",m=1436,x=42.5,y=10.5}}},
  {t="Furlbrow's Wardrobe", lv=11, n="Furlbrow's Wardrobe stands in the ruined house east of the mine, on the way to the Jansen Stead.\nCareful: Two Defias stand guard inside, one of them the level 15 named Benny Blaanco. They are linked, so attacking either one brings both.", g={{"o",64,i=1,txt="Furlbrow's Pocket Watch",n2="Furlbrow's Wardrobe; inside",m=1436,x=49.3,y=19.3}}},
  {t="The Jansen Stead", lv=11, g={{"o",151,i=1,txt="Handful of Oats x8",n2="Sacks of Oats in the fields around the farm",m=1436,x=56.8,y=19.1},{"o",92742,i=1,txt="Jansen Stead Water Sample",n2="Fill the vial at the well",m=1436,x=56.6,y=18.6},{"t",64,m=1436,x=60,y=19.4},{"t",151,m=1436,x=59.9,y=19.4}}},
  {t="Finish the Goretusk Livers", lv=11, n="Still short of eight? Young Goretusks root in the fields just west of Saldean's Farm.", w={{k="has",neg=true,n=8,item=723}}, g={{"o",22,i=1,txt="Goretusk Liver x8",m=1436,x=54.1,y=26.7}}},
  {t="Finish the Stringy Vulture Meat", lv=11, n="Still short of three? Young Fleshrippers circle the fields north-west of Saldean's Farm.", w={{k="has",neg=true,n=3,item=729}}, g={{"o",38,i=1,txt="Stringy Vulture Meat x3",n2="Stringy Vulture Meat: Fleshrippers",m=1436,x=51.9,y=27.7}}},
