  {t="Finish the Red Leather Bandanas", lv=11, n="Still short of fifteen? Defias Trappers camp in the fields just west of Sentinel Hill.", w={{k="has",neg=true,n=15,item=829}}, g={{"o",153,i=1,txt="Red Leather Bandana x15",n2="Red Leather Bandanas",m=1436,x=48.5,y=45.2}}},
