  {t="Jangolode Mine", lv=14, n="Back north past Molsen Farm to the mine: Kobold Diggers work inside.", g={{"o",92745,i=1,txt="Kill Kobold Digger x4",n2="Kobold Diggers",m=1436,x=44.8,y=23.1}}},
  {t="The Gold Coast Quarry", lv=14, n="South-west to the coast, west of Molsen Farm. Riverpaw Miners work the quarry.", g={{"o",92745,i=2,txt="Kill Riverpaw Miner x6",n2="Riverpaw Miners",m=1436,x=30.4,y=45.4}}},
  {t="Moonbrook: kill these as you meet them", lv=14, n="Defias Pillagers and Looters hold the farms west of Sentinel Hill, between the coast road and Moonbrook. Alexston's Chest stands in the farmhouse at the Alexston Farmstead, among them: Baros' compass is inside.\nCareful: The Gold Coast Quarry cave holds many Defias packed together, so it is easy to pull several at once there.", g={{"o",13,i=1,txt="Kill Defias Pillager x15",m=1436,x=30.4,y=46},{"o",13,i=2,txt="Kill Defias Looter x15",m=1436,x=29.9,y=46.1},{"o",399,i=1,txt="A Simple Compass",n2="A Simple Compass, from Alexston's Chest",m=1436,x=36.2,y=54.5}}},
