  {t="High Priestess Laurena", lv=14, n="Walk to Stormwind. High Priestess Laurena is in the Cathedral of Light.", f={c={"PRIEST"},r={"Human"}}, g={{"t",94774,n2="Divine Grace",m=1453,x=49.5,y=44.6,f={r={"Human"}}}}},
