  {t="Tram to Ironforge", lv=14, f={c={"SHAMAN"}}, g={{"g",0,txt="Tram to Ironforge",m=1453,x=69.6,y=30.2}}},
  {t="Shaman training", lv=14, n="Head to Stormwind. It has no shaman trainer: take the Deeprun Tram from the Dwarven District to Ironforge, train with Eldrun Stormbreaker, then ride the tram back for the boat.", f={c={"SHAMAN"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="Stormwind", lv=14, n="Walk to Stormwind, or fly if you know its flight path. Trainers: Old Town (Warriors, Rogues), the Cathedral (Paladins, Priests), the Mage Quarter (Mages, Warlocks), the Dwarven District (Hunters), the Park (Druids).", f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","MAGE","WARLOCK","DRUID"}}, g={{"z",0,txt="Go to Stormwind City",n2="In through the main gate (already done if you are in the city)",m=1453,x=73.5,y=90.6,at="Stormwind City"},{"tr",0,txt="Visit your class trainer",n2="Level 12, 14 and 16 spells",f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","MAGE","WARLOCK","DRUID"}}}}},
  {t="Back to Stormwind City", lv=14, n="Ride the tram back: it comes out in Stormwind's Dwarven District, where the errands below start.", f={c={"SHAMAN"}}, g={{"g",0,txt="Stormwind's Dwarven District",m=1453,x=69.6,y=30.2}}},
