  {t="Woo Ping", lv=14, n="While you're here: learn Swords from Woo Ping (Trade District, 10 silver); a sword in the main hand levels a Rogue steadily.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Swords",skillLine=43}}, f={c={"ROGUE"}}, g={{"tr",0,txt="Train with Woo Ping",m=1453,x=63.9,y=69.1}}},
