  {t="Fishin' Time", lv=14, n="Catherine Leland sells fishing supplies along the canal just west of the Trade District; Gilbert Gray fishes at the harbor, on the way to the boat.", g={{"h",6529,txt="Buy Shiny Bauble (Catherine Leland)",n2="Shiny Bauble, from Catherine Leland",m=1453,x=55.1,y=69.8,n=1},{"h",6530,txt="Buy Nightcrawlers x3 (Catherine Leland)",m=1453,x=55.1,y=69.8,n=3},{"a",95065,m=1453,x=26.1,y=47.1,ml=7},{"t",95065,m=1453,x=26.1,y=47.1},{"g",0,txt="Boat to Auberdine",m=1453,x=22.7,y=56.7}}},
