R:Segment({id="alliance/03-darkshore",title="Darkshore",faction="Alliance",min=15,max=19,zone=1439,zoneName="Darkshore",next="alliance/03-loch-modan"}, function() return {
  {t="Boat to Auberdine", lv=15, g={{"g",0,txt="Boat to Auberdine",m=1453,x=22.7,y=56.7}}},
  {t="Auberdine", lv=15, n="The boat docks west of the village: Cerellean Whiteclaw waits where the pier meets the shore. Go up to Thundris Windweaver at the north end of the village first, then down the main street to the inn. The flight master stands on the hill south of the inn. Wizbang Cranktoggle stands upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart.", g={{"a",963,n2="Cerellean Whiteclaw, on the pier",m=1439,x=35.7,y=43.7,ml=11},{"a",954,n2="Thundris Windweaver, north end of the village",m=1439,x=37.4,y=40.1,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=7},{"a",97914,n2="Thundris Windweaver: for Baros Alexston in Stormwind",m=1439,x=37.4,y=40.1,ml=13},{"i",0,txt="Sell and repair",opt=true},{"a",958,m=1439,x=37.4,y=40.1,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=9},{"t",97894,m=1439,x=38.1,y=41.2},{"a",982,m=1439,x=38.1,y=41.2,ml=13},{"a",984,m=1439,x=39.4,y=43.5,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=10},{"a",965,m=1439,x=39,y=43.5,ml=13},{"a",2118,m=1439,x=38.8,y=43.4,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=10},{"a",4811,m=1439,x=37.7,y=43.4,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=12},{"a",947,m=1439,x=37.3,y=43.6,ml=12},{"a",98025,n2="The WANTED poster outside the inn",m=1439,x=37.2,y=44.2,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=10},{"a",983,n2="Wizbang Cranktoggle, upstairs in the inn",m=1439,x=37,y=44.1,ml=7},{"fp",26,txt="Get the Auberdine flight path (Caylais Moonfeather)",m=1439,x=36.3,y=45.6},{"a",3524,n2="Gwennyth Bly'Leggonde (Night Elves have it from Teldrassil)",m=1439,x=36.6,y=45.6,ml=11},{"a",1138,n2="Gubber Blump, on the pier",m=1439,x=36.1,y=44.9,ml=15}}},
  {t="Gubber Blump", lv=15, n="Fishers only: Gubber Blump stands on the pier. His Darkshore Grouper is fished from the pier itself.", w={{k="skill",n=1,name="Fishing",skillLine=356}}, g={{"a",1141,n2="Gubber Blump, on the pier",m=1439,x=36.1,y=44.9,opt=true,ml=10}}},
  {t="The beach", lv=15, n="Tide Crawlers scuttle along the shore below the village; Buzzbox 827 stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The Beached Sea Creature lies on the shore just south of the village.", g={{"o",3524,i=1,txt="Sea Creature Bones",m=1439,x=36.4,y=50.9},{"o",1141,i=1,txt="Darkshore Grouper x6",n2="Darkshore Grouper: fish from the pier",m=1439,x=36.1,y=44.9,opt=true},{"o",983,i=1,txt="Crawler Leg x6",n2="Crawler Legs",m=1439,x=35.6,y=47.1},{"t",983,m=1439,x=36.6,y=46.3},{"a",1001,m=1439,x=36.6,y=46.3,ml=7}}},
  {t="Auberdine", lv=15, g={{"t",3524,m=1439,x=36.6,y=45.6},{"a",4681,n2="Washed Ashore: the Beached Sea Turtles up the coast offer their quests only once it is handed in",m=1439,x=36.6,y=45.6,ml=11},{"t",1141,m=1439,x=36.1,y=44.9,opt=true},{"b",0,txt="Set your hearthstone at Auberdine",m=1439,x=37,y=44.1,at="Auberdine"}}},
  {t="The skeletal turtle", lv=15, g={{"o",4681,i=1,txt="Sea Turtle Remains",n2="Sea Turtle Remains, on the beach west of the docks; underwater",m=1439,x=31.8,y=46.3},{"t",4681,m=1439,x=36.6,y=45.6}}},
  {t="Plagued bears", lv=15, n="Rabid Thistle Bears roam the hills just east of Auberdine. Use Tharnariun's Hope on one and lead it back to him.", g={{"c",2118,txt="Rabid Thistle Bear",n2="the Rabid Thistle Bears nearest Tharnariun",m=1439,x=38.2,y=52.6,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"t",2118,m=1439,x=38.8,y=43.4,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"a",2138,m=1439,x=38.8,y=43.4,ml=10}}},
  {t="Rabid Thistle Bear on the way", lv=15, al=true, g={{"o",2138,i=1,txt="Kill Rabid Thistle Bear x20",m=1439,x=38.2,y=52.6}}},
  {t="Bears and the Blackwood camp", lv=15, n="Kill Rabid Thistle Bears in the hills east of Auberdine, then walk up to the furbolg camp south-east of them: nothing to kill yet.", g={{"g",0,txt="Go here",m=1439,x=39.9,y=53.9,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"c",984,txt="Find a corrupt furbolg camp",m=1439,x=39.9,y=53.9}}},
  {t="Ameth'Aran", lv=15, n="Sentinel Tysha Moonblade stands at the north edge of the ruins. Cursed, Writhing and Wailing Highborne haunt them; Anaya Dawnrunner's ghost walks among them, Jai'vhanel the owl circles east of them. The two tablets lie in the ruins; a Beached Sea Turtle lies on the shore west of them.", lb="q2138", g={{"a",4722,m=1439,x=37.1,y=62.2,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=11},{"a",953,m=1439,x=40.3,y=59.7,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=9},{"o",958,i=1,txt="Highborne Relic x7",n2="Highborne Relics",m=1439,x=41.6,y=59.6,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"o",2138,i=1,txt="Kill Rabid Thistle Bear x20",m=1439,x=40.1,y=58.3},{"o",98025,i=1,txt="Feather of Jai'vhanel",m=1439,x=43.4,y=57.7,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"o",953,i=1,txt="The Lay of Ameth'Aran",n2="Read the Lay of Ameth'Aran",m=1439,x=43.3,y=58.7,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"o",953,i=2,txt="The Fall of Ameth'Aran",n2="Read the Fall of Ameth'Aran",m=1439,x=42.6,y=63.1,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"o",963,i=1,txt="Anaya's Pendant",m=1439,x=41.8,y=60.7},{"t",953,m=1439,x=40.3,y=59.7,f={r={"Dwarf","Gnome","Human","Skyborne"}}}}},
  {t="The red crystal", lv=15, n="Climb the eastern mountains east of Ameth'Aran; the Mysterious Red Crystal sits on a ledge.", g={{"o",4811,i=1,txt="Mysterious Red Crystal",m=1439,x=47.3,y=48.7,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"c",4811,txt="Mysterious Red Crystal; Locate the large, red crystal on Darkshore's eastern mountain range",f={r={"Dwarf","Gnome","Human","Skyborne"}}}}},
  {t="Rabid Thistle Bear", lv=15, g={{"o",2138,i=1,txt="Kill Rabid Thistle Bear x20",m=1439,x=48.4,y=35.6}}},
  {t="Bashal'Aran", lv=15, n="North along the hills. Asterion waits in the ruins of Bashal'Aran; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. Buzzbox 411 stands by the road west of the ruins; a Beached Sea Creature lies on the shore on the way to him.", g={{"t",954,m=1439,x=44.2,y=36.3,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"a",955,m=1439,x=44.2,y=36.3,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=7},{"o",955,i=1,txt="Grell Earring x8",n2="Grell Earrings",m=1439,x=44.6,y=36.6,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"t",955,m=1439,x=44.2,y=36.3,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"a",956,m=1439,x=44.2,y=36.3,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=7},{"o",956,i=1,txt="Ancient Moonstone Seal",n2="Ancient Moonstone Seal: Deth'ryll Satyrs",m=1439,x=45.5,y=36.5,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"t",956,m=1439,x=44.2,y=36.3,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"a",957,m=1439,x=44.2,y=36.3,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=7},{"a",4723,m=1439,x=41.9,y=31.5,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=11}}},
