  {t="A Lesson to Learn", lv=15, n="Night Elves fly from Auberdine to Rut'theran Village; Skyborne take the boat from the Auberdine dock and learn the Rut'theran flight path. Then take the portal up to Mathrengyl Bearwalker in the Cenarion Enclave.", f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village",f={r={"NightElf"}}},{"fp",27,txt="Get the Rut'theran Village flight path (Vesprystus)",m=1438,x=58.4,y=94,f={r={"Skyborne"}}}}},
  {t="Darnassus", lv=15, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"g",0,txt="Mathrengyl Bearwalker",m=1457,x=35.8,y=11.6}}},
  {t="A Lesson to Learn", lv=16, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"a",26,m=1457,x=35.4,y=8.4,f={r={"NightElf","Skyborne"}},ml=16},{"a",6121,n2="Mathrengyl Bearwalker: Lessons Anew",m=1457,x=35.4,y=8.4,f={r={"NightElf","Skyborne"}},ml=14}}},
  {t="Moonglade", lv=16, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"g",0,txt="Cast Teleport: Moonglade",m=1450,x=56.3,y=32.5}}},
  {t="Trial of the Lake", lv=16, n="Dendrite Starblaze stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart. Shrine Baubles lie in the containers on the floor of Lake Elune'ara, below Nighthaven: take one to the Shrine of Remulos in the north-west, use it there and speak to Tajarri. Trial of the Lake runs on a timer: no teleport or Hearthstone until Tajarri has it. Then fly back to Auberdine from Nighthaven.", f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"t",26,m=1450,x=56.2,y=30.6,f={r={"NightElf","Skyborne"}}},{"t",6121,m=1450,x=56.2,y=30.6,f={r={"NightElf","Skyborne"}}},{"a",6122,n2="The Principal Source: fill the sampler at Cliffspring Falls",m=1450,x=56.2,y=30.6,f={r={"NightElf","Skyborne"}},ml=14},{"a",29,m=1450,x=56.2,y=30.6,f={r={"NightElf","Skyborne"}},ml=16},{"h",15877,txt="Get Shrine Bauble",n2="Shrine Bauble, from a Bauble Container in the lake",m=1450,x=54.7,y=46.4,n=1},{"i",0,txt="Use Shrine Bauble",n2="At the Shrine of Remulos",m=1450,x=36,y=41.4},{"c",29,txt="Shrine Of Remulos",f={r={"NightElf","Skyborne"}}},{"t",29,m=1450,x=36.5,y=40.1,f={r={"NightElf","Skyborne"}}},{"a",272,n2="The half pendants lie in Darkshore and Westfall: later on the route",m=1450,x=36.5,y=40.1,f={r={"NightElf","Skyborne"}},ml=16},{"z",0,txt="Fly to Auberdine",at="Auberdine"}}},
  {t="Blackwood furbolgs", lv=16, n="Blackwood Pathfinders and Windtalkers hold the camp south-east of Auberdine.", g={{"o",985,i=1,txt="Kill Blackwood Pathfinder x8",m=1439,x=39.6,y=54.4,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"o",985,i=2,txt="Kill Blackwood Windtalker x5",m=1439,x=39.6,y=54,f={r={"Dwarf","Gnome","Human","Skyborne"}}}}},
  {t="The Ancient Flame", lv=16, n="The flame burns in the south of Ameth'Aran.", g={{"o",957,i=1,txt="Ancient Flame",m=1439,x=42.4,y=61.8,f={r={"Dwarf","Gnome","Human","Skyborne"}}}}},
  {t="The red crystal", lv=16, n="Back north-east into the mountains to the crystal.", g={{"t",4812,m=1439,x=47.3,y=48.7,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"a",4813,m=1439,x=47.3,y=48.7,f={r={"Dwarf","Gnome","Human","Skyborne"}},ml=12}}},
  {t="Cliffspring Falls", lv=16, n="Follow the hills north to the Cliffspring River and up to the falls. Two more beached remains lie on the north shore: near the Ruins of Mathystra and north of Bashal'Aran.", g={{"o",4762,i=1,txt="Use Empty Sampling Tube",m=1439,x=50.8,y=25.6},{"o",4762,i=1,txt="Cliffspring River Sample",n2="Cliffspring River Sample, at the waterfall",m=1439,x=50.8,y=25.6},{"o",6122,i=1,txt="Filled Cliffspring Falls Sampler",n2="Filled Cliffspring Falls Sampler: at the mouth of the cave by the falls",m=1439,x=54.9,y=33.3,f={c={"DRUID"},r={"NightElf","Skyborne"}}},{"a",4727,m=1439,x=53.1,y=18.1,ml=12},{"a",4725,m=1439,x=44.2,y=20.6,ml=12},{"o",1138,i=1,txt="Fine Crab Chunks x6",n2="Fine Crab Chunks from Encrusted Tide Crawler and Reef Crawler, by this stop",m=1439,x=44.8,y=21.8}}},
  {t="Bashal'Aran", lv=16, g={{"t",957,m=1439,x=44.2,y=36.3,f={r={"Dwarf","Gnome","Human","Skyborne"}}}}},
  {t="Auberdine", lv=16, g={{"t",985,m=1439,x=39.4,y=43.5,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"t",4762,m=1439,x=37.4,y=40.1},{"a",4763,m=1439,x=37.4,y=40.1,ml=15},{"t",6122,m=1439,x=37.7,y=40.7,f={c={"DRUID"},r={"NightElf","Skyborne"}}},{"i",0,txt="Use Empty Cleansing Bowl",m=1439,x=37.8,y=44},{"h",12347,txt="Get Filled Cleansing Bowl",n2="Filled Cleansing Bowl: fill the Empty Cleansing Bowl at the Auberdine Moonwell",m=1439,x=37.8,y=44,n=1},{"t",4813,m=1439,x=37.7,y=43.4,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"t",4727,m=1439,x=36.6,y=45.6},{"t",4725,m=1439,x=36.6,y=45.6},{"t",1138,n2="Gubber Blump, on the pier",m=1439,x=36.1,y=44.9},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Mist's Edge", lv=16, g={{"o",1001,i=1,txt="Thresher Eye x3",n2="Thresher Eyes; underwater",m=1439,x=33.8,y=38.4}}},
  {t="The bay wrecks", lv=16, n="Two wrecks lie on the sea floor in the bay north of Auberdine; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore.\nCareful: The murlocs inside the wrecks are close together and fast. They often swim through the hull walls and holes, so you will usually pull extra murlocs.", g={{"o",982,i=1,txt="Silver Dawning's Lockbox",n2="Silver Dawning's Lockbox; underwater",m=1439,x=38.2,y=28.8},{"o",982,i=2,txt="Mist Veil's Lockbox",n2="Mist Veil's Lockbox; underwater",m=1439,x=39.6,y=27.5}}},
  {t="Bashal'Aran", lv=16, g={{"t",1001,m=1439,x=42,y=28.6},{"a",1002,m=1439,x=42,y=28.6,ml=7}}},
  {t="Darkshore: kill these as you meet them", lv=16, n="Moonstalkers prowl the hills between Bashal'Aran and the tower. Buzzbox 323 stands on the hill west of the tower.", g={{"o",1002,i=1,txt="Moonstalker Fang x6",n2="Moonstalker Fangs",m=1439,x=44.3,y=27.7}}},
  {t="Cliffspring River", lv=16, g={{"t",1002,m=1439,x=51.3,y=24.6},{"a",1003,m=1439,x=51.3,y=24.6,ml=7}}},
  {t="The Tower of Althalaxx", lv=16, n="East of Buzzbox 323, Balthule Shadowstrike hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in Ashenvale.\nCareful: Dark Strand Voidcallers (28-29) with their voidwalkers and Athrikus Narassin (31) stand in the tower itself: take the parchments from the Fanatics south of it and keep away from the tower.", g={{"t",965,m=1439,x=55,y=24.9},{"a",966,m=1439,x=55,y=24.9,ml=13},{"o",966,i=1,txt="Worn Parchment x4",n2="Worn Parchment: Dark Strand Fanatics",m=1439,x=55.8,y=25.9},{"t",966,m=1439,x=55,y=24.9},{"a",967,m=1439,x=55,y=24.9,ml=13}}},
  {t="The cave and the Den Mother", lv=16, n="The cave lies south of the falls: Scaber Stalks grow all through it, the Death Cap at the very back. The Den Mother lairs in the hills south of the falls.", g={{"o",947,i=1,txt="Scaber Stalk x5",n2="Scaber Stalks; below ground",m=1439,x=55,y=33.3},{"o",947,i=2,txt="Death Cap",n2="Death Cap; below ground",m=1439,x=56.3,y=34.9}}},
  {t="The northern Blackwood camp", lv=16, n="The furbolg camp south of the Cliffspring River keeps its Nut, Fruit and Grain Stores by the bonfires. With a sample of each and the Filled Cleansing Bowl in your bags (the Empty Cleansing Bowl is filled at the Auberdine Moonwell), use the bowl by the bonfire closest to the river: it summons Xabraxxis, the satyr corruptor, and the Talisman of Corruption lies in his Demon Bag.", g={{"h",12343,txt="Get Blackwood Nut Sample",m=1439,x=51.8,y=33.5,n=1},{"h",12341,txt="Get Blackwood Fruit Sample",m=1439,x=52.9,y=33.4,n=1},{"h",12342,txt="Get Blackwood Grain Sample",m=1439,x=50.7,y=34.9,n=1},{"o",4763,i=1,txt="Use Filled Cleansing Bowl",n2="By the bonfire closest to the river: summons Xabraxxis",m=1439,x=52.5,y=33.4},{"o",4763,i=1,txt="Talisman of Corruption",n2="Talisman of Corruption, in Xabraxxis' Demon Bag",m=1439,x=52.5,y=33.4}}},
  {t="The cave and the Den Mother", lv=16, n="Careful: If you attack one cub, the other cubs and often the mother join the fight, so expect to take on several at the same time.", g={{"o",2139,i=1,txt="Kill Den Mother",n2="Den Mother, below ground",m=1439,x=51.5,y=38.3}}},
  {t="Auberdine", lv=16, g={{"t",2139,m=1439,x=38.8,y=43.4},{"t",982,m=1439,x=38.1,y=41.2},{"t",4763,m=1439,x=37.4,y=40.1},{"t",947,m=1439,x=37.3,y=43.6},{"a",948,n2="For Onu at the Grove, on Darkshore's southern loop after the trip east",m=1439,x=37.3,y=43.6,ml=12}}},
} end)

R:Segment({id="alliance/03-darkshore-return",title="Darkshore",faction="Alliance",min=21,max=23,zone=1439,zoneName="Darkshore",next="alliance/06-ashenvale"}, function() return {
  {t="Auberdine", lv=21, n="From the dock, up to the north end of the village first (Thundris Windweaver, Alanndarian Nightsong by the moonwell, Archaeologist Hollee), then down the main street: the WANTED poster outside the inn, Terenthis at its east end, where the road leaves south. Sentinel Selarin stands beside Terenthis by the flight master; if she isn't there, she has been killed and respawns shortly: wait a moment.", g={{"t",97926,n2="Thundris Windweaver, north end of the village: Baros Alexston's reply",m=1439,x=37.4,y=40.1,opt=true},{"a",6123,m=1439,x=37.7,y=40.7,f={c={"DRUID"},r={"NightElf","Skyborne"}},ml=14},{"a",729,m=1439,x=37.4,y=41.8,ml=15},{"i",0,txt="Sell and repair",opt=true},{"a",4740,n2="The WANTED poster",m=1439,x=37.2,y=44.2,ml=15},{"a",986,m=1439,x=39.4,y=43.5,ml=10},{"a",990,n2="Sentinel Selarin, beside Terenthis: for Raene Wolfrunner in Astranaar, in the next guide",m=1439,x=39.3,y=43.5,ml=15}}},
  {t="Onu", lv=21, w={{k="onquest",q={952}}}, g={{"t",952,m=1439,x=43.5,y=76.3,f={r={"NightElf"}}}}},
  {t="Onu", lv=21, n="Onu is the ancient at the Grove; Arbal and Kerlonian Evershade sleep beside him.", g={{"t",948,m=1439,x=43.5,y=76.3},{"a",944,m=1439,x=43.5,y=76.3,ml=12}}},
  {t="Lunar Fungus and Earthroot", lv=21, n="The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of Auberdine; the moonkin there are irritable. Earthroot needs Herbalism: herbalists pick it all over Darkshore, anyone else brings it from Stormwind (Maria Lumere) or the Auction House.", f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"o",6123,i=1,txt="Earthroot x5",m=1439,x=42.6,y=71.9,f={r={"NightElf","Skyborne"}}},{"o",6123,i=2,txt="Lunar Fungus x12",m=1439,x=45.4,y=53.2,f={r={"NightElf","Skyborne"}}}}},
  {t="The Grove of the Ancients", lv=21, n="Grizzled Thistle Bears roam the hills around the Grove; Buzzbox 525 stands west of it among them.", g={{"o",1003,i=1,txt="Grizzled Scalp x4",n2="Grizzled Scalps",m=1439,x=41.1,y=81.3},{"t",1003,m=1439,x=41.4,y=80.6}}},
  {t="The Master's Glaive", lv=21, n="Moonstalker Sires prowl the woods around the glaive. The Twilight Tome sits at the bottom of the crater; Therylune stands on its north side. For Onu's quest, use the Phial of Scrying at the bottom of the crater: it makes the Scrying Bowl, and you hand the quest in to the bowl.", g={{"o",986,i=1,txt="Fine Moonstalker Pelt x5",n2="Fine Moonstalker Pelts",m=1439,x=39.9,y=81.4},{"a",945,m=1439,x=38.6,y=87.3,ml=10},{"c",945,txt="Escort Therylune away from the Master's Glaive",n2="Escort her out of the glaive; Therysil takes the turn-in in Ashenvale"},{"a",968,n2="Only if a Disciple or Thug dropped Book: The Powers Below: right-click it",opt=true,ml=10},{"c",944,txt="Enter the Master's Glaive"},{"t",944,n2="The Scrying Bowl",m=1439,x=38.6,y=86.2},{"a",949,m=1439,x=38.6,y=86.2,ml=12},{"t",949,n2="The Twilight Tome",m=1439,x=38.5,y=86},{"a",950,m=1439,x=38.5,y=86,ml=12},{"a",98042,n2="The Twilight Tome, once it has The Twilight Camp",m=1439,x=38.5,y=86,ml=12},{"o",98042,i=1,txt="Peerless Eye",n2="Peerless Eye: Twilight Disciples and Thugs",m=1439,x=38.5,y=86.1}}},
  {t="Prospector Remtravel", lv=21, n="Remtravel's Excavation lies on the coast south of Murkdeep's beach. Protect the prospector while he searches for the fossil.\nCareful: Ambushers appear as he passes certain spots: a scout comes out from under the board ramp, and more scouts come out when he checks the tent.", g={{"t",729,m=1439,x=35.7,y=83.7},{"a",731,m=1439,x=35.7,y=83.7,ml=15},{"c",731,txt="Escort Prospector Remtravel"}}},
  {t="Murkdeep's beach", lv=21, n="Murkdeep camps on the beach west of the glaive: kill the murlocs at the camp fire; he comes in the third wave with his hound. Four beached remains lie on the beaches west and south-west of Remtravel's Excavation: take them on the way north to his camp.", g={{"a",4733,m=1439,x=31.3,y=87.4,ml=13},{"a",4732,m=1439,x=31.2,y=85.6,ml=13},{"a",4731,m=1439,x=31.7,y=83.7,ml=13},{"a",4730,m=1439,x=32.7,y=80.8,ml=12},{"o",4740,i=1,txt="Kill Murkdeep",m=1439,x=36.4,y=76.5}}},
  {t="The Grove of the Ancients", lv=21, g={{"t",950,m=1439,x=43.5,y=76.3},{"a",951,m=1439,x=43.5,y=76.3,ml=12}}},
  {t="The Grove of the Ancients", lv=21, g={{"a",98013,m=1439,x=43.8,y=76.5,ml=12}}},
  {t="The shore west of the Grove", lv=21, n="On the way north to Auberdine, the last Beached Sea Creature lies on the shore west of the Grove.", f={r={"Dwarf","Gnome","Human","Skyborne"}}, g={{"a",4728,m=1439,x=36,y=70.9,ml=12}}},
  {t="Auberdine", lv=21, n="Follow the road north.", g={{"t",4731,m=1439,x=36.6,y=45.6},{"t",4733,m=1439,x=36.6,y=45.6},{"t",4732,m=1439,x=36.6,y=45.6},{"t",4730,m=1439,x=36.6,y=45.6},{"t",4728,m=1439,x=36.6,y=45.6,f={r={"Dwarf","Gnome","Human","Skyborne"}}},{"a",87760,n2="Holy Diver: Gwennyth offers it once all nine beached remains are handed in",m=1439,x=36.6,y=45.6,ml=15},{"t",4740,m=1439,x=37.7,y=43.4},{"a",98461,m=1439,x=37.4,y=41.8,opt=true,ml=18},{"t",731,m=1439,x=37.4,y=41.8},{"t",6123,m=1439,x=37.7,y=40.7,f={c={"DRUID"},r={"NightElf","Skyborne"}}},{"a",6124,n2="She gives you the Curative Animal Salve",m=1439,x=37.7,y=40.7,f={c={"DRUID"},r={"NightElf","Skyborne"}},ml=14},{"t",98042,m=1439,x=37.4,y=40.1},{"t",986,m=1439,x=39.4,y=43.5},{"a",993,m=1439,x=39.4,y=43.5,ml=10},{"i",0,txt="Sell and repair",opt=true}}},
  {t="On the way", lv=21, al=true, g={{"o",98013,i=1,txt="Kill Stormscale Myrmidon x12",m=1439,x=57.7,y=24.4},{"o",98013,i=2,txt="Kill Stormscale Sorceress x8",m=1439,x=58.4,y=24.4}}},
  {t="The naga", lv=21, n="Follow the coast north-east to the Ruins of Mathystra. Mathystra Relics lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore.", lb="q98013", g={{"o",951,i=1,txt="Mathystra Relic x6",n2="Mathystra Relics",m=1439,x=58.5,y=24.2},{"o",98013,i=1,txt="Kill Stormscale Myrmidon x12",m=1439,x=58.5,y=23.6},{"o",98013,i=2,txt="Kill Stormscale Sorceress x8",m=1439,x=58.5,y=23}}},
  {t="The Ruins of Mathystra", lv=21, n="Gelkak Gyromast hides on the little island off the ruins. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom).", g={{"a",2098,m=1439,x=56.7,y=13.5,ml=14},{"o",2098,i=1,txt="Top of Gelkak's Key",m=1439,x=58.4,y=14.2},{"o",2098,i=3,txt="Bottom of Gelkak's Key",m=1439,x=56.9,y=13.1},{"o",2098,i=2,txt="Middle of Gelkak's Key",n2="Underwater",m=1439,x=55.5,y=12.6},{"t",2098,m=1439,x=56.7,y=13.5}}},
  {t="Strange Lockbox", lv=21, w={{k="onquest",q={272}}}, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"h",15883,txt="Get Half Pendant of Aquatic Agility",n2="Half Pendant of Aquatic Agility: the Strange Lockbox under the water off the north coast, west of the ruins",m=1439,x=48.9,y=11.3,n=1}}},
  {t="Mist's Edge: kill these as you meet them", lv=21, g={{"o",98013,i=1,txt="Kill Stormscale Myrmidon x12",m=1439,x=57.6,y=17.2},{"o",98013,i=2,txt="Kill Stormscale Sorceress x8",m=1439,x=58.5,y=18.3},{"o",98013,i=3,txt="Kill Stormscale Warrior x6",m=1439,x=60.1,y=18.8},{"o",87760,i=1,txt="Rod of Deep Dominion",n2="Rod of Deep Dominion: Stormscale Beastmistress",m=1439,x=50.3,y=15.8}}},
  {t="Back south", lv=21, g={{"t",87760,m=1439,x=36.6,y=45.6},{"t",951,n2="Onu, at the Grove",m=1439,x=43.5,y=76.3},{"t",98013,m=1439,x=43.8,y=76.5}}},
  {t="Volcor", lv=21, n="Volcor hides in the hills east of the Master's Glaive. Help him back to the road; he fights on his way out. Terenthis takes the escort in Auberdine on the next visit there.", g={{"t",993,n2="Volcor, inside Blackwood Den",m=1439,x=45,y=85.3},{"a",994,m=1439,x=45,y=85.3,ml=10},{"c",994,txt="Help Volcor to the road",n2="His walk ends at the road, where Grimclaw waits",m=1439,x=41.7,y=81.5},{"o",6124,i=1,txt="Cure Sickly Deer x10",n2="Sickly Deer: use the Curative Animal Salve on them; they roam all of Darkshore",m=1439,x=40.3,y=81.8,f={c={"DRUID"},r={"NightElf","Skyborne"}}}}},
  {t="Auberdine", lv=21, f={c={"DRUID"}}, g={{"t",994,m=1439,x=39.4,y=43.5}}},
  {t="Auberdine flight master", lv=21, f={c={"DRUID"}}, g={{"g",0,txt="Auberdine flight master",m=1439,x=36.4,y=45.6}}},
  {t="The Great Cat Spirit", lv=21, n="Night Elves fly from Auberdine to Rut'theran Village; Skyborne take the boat from the Auberdine dock and learn the Rut'theran flight path there. Take the portal up to Mathrengyl Bearwalker in the Cenarion Enclave.", f={c={"DRUID"}}, g={{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village",f={r={"NightElf"}}},{"fp",27,txt="Get the Rut'theran Village flight path (Vesprystus)",m=1438,x=58.4,y=94,f={r={"Skyborne"}}},{"l",20,txt="Reach level 20",f={c={"DRUID"}}}}},
  {t="Darnassus", lv=21, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"g",0,txt="Mathrengyl Bearwalker",m=1457,x=35.8,y=11.6}}},
  {t="The Great Cat Spirit", lv=21, f={c={"DRUID"}}, g={{"a",98393,m=1457,x=35.4,y=8.4,f={r={"NightElf","Skyborne"}},ml=20}}},
  {t="Moonglade", lv=21, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"g",0,txt="Cast Teleport: Moonglade",m=1450,x=56.3,y=32.5}}},
  {t="Dendrite Starblaze", lv=21, n="Cast Teleport: Moonglade. Dendrite Starblaze stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart. Learn the flight path there if you do not have it.", f={c={"DRUID"}}, g={{"t",98393,m=1450,x=56.2,y=30.6,f={r={"NightElf","Skyborne"}}},{"a",98394,m=1450,x=56.2,y=30.6,f={r={"NightElf"}},ml=20},{"t",6124,m=1450,x=56.2,y=30.6,f={r={"NightElf","Skyborne"}}},{"a",6125,m=1450,x=56.2,y=30.6,f={r={"NightElf","Skyborne"}},ml=14},{"a",98341,m=1450,x=56.2,y=30.6,f={r={"Skyborne"}},ml=20}}},
  {t="Dendrite Starblaze", lv=21, n="Dendrite Starblaze stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart.", w={{k="onquest",q={94914}}}, f={c={"DRUID"}}, g={{"t",94914,n2="Dendrite Starblaze: the welcome from Sheldras",m=1450,x=56.2,y=30.6,f={r={"Skyborne"}}}}},
  {t="Dendrite Starblaze", lv=21, f={c={"DRUID"}}, g={{"fp",49,txt="Get the Moonglade flight path (Sindrayl)",m=1450,x=48.1,y=67.3}}},
  {t="The relics of the Barrow Dens", lv=21, n="The Great Cat Spirit (Night Elves) and the Avatar of Saeyleenan (Skyborne) wait in southern Moonglade. The three relics lie in the Stormrage Barrow Dens, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again.", f={c={"DRUID"}}, g={{"t",98394,m=1450,x=54.5,y=75,f={r={"NightElf"}}},{"a",98396,m=1450,x=54.5,y=75,f={r={"NightElf"}},ml=20},{"t",98341,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}}},{"a",98404,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}},ml=20},{"o",98396,i=1,txt="Relic of the Fang",m=1450,x=72.4,y=66,f={r={"NightElf"}}},{"o",98396,i=2,txt="Relic of the Claw",m=1450,x=75.2,y=67.2,f={r={"NightElf"}}},{"o",98396,i=3,txt="Relic of the Silent Shadow",m=1450,x=74.4,y=65.4,f={r={"NightElf"}}},{"o",98404,i=1,txt="Relic of the Fang",m=1450,x=72.4,y=66,f={r={"Skyborne"}}},{"o",98404,i=2,txt="Relic of the Claw",m=1450,x=75.2,y=67.2,f={r={"Skyborne"}}},{"o",98404,i=3,txt="Relic of the Silent Shadow",m=1450,x=74.4,y=65.4,f={r={"Skyborne"}}},{"t",98396,m=1450,x=54.5,y=75,f={r={"NightElf"}}},{"a",98731,m=1450,x=54.5,y=75,f={r={"NightElf"}},ml=20},{"t",98404,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}}},{"a",98738,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}},ml=20}}},
  {t="Back to Dendrite", lv=21, n="Back to Dendrite Starblaze in Nighthaven, then Silva Fil'naveth there flies Druids straight to Rut'theran Village. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", f={c={"DRUID"}}, g={{"t",98731,m=1450,x=56.2,y=30.6,f={r={"NightElf"}}},{"t",98738,m=1450,x=56.2,y=30.6,f={r={"Skyborne"}}},{"l",20,txt="Reach level 20",f={c={"DRUID"}}},{"a",98397,m=1450,x=56.2,y=30.6,f={r={"NightElf","Skyborne"}},ml=20},{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village"}}},
  {t="Darnassus", lv=21, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"g",0,txt="Mathrengyl Bearwalker",m=1457,x=35.8,y=11.6}}},
  {t="To Darnassus", lv=21, n="Take the portal up to Mathrengyl, then fly back to Auberdine for the road south to Ashenvale.", f={c={"DRUID"}}, g={{"t",98397,n2="Mathrengyl Bearwalker: Cat Form",m=1457,x=35.4,y=8.4,f={r={"NightElf","Skyborne"}}},{"t",6125,n2="Mathrengyl Bearwalker: Cure Poison",m=1457,x=35.4,y=8.4,f={r={"NightElf","Skyborne"}}},{"z",0,txt="Fly to Auberdine",at="Auberdine"}}},
} end)

R:Segment({id="alliance/03-loch-modan",title="Loch Modan, Redridge Mountains & Westfall",faction="Alliance",min=17,max=21,zone=1432,zoneName="Loch Modan",next="alliance/03-darkshore-return"}, function() return {
  {t="Boat to Menethil Harbor", lv=17, n="Sell and repair in Auberdine first: the next stretch is a long one.", g={{"i",0,txt="Sell and repair",opt=true},{"g",0,txt="Boat to Menethil Harbor",m=1439,x=32.4,y=43.8}}},
  {t="Menethil Harbor", lv=17, n="Off the boat, walk up the pier to the flight master by the inn. Nothing to take here yet: Menethil's quests are for your Wetlands visit at about 22.", g={{"fp",7,txt="Get the Menethil Harbor flight path (Shellei Brondir)",m=1437,x=9.5,y=59.7}}},
  {t="Into Loch Modan", lv=17, n="Follow the road east out of Menethil and south through the Dun Algaz pass. Keep to the road: the Wetlands crocolisks and raptors beside it are over your level.", g={{"g",0,txt="Into Loch Modan",m=1432,x=25.6,y=10.5}}},
  {t="Algaz Station", lv=17, n="Mountaineer Stormpike stands at the Algaz Station, at the south end of the pass.", f={r={"Human","NightElf","Skyborne"}}, g={{"a",307,m=1432,x=24.8,y=18.4,ml=9}}},
  {t="Mountaineer Stormpike", lv=17, w={{k="onquest",q={353}}}, g={{"t",353,n2="Mountaineer Stormpike: Grimand Elmore's package",m=1432,x=24.8,y=18.4}}},
  {t="Silver Stream Mine", lv=17, n="East along the hills to the mine: the Miners' League crates sit in its tunnels among the Tunnel Rat kobolds.", f={r={"Human","NightElf","Skyborne"}}, g={{"o",307,i=1,txt="Miners' Gear x4",n2="Miners' Gear, from the crates; below ground",m=1432,x=34.9,y=23.4}}},
  {t="Back to the Algaz Station", lv=17, f={r={"Human","NightElf","Skyborne"}}, g={{"t",307,m=1432,x=24.8,y=18.4}}},
  {t="Stonewrought Dam", lv=17, n="Chief Engineer Hinderweir stands on top of the dam, up the ramp at its west end.", g={{"a",250,m=1432,x=46,y=13.6,ml=16}}},
  {t="The Suspicious Barrel", lv=17, n="Walk east along the dam, down its eastern ramp, then back west along the foot of the dam on the land side: two Dark Iron Sappers guard the barrel. Kill them, then open the barrel: it ends this quest and starts the next.", g={{"t",250,m=1432,x=56,y=13.2},{"a",199,m=1432,x=56,y=13.2,ml=16}}},
  {t="Stonewrought Dam", lv=17, g={{"t",199,m=1432,x=46,y=13.6}}},
  {t="The loch", lv=17, n="South along the west shore. The Discarded Fishing Toolbox lies on the loch bed at one of several places: east of Thelsamar (48.1,39.7), a little south-west of there (45.7,43.4), or at the south end of the loch (48.7,54.4 or 50.6,53.3). If it isn't at the arrow, try the next place. Click it for the quest; the Monogrammed Silver Hair Clip comes with it.", g={{"a",86614,n2="Discarded Fishing Toolbox; underwater",m=1432,x=48.1,y=39.7,ml=13}}},
  {t="Thelsamar", lv=17, n="Khara Deepwater stands on the shore north-east of town, Jern Hornhelm by the inn.", g={{"t",86614,m=1432,x=40.3,y=39.3},{"a",436,m=1432,x=37.2,y=47.4,ml=13}}},
  {t="Ironband's Excavation", lv=17, n="Round the south end of the loch and head east to the dig. Magmar Fellhew and Prospector Ironband stand together at its west edge.", g={{"t",436,m=1432,x=64.9,y=66.7},{"a",297,m=1432,x=64.9,y=66.7,ml=13},{"a",298,m=1432,x=65.9,y=65.6,ml=10}}},
  {t="The dig site", lv=17, n="Stonesplinter Diggers, Geomancers and Berserk Troggs hold the dig east of Ironband; any of them can drop a Carved Stone Idol. Piles of Excavation Tools lie around the dig: open one and right-click the tools to start Excavation Tools, then gather six.\nCareful: Berserk Troggs (19-20) enrage below 40% health.", g={{"h",278049,txt="Get Excavation Tools",n2="Excavation Tools: open a pile at the dig",m=1432,x=66.3,y=66.7,n=1},{"a",86613,n2="Right-click the Excavation Tools",ml=13},{"o",297,i=1,txt="Carved Stone Idol x8",m=1432,x=68,y=66},{"o",86613,i=1,txt="Excavation Tools x6",m=1432,x=67,y=67.6}}},
  {t="Ironband's Excavation", lv=17, g={{"t",297,m=1432,x=64.9,y=66.7},{"t",86613,m=1432,x=65.9,y=65.6}}},
  {t="The Farstrider Lodge", lv=17, n="North-east to the lodge on the hill. Marek Ironheart stands inside, Daryl the Youngling outside.", g={{"a",86758,n2="Marek Ironheart, inside",m=1432,x=81.8,y=61.7,ml=12},{"a",385,n2="Marek Ironheart: the loch crocolisks below the lodge",m=1432,x=81.8,y=61.7,ml=10},{"a",257,n2="Daryl the Youngling: 15 minutes",m=1432,x=83.5,y=65.5,ml=11}}},
  {t="Mountain Buzzards", lv=17, n="Mountain Buzzards circle the hills west and south of the lodge, back toward the dig. A Hunter's Boast runs for 15 minutes.", g={{"o",257,i=1,txt="Kill Mountain Buzzard x6",m=1432,x=79.3,y=66.9}}},
  {t="Daryl the Youngling", lv=17, g={{"t",257,m=1432,x=83.5,y=65.5},{"a",258,n2="12 minutes",m=1432,x=83.5,y=65.5,ml=11}}},
  {t="Elder Mountain Boars", lv=17, n="The Elder Mountain Boars roam the hills north-west of the lodge, along the east shore. A Hunter's Challenge runs for 12 minutes: kill five and go straight back to Daryl; the crocolisks come after.", g={{"o",258,i=1,txt="Kill Elder Mountain Boar x5",m=1432,x=74.8,y=50.7}}},
  {t="Daryl the Youngling", lv=17, g={{"t",258,m=1432,x=83.5,y=65.5}}},
  {t="Daggerfang and the loch crocolisks", lv=17, n="Back down to the east shore below the boars' hills: Daggerfang, a crocolisk, patrols it among the Loch Crocolisks.", g={{"o",86758,i=1,txt="Marek's Croc-Hunting Knife",n2="Marek's Croc-Hunting Knife: Daggerfang",m=1432,x=66.7,y=51.6},{"o",385,i=1,txt="Crocolisk Meat x5",n2="Crocolisk Meat: Loch Crocolisks",m=1432,x=62.4,y=51.5},{"o",385,i=2,txt="Crocolisk Skin x6",m=1432,x=62.4,y=51.5}}},
  {t="The Farstrider Lodge", lv=17, g={{"t",86758,n2="Marek Ironheart, inside",m=1432,x=81.8,y=61.7},{"t",385,m=1432,x=81.8,y=61.7}}},
  {t="Thelsamar", lv=17, n="Back west along the south shore to Thelsamar: Jern Hornhelm by the inn, then Thorgrum Borrelson with the gryphons on the west side of town, on the way south.", g={{"t",298,m=1432,x=37.2,y=47.4},{"a",301,n2="For Prospector Stormpike in Ironforge",m=1432,x=37.2,y=47.4,ml=10},{"fp",8,txt="Get the Thelsamar flight path (Thorgrum Borrelson)",m=1432,x=33.9,y=51}}},
  {t="Mountaineer Ylva", lv=17, n="South of Thelsamar, Ylva lies dead in the mouth of a trogg cave. Take her banner, raise it beside her and hold the spot: troggs come in waves from both sides, then Headsplitter.", g={{"a",86585,m=1432,x=31.8,y=86.3,ml=10},{"o",86585,i=1,txt="Kill Headsplitter",m=1432,x=31.8,y=86.5}}},
  {t="The tunnel post", lv=17, n="West to the dwarven post at the tunnel to Dun Morogh.", g={{"t",86585,m=1432,x=23.2,y=73.7}}},
  {t="Fly to Ironforge", lv=17, n="You have the Ironforge flight path from Dun Morogh: back north to Thelsamar's gryphons, quicker than walking through the tunnel and across Dun Morogh.", f={r={"Dwarf","Gnome"}}, g={{"g",0,txt="Thelsamar flight master",m=1432,x=33.9,y=50.8},{"z",0,txt="Fly to Ironforge",at="Ironforge"}}},
  {t="Into Dun Morogh", lv=17, n="Through the South Gate tunnel and west along the road to Ironforge. Know the Ironforge flight path already? Fly from Thelsamar instead: these two waypoints drop once you are in the city.", w={{k="zone",neg=true,name="Ironforge",area=1537}}, f={r={"Human","NightElf","Skyborne"}}, g={{"g",0,txt="Into Dun Morogh",m=1426,x=86,y=49.6}}},
  {t="Into Ironforge", lv=17, w={{k="zone",neg=true,name="Ironforge",area=1537}}, f={r={"Human","NightElf","Skyborne"}}, g={{"g",0,txt="Into Ironforge",m=1455,x=21.6,y=77.8}}},
  {t="Ironforge", lv=17, n="Gryth Thurden keeps the gryphons in the Great Forge; Prospector Stormpike is in the Hall of Explorers, north-east of it, on the way to the tram in Tinker Town.", g={{"fp",6,txt="Get the Ironforge flight path (Gryth Thurden)",n2="Gryth Thurden, in the Great Forge",m=1455,x=55.5,y=47.7},{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}},{"i",0,txt="Sell and repair",opt=true},{"t",301,n2="Prospector Stormpike, Hall of Explorers",m=1455,x=74.6,y=11.7}}},
  {t="Tram to Stormwind", lv=17, g={{"g",0,txt="Tram to Stormwind",m=1455,x=78,y=51.4}}},
  {t="Elwynn Forest", lv=17, n="From the tram, leave Stormwind by the main gate and follow the road through Goldshire and east through Elwynn to Redridge.", g={{"g",0,txt="The road east to Redridge",m=1429,x=65.8,y=74}}},
  {t="Guard Thomas", lv=17, n="Guard Thomas guards the bridge on this road east, past the Tower of Azora: Marshal Dughan's Further Concerns, from your walk through Goldshire, goes to him.", w={{k="onquest",q={35}}}, f={r={"NightElf"}}, g={{"t",35,n2="Guard Thomas, on the bridge",m=1429,x=74,y=72.2}}},
  {t="Henze Faulk", lv=17, n="From the bridge, head north to Stone Cairn Lake. Henze Faulk lies south of the lake: use the Symbol of Life on him. The Defias Rogue Wizards around him carry the Defias Script.", w={{k="onquest",q={1786,1787}}}, f={c={"PALADIN"},r={"Human"}}, g={{"o",1786,i=1,txt="Use Symbol of Life",n2="Use the Symbol of Life on Henze Faulk",m=1429,x=72.6,y=51.4,f={r={"Human"}}},{"t",1786,m=1429,x=72.6,y=51.4,f={r={"Human"}}},{"a",1787,m=1429,x=72.6,y=51.4,f={r={"Human"}},ml=12},{"o",1787,i=1,txt="Defias Script",n2="Defias Script: Defias Rogue Wizards",m=1429,x=71.7,y=52,f={r={"Human"}}}}},
  {t="Three Corners", lv=17, n="The road crosses into Redridge at Three Corners. Guard Parker walks around the crossroads.", g={{"a",244,n2="Guard Parker walks around Three Corners: look inside the circle on the map",m=1433,x=10.4,y=71.3,ml=11}}},
  {t="Lakeridge Highway", lv=17, n="Follow the road along the south shore of Lake Everstill to the gryphon master. Deputy Feldon stands by the road next to her.", g={{"fp",5,txt="Get the Lakeshire flight path (Ariena Stormfeather)",m=1433,x=25.5,y=59.4},{"t",244,m=1433,x=25.6,y=60},{"a",98407,m=1433,x=25.6,y=60,ml=11},{"a",246,m=1433,x=25.6,y=60,ml=11}}},
  {t="Lakeshire", lv=18, n="Cross the long bridge north into town: Shawn and Hilary play by the shore at its north end, Foreman Oslow and Marshal Marris stand there too, Verner Osgood by the smithy, Magistrate Solomon in the town hall, Dockmaster Baren on the docks, Wiley the Black upstairs in the inn and Darcy and Chef Breanna inside it.", g={{"a",3741,m=1433,x=24.2,y=53.6,ml=12},{"a",125,m=1433,x=27.1,y=48.6,ml=15},{"a",20,n2="Marshal Marris: the Blackrock camps are for your next Redridge visit, at about 24",m=1433,x=28.4,y=49,ml=18},{"a",98387,m=1433,x=28.4,y=49,ml=18},{"a",118,n2="Verner Osgood: for Smith Argus in Goldshire",m=1433,x=25.9,y=47.3,ml=14},{"a",120,n2="Magistrate Solomon, in the town hall: for General Marcus Jonathan in Stormwind",m=1433,x=24.9,y=44.5,ml=14},{"a",127,m=1433,x=22.6,y=47.4,ml=16},{"t",65,n2="Wiley the Black, in the inn; upstairs",m=1433,x=21.4,y=45.4},{"a",132,m=1433,x=21.4,y=45.4,ml=14},{"a",129,n2="Darcy, inside",m=1433,x=21.5,y=44.3,ml=12},{"a",92,n2="Chef Breanna, inside",m=1433,x=17.6,y=43.8,ml=15}}},
  {t="Guard Parker", lv=18, n="West along the road to Three Corners first; the gnolls are on the way back east.", g={{"t",129,n2="Guard Parker walks around Three Corners: look inside the circle on the map",m=1433,x=10.4,y=71.3},{"a",130,m=1433,x=10.4,y=71.3,ml=12}}},
  {t="Lakeridge Highway: kill these as you meet them", lv=18, n="Redridge Mongrels and Thrashers hold the hills east of Three Corners, north of the road; Poachers camp south of the road. Great Goretusks root around the same hills and Dire Condors circle south of the lake; Tarantulas crawl round Three Corners.", g={{"o",98407,i=1,txt="Spiked Collar x5",n2="Spiked Collar: Redridge Thrashers",m=1433,x=10.9,y=67.4},{"o",246,i=1,txt="Kill Redridge Mongrel x10",m=1433,x=10.5,y=66.6},{"o",246,i=2,txt="Kill Redridge Poacher x6",m=1433,x=23.2,y=79.4},{"o",92,i=1,txt="Great Goretusk Snout x5",m=1433,x=23.2,y=79.3},{"o",92,i=2,txt="Tough Condor Meat x5",m=1433,x=30.4,y=70.2},{"o",92,i=3,txt="Crisp Spider Meat x5",n2="Crisp Spider Meat: Tarantulas",m=1433,x=29.9,y=75.1}}},
  {t="Deputy Feldon", lv=18, n="East along the road to the gryphon master; Deputy Feldon stands beside her.", g={{"t",246,m=1433,x=25.6,y=60},{"t",98407,m=1433,x=25.6,y=60}}},
  {t="Sunken Chest", lv=18, n="Back toward town, swim east from the bridge into Lake Everstill; the chest lies on the lake bed beside a sunken boat. Murloc Flesheaters and Tidecallers line the south shore around it: any of them can carry a Spotted Sunfish.", g={{"o",125,i=1,txt="Oslow's Toolbox",n2="Oslow's Toolbox; underwater",m=1433,x=36.4,y=54.7},{"o",127,i=1,txt="Spotted Sunfish x10",m=1433,x=35.7,y=55.6}}},
  {t="Hilary's Necklace", lv=18, n="Then west under the bridge: a Glinting Mud mound on the lake bed beside town holds the necklace. Only one mound shows at a time, anywhere from under the dock to past the bridge.", g={{"o",3741,i=1,txt="Hilary's Necklace",n2="Hilary's Necklace; underwater",m=1433,x=32.8,y=54.5}}},
  {t="Lakeshire", lv=18, n="Through town east to west: Hilary and Foreman Oslow at the north end of the bridge, Dockmaster Baren on the docks, then Martie's garden at the west end; Darcy and Chef Breanna are in the inn.", g={{"t",3741,m=1433,x=24.1,y=53.6},{"t",125,m=1433,x=27.1,y=48.6},{"a",89,n2="Its pikes and rivets come from the gnolls north of the lake, on the loop after Westfall",m=1433,x=27.1,y=48.6,ml=15},{"t",127,m=1433,x=22.6,y=47.4},{"t",130,m=1433,x=16.8,y=46.3},{"a",131,m=1433,x=16.8,y=46.3,ml=12},{"t",131,n2="Darcy, inside",m=1433,x=21.5,y=44.3},{"t",92,n2="Chef Breanna, inside",m=1433,x=17.6,y=43.8}}},
  {t="Dockmaster Baren", lv=20, n="From level 20 Dockmaster Baren gives Murloc Poachers: take it now if he offers it (otherwise on the last Lakeshire stop). Its murlocs are for your next Redridge visit, at about 24.", w={{k="level",op=">=",n=20}}, g={{"a",150,n2="Dockmaster Baren, on the docks",m=1433,x=22.6,y=47.4,opt=true,ml=20}}},
  {t="Goldshire", lv=20, n="West out of Redridge by Three Corners and along the road through Elwynn to Goldshire.", g={{"g",0,txt="Goldshire",m=1429,x=42.1,y=65.9}}},
  {t="Smith Argus", lv=20, n="Smith Argus works at the Goldshire smithy.", g={{"t",118,m=1429,x=41.7,y=65.5},{"a",119,m=1429,x=41.7,y=65.5,ml=13}}},
  {t="Stormwind's gate", lv=20, n="No Defias Brotherhood from Wiley (it starts with Gryan Stoutmantle's letter in Westfall): skip Westfall. North along the road from Goldshire to Stormwind: General Marcus Jonathan sits on his horse at the far end of the bridge outside the main gate. Then the gryphons in the Trade District, back to Lakeshire.", w={{k="turnedin",neg=true,q=65}}, g={{"t",120,n2="General Marcus Jonathan, outside the main gate",m=1453,x=69.2,y=82.7},{"a",121,m=1453,x=69.2,y=82.7,ml=14},{"z",0,txt="Fly to Lakeshire",at="Lakeshire"}}},
  {t="Westfall", lv=20, n="West through Westbrook into Westfall.", w={{k="turnedin",q=65}}, g={{"g",0,txt="Sentinel Hill",m=1436,x=59.9,y=19.4}}},
  {t="Sentinel Hill", lv=20, n="Down the road to Sentinel Hill. Gryan Stoutmantle stands at the top of the stone tower.", w={{k="turnedin",q=65}}, g={{"t",132,m=1436,x=56.3,y=47.5},{"a",135,n2="For Master Mathias Shaw in Stormwind",m=1436,x=56.3,y=47.5,ml=14},{"a",14,m=1436,x=56.3,y=47.5,ml=9},{"a",92747,m=1436,x=52.5,y=53,ml=9}}},
  {t="Fly to Stormwind", lv=20, w={{k="turnedin",q=65}}, g={{"g",0,txt="Sentinel Hill flight master",m=1436,x=56.6,y=52.6},{"z",0,txt="Fly to Stormwind",at="Stormwind"}}},
  {t="Stormwind", lv=20, n="Master Mathias Shaw is upstairs in the SI:7 building in Old Town: the stairs are hard to see at first. General Marcus Jonathan sits on his horse at the far end of the bridge outside the main gate, then back to the gryphons in the Trade District.", w={{k="turnedin",q=65}}, g={{"t",135,n2="Master Mathias Shaw, SI:7; upstairs",m=1453,x=78.3,y=70.7},{"a",141,m=1453,x=78.3,y=70.7,ml=14},{"t",120,n2="General Marcus Jonathan, outside the main gate",m=1453,x=69.2,y=82.7},{"a",121,m=1453,x=69.2,y=82.7,ml=14},{"z",0,txt="Fly to Sentinel Hill",at="Sentinel Hill"}}},
  {t="Sentinel Hill", lv=20, w={{k="turnedin",q=65}}, g={{"t",141,n2="Gryan Stoutmantle, at the top of the tower",m=1436,x=56.3,y=47.5},{"a",142,m=1436,x=56.3,y=47.5,ml=14}}},
  {t="Moonbrook and the Defias hills", lv=20, n="Defias Pathstalkers and Knuckledusters walk Moonbrook; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. The Deadmines entrance in the smithy is a group dungeon.\nCareful: The camps in the hills hold mixed groups of Defias, so it is easy to pull more than one at a time if you are low level.", w={{k="turnedin",q=65}}, g={{"o",14,i=2,txt="Kill Defias Pathstalker x5",m=1436,x=52.8,y=73.5},{"o",14,i=3,txt="Kill Defias Knuckleduster x5",m=1436,x=51.6,y=78.2},{"o",14,i=1,txt="Kill Defias Highwayman x15",m=1436,x=51.7,y=77.2},{"o",92747,i=1,txt="Suspicious Industrial Supplies x8",n2="Suspicious Industrial Supplies, from the crates around Moonbrook",m=1436,x=45.4,y=70.2}}},
  {t="The Defias Messenger", lv=20, n="South along the road to Moonbrook. The Defias Messenger starts in front of the Moonbrook smithy and walks north to the Gold Coast Quarry and the back of the Jangolode Mine, then back: look along his road. Slow him when he runs at 30% health.", w={{k="turnedin",q=65}}, g={{"o",142,i=1,txt="A Mysterious Message",n2="A Mysterious Message: the Defias Messenger",m=1436,x=45.1,y=69.3}}},
  {t="Westfall Lighthouse", lv=20, n="South-west from Moonbrook to the lighthouse on the point: Captain Grayson waits on its steps. Old Murk-Eye walks the beach and the shallows north-east of it among the murlocs: pull him away from the Oracles.", w={{k="turnedin",q=65}}, g={{"a",104,m=1436,x=30,y=86,ml=15},{"o",104,i=1,txt="Scale of Old Murk-Eye",n2="Scale of Old Murk-Eye: Old Murk-Eye, on the beach north-east of the lighthouse",m=1436,x=33.7,y=83.9},{"t",104,m=1436,x=30,y=86}}},
  {t="Captain Grayson", lv=20, n="Kept five Flasks of Oil from Westfall's Harvest Watchers? Captain Grayson takes them for his lighthouse fire.", w={{k="turnedin",q=65},{k="has",n=5,item=814}}, g={{"a",103,m=1436,x=30,y=86,ml=10},{"t",103,m=1436,x=30,y=86}}},
  {t="Sentinel Hill", lv=20, n="Back north up the road to Sentinel Hill. The Defias Traitor waits at the foot of the tower ramp; if he is missing, someone is escorting him and he is back within minutes.", w={{k="turnedin",q=65}}, g={{"t",142,m=1436,x=56.3,y=47.5},{"a",155,m=1436,x=55.7,y=47.5,ml=14},{"t",14,m=1436,x=56.3,y=47.5},{"t",92747,m=1436,x=52.5,y=53},{"a",92748,m=1436,x=52.5,y=53,ml=9}}},
  {t="The Defias Traitor", lv=20, n="Stay with the traitor as he walks south to Moonbrook; he does not stop for fights, so clear what follows him. His walk ends at the Defias hideout below Moonbrook.", w={{k="turnedin",q=65}}, g={{"c",155,txt="Escort The Defias Traitor to discover where VanCleef is hiding",n2="The Defias Traitor, at the foot of the tower ramp",m=1436,x=55.7,y=47.5}}},
  {t="Sentinel Hill", lv=20, n="Back north to Gryan Stoutmantle and the gryphons.", w={{k="turnedin",q=65}}, g={{"t",155,m=1436,x=56.3,y=47.5},{"z",0,txt="Fly to Lakeshire",at="Lakeshire"}}},
  {t="Lakeshire", lv=20, n="From the gryphons, over the bridge into town: Verner Osgood by the smithy, Magistrate Solomon in the town hall.", g={{"t",119,m=1433,x=25.9,y=47.3},{"a",122,m=1433,x=25.9,y=47.3,ml=14},{"a",124,m=1433,x=25.9,y=47.3,ml=15},{"t",121,n2="Magistrate Solomon, in the town hall",m=1433,x=24.9,y=44.5}}},
  {t="Redridge Canyons", lv=20, n="Redridge Brutes and Mystics hold the hills north and north-west of town; both carry the Iron Pikes and Rivets. Black Dragon Whelps nest in the same hills.\nCareful: The whelps cast Fireball from range, and the gnolls run for help at low health.", g={{"o",124,i=1,txt="Kill Redridge Brute x10",m=1433,x=24.4,y=37.9},{"o",124,i=2,txt="Kill Redridge Mystic x8",m=1433,x=21.9,y=37.2},{"o",89,i=1,txt="Iron Pike x5",m=1433,x=21.9,y=37.2},{"o",89,i=2,txt="Iron Rivet x5",m=1433,x=21.9,y=37.2},{"o",122,i=1,txt="Underbelly Whelp Scale x6",n2="Underbelly Whelp Scale: Black Dragon Whelps",m=1433,x=18.7,y=35.2}}},
  {t="Lakeshire", lv=20, n="Back down into town: Verner Osgood by the smithy, Foreman Oslow at the north end of the bridge, Dockmaster Baren on the docks.", g={{"t",124,m=1433,x=25.9,y=47.3},{"t",122,m=1433,x=25.9,y=47.3},{"t",89,m=1433,x=27.1,y=48.6},{"a",98386,n2="Foreman Oslow: Alther's Mill, for your next Redridge visit",m=1433,x=27.1,y=48.6,ml=15},{"a",150,n2="Dockmaster Baren, on the docks: the murlocs are for your next Redridge visit",m=1433,x=22.6,y=47.4,ml=20}}},
  {t="Fly to Stormwind", lv=20, n="Back to Auberdine for Darkshore's southern loops: the gryphon to Stormwind, then the boat from the harbour.", g={{"g",0,txt="Lakeshire flight master",m=1433,x=25.5,y=59.4},{"z",0,txt="Fly to Stormwind",at="Stormwind"}}},
  {t="Sprite Jumpsprocket", lv=20, w={{k="onquest",q={92748}}}, g={{"t",92748,n2="Sprite Jumpsprocket, Dwarven District",m=1453,x=61.9,y=30.6}}},
  {t="Baros Alexston", lv=20, n="Baros Alexston stands at the east side of Cathedral Square, on the way from the Dwarven District to the harbour.", w={{k="onquest",q={97914}}}, g={{"t",97914,n2="Baros Alexston: Thundris' letter from Auberdine",m=1453,x=57.7,y=47.9},{"a",97926,n2="For Thundris Windweaver, where the boat lands",m=1453,x=57.7,y=47.9,opt=true,ml=13}}},
  {t="Gazin Tenorm", lv=20, n="Gazin Tenorm and Duthorian Rall are in the Cathedral of Light, on Cathedral Square, on the way to the harbour.", w={{k="onquest",q={1787,1788}}}, f={c={"PALADIN"},r={"Human"}}, g={{"g",0,txt="Cathedral of Light",m=1453,x=50.5,y=47.5},{"t",1787,m=1453,x=49.5,y=45,f={r={"Human"}}},{"a",1788,m=1453,x=49.5,y=45,f={r={"Human"}},ml=12},{"t",1788,n2="Duthorian Rall: Redemption",m=1453,x=50.5,y=47.5,f={r={"Human"}}}}},
  {t="Boat to Auberdine", lv=20, g={{"g",0,txt="Boat to Auberdine",m=1453,x=22.7,y=56.7}}},
} end)

R:Segment({id="alliance/04-redridge-mountains",title="Duskwood & Redridge Mountains",faction="Alliance",min=25,max=27,zone=1433,zoneName="Redridge Mountains",next="alliance/05-duskwood"}, function() return {
  {t="Stormwind", lv=25, n="Train, then leave by the main gate and follow the road east through Elwynn Forest.\nLook to the Stars in Darkshire needs a Bronze Tube. Its vendors keep only one or two, and Herble Baubbletump in Darkshire is nearly always sold out: buy one at the Auction House in the Trade District on your way out. An engineer can make one too.", g={{"tr",0,txt="Visit your class trainer",n2="Level 18 and 20 spells",f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","MAGE","WARLOCK","DRUID"}}},{"i",0,txt="Sell and repair",opt=true},{"h",4371,txt="Get Bronze Tube",n2="Bronze Tube: the Auction House, for Look to the Stars in Darkshire",m=1453,x=61.2,y=71.3,n=1,opt=true}}},
  {t="Woo Ping", lv=25, n="While you're here: learn Polearms from Woo Ping (Trade District, 1 gold); two-handers level a Warrior fastest.", w={{k="level",op=">=",n=20},{k="money",op=">=",n=10000},{k="skill",neg=true,n=1,name="Polearms",skillLine=229}}, f={c={"WARRIOR"}}, g={{"tr",0,txt="Train with Woo Ping",m=1453,x=63.9,y=69.1}}},
  {t="Woo Ping", lv=25, n="While you're here: learn Polearms from Woo Ping (Trade District, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most.", w={{k="level",op=">=",n=20},{k="money",op=">=",n=10000},{k="skill",neg=true,n=1,name="Polearms",skillLine=229}}, f={c={"HUNTER"}}, g={{"tr",0,txt="Train with Woo Ping",m=1453,x=63.9,y=69.1}}},
  {t="Tram to Ironforge", lv=25, f={c={"SHAMAN"}}, g={{"g",0,txt="Tram to Ironforge",m=1453,x=69.6,y=30.2}}},
  {t="Shaman training", lv=25, n="Stormwind has no shaman trainer: take the Deeprun Tram from the Dwarven District to Ironforge, train with Eldrun Stormbreaker, then ride the tram back.", f={c={"SHAMAN"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="Fly to Sentinel Hill", lv=25, w={{k="onquest",q={272}}}, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"g",0,txt="Stormwind flight master",m=1453,x=71,y=73},{"z",0,txt="Fly to Sentinel Hill",at="Sentinel Hill"}}},
  {t="Half Pendant of Aquatic Endurance", lv=25, n="Fly to Sentinel Hill and head north-west to the coast: the Strange Lockbox lies on the sea floor off the shore. Then head east along the road through Elwynn.", w={{k="onquest",q={272}}}, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"h",15882,txt="Get Half Pendant of Aquatic Endurance",n2="Half Pendant of Aquatic Endurance: the Strange Lockbox",m=1436,x=17.9,y=33.2,n=1}}},
  {t="Back to Elwynn Forest", lv=25, f={c={"SHAMAN"}}, g={{"g",0,txt="The road into Elwynn Forest",m=1429,x=65.2,y=69.7}}},
  {t="Elwynn Forest", lv=25, g={{"g",0,txt="The Tower of Azora",m=1429,x=65.2,y=69.7}}},
  {t="Theocritus", lv=25, g={{"a",94,n2="On the top floor",m=1429,x=65.2,y=69.7,ml=20}}},
  {t="Henze Faulk", lv=25, n="On the road east, past the Tower of Azora, head north from the bridge to Stone Cairn Lake. Henze Faulk lies south of the lake: use the Symbol of Life on him. The Defias Rogue Wizards around him carry the Defias Script.", w={{k="onquest",q={1786,1787}}}, f={c={"PALADIN"},r={"Human"}}, g={{"o",1786,i=1,txt="Use Symbol of Life",n2="Use the Symbol of Life on Henze Faulk",m=1429,x=72.6,y=51.4,f={r={"Human"}}},{"t",1786,m=1429,x=72.6,y=51.4,f={r={"Human"}}},{"a",1787,m=1429,x=72.6,y=51.4,f={r={"Human"}},ml=12},{"o",1787,i=1,txt="Defias Script",n2="Defias Script: Defias Rogue Wizards",m=1429,x=71.7,y=52,f={r={"Human"}}}}},
  {t="Three Corners", lv=25, n="The road east through Elwynn crosses into Redridge at Three Corners, where the roads to Redridge, Duskwood and Elwynn meet: south to Duskwood first.", g={{"g",0,txt="Three Corners",m=1433,x=10.2,y=71.5}}},
  {t="Duskwood", lv=25, g={{"g",0,txt="Darkshire",m=1431,x=75.8,y=45.3}}},
  {t="Darkshire", lv=25, n="Follow the road south from Three Corners into Duskwood; Darkshire lies on the east side of the forest.\nNo Bronze Tube for Look to the Stars? Herble Baubbletump, in the house beside Viktori, is nearly always sold out. Without one, right-click the quest in the guide window and skip it.", g={{"fp",12,txt="Get the Darkshire flight path (Felicia Maline)",n2="Felicia Maline, at the north end of town",m=1431,x=77.5,y=44.3},{"a",101,n2="Madame Eva, in her house by the tavern; inside",m=1431,x=75.8,y=45.3,ml=18},{"a",66,n2="Madame Eva, inside",m=1431,x=75.8,y=45.3,ml=22},{"b",0,txt="Set your hearthstone at Darkshire",n2="Innkeeper Trelayne, Scarlet Raven Tavern",m=1431,x=73.9,y=44.4,at="Darkshire"},{"t",66,n2="Clerk Daltry, in the town hall",m=1431,x=72.5,y=46.9},{"a",56,n2="Commander Althea Ebonlocke, in the town hall",m=1431,x=73.5,y=46.8,ml=18},{"a",96139,n2="Sirra Von'Indi, in the house behind the town hall",m=1431,x=72.6,y=47.6,ml=18},{"a",164,n2="Elaine Carevin, at the south end of town; inside",m=1431,x=75.3,y=48.8,ml=17},{"a",165,m=1431,x=75.3,y=48.8,ml=17},{"a",163,n2="Elaine Carevin: Jitters, at Raven Hill",m=1431,x=75.3,y=48.8,ml=17},{"a",174,n2="Viktori Prism'Antras, inside",m=1431,x=79.8,y=48,ml=20},{"t",174,m=1431,x=79.8,y=48},{"a",175,n2="For Blind Mary, on the hill south-east of town",m=1431,x=79.8,y=48,ml=20}}},
  {t="Tranquil Gardens Cemetery: kill these as you meet them", lv=25, n="Skeletal Warriors and Skeletal Mages walk among the graves south-east of Darkshire, below Blind Mary's house on the hill. Every skeleton in Duskwood can drop a Skeleton Finger.\nCareful: Because the skeletons stand near each other, running straight in tends to pull several at once.", g={{"o",101,i=3,txt="Skeleton Finger x10",m=1431,x=79.8,y=66},{"o",56,i=2,txt="Kill Skeletal Mage x6",m=1431,x=79.8,y=66},{"o",56,i=1,txt="Kill Skeletal Warrior x8",m=1431,x=80.6,y=66.7}}},
  {t="Watcher Dodds", lv=25, n="Watcher Dodds stands south of the road, at the Yorgen Farmstead.", g={{"a",245,m=1431,x=45.1,y=67,ml=17}}},
  {t="Raven Hill", lv=25, n="Continue west to Raven Hill. The Memory of Valor glows by the ruined house south of the road; Jitters hides in the house at the west end of the village.", g={{"o",96139,i=1,txt="Raven Hill Tome",n2="Raven Hill Tome, from the Memory of Valor",m=1431,x=21.1,y=55.6},{"t",163,m=1431,x=18.4,y=56.4},{"a",5,n2="for Chef Grual in Darkshire",m=1431,x=18.4,y=56.4,ml=17}}},
  {t="Sven's Camp", lv=25, n="Follow the road north-west past the cemetery to Sven's camp on the far west edge of the forest. Lars stands beside Sven.", g={{"t",164,m=1431,x=7.8,y=34.1},{"a",95,m=1431,x=7.8,y=34.1,ml=20},{"a",226,m=1431,x=7.7,y=33.2,ml=19}}},
  {t="The Hushed Bank: kill these as you meet them", lv=25, n="Rabid Dire Wolves roam the woods around the cemetery and Abercrombie, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders are the small spiders, and few: most crawl along the Hushed Bank west of Raven Hill, fewer up north towards Sven's camp; they drop the venom too. Every ghoul of the cemetery's northern half can drop a fang. Wolves and the bigger spiders share the Westfall border, so pull with care.", g={{"o",226,i=2,txt="Kill Rabid Dire Wolf x8",m=1431,x=11,y=32.3},{"o",226,i=1,txt="Kill Starving Dire Wolf x12",m=1431,x=10.8,y=29.5},{"o",245,i=1,txt="Kill Pygmy Venom Web Spider x15",m=1431,x=10.6,y=55.4},{"o",101,i=2,txt="Vial of Spider Venom x5",n2="Vial of Spider Venom: Pygmy Venom Web Spiders, Venom Web Spiders and Green Recluses",m=1431,x=11.2,y=54.8},{"h",2251,txt="Get Gooey Spider Leg x6",n2="Gooey Spider Leg: keep the ones these spiders drop, for Chef Grual in Darkshire",m=1431,x=11.2,y=54.8,n=6,opt=true}}},
  {t="Abercrombie", lv=25, n="The hermit's shack stands in the woods north-east of the Raven Hill Cemetery.", g={{"t",165,m=1431,x=28.1,y=31.5},{"a",148,m=1431,x=28.1,y=31.5,ml=20}}},
  {t="Raven Hill Cemetery: kill these as you meet them", lv=25, n="The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. Mor'Ladim, an elite, wanders the graves: keep away from him.", g={{"o",101,i=1,txt="Ghoul Fang x10",m=1431,x=25.8,y=32.9},{"o",101,i=3,txt="Skeleton Finger x10",m=1431,x=76.9,y=68.2}}},
  {t="Watcher Dodds", lv=25, n="Head back east along the road to the Yorgen Farmstead.", g={{"t",245,m=1431,x=45.1,y=67}}},
  {t="Yorgen Farmstead", lv=25, n="The mound of loose dirt lies south of the farmhouse, by the old stump.", g={{"t",95,m=1431,x=49.9,y=77.7},{"a",230,m=1431,x=49.9,y=77.7,ml=20}}},
  {t="Darkshire", lv=25, g={{"t",96139,n2="Sirra Von'Indi, inside",m=1431,x=72.6,y=47.6},{"t",5,n2="Chef Grual, in the Scarlet Raven Tavern",m=1431,x=73.8,y=43.5},{"a",93,n2="Chef Grual: six Gooey Spider Legs, which Duskwood's spiders drop even without the quest",m=1431,x=73.8,y=43.5,ml=17},{"t",93,n2="Already carrying six? Hand them in now",m=1431,x=73.8,y=43.5,opt=true},{"a",240,n2="For Jitters, at Raven Hill on the next Duskwood loop",m=1431,x=73.8,y=43.5,opt=true,ml=17},{"t",56,m=1431,x=73.5,y=46.8},{"a",57,m=1431,x=73.5,y=46.8,ml=18},{"l",23,txt="Reach level 23"},{"a",173,n2="Calor, by the town hall",m=1431,x=75.8,y=47.6,ml=23}}},
  {t="Madame Eva", lv=25, g={{"t",101,n2="Madame Eva, inside",m=1431,x=75.8,y=45.3},{"t",148,m=1431,x=75.8,y=45.3},{"a",149,m=1431,x=75.8,y=45.3,ml=20},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Redridge Mountains", lv=25, n="Back north along the road from Darkshire to Three Corners.", g={{"g",0,txt="Lakeridge Highway",m=1433,x=10.2,y=71.5}}},
  {t="Lakeridge Highway", lv=25, n="Follow the road along the south shore of Lake Everstill to the gryphon master. Guard Howe stands by the road next to her.", g={{"fp",5,txt="Get the Lakeshire flight path (Ariena Stormfeather)",m=1433,x=25.5,y=59.4},{"a",128,m=1433,x=26.4,y=57.9,ml=20}}},
  {t="Lake Everstill's murlocs: kill these as you meet them", lv=25, n="Murloc Flesheaters and Tidecallers line the south shore of Lake Everstill, just east of the gryphons and the bridge. Any of them can carry a fin.", g={{"o",150,i=1,txt="Murloc Fin x8",m=1433,x=30.7,y=56.5}}},
  {t="Lakeshire", lv=25, n="Cross the long bridge north into town: Dockmaster Baren on the docks, Bailiff Conacher in the town hall, Martie Jainrose in her garden at the west end. Marshal Marris's Blackrock quests and Alther's Mill came with you from your first Redridge visit.", g={{"a",126,n2="Verner Osgood, by the road at the north end of the bridge",m=1433,x=25.9,y=47.3,ml=15},{"t",150,m=1433,x=22.6,y=47.4},{"a",91,n2="Bailiff Conacher, in the town hall",m=1433,x=24.6,y=44.3,ml=17},{"a",180,n2="The Wanted poster by the inn",m=1433,x=21.7,y=46.4,ml=15},{"a",34,m=1433,x=16.8,y=46.3,ml=18}}},
  {t="Bellygrub", lv=25, n="Bellygrub (level 24) roots around the pen just west of Lakeshire, beside Martie's garden. Pull him away from the other boars and fight at full health.", g={{"o",34,i=1,txt="Bellygrub's Tusk",m=1433,x=10.6,y=49.3}}},
  {t="Martie Jainrose", lv=25, n="Martie's garden is at the west end of town.", g={{"t",34,m=1433,x=16.8,y=46.3}}},
  {t="Lakeshire", lv=25, n="Back east through town from Martie's garden: two Wanted posters hang on the town hall doorway.", g={{"a",169,n2="The Wanted poster on the town hall doorway",m=1433,x=24.5,y=46.2,opt=true,ml=15},{"a",95999,n2="The Wanted poster beside it",m=1433,x=24.3,y=46.2,opt=true,ml=16},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Alther's Mill", lv=25, n="Greater Tarantulas crawl on the slopes around Alther's Mill, north-east of the lake; their Tarantula Eggs lie on the ground among them: click six.", g={{"o",98386,i=1,txt="Kill Greater Tarantula x12",m=1433,x=42.7,y=38.5},{"o",98386,i=2,txt="Tarantula Egg",m=1433,x=46.1,y=37.3}}},
  {t="Blackrock camps", lv=25, n="South-east from the mill, west of Galardell Valley's gnolls, to the Blackrock camps east of Stonewatch Keep. Renegades, Grunts and Outrunners fill them; keep east of the keep, whose orcs are elite. Weapon racks and swords lie about the camps; meat haunches, grain sacks and water barrels hold the supplies.", g={{"o",20,i=1,txt="Battleworn Axe x10",m=1433,x=71,y=70.5},{"o",98387,i=1,txt="Stolen Weapon x8",n2="Stolen Weapon: weapon racks and swords on the ground",m=1433,x=68.3,y=79.4},{"o",98387,i=2,txt="Blackrock Supplies x10",n2="Blackrock Supplies: meat haunches, grain sacks, water barrels",m=1433,x=67.4,y=78.9}}},
  {t="Incinerator Gar'im", lv=25, n="Gar'im keeps to the cave at the camps' south end with his imp and two orcs. Elite: group up if you can; solo, pull the orcs at the mouth first and interrupt his fire cast.", w={{k="group",q=95999},{k="onquest",q={95999}}}, g={{"o",95999,i=1,txt="Broken Staff of Incinerator Gar'im",m=1433,x=72.8,y=86.3,grp=true}}},
  {t="Galardell Valley", lv=25, n="North up the valley's east side. Shadowhide gnolls fill it; Lieutenant Fangore (26) and his two guards stand at its north end: clear the gnolls around him first and fight at full health. Stay out of Stonewatch Keep to the west until the watch tower: its orcs are elite.", g={{"o",91,i=1,txt="Shadowhide Pendant x10",n2="Shadowhide Pendant: any Shadowhide gnoll",m=1433,x=77.7,y=59.3},{"o",180,i=1,txt="Fangore's Paw",m=1433,x=75.1,y=37.1}}},
  {t="A Watchful Eye", lv=25, n="The Old Lion Statue stands at the valley's east edge.", g={{"t",94,m=1433,x=79.4,y=46.8},{"a",248,m=1433,x=79.4,y=46.8,ml=20}}},
  {t="Looking Further", lv=25, n="West to the intact watch tower beside Stonewatch Keep: climb it and leave the Glyph in the empty jar at the top.", g={{"t",248,m=1433,x=58.2,y=49.8}}},
  {t="Stonewatch Keep", lv=25, n="The keep stands beside the tower. Gath'Ilzogg (elite) waits in the keep's top room with two guards and a dragon; Blackrock Shadowcasters (elite) and Sentries stand on its west side, so pull one at a time on the way in, and hug the right wall as you enter his room so you don't pull him at once. Elite: group up if you can.", w={{k="group",q=169},{k="onquest",q={169}}}, g={{"o",169,i=1,txt="Head of Gath'Ilzogg",m=1433,x=64.5,y=55.8,grp=true}}},
  {t="Yowler", lv=25, n="From the keep head back west along the lake's north shore and north up the Redridge Canyons. Just south of Render's Valley, Yowler, a level 25 gnoll, walks among the Redridge Alphas and Mystics.", g={{"o",126,i=1,txt="Yowler's Paw",m=1433,x=22.7,y=21.6}}},
  {t="Render's Valley", lv=25, n="From the keep head back west along the lake's north shore and north up the Redridge Canyons to Render's Valley; Lakeshire's hand-ins wait for Keeshan's escort, which ends there. Blackrock Champions camp in the valley.", g={{"o",128,i=1,txt="Kill Blackrock Champion x15",n2="Blackrock Champion, below ground",m=1433,x=23.5,y=17.2}}},
  {t="Corporal Keeshan", lv=25, n="Keeshan hides at the very north end of the valley, by the Burning Steppes border. Escort him down to Lakeshire; Blackrock orcs ambush you on the way.", g={{"a",219,n2="Corporal Keeshan, below ground",m=1433,x=23.3,y=12.6,ml=19},{"c",219,txt="Escort Corporal Keeshan back to Redridge"}}},
  {t="Magistrate Solomon: Gath'Ilzogg", lv=25, w={{k="group",q=169},{k="complete",q=169}}, g={{"t",169,n2="Magistrate Solomon, in the town hall",m=1433,x=24.9,y=44.5}}},
  {t="Magistrate Solomon: Incinerator Gar'im", lv=25, w={{k="group",q=95999},{k="complete",q=95999}}, g={{"t",95999,n2="Magistrate Solomon, in the town hall",m=1433,x=24.9,y=44.5}}},
  {t="Back to Lakeshire", lv=25, n="Into Lakeshire from the north with Keeshan: Bailiff Conacher and Magistrate Solomon in the town hall, Marshal Marris and Foreman Oslow at the north end of the bridge, then over the bridge to Guard Howe and the gryphons.", g={{"t",91,n2="Bailiff Conacher, in the town hall",m=1433,x=24.6,y=44.3},{"t",180,n2="Magistrate Solomon, in the town hall",m=1433,x=24.9,y=44.5},{"t",126,n2="Verner Osgood, by the road on the way to the bridge",m=1433,x=25.9,y=47.3},{"t",219,m=1433,x=28.4,y=49},{"t",20,m=1433,x=28.4,y=49},{"t",98387,m=1433,x=28.4,y=49},{"t",98386,m=1433,x=27.1,y=48.6},{"t",128,n2="Guard Howe, by the gryphons south of the bridge",m=1433,x=26.4,y=57.9},{"i",0,txt="Next: the gryphon to Darkshire for Duskwood's second loop (05-duskwood)."}}},
} end)

R:Segment({id="alliance/05-duskwood",title="Duskwood",faction="Alliance",min=27,max=28,zone=1431,zoneName="Duskwood",next="alliance/06-wetlands"}, function() return {
  {t="Fly to Darkshire", lv=27, n="Back to the Lakeshire gryphon master: fly to Darkshire for Duskwood's second loop.", g={{"g",0,txt="Lakeshire flight master",m=1433,x=25.5,y=59.4},{"z",0,txt="Fly to Darkshire",at="Darkshire"}}},
  {t="Blind Mary", lv=27, n="Her house stands on the hill south-east of Darkshire, above the Tranquil Gardens Cemetery.", g={{"t",149,n2="Inside",m=1431,x=82,y=59.1},{"a",154,m=1431,x=82,y=59.1,ml=20},{"t",175,m=1431,x=82,y=59.1},{"a",177,n2="Mary's Looking Glass: the Insane Ghoul in the cemetery's crypt is level 26; it waits for the Duskwood return",m=1431,x=82,y=59.1,ml=20}}},
  {t="Tranquil Gardens Cemetery", lv=27, g={{"h",2794,txt="Get An Old History Book",n2="An Old History Book: a rare drop from Duskwood's mobs",m=1431,x=81.7,y=60.5,n=1,opt=true},{"a",337,opt=true,ml=20}}},
  {t="Madame Eva", lv=27, g={{"t",154,n2="Inside",m=1431,x=75.8,y=45.3},{"a",157,m=1431,x=75.8,y=45.3,ml=20}}},
  {t="Abercrombie", lv=27, n="Head west along the road once more.", g={{"t",157,m=1431,x=28.1,y=31.5},{"a",158,m=1431,x=28.1,y=31.5,ml=20}}},
  {t="Gooey Spider Legs", lv=27, n="Carrion Recluses lurk in the woods on the way west, and Venom Web Spiders, Pygmy Venom Web Spiders and Green Recluses crawl just south of Sven's camp: each can drop a leg.", w={{k="onquest",q={93}}}, g={{"o",93,i=1,txt="Gooey Spider Leg x6",m=1431,x=10.5,y=41.5}}},
  {t="Sven's Camp", lv=27, g={{"t",226,m=1431,x=7.7,y=33.2},{"t",230,m=1431,x=7.8,y=34.1},{"a",262,m=1431,x=7.8,y=34.1,ml=20}}},
  {t="Back to Darkshire", lv=27, n="Hearth back to Darkshire if you bound at the Scarlet Raven Tavern on the first loop, or head back east along the road.", g={{"t",262,n2="Madame Eva, inside",m=1431,x=75.8,y=45.3},{"a",265,m=1431,x=75.8,y=45.3,ml=20},{"t",265,n2="Clerk Daltry, in the town hall",m=1431,x=72.5,y=46.9},{"a",266,m=1431,x=72.5,y=46.9,ml=20},{"t",266,n2="Tavernkeep Smitts, in the tavern",m=1431,x=73.8,y=44.5},{"a",453,m=1431,x=73.8,y=44.5,ml=20},{"t",158,m=1431,x=73.8,y=44.5},{"a",156,m=1431,x=73.8,y=44.5,ml=20}}},
  {t="Chef Grual", lv=27, n="Chef Grual is in the Scarlet Raven Tavern too.", w={{k="onquest",q={93}}}, g={{"t",93,m=1431,x=73.8,y=43.5},{"a",240,n2="For Jitters, at Raven Hill on the way west",m=1431,x=73.8,y=43.5,ml=17}}},
  {t="Rot Blossoms", lv=27, n="Skeletal Horrors walk the hillside between Darkshire and the Tranquil Gardens Cemetery, south-east of town; they drop the Rot Blossoms.", g={{"o",156,i=1,txt="Rot Blossom x8",m=1431,x=79.2,y=57.5},{"o",57,i=2,txt="Kill Skeletal Horror x15",m=1431,x=79.2,y=57.5}}},
  {t="Tavernkeep Smitts", lv=27, g={{"t",156,n2="Inside",m=1431,x=73.8,y=44.5},{"a",159,m=1431,x=73.8,y=44.5,ml=20},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Abercrombie", lv=27, n="Head west to the hermit once more.", g={{"t",159,m=1431,x=28.1,y=31.5},{"a",133,m=1431,x=28.1,y=31.5,ml=20}}},
  {t="Ghoul Ribs", lv=27, n="Every ghoul of the Raven Hill Cemetery's northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters.\nCareful: A Rotted One casts Summon Flesh Eating Worms as it dies, which brings extra adds.", g={{"o",133,i=1,txt="Ghoul Rib x7",m=1431,x=26.9,y=34.3}}},
  {t="Abercrombie", lv=27, g={{"t",133,m=1431,x=28.1,y=31.5},{"a",134,m=1431,x=28.1,y=31.5,ml=20}}},
  {t="Raven Hill Cemetery: kill these as you meet them", lv=27, n="Head south through the cemetery towards Raven Hill. Skeletal Fiends and Skeletal Horrors walk its southern half. Mor'Ladim, an elite, wanders the graves: keep away from him.", g={{"o",57,i=1,txt="Kill Skeletal Fiend x15",m=1431,x=22.6,y=40.5},{"o",57,i=2,txt="Kill Skeletal Horror x15",m=1431,x=24.6,y=41.9}}},
  {t="Jitters", lv=27, n="Jitters hides in the house at the west end of Raven Hill.", g={{"t",453,m=1431,x=18.4,y=56.4},{"a",268,m=1431,x=18.4,y=56.4,ml=20}}},
  {t="Jitters", lv=27, w={{k="onquest",q={240}}}, g={{"t",240,m=1431,x=18.4,y=56.4}}},
  {t="Sven's Camp", lv=27, g={{"t",268,m=1431,x=7.8,y=34.1},{"i",0,txt="Next: training, then the flight from Stormwind to Menethil Harbor for the Wetlands."},{"a",323,m=1431,x=7.8,y=34.1,ml=20}}},
  {t="Westfall", lv=27, w={{k="onquest",q={2360}}}, f={c={"ROGUE"}}, g={{"g",0,txt="Agent Kearnen",m=1436,x=68.5,y=70.1}}},
  {t="Agent Kearnen", lv=27, n="Head west along the road out of Raven Hill into Westfall. Agent Kearnen watches Klaven Mortwake's tower from the hills just inside the border. The Malformed Defias Drone (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top.", f={c={"ROGUE"}}, g={{"t",2360,m=1436,x=68.5,y=70.1},{"a",2359,m=1436,x=68.5,y=70.1,ml=20},{"o",2359,i=2,txt="Defias Tower Key",n2="Defias Tower Key: Malformed Defias Drone",m=1436,x=69.5,y=74},{"o",2359,i=1,txt="Klaven Mortwake's Journal",n2="Klaven Mortwake's Journal, in the chest",m=1436,x=70.4,y=73.9}}},
  {t="Master Mathias Shaw", lv=27, n="Head north through Elwynn to Stormwind; Mathias Shaw is at SI:7 in Old Town.", f={c={"ROGUE"}}, g={{"t",2359,n2="Master Mathias Shaw: Poisons, and Recipe: Thistle Tea",m=1453,x=78.3,y=70.7},{"a",2607,n2="The Touch of Zanzil: Doc Mixilpixil, in the cellar of the Barracks",m=1453,x=78.3,y=70.7,opt=true,ml=20},{"t",2607,m=1453,x=80.1,y=69.9,opt=true},{"a",2608,m=1453,x=80.1,y=69.9,opt=true,ml=20},{"c",2608,txt="Diagnosis Complete",n2="/lay down beside Doc Mixilpixil",opt=true},{"t",2608,m=1453,x=80.1,y=69.9,opt=true},{"a",2609,m=1453,x=80.1,y=69.9,opt=true,ml=20},{"h",3421,txt="Buy Simple Wildflowers (Bernard Gump)",n2="Simple Wildflowers: Bernard Gump",m=1453,x=69.2,y=71.8,n=1,opt=true},{"h",3372,txt="Buy Leaded Vial (Maria Lumere)",n2="Leaded Vial: Maria Lumere, Alchemy Supplies",m=1453,x=55.9,y=85.6,n=1,opt=true},{"h",4371,txt="Get Bronze Tube",n2="Bronze Tube: the Auction House, Trade District; Billibub Cogspinner keeps one and is nearly always sold out",m=1453,x=61.2,y=71.3,n=1,opt=true},{"o",2609,i=4,txt="Spool of Light Chartreuse Silk Thread",m=1453,x=50.6,y=60.1,opt=true},{"t",2609,n2="Doc Mixilpixil: Eau de Mixilpixil",m=1453,x=80.1,y=69.9,opt=true}}},
  {t="Elwynn Forest", lv=27, n="North from Raven Hill through Elwynn: Goldshire is on the road to Stormwind.", f={c={"WARRIOR","PALADIN","HUNTER","PRIEST","SHAMAN","MAGE","WARLOCK","DRUID"}}, g={{"g",0,txt="Goldshire",m=1429,x=43.5,y=65.3}}},
  {t="Class trainer", lv=27, f={c={"WARRIOR","PALADIN","HUNTER","PRIEST","MAGE","WARLOCK","DRUID"}}, g={{"tr",0,txt="Visit your class trainer",n2="Level 22 and 24 spells",f={c={"WARRIOR","PALADIN","HUNTER","PRIEST","MAGE","WARLOCK","DRUID"}}}}},
  {t="Gazin Tenorm", lv=27, n="On into Stormwind: Gazin Tenorm and Duthorian Rall are in the Cathedral of Light, on the way to the gryphon master.", w={{k="onquest",q={1787,1788}}}, f={c={"PALADIN"},r={"Human"}}, g={{"g",0,txt="Cathedral of Light",m=1453,x=50.5,y=47.5},{"t",1787,m=1453,x=49.5,y=45,f={r={"Human"}}},{"a",1788,m=1453,x=49.5,y=45,f={r={"Human"}},ml=12},{"t",1788,n2="Duthorian Rall: Redemption",m=1453,x=50.5,y=47.5,f={r={"Human"}}}}},
