  {t="Tram to Ironforge", lv=27, f={c={"SHAMAN"}}, g={{"g",0,txt="Tram to Ironforge",m=1453,x=69.6,y=30.2}}},
  {t="Shaman training", lv=27, n="Stormwind has no shaman trainer: take the Deeprun Tram from the Dwarven District to Ironforge, train with Eldrun Stormbreaker, then ride the tram back.", f={c={"SHAMAN"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="Rogue training", lv=27, n="Train here, in Stormwind City, before you go on.", f={c={"ROGUE"}}, g={{"tr",0,txt="Visit your class trainer"}}},
} end)

R:Segment({id="alliance/06-ashenvale",title="Ashenvale, Wetlands & Stonetalon Mountains",faction="Alliance",min=22,max=25,zone=1440,zoneName="Ashenvale",next="alliance/04-redridge-mountains"}, function() return {
  {t="Kerlonian Evershade", lv=22, n="Back north from the glaive (Druids: south along the road from Auberdine) to the Grove of the Ancients, where Kerlonian sleeps beside Arbal. Take his quest: it gives you the Horn of Awakening. Use the horn to wake him and lead him south along the road to his bag at the southern edge of Darkshore; blow it again whenever he falls asleep. Then go on to Liladris Moonriver at Maestra's Post.\nCareful: Scripted ambushes of three mobs each attack along the road.", g={{"a",5321,m=1439,x=44.4,y=76.4,ml=17},{"g",0,txt="Kerlonian Evershade",m=1439,x=44.4,y=76.4},{"i",0,txt="Escort Kerlonian south along the road to his bag at the southern edge of Darkshore, then go on to Liladris at Maestra's Post."}}},
  {t="Ashenvale", lv=22, g={{"g",0,txt="Maestra's Post",m=1440,x=26.2,y=38.7}}},
  {t="Maestra's Post", lv=22, g={{"t",967,m=1440,x=26.2,y=38.7},{"a",970,m=1440,x=26.2,y=38.7,ml=13},{"a",1010,m=1440,x=26.4,y=38.6,ml=20},{"t",5321,m=1440,x=27.3,y=35.6}}},
  {t="Bathran's Haunt: kill these as you meet them", lv=22, n="North of Maestra's Post, plant bundles lie around the ruins of Bathran's Haunt. Dark Strand cultists hold the ruins just south of them: any of them can drop the Glowing Soul Gem.", g={{"o",970,i=1,txt="Glowing Soul Gem",m=1440,x=30.4,y=31.8},{"o",1010,i=1,txt="Bathran's Hair x5",n2="Bathran's Hair, from the plant bundles",m=1440,x=30.4,y=25.5}}},
  {t="Maestra's Post", lv=22, g={{"t",1010,m=1440,x=26.4,y=38.6},{"a",1020,m=1440,x=26.4,y=38.6,ml=20},{"t",970,m=1440,x=26.2,y=38.7},{"a",973,m=1440,x=26.2,y=38.7,ml=13}}},
  {t="Astranaar", lv=22, n="The road from Maestra's Post comes in by the flight master: Shindrell Swiftfire and Sentinel Thenysil stand there, Raene Wolfrunner in the inn, Pelturas Whitemoon inside the building beyond it.", g={{"fp",28,txt="Get the Astranaar flight path (Daelyshia)",m=1440,x=34.4,y=48},{"a",1008,m=1440,x=34.7,y=48.8,ml=14},{"a",1070,m=1440,x=34.9,y=49.8,ml=17},{"b",0,txt="Set your hearthstone at Astranaar",m=1440,x=37,y=49.2,at="Astranaar"},{"a",991,n2="Raene Wolfrunner, in the inn",m=1440,x=36.6,y=49.6,ml=18},{"t",990,n2="Raene Wolfrunner: Trek to Ashenvale, from Auberdine",m=1440,x=36.6,y=49.6},{"a",1054,m=1440,x=36.6,y=49.6,ml=18},{"t",1020,n2="Pelturas Whitemoon, inside",m=1440,x=37.4,y=51.8},{"a",1033,m=1440,x=37.4,y=51.8,ml=20}}},
  {t="Teronis' Corpse", lv=22, n="Head west to the shore of Lake Falathim. Teronis lies among the Saltspittle murlocs; any murloc can drop the Glowing Gem.", g={{"t",991,m=1440,x=20.3,y=42.3},{"a",1023,m=1440,x=20.3,y=42.3,ml=18},{"o",1023,i=1,txt="Glowing Gem",m=1440,x=20.6,y=42.2}}},
  {t="Shrine of Aessina", lv=22, n="South of the murlocs, Therysil waits at the Shrine of Aessina.", g={{"t",945,m=1440,x=22.6,y=51.9}}},
  {t="Elune's Tear", lv=22, n="The tears glow on the small isle east of Astranaar.", g={{"o",1033,i=1,txt="Elune's Tear",m=1440,x=46.4,y=46.4}}},
  {t="Astranaar", lv=22, g={{"t",1023,m=1440,x=36.6,y=49.6},{"a",1024,m=1440,x=36.6,y=49.6,ml=18},{"a",1025,m=1440,x=36.6,y=49.6,ml=18},{"t",1033,n2="Pelturas Whitemoon, inside",m=1440,x=37.4,y=51.8},{"a",1034,m=1440,x=37.4,y=51.8,ml=20},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Stonetalon Mountains", lv=22, n="Head south past Mystral Lake into the Talondeep Path tunnel; it comes out in Stonetalon's Windshear Crag, north of the Windshear Mine.", g={{"g",0,txt="Windshear Crag",m=1442,x=76.5,y=45.5}}},
  {t="Piznik", lv=22, n="Piznik's defence is hard alone at this level: grouping up is encouraged, look for people to do it with. Skip it if you are alone.\nPiznik mines at the bottom of the Windshear Mine at the east end of the crag, past its kobolds (levels 19-23). Talk to him, then keep him alive for five minutes while he mines: a dozen or more kobolds come at him in waves, melee fighters first, then casters, and the mine's own kobolds respawn into the fight. If he dies, the quest fails.", w={{k="group",q=1090}}, g={{"a",1090,n2="Below ground",m=1442,x=71.9,y=60,ml=17},{"c",1090,txt="Piznik",n2="Keep Piznik alive while he mines, below ground",m=1442,x=71.9,y=60},{"t",1090,m=1442,x=71.9,y=60},{"a",1092,m=1442,x=71.9,y=60,ml=17}}},
  {t="Windshear Crag", lv=22, n="Kaela and Gaxim camp on the Webwinder Path, south-west of the mine.", g={{"t",1070,m=1442,x=59.9,y=66.8},{"a",1085,m=1442,x=59.9,y=66.8,ml=17},{"t",1085,m=1442,x=59.5,y=67.2},{"a",1071,m=1442,x=59.5,y=67.2,ml=17}}},
  {t="Ziz Fizziks: Gerenzo's Orders", lv=22, n="His hut stands just north of Kaela and Gaxim.", w={{k="group",q=1090}}, g={{"t",1092,n2="Ziz Fizziks, inside",m=1442,x=59,y=62.6}}},
  {t="Ziz Fizziks", lv=22, n="His hut stands just north of Kaela and Gaxim.", g={{"a",1093,n2="Ziz Fizziks, inside",m=1442,x=59,y=62.6,ml=16}}},
  {t="Windshear Crag: kill these as you meet them", lv=22, n="The Venture Co. clear the forest of Windshear Crag. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints.", g={{"o",1071,i=1,txt="Kill Venture Co. Logger x10",m=1442,x=61.5,y=55.3},{"o",1071,i=2,txt="Kill Venture Co. Deforester x10",m=1442,x=61.9,y=54.3},{"o",1093,i=1,txt="Super Reaper 6000 Blueprints",m=1442,x=62.5,y=53.8}}},
  {t="Webwinder Path", lv=22, g={{"t",1093,n2="Inside",m=1442,x=59,y=62.6},{"t",1071,m=1442,x=59.5,y=67.2},{"a",1072,m=1442,x=59.5,y=67.2,ml=17},{"a",1075,m=1442,x=59.5,y=67.2,ml=17}}},
  {t="The Ruins of Stardust", lv=22, n="Back north through the Talondeep Path: west of Mystral Lake, the stardust bushes grow among the ruins.", g={{"g",0,txt="The Ruins of Stardust",m=1440,x=33.3,y=67.7},{"o",1034,i=1,txt="Handful of Stardust x5",m=1440,x=33.3,y=67.7}}},
  {t="Alonso", lv=22, f={c={"WARRIOR"}}, g={{"g",0,txt="Alonso",m=1440,x=42.4,y=70},{"a",78132,n2="Alonso may not offer these to every class; if he doesn't, carry on.; walks around The Talondeep Path: the map marks where to look",m=1440,x=42.4,y=70,opt=true,ml=15},{"t",78132,m=1440,x=42.4,y=70},{"a",78133,m=1440,x=42.4,y=70,opt=true,ml=15},{"t",78133,m=1440,x=42.4,y=70},{"a",78134,m=1440,x=42.4,y=70,opt=true,ml=15},{"t",78134,m=1440,x=42.4,y=70}}},
  {t="Mystral Lake", lv=22, n="Sentinel Velene Starstrike stands at the Silverwind Refuge on the east shore of Mystral Lake; Alonso camps on its west shore. Befouled Water Elementals wade in the lake between them.", g={{"a",1016,m=1440,x=49.8,y=67.2,ml=20},{"h",12220,txt="Get Intact Elemental Bracer x5",n2="Underwater",m=1440,x=50.9,y=67.4,n=5,opt=true},{"o",1016,i=1,txt="Divined Scroll",n2="Kill the elementals for 5 Intact Elemental Bracers, then use the Divining Scroll",m=1440,x=49.6,y=71.3},{"t",1016,m=1440,x=49.8,y=67.2}}},
  {t="The Foulweald", lv=22, n="The Foulweald furbolgs live in the woods south of the road, south-east of Astranaar. The Den Watcher and the Ursas guard the den.", g={{"o",1025,i=1,txt="Kill Foulweald Den Watcher",m=1440,x=50.2,y=60.4},{"o",1025,i=2,txt="Kill Foulweald Ursa x2",m=1440,x=50.2,y=60.1},{"o",1025,i=3,txt="Kill Foulweald Totemic x10",m=1440,x=50.6,y=60.7},{"o",1025,i=4,txt="Kill Foulweald Warrior x12",m=1440,x=51.1,y=60.5}}},
  {t="Shael'dryn", lv=22, n="Follow the road east to the Howling Vale; Shael'dryn stands by the moonwell.", g={{"t",1024,m=1440,x=53.5,y=46.2}}},
  {t="Dal Bloodclaw", lv=22, n="Dal Bloodclaw (25) leads the Thistlefur furbolgs at the camp north of Astranaar. Clear his guards first, one at a time.\nCareful: The furbolgs near him usually join in when he is pulled. Killing the ones along his path first lets you fight him alone.", g={{"o",1054,i=1,txt="Dal Bloodclaw's Skull",m=1440,x=39.6,y=36.3}}},
  {t="Astranaar", lv=22, n="South from Dal Bloodclaw's camp, Astranaar is on the way west: Raene Wolfrunner in the inn, Pelturas Whitemoon inside the building beyond it.", g={{"t",1025,m=1440,x=36.6,y=49.6},{"t",1054,m=1440,x=36.6,y=49.6},{"t",1034,n2="Pelturas Whitemoon, inside",m=1440,x=37.4,y=51.8},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Ilkrud Magthrull", lv=22, n="From Astranaar head south-west to the Ruins of Ordil'Aran south of the shrine: Ilkrud and his voidwalkers hold them. Pull his guards first.", g={{"o",973,i=1,txt="Ilkrud Magthrull's Tome",m=1440,x=25.3,y=60.7}}},
  {t="The Zoram Strand", lv=22, n="Follow the coast north to the Zoram Strand. Talen camps on the beach; Wrathtail nagas fill the shore.", g={{"a",1007,m=1440,x=14.8,y=31.3,ml=19},{"o",1007,i=1,txt="Ancient Statuette",n2="Ancient Statuette, in the ruins on the shore",m=1440,x=14.2,y=20.6},{"o",1008,i=1,txt="Wrathtail Head x20",n2="Wrathtail Head: any Wrathtail naga on the strand",m=1440,x=14.1,y=20.5}}},
  {t="Talen", lv=22, g={{"t",1007,m=1440,x=14.8,y=31.3},{"a",1009,m=1440,x=14.8,y=31.3,ml=20}}},
  {t="Ruuzel", lv=22, n="Ruuzel walks the northern tip of the Zoram Strand with Wrathtail guards.", g={{"o",1009,i=1,txt="Ring of Zoram",m=1440,x=13.6,y=24.7}}},
  {t="Talen", lv=22, g={{"t",1009,m=1440,x=14.8,y=31.3}}},
  {t="Maestra's Post", lv=22, g={{"t",973,m=1440,x=26.2,y=38.7},{"a",1140,n2="Delgren the Purifier: its circles are for your next Ashenvale visit, at about 28",m=1440,x=26.2,y=38.7,ml=13}}},
  {t="Astranaar", lv=22, n="Follow the road south-east from Maestra's Post back to Astranaar: Shindrell Swiftfire stands by the flight master.", g={{"t",1008,m=1440,x=34.7,y=48.8}}},
  {t="Fly to Auberdine", lv=22, g={{"g",0,txt="Astranaar flight master",m=1440,x=34.5,y=48},{"z",0,txt="Fly to Auberdine",at="Auberdine"}}},
  {t="Boat to Menethil Harbor", lv=22, g={{"g",0,txt="Boat to Menethil Harbor",m=1439,x=32.4,y=43.8}}},
  {t="To Menethil Harbor", lv=22, g={{"fp",7,txt="Get the Menethil Harbor flight path (Shellei Brondir)",m=1437,x=9.5,y=59.7}}},
  {t="Menethil Harbor", lv=22, n="Off the boat, walk up the pier: Karl Boran on the pier, James Halloran by the docks to the north, Valstag Ironjaw in the keep, the inn (First Mate Fitzsimmons) east of it with Caitlin Grassman and Sida beside it, Tarrel Rockweaver by the north gate on the way out east.", g={{"a",279,n2="Karl Boran, on the pier north of the inn",m=1437,x=8.3,y=58.6,ml=20},{"a",484,m=1437,x=8.6,y=55.7,ml=18},{"a",98197,n2="Valstag Ironjaw, by the keep; inside",m=1437,x=10.1,y=56.9,ml=18},{"b",0,txt="Set your hearthstone at Deepwater Tavern",m=1437,x=10.7,y=61,at="Deepwater Tavern"},{"i",0,txt="Sell and repair",opt=true},{"a",463,n2="First Mate Fitzsimmons, in the inn",m=1437,x=10.9,y=59.6,ml=20},{"a",98282,m=1437,x=11.9,y=58.8,ml=20},{"a",470,m=1437,x=11.8,y=58,ml=19},{"t",98461,n2="Tarrel Rockweaver: he won't offer 305 while you carry it",m=1437,x=11.5,y=52.2,opt=true},{"a",305,n2="Tarrel Rockweaver, by the north gate",m=1437,x=11.5,y=52.2,ml=21}}},
  {t="Spoils of War", lv=22, n="Timber and iron piles lie around the keep and along the harbor's walls.", g={{"o",98197,i=1,txt="Khaz Modan Timber x6",m=1437,x=12,y=53.3},{"o",98197,i=2,txt="Khaz Modan Iron x30",m=1437,x=11.4,y=53}}},
  {t="Bluegill Marsh", lv=22, n="Follow the coast north out of Menethil. Bluegill Murlocs fill the marsh; Gobbler walks with a pack in the middle of it.", g={{"o",279,i=1,txt="Kill Bluegill Murloc x12",m=1437,x=12.7,y=42.3},{"o",279,i=2,txt="Gobbler's Head",m=1437,x=15.2,y=41.5}}},
  {t="Young crocolisks", lv=22, n="From the marsh head east across the Wetlands. Young Wetlands Crocolisks lurk in the pools north of the excavation site.", g={{"o",484,i=1,txt="Young Crocolisk Skin x6",m=1437,x=15.8,y=46.4}}},
  {t="Whelgar's Excavation Site", lv=22, n="The excavation site sits on the hill south of the road.", g={{"t",305,n2="Merrin Rockweaver, below ground",m=1437,x=38.9,y=52.3},{"a",306,m=1437,x=38.9,y=52.3,ml=21},{"a",294,m=1437,x=38.2,y=50.9,ml=22}}},
  {t="The raptor hills", lv=22, n="Mottled Raptors and Screechers roam the hills west of the excavation site.\nCareful: Once a Mottled Screecher drops to 30% health, it calls for help from creatures within 20 yd. Mottled Screechers frequently come in packs of three, and raptors summoned by their calls for help may also join the fight.", g={{"o",294,i=2,txt="Kill Mottled Screecher x10",m=1437,x=30.2,y=44.1},{"o",294,i=1,txt="Kill Mottled Raptor x10",m=1437,x=29.5,y=42.4}}},
  {t="Ormer Ironbraid", lv=22, g={{"t",294,m=1437,x=38.2,y=50.9},{"a",295,n2="Ormer Ironbraid: the bigger raptors in the valley west of the dig are for your next Wetlands visit, at about 27",m=1437,x=38.2,y=50.9,ml=22}}},
  {t="The Green Belt", lv=22, n="Einar Stonegrip camps by the road; Rethiel the Greenwarden stands farther east, by the river.", g={{"t",463,m=1437,x=56.4,y=40.4},{"a",276,m=1437,x=56.4,y=40.4,ml=20}}},
  {t="Thelgen Rock", lv=22, n="Cave Stalkers and Leech Stalkers fill Thelgen Rock, the cave south-east of the excavation site.", g={{"o",98282,i=1,txt="Unruptured Stalker Gland",m=1437,x=56.2,y=60.9}}},
  {t="The Mosshide gnolls", lv=22, n="Mosshide Gnolls and Mongrels hold the hills south-east of the Green Belt.", g={{"o",276,i=1,txt="Kill Mosshide Gnoll x15",m=1437,x=60.5,y=63.7},{"o",276,i=2,txt="Kill Mosshide Mongrel x10",m=1437,x=60.7,y=64.3}}},
  {t="Rethiel the Greenwarden", lv=22, g={{"t",276,m=1437,x=56.4,y=40.4},{"a",277,n2="Its flint comes from the Mosshide Fenrunners on the way to Ironbeard's Tomb; Rethiel takes it on your next Wetlands visit",m=1437,x=56.4,y=40.4,ml=20}}},
  {t="Ironbeard's Tomb", lv=22, n="North-west from Rethiel: Mosshide Fenrunners and Mistweavers roam the riverbanks on the way, and almost every one drops flint. Black, Crimson and Monstrous Oozes fill Ironbeard's Tomb, just west of the road to Dun Modr and north of Einar's camp. Any ooze there may hold Sida's bag.", g={{"o",277,i=1,txt="Crude Flint x9",n2="Crude Flint: Mosshide Fenrunners and Mistweavers",m=1437,x=51.2,y=30.8},{"o",470,i=1,txt="Sida's Bag",m=1437,x=44.6,y=25.6}}},
  {t="Menethil", lv=22, n="Hearth back to Menethil Harbor if you bound at the Deepwater Tavern, or walk west along the road into Menethil: Tarrel Rockweaver by the road in at the north gate, Sida and Caitlin Grassman at the inn, Valstag Ironjaw in the keep, James Halloran on the west side by the docks, Karl Boran on the pier north of the inn.", g={{"t",306,m=1437,x=11.5,y=52.2},{"t",470,m=1437,x=11.8,y=58},{"t",98282,n2="Caitlin Grassman, inside",m=1437,x=11.9,y=58.8},{"t",98197,n2="Valstag Ironjaw, in the keep",m=1437,x=10.1,y=56.9},{"t",484,m=1437,x=8.6,y=55.7},{"t",279,n2="Karl Boran, on the pier",m=1437,x=8.3,y=58.6},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Fly to Ironforge", lv=22, n="Shellei Brondir is the flight master by Menethil's inn: you have both flight paths since your first trip east.", g={{"g",0,txt="Menethil Harbor flight master",m=1437,x=9.5,y=59.7},{"z",0,txt="Fly to Ironforge",at="Ironforge"}}},
  {t="Ironforge", lv=22, n="The gryphons land in the Great Forge. Lomac Gearstrip stands in Tinker Town, east of it, by the Deeprun Tram.", g={{"t",1072,n2="Lomac Gearstrip, Tinker Town",m=1455,x=72.1,y=51.9},{"h",4371,txt="Buy Bronze Tube (Gearcutter Cogspinner)",n2="Bronze Tube, for Look to the Stars in Darkshire: Gearcutter Cogspinner, beside Lomac, sometimes has one",m=1455,x=67.8,y=42.5,n=1,opt=true},{"t",968,n2="Only with Book: The Powers Below from Darkshore: Gerrig Bonegrip, the Forlorn Cavern",m=1455,x=50.8,y=5.6,opt=true},{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Buliwyf Stonehand", lv=22, n="While you're here: learn Two-Handed Axes from Buliwyf Stonehand (Military Ward, 10 silver); two-handers level a Warrior fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Axes",skillLine=172}}, f={c={"WARRIOR"}}, g={{"tr",0,txt="Train with Buliwyf Stonehand",m=1455,x=61.2,y=89.5}}},
  {t="Buliwyf Stonehand", lv=22, n="While you're here: learn Two-Handed Maces from Buliwyf Stonehand (Military Ward, 10 silver); two-handers level a Warrior fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Maces",skillLine=160}}, f={c={"WARRIOR"}}, g={{"tr",0,txt="Train with Buliwyf Stonehand",m=1455,x=61.2,y=89.5}}},
  {t="Buliwyf Stonehand", lv=22, n="While you're here: learn Two-Handed Axes from Buliwyf Stonehand (Military Ward, 10 silver); two-handers level a Paladin fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Axes",skillLine=172}}, f={c={"PALADIN"}}, g={{"tr",0,txt="Train with Buliwyf Stonehand",m=1455,x=61.2,y=89.5}}},
  {t="Tram to Stormwind", lv=22, g={{"g",0,txt="Tram to Stormwind",m=1455,x=78,y=51.4}}},
  {t="Baros Alexston", lv=22, n="The tram comes in at the Dwarven District; walk west to the Cathedral Square: Baros Alexston stands at its east side. (The route hands his letter in at the end of 03-loch-modan; this is for a character still carrying it.)", w={{k="onquest",q={97914}}}, g={{"t",97914,n2="Baros Alexston: Thundris' letter from Auberdine",m=1453,x=57.7,y=47.9},{"a",97926,n2="For Thundris Windweaver, back in Auberdine (06-wetlands)",m=1453,x=57.7,y=47.9,opt=true,ml=13}}},
  {t="Cathedral Square", lv=22, n="The tram comes in at the Dwarven District; walk west to the Cathedral Square. High Priestess Laurena is in the Cathedral of Light.", g={{"t",5676,n2="Arcane Feedback",m=1453,x=49.5,y=44.6,f={c={"PRIEST"},r={"Human"}}},{"a",5645,n2="High Priestess Laurena: High Priest Rohan in Ironforge takes it, later",m=1453,x=49.5,y=44.6,f={c={"PRIEST"},r={"Dwarf"}},ml=20},{"a",94819,n2="High Priestess Laurena: High Priestess Mims in Ironforge takes it, later",m=1453,x=49.5,y=44.6,f={c={"PRIEST"},r={"Gnome"}},ml=20},{"a",5673,n2="High Priestess Laurena: Priestess Alathea in Darnassus takes it, later",m=1453,x=49.5,y=44.6,f={c={"PRIEST"},r={"NightElf"}},ml=20}}},
  {t="Master Mathias Shaw", lv=22, n="Mathias Shaw is at SI:7 in Old Town, south of the Keep.", f={c={"ROGUE"}}, g={{"l",20,txt="Reach level 20"},{"a",2360,n2="Master Mathias Shaw: Agent Kearnen in Westfall takes it, at the end of Duskwood's second loop",m=1453,x=78.3,y=70.7,ml=20}}},
  {t="Collin Mauren", lv=22, n="The Slaughtered Lamb is in the Mage Quarter. Warlocks: Gakin the Darkbinder is in its cellar.", g={{"a",1078,m=1453,x=53,y=86.6,ml=17},{"t",1075,m=1453,x=53,y=86.6},{"l",20,txt="Reach level 20",f={c={"WARLOCK"}}},{"a",1716,n2="Gakin the Darkbinder: Takar the Seer in the Barrens takes it, later",m=1453,x=39.2,y=85.2,f={c={"WARLOCK"}},ml=20}}},
  {t="Trade District", lv=22, g={{"i",0,txt="Next: training in Stormwind, then the road east through Elwynn and south to Duskwood."}}},
} end)

