  {t="Moonglade", lv=27, w={{k="onquest",q={272}}}, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"g",0,txt="Cast Teleport: Moonglade",m=1450,x=56.3,y=32.5}}},
  {t="Trial of the Sea Lion", lv=27, n="Cast Teleport: Moonglade. With both half pendants in your bags, stand by the Shrine of Remulos on the north-west shore of the lake and use a half to join them, then go to Dendrite Starblaze in Nighthaven. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", w={{k="onquest",q={272}}}, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"o",272,i=1,txt="Pendant of the Sea Lion",n2="Pendant of the Sea Lion: join the halves at the Shrine of Remulos",m=1450,x=36,y=41.4},{"t",272,m=1450,x=56.2,y=30.6}}},
  {t="Aquatic Form", lv=27, n="Take Aquatic Form from Dendrite Starblaze, upstairs in his building. Then Silva Fil'naveth in Nighthaven flies Druids straight to Rut'theran Village.", w={{k="turnedin",q=272},{k="turnedin",neg=true,q=5061}}, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"a",5061,m=1450,x=56.2,y=30.6,ml=16},{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village"}}},
  {t="Darnassus", lv=27, w={{k="onquest",q={5061}}}, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"g",0,txt="Mathrengyl Bearwalker",m=1457,x=35.8,y=11.6}}},
  {t="Mathrengyl Bearwalker", lv=27, n="Take the portal up to the Cenarion Enclave, then fly back to Auberdine for the boat to Menethil Harbor.", w={{k="onquest",q={5061}}}, f={c={"DRUID"},r={"NightElf","Skyborne"}}, g={{"t",5061,n2="Mathrengyl Bearwalker: Aquatic Form",m=1457,x=35.4,y=8.4},{"z",0,txt="Fly to Auberdine",at="Auberdine"}}},
  {t="Boat to Auberdine", lv=27, w={{k="onquest",q={5673}}}, f={c={"PRIEST"},r={"NightElf"}}, g={{"g",0,txt="Boat to Auberdine",m=1453,x=21.8,y=56.9}}},
  {t="Fly to Rut'theran Village", lv=27, w={{k="onquest",q={5673}}}, f={c={"PRIEST"},r={"NightElf"}}, g={{"g",0,txt="Auberdine flight master",m=1439,x=36.4,y=45.6},{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village"}}},
  {t="Into Darnassus", lv=27, w={{k="onquest",q={5673}}}, f={c={"PRIEST"},r={"NightElf"}}, g={{"g",0,txt="Into Darnassus",m=1457,x=85.7,y=35.9}}},
  {t="Darnassus", lv=27, w={{k="onquest",q={5673}}}, f={c={"PRIEST"},r={"NightElf"}}, g={{"g",0,txt="Priestess Alathea",m=1457,x=39.5,y=81.2}}},
  {t="Elune's Grace", lv=27, w={{k="onquest",q={5673}}}, f={c={"PRIEST"},r={"NightElf"}}, g={{"t",5673,n2="Priestess Alathea: Elune's Grace",m=1457,x=39.5,y=81.2,f={r={"NightElf"}}},{"z",0,txt="Fly to Auberdine",at="Auberdine"}}},
  {t="Boat to Menethil Harbor", lv=27, n="Take the boat from Auberdine's dock to Menethil Harbor.", w={{k="zone",name="Darkshore",area=148}}, f={c={"PRIEST","DRUID"},r={"NightElf","Skyborne"}}, g={{"g",0,txt="Boat to Menethil Harbor",m=1439,x=32.4,y=43.8}}},
