  {t="Menethil Harbor", lv=27, g={{"a",288,n2="First Mate Fitzsimmons, in the inn",m=1437,x=10.9,y=59.6,ml=22},{"b",0,txt="Set your hearthstone at Deepwater Tavern",m=1437,x=10.7,y=61,at="Deepwater Tavern"},{"h",2594,txt="Buy Flagon of Dwarven Honeymead (Innkeeper Helbrek)",n2="Flagon of Dwarven Honeymead, from Innkeeper Helbrek",m=1437,x=10.7,y=61,n=1},{"t",288,m=1437,x=10.9,y=59.6},{"a",289,m=1437,x=10.9,y=59.6,ml=22},{"a",464,n2="Captain Stoutfist, by the keep; on the top floor",m=1437,x=9.9,y=57.5,ml=23},{"a",98221,n2="Captain Stoutfist: From the Ashes, the Attack Plans in the Angerfang Encampment",m=1437,x=9.9,y=57.5,ml=23},{"a",281,n2="Karl Boran, on the pier north of the inn",m=1437,x=8.3,y=58.6,ml=20},{"a",471,n2="James Halloran, by the docks",m=1437,x=8.6,y=55.7,ml=18},{"a",98208,n2="Sylessa Duskwhisper, beside James Halloran by the docks",m=1437,x=7.9,y=55.8,ml=22},{"a",472,n2="Harlo Barnaby, by the north gate: Longbraid the Grim takes it on 30-40/01-hillsbrad-foothills' Dun Modr stop",m=1437,x=10.8,y=55.9,ml=25}}},
  {t="Nord'el", lv=27, n="Nord'el lies on the shore just south of Menethil Harbor, a short walk past the town's south end. Then follow the coast north out of town to the hovels.", g={{"o",98208,i=1,txt="Nord'el",m=1437,x=12.2,y=63.8}}},
  {t="The Bluegill hovels", lv=27, n="Follow the coast north out of Menethil into Bluegill Marsh. Three containers in the murloc hovels, south to north: the Damaged Crate, then the Sealed Barrel, then the Half-buried Barrel at the north end.", g={{"t",281,m=1437,x=13.5,y=41.4},{"a",284,m=1437,x=13.5,y=41.4,ml=20},{"t",284,m=1437,x=13.6,y=38.2},{"a",285,m=1437,x=13.6,y=38.2,ml=20},{"t",285,m=1437,x=13.9,y=34.8},{"a",286,m=1437,x=13.9,y=34.8,ml=20}}},
  {t="The Lost Fleet: kill these as you meet them", lv=27, n="Follow the coast north to the wrecked ship. Cursed Sailors walk the beach, Cursed Marines the deck; First Mate Snellig stands on the beach by the bow. Giant Wetlands Crocolisks lurk on the coast just north of it.\nCareful: Fen Creepers hide in stealth where the river splits close to the ghost ship, and they can join a fight.", g={{"o",289,i=2,txt="Kill Cursed Marine x5",m=1437,x=13.5,y=30.9},{"o",289,i=1,txt="Kill Cursed Sailor x13",m=1437,x=13.8,y=30.8},{"o",289,i=3,txt="Snellig's Snuffbox",n2="Snellig's Snuffbox: First Mate Snellig",m=1437,x=13.8,y=30.2},{"o",471,i=1,txt="Giant Crocolisk Skin x6",m=1437,x=15.2,y=29.2}}},
  {t="Menethil Harbor", lv=27, n="In from the north: James Halloran by the docks, Karl Boran on the pier, Captain Stoutfist in the keep, then First Mate Fitzsimmons in the inn.", g={{"t",471,m=1437,x=8.6,y=55.7},{"a",98072,m=1437,x=8.6,y=55.7,ml=19},{"t",98208,n2="Sylessa Duskwhisper, beside him",m=1437,x=7.9,y=55.8},{"a",98209,n2="For Thundris Windweaver in Auberdine, on this guide's boat trip: keep it",m=1437,x=7.9,y=55.8,ml=22},{"t",286,m=1437,x=8.3,y=58.6},{"a",98189,n2="Karl Boran: for Captain Stoutfist in the keep",m=1437,x=8.3,y=58.6,ml=20},{"t",98189,n2="Captain Stoutfist, on the top floor",m=1437,x=9.9,y=57.5},{"a",98190,n2="For Bolvar Fordragon in Stormwind Keep: keep it",m=1437,x=9.9,y=57.5,ml=20},{"t",289,n2="First Mate Fitzsimmons, in the inn",m=1437,x=10.9,y=59.6},{"a",290,m=1437,x=10.9,y=59.6,ml=22},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Captain Halyndor", lv=27, n="The captain walks the deck of the wrecked ship; his strongbox sits in the hold.", g={{"o",290,i=1,txt="Intrepid Strongbox Key",m=1437,x=15.4,y=23.6},{"t",290,m=1437,x=14.4,y=24},{"a",292,m=1437,x=14.4,y=24,ml=22}}},
  {t="Raptor valley", lv=27, n="Follow the road east: the bigger raptors for Ormer's Revenge hunt in the valley just west of the excavation site.", g={{"o",295,i=1,txt="Kill Mottled Scytheclaw x10",m=1437,x=30.6,y=48.7},{"o",295,i=2,txt="Kill Mottled Razormaw x10",m=1437,x=32.2,y=48.7}}},
  {t="Whelgar's Excavation Site", lv=27, n="The excavation site sits on the hill south of the road: Ormer Ironbraid at the top, Prospector Whelgar below ground.", g={{"t",295,m=1437,x=38.2,y=50.9},{"a",296,m=1437,x=38.2,y=50.9,ml=22},{"a",299,m=1437,x=38.8,y=52.4,ml=22}}},
  {t="Whelgar's Excavation Site: kill these as you meet them", lv=27, n="The relics lie in the dig itself. Sarltooth, a big Razormaw, prowls the raptor valley just west of it.\nGoaz Warders (elite, 32) stand among the relics and the Loose Soil: pull them away one at a time, or work around them.", g={{"o",299,i=1,txt="Ados Fragment",m=1437,x=36.1,y=50},{"o",299,i=2,txt="Modr Fragment",m=1437,x=36.1,y=50},{"o",299,i=3,txt="Golm Fragment",m=1437,x=36.1,y=50},{"o",299,i=4,txt="Neru Fragment",n2="Neru Fragment: the Loose Soil",m=1437,x=36.1,y=50},{"o",296,i=1,txt="Sarltooth's Talon",m=1437,x=33.3,y=51.5}}},
  {t="Ormer and Whelgar", lv=27, g={{"t",296,m=1437,x=38.2,y=50.9},{"t",299,m=1437,x=38.8,y=52.4},{"a",98216,n2="Prospector Whelgar, below ground: the Titanic Keystone, from the elite Goaz Warders",m=1437,x=38.8,y=52.4,opt=true,ml=23}}},
  {t="Goaz Warders", lv=27, n="The Goaz Warders stand just west of Whelgar's camp: use the Goaz Stone he gave you beside one.\nGoaz Warder is elite: grouping up is advised.", w={{k="group",q=98216},{k="onquest",q={98216}}}, g={{"o",98216,i=1,txt="Titanic Keystone",m=1437,x=36.6,y=52.3,grp=true}}},
  {t="Prospector Whelgar", lv=27, w={{k="group",q=98216},{k="complete",q=98216}}, g={{"t",98216,n2="Below ground",m=1437,x=38.8,y=52.4}}},
  {t="Prospector Whelgar", lv=27, w={{k="group",q=98310},{k="turnedin",q=98216}}, g={{"a",98310,n2="A new Goaz Stone, for the four titan watchers around the Wetlands; below ground. Their hearts drop from level 32 elites on the Dun Modr visit",m=1437,x=38.8,y=52.4,ml=24}}},
  {t="Angerfang Encampment", lv=27, n="North from the dig into the Dragonmaw camp: click the four sets of Attack Plans. The Ironforge plan lies at the camp's west end, the other three further east. Chieftain Nek'rosh, an elite, stands apart to the south-east: From the Ashes doesn't need him.", g={{"o",98221,i=4,txt="Attack Plan: Ironforge",m=1437,x=38.5,y=46.1},{"o",98221,i=1,txt="Attack Plan: Menethil Harbor",m=1437,x=45.6,y=42.7},{"o",98221,i=3,txt="Attack Plan: Southshore",m=1437,x=45.4,y=45.7},{"o",98221,i=2,txt="Attack Plan: Thelsamar",m=1437,x=49.4,y=46.8},{"o",464,i=1,txt="Dragonmaw War Banner x8",n2="Dragonmaw War Banner: the camp's Raiders and Swamprunners",m=1437,x=45.5,y=44.7}}},
  {t="Rethiel the Greenwarden", lv=27, n="Follow the road east to the Green Belt; Rethiel the Greenwarden stands by the river. Fire Taboo's flint came with you from your last Wetlands visit.", g={{"t",277,m=1437,x=56.4,y=40.4},{"a",275,m=1437,x=56.4,y=40.4,ml=20}}},
  {t="Howin Kindfeather", lv=27, n="Howin Kindfeather camps among the Fenrunners, just west of Rethiel.", g={{"a",98245,n2="Razormaw Incisors: from the raptors by the Dragonmaw Gates, on the Wetlands loop of 30-40/01-hillsbrad-foothills",m=1437,x=49.4,y=42.1,ml=21},{"a",98246,n2="Trying Times: the Razormaw eggs, on the same loop",m=1437,x=49.4,y=42.1,ml=21}}},
  {t="Einar Stonegrip", lv=27, n="East from Howin: Einar Stonegrip stands beside the road.", g={{"a",469,n2="Einar Stonegrip: for James Halloran in Menethil",m=1437,x=49.9,y=39.4,ml=18}}},
  {t="Fen Creepers along the river", lv=27, n="North-west from Einar to the river: Fen Creepers hide in its pools and along its banks all the way west to Sundown Marsh. Work west along it until you have twelve, then back east to Rethiel.\nCareful: When out of combat, Fen Creepers cast Sneak from time to time, so they are stealthed and hard to see.", g={{"o",275,i=1,txt="Kill Fen Creeper x12",m=1437,x=47.6,y=32.8}}},
  {t="Rethiel the Greenwarden", lv=27, g={{"t",275,m=1437,x=56.4,y=40.4},{"a",98283,n2="Carnage, an elite raptor, on the Wetlands loop of 30-40/01-hillsbrad-foothills",m=1437,x=56.4,y=40.4,opt=true,ml=22}}},
  {t="Captain Stoutfist", lv=27, n="Hearth back to Menethil Harbor if you bound at the Deepwater Tavern, or walk west along the road: Captain Stoutfist stands on the top floor of Menethil Keep, Glorin Steelbrow in the Deepwater Tavern south of it, James Halloran by the docks on the way to the boat.", g={{"t",464,n2="On the top floor",m=1437,x=9.9,y=57.5},{"t",98221,m=1437,x=9.9,y=57.5},{"a",465,n2="For the Dragonmaw catapult, on the Wetlands loop of 30-40/01-hillsbrad-foothills",m=1437,x=9.9,y=57.5,ml=23},{"t",292,n2="Glorin Steelbrow, in the Deepwater Tavern",m=1437,x=10.6,y=60.6},{"a",293,n2="For Archbishop Benedictus in Stormwind, at the end of this guide",m=1437,x=10.6,y=60.6,ml=22},{"t",469,n2="James Halloran, by the docks, on the way to the boat",m=1437,x=8.6,y=55.7}}},
  {t="Boat to Auberdine", lv=27, n="The boat to Auberdine leaves from the far end of Menethil's western pier.", g={{"g",0,txt="Boat to Auberdine",m=1437,x=4.5,y=56.7}}},
  {t="Thundris Windweaver", lv=27, n="Thundris Windweaver stands at the north end of Auberdine, up the road from the dock.", w={{k="onquest",q={98209}}}, g={{"t",98209,n2="Nord'el, from Sylessa in Menethil Harbor",m=1439,x=37.4,y=40.1}}},
  {t="Thundris Windweaver", lv=27, n="Thundris Windweaver stands at the north end of Auberdine.", w={{k="onquest",q={97926}}}, g={{"t",97926,n2="Alexston's reply, if you still carry it (the route hands it in on 03-darkshore-return's first Auberdine stop)",m=1439,x=37.4,y=40.1}}},
  {t="Auberdine", lv=27, n="Terenthis stands by the flight master.", g={{"t",994,n2="Terenthis: Volcor's escort from the end of Darkshore",m=1439,x=39.4,y=43.5}}},
  {t="Fly to Astranaar", lv=27, g={{"g",0,txt="Auberdine flight master",m=1439,x=36.4,y=45.6},{"z",0,txt="Fly to Astranaar",at="Astranaar"}}},
  {t="Shindrell Swiftfire", lv=27, n="Shindrell Swiftfire stands by Astranaar's flight master.", g={{"a",4581,n2="For Kayneth Stillwind at Forest Song",m=1440,x=34.7,y=48.8,ml=24}}},
  {t="Astranaar", lv=27, g={{"b",0,txt="Set your hearthstone at Astranaar",m=1440,x=37,y=49.2,at="Astranaar"},{"a",1035,n2="Pelturas Whitemoon, inside",m=1440,x=37.4,y=51.8,ml=20}}},
  {t="Melyria and Illiyana", lv=27, n="The two stand together at the western end of the road, south-west of Astranaar.", g={{"a",1021,m=1440,x=21.7,y=53.3,ml=26},{"a",1022,m=1440,x=22.2,y=53,ml=25}}},
  {t="Shael'dryn", lv=27, n="Follow the road east to the Howling Vale; Shael'dryn stands by the moonwell.", g={{"a",1026,m=1440,x=53.5,y=46.2,ml=18}}},
  {t="Dartol's Rod", lv=27, n="The Crazed and Withered Ancients north of the moonwell carry the Wooden Key; the worn chest it opens stands among them.", g={{"h",5475,txt="Get Wooden Key",m=1440,x=57.7,y=41.8,n=1},{"o",1026,i=1,txt="Iron Shaft",m=1440,x=54.4,y=35.4}}},
  {t="Shael'dryn", lv=27, g={{"t",1026,m=1440,x=53.5,y=46.2},{"a",1027,m=1440,x=53.5,y=46.2,ml=18}}},
  {t="Anilia", lv=27, n="Follow the road east to the satyr camps of Xavian; Anilia hides at their edge.", g={{"t",1021,m=1440,x=78.3,y=44.8},{"a",1031,m=1440,x=78.3,y=44.8,ml=26}}},
  {t="Geltharis", lv=27, n="Geltharis leads the Xavian satyrs; he carries the branch.", g={{"o",1031,i=1,txt="Branch of Cenarius",m=1440,x=78,y=42.4}}},
  {t="Forest Song", lv=27, n="Forest Song, the Night Elf outpost at the eastern end of the road: Kayneth Stillwind stands there, Maseara Autumnmoon a few steps east of her.", g={{"t",4581,m=1440,x=85.2,y=44.7},{"a",1011,m=1440,x=85.2,y=44.7,ml=24},{"a",98417,n2="Maseara Autumnmoon: her husband's trail in Satyrnaar, on the way back from the lake",m=1440,x=86.2,y=45.9,ml=23}}},
  {t="The Dor'Danil Barrow Den: kill these as you meet them", lv=27, n="The Forsaken's camp lies in the woods south of Forest Song.\nRusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel.\nCareful: Non-elite Forsaken of about level 28-30 guard the camp. Some of them are stealthed, and the ones around the table often aggro together.", g={{"o",1027,i=1,txt="Iron Pommel",m=1440,x=78.3,y=64.6},{"o",1011,i=1,txt="Bottle of Disease",m=1440,x=75.3,y=71.8}}},
  {t="Fallen Sky Lake", lv=27, n="The Shadethicket Oracle walks the shore of Fallen Sky Lake, south-west of the chests; the Gleaming Crescent Pendant lies north of the lake, on the way.\nCareful: Other mobs, some of them underwater, sit near the island. Clear them first so they don't join the fight when you pull the Oracle.", g={{"o",1035,i=1,txt="Fallen Moonstone",m=1440,x=66.7,y=82.2},{"a",98027,n2="Gleaming Crescent Pendant: for Maliynn in Astranaar",m=1440,x=63,y=71.5,ml=22}}},
  {t="Satyrnaar", lv=27, n="North from the lake to the satyr camp of Satyrnaar, just west of Forest Song: the Circle of Imprisonment stands in it, and Kurothel's Knapsack lies beside it with the Vine-Wrapped Scroll.\nCareful: The Felmusk Rogues in Night Run often go stealthed, and Satyrnaar has satyr casters.", g={{"o",1140,i=2,txt="Circle of Imprisonment",m=1440,x=81.6,y=48.6},{"o",98417,i=1,txt="Vine-Wrapped Scroll",n2="Vine-Wrapped Scroll, from Kurothel's Knapsack",m=1440,x=81.7,y=49.2}}},
  {t="Kayneth Stillwind", lv=27, n="Optional: Kayneth also offers Insane Druids, three level 32 druids deep in The Dor'Danil Barrow Den, a cave of quickly respawning, stealthed mobs, and back to her afterwards. It is above your level here: take it only if you are grouped or want the extra XP; the guide doesn't need it.", g={{"t",1011,m=1440,x=85.2,y=44.7},{"a",1012,m=1440,x=85.2,y=44.7,opt=true,ml=24},{"t",98417,n2="Maseara Autumnmoon, a few steps east",m=1440,x=86.2,y=45.9}}},
  {t="The Dor'Danil Barrow Den's entrance", lv=27, w={{k="onquest",q={1012}}}, g={{"g",0,txt="The Dor'Danil Barrow Den",m=1440,x=76,y=75.5}}},
  {t="Insane druids", lv=27, n="The three druids are inside The Dor'Danil Barrow Den, apart from each other: go in at its mouth, south of the Forsaken camp, not over the hill above them. Taneel Darkwood is in the eastern halls, Uthil Mooncall deepest down at the north-east end and Mavoris Cloudsbreak at the western end.\nCareful: The den has many mobs that respawn quickly, including stealthed undead and patrols, so extra mobs often join a fight.", w={{k="onquest",q={1012}}}, g={{"o",1012,i=1,txt="Kill Taneel Darkwood",n2="Taneel Darkwood, inside The Dor'Danil Barrow Den",m=1440,x=77.2,y=74},{"o",1012,i=2,txt="Kill Uthil Mooncall",n2="Uthil Mooncall, inside The Dor'Danil Barrow Den",m=1440,x=78,y=72.7},{"o",1012,i=3,txt="Kill Mavoris Cloudsbreak",n2="Mavoris Cloudsbreak, inside The Dor'Danil Barrow Den",m=1440,x=75,y=74.2}}},
  {t="Forest Song", lv=27, w={{k="onquest",q={1012}}}, g={{"t",1012,m=1440,x=85.2,y=44.7}}},
  {t="Night Run", lv=27, n="The second Circle of Imprisonment lies in the valley of Night Run, on the way west.", g={{"o",1140,i=1,txt="Circle of Imprisonment",m=1440,x=66.6,y=57}}},
  {t="Shael'dryn", lv=27, g={{"t",1027,m=1440,x=53.5,y=46.2},{"a",1028,m=1440,x=53.5,y=46.2,ml=18}}},
  {t="Hidden Shrine", lv=27, n="The shrine sits on the hill just south-east of the moonwell; follow the winding path up.", g={{"t",1028,m=1440,x=56.4,y=49.2},{"a",1055,m=1440,x=56.4,y=49.2,ml=18}}},
  {t="Shael'dryn", lv=27, g={{"t",1055,m=1440,x=53.5,y=46.2},{"a",1029,m=1440,x=53.5,y=46.2,ml=18}}},
  {t="The Howling Vale", lv=27, n="Take the tunnel into the Howling Vale; the tome lies in the ruins at its west end. Careful: Terrowulf Fleshrippers and Shadow Weavers (28-30) stand in tight packs around the tome, and the Terrowulf Packlord, a level 32 rare, walks the vale. Pull the wolves one at a time from the tunnel and let the Packlord pass first.", g={{"o",1022,i=1,txt="Tome of Mel'Thandris",m=1440,x=50.5,y=39.1}}},
  {t="Astranaar", lv=27, n="Raene Wolfrunner and Maliynn are in the inn; Pelturas Whitemoon is inside the building just south of it.", g={{"t",1029,m=1440,x=36.6,y=49.6},{"a",1030,m=1440,x=36.6,y=49.6,ml=18},{"t",98027,n2="Maliynn, in the inn",m=1440,x=36.6,y=50},{"t",1035,n2="Pelturas Whitemoon, inside the building south of the inn",m=1440,x=37.4,y=51.8}}},
  {t="Krolg", lv=27, n="Krolg, a furbolg untouched by the corruption, sits south of the road below Mystral Lake. Use Dartol's Rod of Transformation near him first: he only speaks to you in furbolg form.", g={{"t",1030,m=1440,x=50.8,y=75.1},{"a",1045,m=1440,x=50.8,y=75.1,ml=18}}},
  {t="Ran Bloodtooth", lv=27, n="Ran Bloodtooth and his guards camp just east of Krolg.\nCareful: Wolves and spiders roam near the camp and can join a fight. Some of the wolves come in pairs.", g={{"o",1045,i=1,txt="Kill Bloodtooth Guard x4",m=1440,x=54.9,y=76},{"o",1045,i=2,txt="Ran Bloodtooth's Skull",n2="Ran Bloodtooth's Skull, from Ran Bloodtooth",m=1440,x=54.8,y=79.6}}},
  {t="Krolg", lv=27, g={{"t",1045,m=1440,x=50.8,y=75.1},{"a",1046,m=1440,x=50.8,y=75.1,ml=18},{"c",1046,txt="Dartol's Rod of Transformation"}}},
  {t="Melyria and Illiyana", lv=27, n="West from Krolg along the southern hills to the Shrine of Aessina: Melyria and Illiyana stand together by it.", g={{"t",1022,m=1440,x=22.2,y=53},{"a",1037,m=1440,x=22.2,y=53,ml=25},{"t",1031,m=1440,x=21.7,y=53.3}}},
  {t="Delgren the Purifier", lv=27, n="North to Maestra's Post.", g={{"t",1140,m=1440,x=26.2,y=38.7}}},
  {t="Astranaar", lv=27, n="South-east along the road to Astranaar: Raene Wolfrunner in the inn, the flight master at the west end.", g={{"t",1046,m=1440,x=36.6,y=49.6}}},
  {t="Fly to Auberdine", lv=27, g={{"g",0,txt="Astranaar flight master",m=1440,x=34.5,y=48},{"z",0,txt="Fly to Auberdine",at="Auberdine"}}},
  {t="Boat to Menethil Harbor", lv=27, g={{"g",0,txt="Boat to Menethil Harbor",m=1439,x=32.4,y=43.8}}},
  {t="Fly to Ironforge", lv=27, n="Shellei Brondir is the flight master by Menethil's inn.", g={{"g",0,txt="Menethil Harbor flight master",m=1437,x=9.5,y=59.7},{"z",0,txt="Fly to Ironforge",at="Ironforge"}}},
  {t="Ironforge", lv=28, g={{"a",1179,m=1455,x=72.7,y=94,ml=28},{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Ironforge priests", lv=28, n="High Priest Rohan and High Priestess Mims are in the Hall of Mysteries, in the Mystic Ward.", f={c={"PRIEST"},r={"Dwarf","Gnome"}}, g={{"t",5645,n2="High Priest Rohan: Chastise",m=1455,x=24.7,y=8.2,f={r={"Dwarf"}}},{"t",94819,n2="High Priestess Mims: Contingency Plan",m=1455,x=24.6,y=10,f={r={"Gnome"}}}}},
  {t="Tram to Stormwind", lv=28, g={{"g",0,txt="Tram to Stormwind",m=1455,x=78,y=51.4}}},
  {t="Cathedral of Light", lv=28, n="Take the Deeprun Tram from Tinker Town to Stormwind's Dwarven District, then walk to the Cathedral Square.", g={{"a",1274,n2="Thomas, in the Cathedral of Light",m=1453,x=49.6,y=44.5,ml=28},{"t",293,m=1453,x=50.3,y=45.5}}},
  {t="Stormwind Keep", lv=28, g={{"t",1274,m=1453,x=80.2,y=44.1},{"a",1241,m=1453,x=80.2,y=44.1,ml=28},{"t",98190,m=1453,x=80.2,y=38.4},{"a",98191,m=1453,x=80.2,y=38.4,ml=20},{"t",337,n2="Only if you looted An Old History Book in Duskwood",m=1453,x=77.1,y=30.2,opt=true}}},
  {t="Lord Grayson Shadowbreaker", lv=28, n="Back to the Cathedral of Light: Lord Grayson Shadowbreaker stands inside.", g={{"t",98191,m=1453,x=48.4,y=50.2},{"a",98219,n2="For Lieutenant Farren Orinelle in Southshore: keep it",m=1453,x=48.4,y=50.2,ml=20}}},
  {t="Jorgen and Elling Trias", lv=28, g={{"t",1241,m=1453,x=76.3,y=85.1},{"a",1242,m=1453,x=76.3,y=85.1,ml=28},{"t",1242,n2="Elling Trias, the cheese shop in the Trade District",m=1453,x=66,y=74.1},{"a",1243,m=1453,x=66,y=74.1,ml=28}}},
