R:Segment({id="alliance/07-thousand-needles",title="Duskwood",faction="Alliance",min=29,max=31,zone=1431,zoneName="Duskwood",next="alliance/30-40/01-hillsbrad-foothills"}, function() return {
  {t="Duskwood", lv=29, g={{"g",0,txt="Darkshire",m=1431,x=74.8,y=44.2}}},
  {t="Darkshire", lv=29, g={{"b",0,txt="Set your hearthstone at Darkshire",n2="Innkeeper Trelayne, Scarlet Raven Tavern",m=1431,x=73.9,y=44.4,at="Darkshire"},{"t",1243,n2="Watcher Backus, at the north entrance of town; walks around Darkshire: look inside the circle on the map",m=1431,x=74.8,y=44.2},{"a",1244,m=1431,x=74.8,y=44.2,ml=28},{"t",57,m=1431,x=73.5,y=46.8},{"a",58,m=1431,x=73.5,y=46.8,ml=18}}},
  {t="Nightbane Shadow Weavers", lv=29, n="The worgen hold the woods of Brightwood, west of Darkshire and north of the road. Pull them one at a time.", g={{"o",173,i=1,txt="Kill Nightbane Shadow Weaver x6",m=1431,x=65,y=45.8}}},
  {t="Calor", lv=29, g={{"t",173,m=1431,x=75.8,y=47.6},{"a",221,m=1431,x=75.8,y=47.6,ml=23}}},
  {t="Nightbane Dark Runners", lv=29, n="The Dark Runners prowl the woods south of the road, west of Darkshire.", g={{"o",221,i=1,txt="Kill Nightbane Dark Runner x12",m=1431,x=67.6,y=45.9}}},
  {t="Calor", lv=29, g={{"t",221,m=1431,x=75.8,y=47.6},{"a",222,m=1431,x=75.8,y=47.6,ml=23}}},
  {t="Nightbane Vile Fangs and the Insane Ghoul", lv=29, n="The strongest worgen roam the woods south of Darkshire, west and south of the Tranquil Gardens Cemetery. The Insane Ghoul hides in the small crypt by the cemetery.\nCareful: Curse of Blood lasts 10 minutes and adds 13 to each hit of physical damage you take.\nCareful: Some worgen outside the cave stand in groups, including one camp of four. To avoid adds, pull them one at a time from the raised ground next to the cave entrance.", g={{"o",177,i=1,txt="Mary's Looking Glass",n2="Mary's Looking Glass; inside",m=1431,x=80.9,y=72},{"o",222,i=1,txt="Kill Nightbane Vile Fang x8",m=1431,x=73.7,y=69.9},{"o",222,i=2,txt="Kill Nightbane Tainted One x8",m=1431,x=73.1,y=75.5}}},
  {t="Darkshire", lv=29, g={{"t",177,n2="Viktori Prism'Antras, inside",m=1431,x=79.8,y=48},{"a",181,m=1431,x=79.8,y=48,ml=20},{"t",222,m=1431,x=75.8,y=47.6},{"a",223,m=1431,x=75.8,y=47.6,ml=23},{"t",223,n2="Jonathan Carevin, by Elaine Carevin's house; inside",m=1431,x=75.3,y=49},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Vul'Gol Ogre Mound: kill these as you meet them", lv=29, n="Head south-west from Darkshire to the ogre mound. Abercrombie's Crate sits in the camp at its entrance; Splinter Fist ogres guard it.", g={{"a",96138,n2="Only if a Lost Watcher dropped Merrick's Bow: right-click it",opt=true,ml=18},{"o",96138,i=1,txt="Kill Splinter Fist Warrior x8",m=1431,x=36.6,y=77.4,opt=true},{"o",96138,i=2,txt="Kill Splinter Fist Taskmaster x4",m=1431,x=39.5,y=75,opt=true},{"o",181,i=1,txt="Ogre's Monocle",n2="Below ground",m=1431,x=38,y=80},{"o",134,i=1,txt="Abercrombie's Crate",m=1431,x=33.4,y=76.3}}},
  {t="Defias Strongbox", lv=29, n="The Defias camp lies in the south-west of Duskwood, south of Raven Hill near the Westfall border. The strongbox stands among the tents.", g={{"o",1244,i=1,txt="Defias Docket",n2="Defias Docket; inside",m=1431,x=23.9,y=72.1}}},
  {t="Abercrombie", lv=29, g={{"t",134,m=1431,x=28.1,y=31.5},{"a",160,m=1431,x=28.1,y=31.5,ml=20}}},
  {t="Raven Hill Cemetery: kill these as you meet them", lv=29, n="The Plague Spreaders walk the northern half of the Raven Hill Cemetery. Mor'Ladim, an elite, wanders the graves: keep away from him.\nSkeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of Sven's camp.\nCareful: The skeletons in the catacombs are packed close together, so you can easily pull extra mobs.", g={{"o",58,i=1,txt="Kill Plague Spreader x20",m=1431,x=26.3,y=34.2},{"o",323,i=3,txt="Kill Skeletal Warder x3",m=1431,x=18.3,y=35.7},{"o",323,i=1,txt="Kill Skeletal Raider x15",m=1431,x=17.6,y=37},{"o",323,i=2,txt="Kill Skeletal Healer x3",m=1431,x=17.3,y=37.4}}},
  {t="The Weathered Grave", lv=29, n="The grave stands among the skeletons at the cemetery's north-west corner, on the way to Sven. Its quest and the next are talk-only, to Sirra Von'Indi and Commander Althea in Darkshire: level 35 from level 28, but no fight.", g={{"a",225,m=1431,x=17.7,y=29.1,opt=true,ml=28}}},
  {t="Sven's Camp", lv=29, g={{"t",323,m=1431,x=7.8,y=34.1},{"a",269,n2="For Bishop Farthing in Stormwind, in the next guide",m=1431,x=7.8,y=34.1,ml=20}}},
  {t="Back to Darkshire", lv=29, g={{"t",160,n2="Lord Ello Ebonlocke, in the town hall",m=1431,x=71.9,y=46.4},{"a",251,m=1431,x=71.9,y=46.4,ml=20},{"t",251,n2="Sirra Von'Indi, in the house behind the town hall",m=1431,x=72.6,y=47.6},{"t",225,m=1431,x=72.6,y=47.6,opt=true},{"a",227,m=1431,x=72.6,y=47.6,opt=true,ml=28},{"t",96138,m=1431,x=72.6,y=47.6,opt=true},{"a",401,m=1431,x=72.6,y=47.6,ml=20},{"t",401,n2="Wait a moment, then speak with her again",m=1431,x=72.6,y=47.6},{"a",252,m=1431,x=72.6,y=47.6,ml=20},{"t",252,m=1431,x=71.9,y=46.4},{"t",227,m=1431,x=73.5,y=46.8,opt=true},{"t",58,m=1431,x=73.5,y=46.8},{"t",1244,n2="Watcher Backus walks around Darkshire: look inside the circle on the map",m=1431,x=74.8,y=44.2},{"a",1245,n2="For Elling Trias in Stormwind, in the next guide",m=1431,x=74.8,y=44.2,ml=28}}},
  {t="Viktori Prism'Antras", lv=29, n="Viktori's house stands at the east end of town, on the way to the flight master.", g={{"t",181,n2="Inside",m=1431,x=79.8,y=48}}},
  {t="Fly to Menethil Harbor", lv=29, g={{"g",0,txt="Darkshire flight master",m=1431,x=77.6,y=44.4},{"z",0,txt="Fly to Menethil Harbor",at="Menethil Harbor"}}},
} end)

R:Segment({id="alliance/30-40/01-hillsbrad-foothills",title="Wetlands & Hillsbrad Foothills",faction="Alliance",min=30,max=33,zone=1437,zoneName="Wetlands",next="alliance/30-40/03-ashenvale"}, function() return {
  {t="To Deepwater Tavern", lv=30, g={{"g",0,txt="Deepwater Tavern",m=1437,x=10.7,y=61}}},
  {t="Angerfang Encampment", lv=30, n="South-east from Menethil to the Dragonmaw's Angerfang Encampment: the first catapult stands on the way, and the Tattered Spellbook lies in the camp.", g={{"t",465,m=1437,x=47.5,y=47}}},
  {t="Angerfang Encampment", lv=30, w={{k="group",q=474}}, g={{"a",474,m=1437,x=47.5,y=47,ml=23}}},
  {t="Angerfang Encampment", lv=30, g={{"a",98223,n2="Tattered Spellbook: for Captain Stoutfist",m=1437,x=53.5,y=54.5,ml=23}}},
  {t="Defeat Nek'rosh", lv=30, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Chieftain Nek'rosh is a level 32 elite: most classes solo it at level 34, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Shadowcasters stand on either side of him, and at least one is linked to him, so it joins when he is pulled. Non-elite centurions and captains are spread around his ring of tents.", w={{k="group",q=474}}, g={{"o",474,i=1,txt="Nek'rosh's Head",m=1437,x=53.5,y=54.7,grp=true}}},
  {t="Golm", lv=30, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Golm, Ados, Neru and Modr are level 32 elites, each called up by using the Goaz Stone beside it. Skip them if you are alone. Golm stands in the south-eastern hills.", w={{k="group",q=98310}}, g={{"o",98310,i=3,txt="Heart of Golm",m=1437,x=64.5,y=62.8,grp=true}}},
  {t="Ados", lv=30, n="North-east to the Dragonmaw Gates: Ados stands at the gates (use the Goaz Stone).", w={{k="group",q=98310}}, g={{"o",98310,i=1,txt="Heart of Ados",m=1437,x=75.1,y=48.2,grp=true}}},
  {t="Dragonmaw Gates: kill these as you meet them", lv=30, n="The whelps nest in the hills north-east of the Angerfang Encampment; Carnage prowls further north, and the Razormaw raptors hunt the highlands on the way north to Dun Modr.\nCarnage is elite: grouping up is advised.", g={{"o",98072,i=1,txt="Pristine Crimson Scale x8",m=1437,x=71.6,y=47.4},{"o",98283,i=2,txt="Carnage's Head",m=1437,x=69.5,y=30.3,opt=true,grp=true},{"o",98245,i=1,txt="Razormaw Incisor x10",m=1437,x=69.7,y=30.4}}},
  {t="Razormaw nests", lv=30, n="The Perfect Razormaw Eggs for Trying Times lie in the raptors' nests in the hills around Carnage.", w={{k="onquest",q={98246}}}, g={{"o",98246,i=1,txt="Perfect Razormaw Egg x12",m=1437,x=69.2,y=32.7}}},
  {t="Neru", lv=30, n="Neru stands in the hills between the Dragonmaw Gates and Dun Modr (use the Goaz Stone).", w={{k="group",q=98310}}, g={{"o",98310,i=4,txt="Heart of Neru",m=1437,x=60.5,y=26.7,grp=true}}},
  {t="The Green Belt", lv=30, n="Maddened Rotclaws roam the Green Belt around Rethiel; one of them drops the flesh. Rethiel takes the quest only with Carnage's head too.", w={{k="has",n=1,item=280330}}, g={{"o",98283,i=1,txt="Malignant Rotclaw Flesh",m=1437,x=59.8,y=26.6}}},
  {t="Rethiel the Greenwarden", lv=30, w={{k="complete",q=98283}}, g={{"t",98283,n2="With Carnage's head and the flesh",m=1437,x=56.4,y=40.4}}},
  {t="Dun Modr", lv=30, n="North along the road to Dun Modr. Longbraid the Grim and Rhag Garmason stand together in the dwarves' camp on the east side of the road; the Dark Iron ruins west of it are full of elites.", g={{"t",472,m=1437,x=49.8,y=18.3},{"a",631,m=1437,x=49.9,y=18.2,ml=26}}},
  {t="Captive Fire Elemental", lv=30, n="These are elite mobs: grouping up is encouraged, look for people to do it with. The Captive Fire Elemental is held at the far west end of the Dark Iron ruins, past level 27-30 elite dwarves, and Balgaras the Foul (34, elite) can be among them. Lead it east out of the ruins, then hand it in to Roggo Harlbarrow in the camp. Skip it if you are alone.", w={{k="group",q=87491}}, g={{"a",87491,m=1437,x=45.7,y=16.7,ml=25},{"t",87491,m=1437,x=49.9,y=18.1}}},
  {t="Modr", lv=30, n="Modr stands in the ruins of Dun Modr (use the Goaz Stone).", w={{k="group",q=98310}}, g={{"o",98310,i=2,txt="Heart of Modr",m=1437,x=50.2,y=18.2,grp=true}}},
  {t="Ebenezer Rustlocke", lv=30, n="North along the road from Dun Modr towards the Thandol Span: Ebenezer Rustlocke's corpse lies under the span. Rustlocke's parchment goes back to Rhag.\nTwo elite Dark Iron Saboteurs stand by the corpse inside the span: pull them one at a time, or loot the corpse and run out.", g={{"t",631,n2="Ebenezer Rustlocke's Corpse, inside",m=1437,x=51.3,y=8},{"a",632,n2="the same corpse",m=1437,x=51.3,y=8,ml=26}}},
  {t="Rhag Garmason", lv=30, n="Back down the road to Dun Modr: Rhag wants the Dark Iron explosives under the far end of the span destroyed.", g={{"t",632,m=1437,x=49.9,y=18.2},{"a",633,m=1437,x=49.9,y=18.2,ml=26}}},
  {t="The Cache of Explosives", lv=30, n="Over the Thandol Span: the Dark Irons' cache of explosives sits by its Arathi end.", g={{"o",633,i=1,txt="Cache of Explosives",m=1417,x=48.8,y=88}}},
  {t="Waterlogged Envelope", lv=30, g={{"h",4433,txt="Get Waterlogged Envelope",n2="Underwater",m=1417,x=44.3,y=92.9,n=1,opt=true},{"a",637,opt=true,ml=25}}},
  {t="Rhag Garmason again", lv=30, n="Back over the span and down the road through Dun Modr on the way south.", g={{"t",633,m=1437,x=49.9,y=18.2},{"a",634,n2="for Captain Nials at Refuge Pointe, in 05-arathi-highlands",m=1437,x=49.9,y=18.2,ml=28}}},
  {t="The Green Belt", lv=30, g={{"t",98245,m=1437,x=49.4,y=42.1}}},
  {t="Howin Kindfeather", lv=30, w={{k="complete",q=98246}}, g={{"t",98246,n2="Trying Times: the eggs",m=1437,x=49.4,y=42.1}}},
  {t="Prospector Whelgar", lv=30, w={{k="group",q=98310}}, g={{"t",98310,n2="Below ground",m=1437,x=38.8,y=52.4},{"a",98313,n2="For Historian Karnik in Ironforge, at the end of this guide",m=1437,x=38.8,y=52.4,ml=24}}},
  {t="Menethil Harbor", lv=30, n="West along the road to Menethil.", g={{"t",98223,n2="On the top floor",m=1437,x=9.9,y=57.5},{"a",1132,n2="Red Jack Flint, by the keep's door: for Fiora Longears in Theramore, in the next guide",m=1437,x=10,y=58,ml=30}}},
  {t="Menethil Harbor", lv=30, n="Captain Stoutfist stands on the top floor of Menethil Keep: go up inside, the arrow cannot tell the floors apart.", w={{k="group",q=474}}, g={{"t",474,m=1437,x=9.9,y=57.5},{"a",98230,n2="Captain Stoutfist: for Howin Kindfeather, back east along the road",m=1437,x=9.9,y=57.5,ml=22}}},
  {t="Howin Kindfeather", lv=30, n="Back east along the road to the Green Belt: Howin Kindfeather camps among the Fenrunners, just west of Rethiel. Then west again to Menethil for the boat.", w={{k="group",q=474}}, g={{"t",98230,m=1437,x=49.4,y=42.1},{"a",98300,n2="For King Magni in Ironforge, at the end of this guide",m=1437,x=49.4,y=42.1,opt=true,ml=24}}},
  {t="Level 30.8", lv=30, n="Skipped Defeat Nek'rosh and short of 30.8? Kill the Bluegill murlocs on the coast south of Menethil until level 30.8. Or, with a group, run the Gnomeregan dungeon or the Scarlet Monastery dungeon (Graveyard) instead.", w={{k="group",neg=true,q=474},{k="level",op="<",n=30,frac=0.8}}, g={{"g",0,txt="Bluegill Raider",m=1437,x=12.3,y=64.9},{"l",30,txt="Reach level 30 (80% in): grind Bluegill Raider",n2="grind on Bluegill Raider",m=1437,x=12.7,y=65.3,fr=0.8}}},
  {t="Menethil Harbor", lv=30, g={{"t",98072,m=1437,x=8.6,y=55.7}}},
  {t="Boat to Southshore", lv=30, g={{"g",0,txt="Boat to Southshore",m=1437,x=4.8,y=57}}},
  {t="Southshore", lv=30, n="Off the boat, walk up the pier into town: Phin Odelic and Lieutenant Farren stand by the inn, Chef Jessen upstairs, Darren Malvew east of it; the flight master is at the north end, Micha Yance and Bartolo Ginsetti between her and the inn, Maleb in the town hall at the west side.\nBarkeep Kelly may not offer Talk of the Town on Forever: if she doesn't, skip it.", g={{"a",659,n2="Phin Odelic: his trail leads to Arathi",m=1424,x=50.4,y=59,ml=30},{"t",98219,n2="Lieutenant Farren Orinelle, inside",m=1424,x=51.5,y=58.4},{"a",536,m=1424,x=51.5,y=58.4,ml=25},{"b",0,txt="Set your hearthstone at Southshore",m=1424,x=51.2,y=58.9,at="Southshore"},{"a",98463,n2="Barkeep Kelly, in the inn: for Booty Bay (04-stranglethorn-vale)",m=1424,x=51.6,y=58.6,opt=true,ml=28},{"a",555,n2="Chef Jessen, upstairs",m=1424,x=51.9,y=58.7,ml=28},{"a",564,n2="Darren Malvew: the lions come later",m=1424,x=52.4,y=56,ml=30},{"fp",14,txt="Get the Southshore flight path (Darla Harris)",m=1424,x=49.3,y=52.3},{"h",3713,txt="Buy Soothing Spices (Micha Yance)",n2="Soothing Spices, from Micha Yance",m=1424,x=48.9,y=55,n=1},{"a",505,n2="Magistrate Henry Maleb, inside",m=1424,x=48.1,y=59.1,ml=26},{"a",92432,m=1424,x=48.3,y=60,ml=30}}},
  {t="Bartolo Ginsetti", lv=30, n="Bartolo makes a yeti fur cloak for anyone who brings a Hillman's Cloak (Leatherworking) and a Bolt of Woolen Cloth (Tailoring); no vendor sells either, so this step shows only when you carry both.", w={{k="has",n=1,item=3719},{k="has",n=1,item=2997}}, g={{"a",565,n2="Bartolo Ginsetti, between the flight master and the inn: he wants a Hillman's Cloak and a Bolt of Woolen Cloth too",m=1424,x=49.4,y=55.5,opt=true,ml=29}}},
  {t="Torn Fin murlocs", lv=30, n="The Torn Fin murlocs crowd the Western Strand, south-west of Southshore.\nCareful: One camp holds a tight cluster of Oracles that all aggro together.", g={{"o",536,i=1,txt="Kill Torn Fin Tidehunter x10",m=1424,x=48.6,y=64.4},{"o",536,i=2,txt="Kill Torn Fin Oracle x10",m=1424,x=48.3,y=66.4}}},
  {t="Farren", lv=30, g={{"t",536,n2="Inside",m=1424,x=51.5,y=58.4},{"a",559,m=1424,x=51.5,y=58.4,ml=25}}},
  {t="Murloc heads", lv=30, n="Back to the same murlocs; not every one drops a head.", g={{"o",559,i=1,txt="Murloc Head x10",m=1424,x=48.6,y=64.4}}},
  {t="Farren's Proof", lv=30, g={{"t",559,n2="Lieutenant Farren Orinelle, inside",m=1424,x=51.5,y=58.4},{"a",560,m=1424,x=51.5,y=58.4,ml=25},{"t",560,m=1424,x=49.5,y=58.7},{"a",561,m=1424,x=49.5,y=58.7,ml=25},{"t",561,m=1424,x=51.5,y=58.4},{"a",562,m=1424,x=51.5,y=58.4,ml=25}}},
  {t="Daggerspine naga", lv=30, n="The naga hold the shore south-east of Southshore.", g={{"o",562,i=1,txt="Kill Daggerspine Shorehunter x10",m=1424,x=53.7,y=63.5},{"o",562,i=2,txt="Kill Daggerspine Siren x10",m=1424,x=53.2,y=64.2}}},
  {t="Farren", lv=30, g={{"t",562,n2="Inside",m=1424,x=51.5,y=58.4},{"a",563,n2="A report for Stormwind Keep; inside",m=1424,x=51.5,y=58.4,ml=25}}},
  {t="Southshore", lv=30, g={{"h",3713,txt="Buy Soothing Spices (Micha Yance)",n2="Soothing Spices, from Micha Yance",m=1424,x=48.9,y=55,n=1}}},
