  {t="Yeti cave", lv=30, n="The yetis live in the cave in the hills north of Southshore, on the way north to the Syndicate camp.\nStay in the Foothill Caverns: the cave further north has Mountain and Giant Yetis (32-34) in pairs and The Abominable Greench, a level 36 elite.", w={{k="onquest",q={565}}}, g={{"o",565,i=4,txt="Yeti Fur x10",m=1424,x=44.5,y=29.4}}},
  {t="Alterac Mountains", lv=30, g={{"g",0,txt="Syndicate camp",m=1416,x=58.3,y=68}}},
  {t="Syndicate camp", lv=30, n="The Syndicate camp sits on the Alterac border in northern Hillsbrad, west of Tarren Mill (Horde); the documents lie in the camp, and its Footpads and Thieves are the Syndicate Maleb wants.", g={{"o",505,i=1,txt="Kill Syndicate Footpad x12",m=1416,x=58.7,y=68.4},{"o",505,i=2,txt="Kill Syndicate Thief x8",m=1416,x=58.2,y=68.4},{"a",510,m=1416,x=58.3,y=68,ml=26},{"a",511,m=1416,x=58.3,y=68,ml=30}}},
  {t="Hillsbrad Fields", lv=30, n="South-west from the Syndicate camp to the Hillsbrad Fields farms.", w={{k="onquest",q={98059}}}, g={{"g",0,txt="Hillsbrad Fields",m=1424,x=32.5,y=39.5}}},
  {t="Hillsbrad council", lv=30, n="Use the Sealed Company Request at the Hillsbrad council.", w={{k="onquest",q={98059}}}, g={{"o",98059,i=1,txt="Use Sealed Company Request",m=1424,x=29.7,y=41.7}}},
