  {t="Southshore", lv=30, g={{"h",3713,txt="Buy Soothing Spices (Micha Yance)",n2="Soothing Spices, from Micha Yance",m=1424,x=48.9,y=55,n=1},{"t",511,m=1424,x=50.6,y=57.1},{"a",514,m=1424,x=50.6,y=57.1,ml=30},{"t",510,n2="Inside",m=1424,x=48.1,y=59.1},{"a",512,m=1424,x=48.1,y=59.1,ml=26},{"t",505,m=1424,x=48.1,y=59.1},{"t",555,n2="Chef Jessen, upstairs",m=1424,x=51.9,y=58.7},{"t",98059,m=1424,x=46.4,y=50.2,opt=true}}},
  {t="Fly to Ironforge", lv=30, g={{"g",0,txt="Southshore flight master",m=1424,x=49.4,y=52.1},{"z",0,txt="Fly to Ironforge",at="Ironforge"}}},
