R:Segment({id="alliance/30-40/02-desolace",title="Desolace",faction="Alliance",min=35,max=36,zone=1443,zoneName="Desolace",next="alliance/30-40/04b-stranglethorn-vale"}, function() return {
  {t="Nijel's Point", lv=35, n="Follow the road west past Sun Rock Retreat (Horde) and south-west through the Charred Vale into Desolace; Nijel's Point stands at the top of the pass.", g={{"fp",37,txt="Get the Nijel's Point flight path (Baritanas Skyriver)",m=1443,x=64.7,y=10.5},{"b",0,txt="Set your hearthstone at Nijel's Point",m=1443,x=66.3,y=6.5,at="Nijel's Point"},{"t",1453,m=1443,x=66.2,y=9.6},{"a",1458,m=1443,x=66.2,y=9.6,ml=30},{"a",1454,n2="Kreldig Ungor: the wreck's chest lies below Azore's tower, on the way to Thunder Axe Fortress",m=1443,x=66.2,y=9.6,ml=30},{"a",1387,m=1443,x=66.7,y=10.9,ml=30},{"a",93224,n2="Captain Pentigast, beside Corporal Melkins",m=1443,x=66.7,y=10.9,ml=30},{"a",1437,m=1443,x=66.4,y=11.8,ml=30}}},
  {t="Malem chest", lv=35, n="The chest lies in the ruins south-west of Nijel's Point.", g={{"t",1437,m=1443,x=56.5,y=17.8},{"a",1465,m=1443,x=56.5,y=17.8,ml=30}}},
  {t="Sargeron", lv=35, n="The Hatefury satyrs hold the ruins of Sargeron, east of Nijel's Point.\nCareful: Hatefury Rogues spawn stealthed, and Hatefury Tricksters have a poison proc on their attacks.", g={{"o",1458,i=1,txt="Hatefury Claw x10",m=1443,x=70.1,y=15.6},{"o",1458,i=2,txt="Hatefury Horn x10",m=1443,x=70.1,y=15.6}}},
  {t="Kreldig Ungor", lv=35, g={{"t",1458,m=1443,x=66.2,y=9.6},{"a",1459,m=1443,x=66.2,y=9.6,ml=30}}},
  {t="Nijel's Point", lv=35, g={{"t",1465,m=1443,x=66.4,y=11.8},{"a",1438,m=1443,x=66.4,y=11.8,ml=30},{"a",97284,n2="Vahlarriel Demonslayer: the Burning Blade in Thunder Axe Fortress, where her search leads",m=1443,x=66.4,y=11.8,ml=30}}},
  {t="Azore Aldamort", lv=35, n="Azore's tower stands on the hill west of Thunder Axe Fortress: take his quest first, the sceptre he wants is in the fortress.", g={{"a",5741,m=1443,x=38.9,y=27.2,ml=30}}},
  {t="Karnitol's Chest", lv=35, n="The wrecked ship lies just south-west of Azore's tower; its chest sits beside Rackmore's Log.", g={{"t",1454,m=1443,x=36.1,y=30.4},{"a",1455,n2="For Kreldig Ungor, at the end of this guide",m=1443,x=36.1,y=30.4,ml=30}}},
  {t="Dalinda Malem", lv=35, n="Dalinda hides inside the Burning Blade's fortress south-west of Nijel's Point.", g={{"t",1438,n2="Inside",m=1443,x=54.9,y=26.1},{"a",1439,m=1443,x=54.9,y=26.1,ml=30}}},
  {t="Tyranis and the Seer", lv=35, n="Her brother Tyranis (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The Burning Blade Seer keeps the sceptre in the fortress's main building. Vahlarriel wants four of each kind of cultist on the way.", g={{"o",1439,i=1,txt="Tyranis' Pendant",n2="Tyranis' Pendant; inside",m=1443,x=53,y=29.1},{"o",5741,i=1,txt="Sceptre of Light",n2="Sceptre of Light; on the top floor",m=1443,x=55.2,y=30.1},{"o",97284,i=1,txt="Kill Burning Blade Augur x4",m=1443,x=55.2,y=30.1},{"o",97284,i=2,txt="Kill Burning Blade Reaver x4",m=1443,x=56,y=29.9},{"o",97284,i=3,txt="Kill Burning Blade Adept x4",m=1443,x=56,y=31.1},{"o",97284,i=4,txt="Kill Burning Blade Felsworn x4",m=1443,x=55.4,y=30.1}}},
  {t="Escort Dalinda", lv=35, g={{"t",1439,n2="Dalinda Malem, inside",m=1443,x=54.9,y=26.1},{"a",1440,m=1443,x=54.9,y=26.1,ml=30},{"g",0,txt="Out of Thunder Axe Fortress",m=1443,x=58.3,y=30.9},{"i",0,txt="Lead Dalinda out of the fortress; she walks off once you are clear of it. Vahlarriel takes the turn-in at Nijel's Point at the end of the guide."},{"c",1440,txt="Rescue Dalinda Malem"}}},
  {t="Smeed Scrabblescrew", lv=35, n="Smeed's camp is on the road south of Kolkar Village, by the Kodo Graveyard.", g={{"a",5561,m=1443,x=60.9,y=61.9,ml=30}}},
  {t="Kodo Graveyard", lv=35, n="Use Smeed's Kodo Kombobulator on an Aged, Dying or Ancient Kodo: it becomes a tamed kodo that follows you. Walk it back to Smeed's camp; there, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time; Aged Kodos also drop the hides, and the Scorpashi Lashers that hunt around the graveyard carry the venom.", g={{"i",0,txt="Use Kodo Kombobulator",n2="on an Aged, Dying or Ancient Kodo in the graveyard; don't kill it",m=1443,x=51,y=58.5},{"o",5561,i=1,txt="Talk to Aged Kodo",n2="the tamed kodo, at Smeed's camp: talk to it, five times",m=1443,x=60.6,y=61.6},{"o",1459,i=2,txt="Aged Kodo Hide x3",m=1443,x=57.8,y=71},{"o",1459,i=1,txt="Scorpashi Venom x7",m=1443,x=58.9,y=72.1}}},
  {t="Smeed Scrabblescrew", lv=35, g={{"t",5561,m=1443,x=60.9,y=61.9}}},
  {t="Kolkar Village", lv=35, n="The Kolkar roam the plains around Kolkar Village; their ears are for Corporal Melkins.", g={{"o",1387,i=1,txt="Centaur Ear x15",m=1443,x=65.6,y=70.3},{"o",93224,i=1,txt="Carved Centaur Totem x5",m=1443,x=65.6,y=70.3}}},
  {t="Nijel's Point", lv=35, g={{"t",1440,m=1443,x=66.4,y=11.8},{"t",97284,m=1443,x=66.4,y=11.8},{"t",1387,m=1443,x=66.7,y=10.9},{"t",93224,m=1443,x=66.7,y=10.9},{"t",1459,m=1443,x=66.2,y=9.6},{"t",1455,m=1443,x=66.2,y=9.6},{"a",1456,n2="Kreldig Ungor: the satchel lies off the north-west coast, on the south loop at the end of 30-40 (06-badlands): keep it",m=1443,x=66.2,y=9.6,ml=30}}},
  {t="Fly to Auberdine", lv=35, g={{"g",0,txt="Nijel's Point flight master",m=1443,x=64.7,y=10.4},{"z",0,txt="Fly to Auberdine",at="Auberdine"}}},
  {t="Boat to Stormwind Harbor", lv=35, g={{"g",0,txt="Boat to Stormwind Harbor",m=1439,x=30.7,y=41}}},
} end)

R:Segment({id="alliance/30-40/03-ashenvale",title="Wetlands, Dustwallow Marsh & Thousand Needles",faction="Alliance",min=32,max=33,zone=1437,zoneName="Wetlands",next="alliance/30-40/04-stranglethorn-vale"}, function() return {
  {t="Fly to Menethil Harbor", lv=32, g={{"g",0,txt="Stormwind flight master",m=1453,x=71,y=73},{"z",0,txt="Fly to Menethil Harbor",at="Menethil Harbor"}}},
  {t="Red Jack Flint", lv=32, n="Red Jack Flint stands by Menethil Keep's door, just north of the flight master.", g={{"a",1132,n2="For Fiora Longears in Theramore's inn, where this guide's boat goes",m=1437,x=10,y=58,ml=30}}},
  {t="Glorin Steelbrow", lv=32, n="Glorin stands in the Deepwater Tavern, south of the keep, where Mikhail and Vincent Hyal wait too.", g={{"t",270,n2="Inside",m=1437,x=10.6,y=60.6},{"a",321,m=1437,x=10.6,y=60.6,ml=20}}},
  {t="Deepwater Tavern", lv=32, n="Tapoke Jahn (34) slips out of the tavern once you take The Missing Diplomat: stay close behind him. He turns on you outside, a friend joins him, and he gives up once badly hurt. If you lose him the quest fails: abandon it and take it again from Mikhail.", g={{"b",0,txt="Set your hearthstone at Deepwater Tavern",m=1437,x=10.7,y=61,at="Deepwater Tavern"},{"t",1248,m=1437,x=10.6,y=60.8},{"a",1249,m=1437,x=10.6,y=60.8,ml=28},{"o",1249,i=1,txt="Kill Tapoke \"Slim\" Jahn",m=1437,x=10.5,y=60.3},{"t",1249,m=1437,x=10.6,y=60.8},{"a",1250,m=1437,x=10.5,y=60.3,ml=28},{"t",1301,m=1437,x=10.8,y=60.4},{"a",1302,m=1437,x=10.8,y=60.4,ml=30},{"t",1250,m=1437,x=10.6,y=60.8},{"a",1264,m=1437,x=10.6,y=60.8,ml=28}}},
  {t="Waterlogged Chest", lv=32, n="The wreck of the Flying Osprey lies in the shallows south of the keep.", g={{"t",321,m=1437,x=12.1,y=64.2},{"a",324,m=1437,x=12.1,y=64.2,ml=20}}},
  {t="Lightforge Ingots", lv=32, n="The Bluegill murlocs on the beach south-west of Menethil carry the ingots.", g={{"o",324,i=1,txt="Lightforge Ingot x5",n2="Lightforge Ingot; underwater",m=1437,x=11.8,y=64.4}}},
  {t="Glorin Steelbrow", lv=32, g={{"t",324,n2="Inside",m=1437,x=10.6,y=60.6},{"a",322,n2="For Grimand Elmore in Stormwind, after Stranglethorn",m=1437,x=10.6,y=60.6,ml=20}}},
  {t="Boat to Theramore", lv=32, g={{"g",0,txt="Boat to Theramore",m=1437,x=5.1,y=63.6}}},
  {t="Theramore", lv=32, n="The flight master stands by the gate of Foothold Citadel; Clerk Lendry and Commander Samaul are inside the citadel.", g={{"fp",32,txt="Get the Theramore flight path (Baldruc)",m=1445,x=67.5,y=51.3},{"t",1302,n2="Clerk Lendry, on the top floor",m=1445,x=67.9,y=48.2},{"t",1264,n2="Commander Samaul, on the top floor",m=1445,x=68,y=48.7},{"t",1132,n2="Fiora Longears, inside the inn in the north of town",m=1445,x=66.5,y=45.1},{"i",0,txt="Fiora's next errand goes to Astranaar, off this route: leave it."},{"a",1135,n2="Fiora Longears: the wyverns are in Thousand Needles, later in this guide",m=1445,x=66.5,y=45.1,ml=25}}},
  {t="The Shady Rest Inn", lv=32, n="Follow the road west out of Theramore to the burned inn on the road toward the Barrens: the black shield lies in the ashes and the hoofprints are in the mud beside the inn.", g={{"a",1284,m=1445,x=29.7,y=47.6,ml=30},{"a",1253,m=1445,x=29.6,y=48.6,ml=30}}},
  {t="Into The Barrens", lv=32, g={{"g",0,txt="Into The Barrens",m=1413,x=49.5,y=78.4}}},
  {t="Takar the Seer", lv=32, n="On the road south through the Barrens, Takar the Seer camps east of the road, north-east of Camp Taurajo; come in from the east and keep clear of the Horde guards.", f={c={"WARLOCK"}}, g={{"t",1716,m=1413,x=49.3,y=57.1},{"a",1738,n2="Heartswood: in Ashenvale, on the way to Desolace",m=1413,x=49.3,y=57.1,ml=20},{"a",65602,n2="What Is Love?: the incubus, beside the succubus; the Wooden Figurine is near the Heartswood",m=1413,x=49.3,y=57.1,opt=true,ml=20}}},
  {t="Highperch", lv=32, n="Down the Great Lift into Thousand Needles, then west to the wyverns' cliffs at Highperch. Every wyvern there can drop a venom sac.", g={{"o",1135,i=1,txt="Highperch Venom Sac x10",m=1441,x=12.7,y=37.5}}},
  {t="Thousand Needles", lv=32, n="East through the canyons. Freewind Post, a Horde camp with guards, sits on the mesa here: keep to the canyon floor and give the foot of its lifts a wide berth.", g={{"g",0,txt="The canyons east of Highperch",m=1441,x=46.3,y=40.9}}},
  {t="Thousand Needles", lv=32, g={{"g",0,txt="Mirage Raceway",m=1441,x=77.8,y=77.3}}},
  {t="Mirage Raceway", lv=32, n="Follow the canyons east to the salt flats. The goblins and gnomes of the Mirage Raceway are neutral and give quests to both factions.", g={{"a",5762,n2="For Hemet Nesingwary in Stranglethorn, later",m=1441,x=77.8,y=77.3,ml=28},{"a",1110,m=1441,x=77.8,y=77.3,ml=28},{"a",1104,m=1441,x=78.1,y=77.1,ml=28},{"t",1179,m=1441,x=78.1,y=77.1},{"a",1105,m=1441,x=78.1,y=77.1,ml=28},{"a",1176,m=1441,x=80.2,y=75.9,ml=29},{"a",1175,m=1441,x=81.6,y=78,ml=28}}},
  {t="Mirage Raceway: kill these as you meet them", lv=32, n="Rocket Car Rubble lies all over the flats. Scorpid Reavers and Salt Flats Scavengers roam the north half, Sparkleshell Snappers (tortoises) the whole flats. Saltstone Basilisks and Crystalhides hold the middle; the Gazers (34-35) only the far south.", g={{"o",1104,i=1,txt="Salty Scorpid Venom x6",m=1441,x=82.8,y=79.7},{"o",1110,i=1,txt="Rocket Car Parts x30",m=1441,x=82.8,y=85.4},{"o",1176,i=1,txt="Hollow Vulture Bone x10",m=1441,x=79.3,y=89.2},{"o",1105,i=1,txt="Hardened Tortoise Shell x9",m=1441,x=79.9,y=85.7},{"o",1175,i=1,txt="Kill Saltstone Basilisk x10",m=1441,x=77.6,y=64.9},{"o",1175,i=2,txt="Kill Saltstone Crystalhide x10",m=1441,x=76.9,y=64.7},{"o",1175,i=3,txt="Kill Saltstone Gazer x6",m=1441,x=83.5,y=78.8},{"o",1078,i=1,txt="Crystalized Scales x8",n2="Crystalized Scale, from the Saltstone Basilisks: eight for Collin Mauren in Stormwind",m=1441,x=80.6,y=64.2,opt=true}}},
  {t="Mirage Raceway", lv=32, g={{"t",1110,m=1441,x=77.8,y=77.3},{"t",1105,m=1441,x=78.1,y=77.1},{"t",1104,m=1441,x=78.1,y=77.1},{"a",1106,n2="Fizzle Brassbolts: for Martek in the Badlands, at the end of 30-40",m=1441,x=78.1,y=77.1,ml=26},{"t",1176,m=1441,x=80.2,y=75.9},{"t",1175,m=1441,x=81.6,y=78}}},
  {t="Into Tanaris", lv=32, n="From the raceway follow the road south out of the Shimmering Flats into Tanaris.", g={{"g",0,txt="Into Tanaris",m=1441,x=74.2,y=93.6}}},
  {t="Gadgetzan", lv=32, n="Gadgetzan is a short walk down the road; keep to it. Bera Stonehammer, the Alliance flight master, stands inside the walls.", g={{"fp",39,txt="Get the Gadgetzan flight path (Bera Stonehammer)",m=1446,x=51,y=29.3}}},
  {t="Fly to Theramore", lv=32, g={{"g",0,txt="Gadgetzan flight master",m=1446,x=51,y=29.3},{"z",0,txt="Fly to Theramore",at="Theramore"}}},
  {t="Theramore", lv=32, n="Fiora Longears is in the north of town, Captain Vimes in Foothold Citadel; Caz Twosprocket stands in the town.", g={{"t",1135,m=1445,x=66.5,y=45.1},{"t",1284,m=1445,x=68.2,y=48.6},{"t",1253,m=1445,x=68.2,y=48.6},{"a",1319,m=1445,x=68.2,y=48.6,ml=30},{"t",1319,m=1445,x=64.8,y=50.4},{"a",1320,m=1445,x=64.8,y=50.4,ml=30},{"t",1320,m=1445,x=68.2,y=48.6}}},
  {t="Boat to Menethil Harbor", lv=32, g={{"g",0,txt="Boat to Menethil Harbor",m=1445,x=71.6,y=56.4}}},
} end)

R:Segment({id="alliance/30-40/04-stranglethorn-vale",title="Stranglethorn Vale",faction="Alliance",min=33,max=35,zone=1434,zoneName="Stranglethorn Vale",next="alliance/30-40/02-desolace"}, function() return {
  {t="Fly to Darkshire", lv=33, g={{"g",0,txt="Menethil Harbor flight master",m=1437,x=9.5,y=59.7},{"z",0,txt="Fly to Darkshire",at="Darkshire"}}},
  {t="Stranglethorn Vale", lv=33, g={{"g",0,txt="Nesingwary's Expedition",m=1434,x=35.7,y=10.5}}},
  {t="Nesingwary's Expedition", lv=33, n="From Duskwood take the road south into Stranglethorn; the hunters' tents stand just west of the road past the Rebel Camp turn-off.", g={{"a",583,m=1434,x=35.7,y=10.5,ml=28},{"t",583,m=1434,x=35.7,y=10.8},{"t",5762,n2="Hemet Nesingwary, from Thousand Needles",m=1434,x=35.7,y=10.8},{"a",194,m=1434,x=35.7,y=10.8,ml=28},{"a",185,m=1434,x=35.6,y=10.6,ml=28},{"a",190,m=1434,x=35.5,y=10.6,ml=28},{"a",338,m=1434,x=35.7,y=10.5,opt=true,ml=30}}},
  {t="Young tigers and panthers", lv=33, n="Both roam the grass around the camp and along the road north.", g={{"o",185,i=1,txt="Kill Young Stranglethorn Tiger x10",m=1434,x=35.6,y=12.1}}},
  {t="Nesingwary's Expedition", lv=33, g={{"t",185,m=1434,x=35.6,y=10.6},{"a",186,m=1434,x=35.6,y=10.6,ml=28}}},
  {t="Young Panther", lv=33, g={{"o",190,i=1,txt="Kill Young Panther x10",m=1434,x=36.1,y=7.2}}},
  {t="Nesingwary's Expedition", lv=33, g={{"t",190,m=1434,x=35.5,y=10.6},{"a",191,m=1434,x=35.5,y=10.6,ml=28}}},
  {t="Stranglethorn Tigers", lv=33, n="The adult tigers prowl the hills just south and west of the camp.", g={{"o",186,i=1,txt="Kill Stranglethorn Tiger x10",m=1434,x=36.4,y=13.8}}},
  {t="Level 33.2", lv=33, n="The jungle's quests climb to 37 from here: short of 33.2? Keep on the Stranglethorn Tigers in the hills just south and west of the camp until level 33.2. Or, with a group, run the Scarlet Monastery dungeon (Library) instead.", w={{k="level",op="<",n=33,frac=0.2}}, g={{"g",0,txt="Stranglethorn Tiger",m=1434,x=30.8,y=11.2},{"l",33,txt="Reach level 33 (20% in): grind Stranglethorn Tiger",n2="grind on Stranglethorn Tiger",m=1434,x=30.8,y=11.2,fr=0.2}}},
  {t="Ajeck Rouack", lv=33, g={{"t",186,m=1434,x=35.6,y=10.6},{"a",187,n2="The elder tigers come later, on the way back from the Rebel Camp",m=1434,x=35.6,y=10.6,ml=28}}},
  {t="Panthers, raptors and elder tigers", lv=33, n="Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west.", g={{"o",191,i=1,txt="Kill Panther x10",m=1434,x=30.8,y=11.2},{"a",635,n2="Gluggle, a rare murloc on the coast west of camp, drops the Pendant of Myzrael: take it if you meet him",opt=true,ml=30}}},
  {t="Sir S. J. Erlgadin", lv=33, n="Back east to Nesingwary's camp on the way north to the Rebel Camp.", g={{"t",191,m=1434,x=35.5,y=10.6}}},
  {t="Rebel Camp", lv=33, n="Take the road north; the camp sits in the hills to the west.\nPrivate Thorsen offers Jungle Secrets only while he is out of the camp: about every half hour he walks down the path to the road, where two Kurzen's Agents ambush him. Help him kill them and take the quest at once, before he walks back up. He isn't there? Leave it: the guide passes Bookie Herod, which follows from it, as well.", g={{"a",215,n2="Private Thorsen, at the foot of the path",m=1434,x=40.3,y=8.4,opt=true,ml=30},{"t",215,n2="Lieutenant Doren, in the hut",m=1434,x=38,y=3},{"a",200,n2="Lieutenant Doren: Bookie Herod's records lie at the edge of Kurzen's Compound, next",m=1434,x=38,y=3,ml=30},{"a",210,n2="Corporal Kaleb: for Krazek in Booty Bay, later in this guide",m=1434,x=37.7,y=3.3,ml=32},{"a",203,m=1434,x=38,y=3.3,ml=30},{"a",204,m=1434,x=38,y=3.3,ml=30}}},
  {t="Kurzen's Compound: kill these as you meet them", lv=33, n="The Kurzen rebels hold the camp east of the Rebel Camp; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents. Bookie Herod's records lie in a hut on the compound's west side.", g={{"t",200,n2="Bookie Herod's Records, in the hut",m=1434,x=43.7,y=9.4},{"a",328,n2="The strongbox is deeper in, by the cave: on the northern loop (04b)",m=1434,x=43.7,y=9.4,ml=30},{"o",204,i=1,txt="Jungle Remedy x7",m=1434,x=43.7,y=9.5},{"o",203,i=1,txt="Kill Kurzen Jungle Fighter x15",m=1434,x=43.6,y=9.7},{"o",204,i=2,txt="Venom Fern Extract",n2="Venom Fern Extract, from a Kurzen Supplies crate",m=1434,x=44.1,y=9.5}}},
  {t="Level 33.6", lv=33, n="Short of 33.6? Keep on the Kurzen Jungle Fighters and Medicine Men around the compound's outer edge until level 33.6. Or, with a group, run the Scarlet Monastery dungeon (Library) instead.", w={{k="level",op="<",n=33,frac=0.6}}, g={{"g",0,txt="Kurzen Jungle Fighter",m=1434,x=44.6,y=10},{"l",33,txt="Reach level 33 (60% in): grind Kurzen Jungle Fighter",n2="grind on Kurzen Jungle Fighter",m=1434,x=44.5,y=10,fr=0.6}}},
  {t="Rebel Camp", lv=33, g={{"t",203,m=1434,x=38,y=3.3},{"t",204,m=1434,x=38,y=3.3}}},
  {t="Stranglethorn Vale: kill these as you meet them", lv=33, n="Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults.", g={{"o",187,i=1,txt="Kill Elder Stranglethorn Tiger x10",m=1434,x=34,y=17.6},{"o",194,i=1,txt="Kill Stranglethorn Raptor x10",m=1434,x=27.6,y=17.7}}},
  {t="Level 34", lv=34, n="The quests from here on are 37: if you are short of 34, keep on the elder tigers in the hills south-west of Nesingwary's camp until level 34. Or, with a group, run the Scarlet Monastery dungeon (Library or Armory) instead.", w={{k="level",op="<",n=34}}, g={{"g",0,txt="Elder Stranglethorn Tiger",m=1434,x=33.2,y=18.7},{"l",34,txt="Reach level 34: grind Elder Stranglethorn Tiger",n2="grind on Elder Stranglethorn Tiger",m=1434,x=32.9,y=19}}},
  {t="Nesingwary's Expedition", lv=34, n="Barnil collects the Green Hills of Stranglethorn: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go.", g={{"a",339,m=1434,x=35.7,y=10.5,opt=true,ml=30},{"a",340,m=1434,x=35.7,y=10.5,opt=true,ml=30},{"a",341,m=1434,x=35.7,y=10.5,opt=true,ml=30},{"a",342,m=1434,x=35.7,y=10.5,opt=true,ml=30},{"t",187,m=1434,x=35.6,y=10.6},{"a",188,m=1434,x=35.6,y=10.6,ml=28},{"t",194,m=1434,x=35.7,y=10.8},{"a",195,m=1434,x=35.7,y=10.8,ml=28}}},
  {t="Sin'Dall and the Lashtail raptors", lv=34, n="Sin'Dall, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to Booty Bay.", g={{"o",195,i=1,txt="Kill Lashtail Raptor x10",m=1434,x=38.3,y=19.2}}},
  {t="Down to Booty Bay", lv=34, n="Follow the main road south the length of the jungle, past the Grom'gol turn-off, to Booty Bay on the southern cape.", g={{"fp",19,txt="Get the Booty Bay flight path (Gyll)",m=1434,x=27.5,y=77.8},{"a",575,n2="Drizzlik, by the bank; inside",m=1434,x=28.3,y=77.6,ml=26},{"a",605,n2="Crank Fizzlebub, inside",m=1434,x=27.1,y=77.2,ml=30},{"b",0,txt="Set your hearthstone at Booty Bay",n2="Innkeeper Skindle, The Salty Sailor Tavern; upstairs",m=1434,x=27,y=77.3,at="Booty Bay"},{"t",98463,n2="Nixxrax Fillamug, in the Salty Sailor Tavern; upstairs",m=1434,x=27,y=77.2,opt=true},{"a",198,n2="Krazek, in the tavern; upstairs",m=1434,x=26.9,y=77.2,ml=30},{"t",210,n2="Krazek, from Corporal Kaleb",m=1434,x=26.9,y=77.2},{"a",201,m=1434,x=26.9,y=77.2,ml=28},{"a",616,m=1434,x=26.9,y=77.2,ml=32},{"a",189,n2="Kebok, in the tavern",m=1434,x=27,y=77.1,ml=30},{"a",213,n2="Kebok: the Tumbled Crystals, on the northern loop",m=1434,x=27,y=77.1,ml=31},{"i",0,txt="Sell and repair",opt=true},{"t",616,n2="Baron Revilgaz, upstairs in the tavern",m=1434,x=27.2,y=76.9},{"a",578,m=1434,x=27.2,y=76.9,ml=32}}},
  {t="Fly to Sentinel Hill", lv=34, g={{"g",0,txt="Booty Bay flight master",m=1434,x=27.5,y=77.7},{"z",0,txt="Fly to Sentinel Hill",at="Sentinel Hill"}}},
  {t="Stranglethorn Vale", lv=34, g={{"g",0,txt="The Savage Coast",m=1434,x=24.4,y=17.5}}},
  {t="The Savage Coast: kill these as you meet them", lv=34, n="From Sentinel Hill the way leads south out of Westfall into Stranglethorn's north-west, to the Crystalvein Mine near the coast; the Crystal Spine Basilisks around it drop the shards.\nThe haunted island lies just off the coast south-west of the mine: just reach it. The Bloodscalp trolls hold the ruins on the coast to the north.", g={{"o",605,i=1,txt="Singing Crystal Shard x10",m=1434,x=24.2,y=17.7},{"c",578,txt="Locate the haunted island",n2="The haunted island",m=1434,x=21.9,y=22.4},{"o",189,i=1,txt="Bloodscalp Ear x15",m=1434,x=22.5,y=13.4},{"o",188,i=1,txt="Paw of Sin'Dall",m=1434,x=31.5,y=15.5}}},
  {t="River crocolisks", lv=34, n="River Crocolisks swim the river by the Rebel Camp.", g={{"o",575,i=1,txt="Large River Crocolisk Skin x2",m=1434,x=32.5,y=8.9}}},
  {t="Private Thorsen", lv=34, n="Private Thorsen spends most of his time at the top of the Rebel Camp's path, by the huts, and now and then walks down it to the road and back (about eight minutes). If he isn't at the arrow, look along that path.", g={{"t",198,m=1434,x=38,y=3.4}}},
  {t="Nesingwary's Expedition", lv=34, g={{"t",195,m=1434,x=35.7,y=10.8},{"t",188,m=1434,x=35.6,y=10.6},{"c",201,txt="Locate the hunters' camp",n2="Investigate the Camp: just look around the hunters' camp",m=1434,x=35.6,y=10.6}}},
  {t="Booty Bay", lv=34, g={{"t",575,n2="Drizzlik, inside",m=1434,x=28.3,y=77.6},{"a",577,n2="Drizzlik: the Snapjaw Crocolisks, on the northern loop",m=1434,x=28.3,y=77.6,ml=31},{"t",605,n2="Crank Fizzlebub, inside",m=1434,x=27.1,y=77.2},{"t",201,n2="Krazek, upstairs",m=1434,x=26.9,y=77.2},{"t",189,n2="Kebok, upstairs",m=1434,x=27,y=77.1},{"t",578,n2="Baron Revilgaz, upstairs in the tavern",m=1434,x=27.2,y=76.9},{"a",601,n2="Baron Revilgaz: the water elementals rise around the haunted island, on the northern loop",m=1434,x=27.2,y=76.9,ml=32}}},
  {t="Fly to Stormwind", lv=34, g={{"g",0,txt="Booty Bay flight master",m=1434,x=27.5,y=77.7},{"z",0,txt="Fly to Stormwind",at="Stormwind"}}},
  {t="Grimand Elmore", lv=34, g={{"t",322,m=1453,x=59.7,y=33.8}}},
  {t="Collin Mauren", lv=34, n="Collin Mauren is in the Slaughtered Lamb, in the Mage Quarter.", w={{k="complete",q=1078}}, g={{"t",1078,m=1453,x=53,y=86.6}}},
  {t="Druid training", lv=34, n="Sheldras Moontree, the druid trainer, stands in Stormwind, north-west of the Mage Quarter.", f={c={"DRUID"}}, g={{"tr",0,txt="Visit your class trainer"}}},
  {t="Boat to Auberdine", lv=34, g={{"g",0,txt="Boat to Auberdine",m=1453,x=22.7,y=56.7}}},
  {t="Fly to Astranaar", lv=34, g={{"g",0,txt="Auberdine flight master",m=1439,x=36.4,y=45.6},{"z",0,txt="Fly to Astranaar",at="Astranaar"}}},
  {t="Heartswood", lv=34, n="From Astranaar head north-west into the hills: the Heartswood is a glowing tree north of the road to Maestra's Post. If you took What Is Love?, the Wooden Figurine lies in a house among the trees north of Maestra's Post (26.6,22.0). Then take the road west to Stonetalon.", f={c={"WARLOCK"}}, g={{"o",1738,i=1,txt="Heartswood",m=1440,x=31.6,y=31.6},{"o",65602,i=1,txt="Wooden Figurine",n2="Wooden Figurine, north of Maestra's Post",m=1440,x=26.6,y=22,opt=true}}},
  {t="Stonetalon Mountains", lv=34, g={{"g",0,txt="The road to Nijel's Point",m=1442,x=33.7,y=72.8}}},
} end)

R:Segment({id="alliance/30-40/04b-stranglethorn-vale",title="Stranglethorn Vale",faction="Alliance",min=35,max=36,zone=1434,zoneName="Stranglethorn Vale",next="alliance/30-40/05-arathi-highlands"}, function() return {
  {t="Collin Mauren", lv=35, w={{k="complete",q=1078}}, g={{"t",1078,n2="In the Slaughtered Lamb, if you still carry it",m=1453,x=53,y=86.6}}},
  {t="Fly to Darkshire", lv=35, g={{"g",0,txt="Stormwind flight master",m=1453,x=71,y=73},{"z",0,txt="Fly to Darkshire",at="Darkshire"}}},
  {t="Stranglethorn Vale", lv=35, g={{"g",0,txt="Into Stranglethorn Vale",m=1434,x=40.8,y=4.2}}},
  {t="Rebel Camp", lv=35, n="From Duskwood take the road south; the camp sits in the hills west of the road.", g={{"a",207,m=1434,x=37.8,y=3.6,ml=30},{"a",574,m=1434,x=38,y=3.3,ml=30},{"a",210,n2="Corporal Kaleb: for Krazek in Booty Bay",m=1434,x=37.7,y=3.3,ml=32}}},
  {t="Nesingwary's Expedition", lv=35, n="South along the road: the hunters' tents stand just west of it.", g={{"a",192,n2="Sir S. J. Erlgadin: the Shadowmaw Panthers prowl around Lake Nazferiti, after Kurzen's Compound",m=1434,x=35.5,y=10.6,ml=28}}},
  {t="Bookie Herod", lv=35, n="East to Kurzen's Compound: Herod's records lie in a hut on its west side.", w={{k="onquest",q={200}}}, g={{"t",200,n2="Bookie Herod's Records, upstairs",m=1434,x=43.7,y=9.4},{"a",328,m=1434,x=43.7,y=9.4,ml=30}}},
  {t="Kurzen's Compound", lv=35, n="Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave, and Herod's strongbox sits by the cave mouth. Pick up Green Hills pages as they drop.\nCareful: Kurzen Commandos are level 34-35, not elite, and often spawn stealthed; near death they use Smoke Bomb.", g={{"o",574,i=1,txt="Kill Kurzen Commando x10",m=1434,x=46.3,y=7.8},{"o",574,i=2,txt="Kill Kurzen Headshrinker x6",n2="Kurzen Headshrinker, below ground",m=1434,x=46.4,y=7.9},{"t",328,n2="Bookie Herod's Strongbox, below ground",m=1434,x=49.6,y=7.6},{"a",329,m=1434,x=49.6,y=7.6,ml=30}}},
  {t="Lake Nazferiti", lv=35, n="South from the compound to Lake Nazferiti: the Venture Co. Geologists in the camps on its shore carry the Tumbled Crystals, and the Shadowmaw Panthers prowl stealthed in the jungle south and east of it.", g={{"o",213,i=1,txt="Tumbled Crystal x8",m=1434,x=44.5,y=20.5},{"o",192,i=1,txt="Kill Shadowmaw Panther x10",m=1434,x=48.6,y=22.2}}},
  {t="The jungle ruins", lv=35, n="West across the jungle to the troll ruins: each holds one stone tablet of the troll legends, the first two in the ruins south-west of Nesingwary's camp, the last two on the hill in the north-west.", g={{"o",207,i=1,txt="The First Troll Legend",n2="The First Troll Legend: Moon Over the Vale",m=1434,x=29.5,y=19.1},{"o",207,i=2,txt="The Second Troll Legend",n2="The Second Troll Legend: Gri'lek the Wanderer; underwater",m=1434,x=24.8,y=22.9}}},
  {t="Water Elementals", lv=35, n="The haunted island lies just off the shore west of the second tablet: the Lesser Water Elementals rise from the water around it.", g={{"o",601,i=1,txt="Water Elemental Bracers x6",m=1434,x=22.5,y=23.1}}},
  {t="The Ruins of Zul'Kunda", lv=35, n="North along the coast to the ruins on the hill: the last two tablets lie there. Pick up Green Hills pages as they drop.", g={{"o",207,i=3,txt="The Third Troll Legend",n2="The Third Troll Legend: Fall of Gurubashi",m=1434,x=22.9,y=12},{"o",207,i=4,txt="The Fourth Troll Legend",n2="The Fourth Troll Legend: The Emperor's Tomb",m=1434,x=24.7,y=8.9},{"c",339,txt="Green Hills of Stranglethorn - Page 1; Green Hills of Stranglethorn - Page 4; Green Hills of Stranglethorn - Page 6; Green Hills of Stranglethorn - Page 8",n2="Chapter I",opt=true},{"c",340,txt="Green Hills of Stranglethorn - Page 10; Green Hills of Stranglethorn - Page 11; Green Hills of Stranglethorn - Page 14; Green Hills of Stranglethorn - Page 16",n2="Chapter II",opt=true},{"c",341,txt="Green Hills of Stranglethorn - Page 18; Green Hills of Stranglethorn - Page 20; Green Hills of Stranglethorn - Page 21; Green Hills of Stranglethorn - Page 24",n2="Chapter III",opt=true},{"c",342,txt="Green Hills of Stranglethorn - Page 25; Green Hills of Stranglethorn - Page 26; Green Hills of Stranglethorn - Page 27",n2="Chapter IV",opt=true}}},
  {t="Rebel Camp", lv=35, n="East to the Rebel Camp, on the way back to Nesingwary's camp.", g={{"t",329,m=1434,x=38,y=3},{"a",330,m=1434,x=38,y=3,ml=30},{"t",330,m=1434,x=37.7,y=3.4},{"a",331,m=1434,x=37.7,y=3.4,ml=30},{"t",331,m=1434,x=38,y=3},{"t",574,n2="Sergeant Yohwa: the Commandos and Headshrinkers fell in the compound",m=1434,x=38,y=3},{"t",207,m=1434,x=37.8,y=3.6},{"a",205,m=1434,x=37.8,y=3.6,ml=30}}},
  {t="Nesingwary's Expedition", lv=35, g={{"t",339,m=1434,x=35.7,y=10.5,opt=true},{"t",340,m=1434,x=35.7,y=10.5,opt=true},{"t",341,m=1434,x=35.7,y=10.5,opt=true},{"t",342,m=1434,x=35.7,y=10.5,opt=true},{"t",338,m=1434,x=35.7,y=10.5,opt=true},{"t",192,m=1434,x=35.5,y=10.6},{"a",196,m=1434,x=35.7,y=10.8,ml=28}}},
  {t="Nesingwary's Expedition", lv=35, w={{k="group",q=193}}, g={{"a",193,m=1434,x=35.5,y=10.6,ml=28}}},
  {t="Snapjaw Crocolisks", lv=35, n="Snapjaw Crocolisks bask along the river in the middle of the jungle, on the way south to the Skullsplitter ruins.", g={{"o",577,i=1,txt="Snapjaw Crocolisk Skin x5",m=1434,x=39.8,y=16}}},
  {t="Level 36", lv=36, n="Troll Witchery's Skullsplitter trolls are 39-42. Below 36? Keep killing the Snapjaw Crocolisks along the river until level 36. Or, with a group, run the Scarlet Monastery dungeon (Armory) or the Razorfen Downs dungeon instead.", w={{k="level",op="<",n=36}}, g={{"g",0,txt="Snapjaw Crocolisk",m=1434,x=40.2,y=27.2},{"l",36,txt="Reach level 36: grind Snapjaw Crocolisk",n2="grind on Snapjaw Crocolisk",m=1434,x=40.2,y=27.2}}},
  {t="Skullsplitter trolls", lv=36, n="The Skullsplitter trolls hold the ruins east of the road between Nesingwary and Grom'gol.", g={{"o",205,i=1,txt="Skullsplitter Fetish x4",m=1434,x=42.5,y=33.3}}},
  {t="Booty Bay", lv=36, g={{"t",577,n2="Drizzlik, inside",m=1434,x=28.3,y=77.6},{"t",601,n2="Baron Revilgaz, upstairs in the tavern",m=1434,x=27.2,y=76.9},{"a",602,n2="For Archmage Ansirem in Alterac Mountains",m=1434,x=27.2,y=76.9,ml=32},{"t",213,m=1434,x=27,y=77.1},{"t",210,n2="Krazek, upstairs",m=1434,x=26.9,y=77.2},{"a",627,n2="Krazek, upstairs: this optional quest needs four Lesser Bloodstone Ore. Mine Lesser Bloodstone Deposits in Arathi Highlands with Mining 75, or buy the ore at the Auction House or ask a miner friend. The kobolds do not drop it; skip this quest if you cannot get the ore.",m=1434,x=26.9,y=77.2,opt=true,ml=32},{"a",600,n2="Crank Fizzlebub, inside",m=1434,x=27.1,y=77.2,ml=30},{"a",606,n2="\"Sea Wolf\" MacKinley, on the top floor",m=1434,x=27.8,y=77.1,ml=30}}},
} end)

R:Segment({id="alliance/30-40/05-arathi-highlands",title="Arathi Highlands, Alterac Mountains & Swamp of Sorrows",faction="Alliance",min=36,max=38,zone=1417,zoneName="Arathi Highlands",next="alliance/30-40/06-badlands"}, function() return {
  {t="Fly to Darkshire", lv=36, g={{"g",0,txt="Booty Bay flight master",m=1434,x=27.5,y=77.7},{"z",0,txt="Fly to Darkshire",at="Darkshire"}}},
  {t="Swamp of Sorrows", lv=36, g={{"g",0,txt="Watcher Biggs",m=1435,x=26.7,y=59.8}}},
  {t="Watcher Biggs", lv=36, n="Watcher Biggs guards the road junction in the west of the swamp. Amaryllis Webb stands a short way north of him.\nAmaryllis Webb may not be here on Forever: if Amaryllis Webb doesn't offer My Little Friends, skip it.", g={{"a",1396,m=1435,x=26.7,y=59.8,ml=30},{"a",93176,n2="Amaryllis Webb: three critters to catch in Arathi, Desolace and Stranglethorn",m=1435,x=25.1,y=54.2,opt=true,ml=25}}},
  {t="The western swamp", lv=36, n="Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road.", g={{"o",1396,i=1,txt="Kill Young Sawtooth Crocolisk x8",m=1435,x=25.9,y=52.2},{"o",1396,i=2,txt="Kill Sorrow Spinner x10",m=1435,x=26,y=49.5},{"o",1396,i=3,txt="Kill Swamp Jaguar x10",m=1435,x=26.4,y=47.4}}},
  {t="Watcher Biggs", lv=36, g={{"t",1396,m=1435,x=26.7,y=59.8},{"a",1421,m=1435,x=26.7,y=59.8,ml=30}}},
  {t="The Harborage", lv=36, n="Follow the road north to the draenei of the Harborage.", g={{"a",1389,m=1435,x=26,y=31.4,ml=30}}},
  {t="Fallow Sanctuary", lv=36, n="East along the road to the Fallow Sanctuary. The Lost One mobs drop the crystals. Noboru the Cudgel walks a long path through the ruins: if you meet him, kill him, his cudgel starts a quest for Magtoor. Don't wait for him.", g={{"h",6196,txt="Get Noboru's Cudgel",n2="from Noboru the Cudgel: he walks a path through the ruins",m=1435,x=54.9,y=34.1,n=1,opt=true},{"a",1392,opt=true,ml=29},{"o",1389,i=1,txt="Draenethyst Crystal x6",m=1435,x=55.1,y=30.1}}},
  {t="The Lost Caravan", lv=36, n="The wrecked caravan's chest lies at the north end of the Fallow Sanctuary, beside Galen Goodward's cage.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly.", g={{"o",1421,i=1,txt="Wizards' Reagents",m=1435,x=64.5,y=18.3}}},
  {t="Galen Goodward", lv=36, n="Galen is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards.", g={{"a",1393,m=1435,x=65.5,y=18.2,ml=30},{"c",1393,txt="Escort Galen out of the Fallow Sanctuary."},{"t",1393,m=1435,x=47.8,y=39.8}}},
  {t="The Harborage", lv=36, n="West along the road from Galen's strongbox to the Harborage.", g={{"t",1392,n2="Magtoor: Noboru's cudgel",m=1435,x=26,y=31.4},{"t",1389,m=1435,x=26,y=31.4}}},
  {t="Watcher Biggs", lv=36, n="South down the road to Watcher Biggs, on the way west out of the swamp.", g={{"t",1421,m=1435,x=26.7,y=59.8}}},
  {t="Duskwood", lv=36, g={{"g",0,txt="Darkshire",m=1431,x=77.6,y=44.4}}},
  {t="Fly to Stormwind", lv=36, n="Back west through Deadwind Pass to Darkshire.", g={{"z",0,txt="Fly to Stormwind",n2="Felicia Maline, Darkshire",at="Stormwind"}}},
  {t="Stormwind", lv=36, g={{"a",1260,n2="Angus Stern, Stormwind Harbor road",m=1453,x=51.8,y=93.6,ml=33}}},
  {t="The Binding", lv=36, n="Gakin the Darkbinder waits in the Slaughtered Lamb's cellar, in the Mage Quarter. Use the Heartswood Core at the summoning circle there and defeat the succubus it calls. If you took What Is Love?, hand him the Wooden Figurine too, place it at the same circle and defeat the incubus.", f={c={"WARLOCK"}}, g={{"t",1738,m=1453,x=39.2,y=85.2},{"a",1739,m=1453,x=39.2,y=85.2,ml=20},{"o",1739,i=1,txt="Kill Summoned Succubus",n2="Summoned Succubus, at the summoning circle",m=1453,x=39.2,y=84.4},{"t",1739,n2="Summon Succubus",m=1453,x=39.2,y=85.2},{"t",65602,n2="What Is Love?, if you took it",m=1453,x=39.2,y=85.2,opt=true},{"a",65603,m=1453,x=39.2,y=85.2,opt=true,ml=20},{"o",65603,i=1,txt="Kill Summoned Incubus",n2="Summoned Incubus, at the same circle",m=1453,x=39,y=84.6,opt=true},{"t",65603,n2="Gakin binds the incubus to you",m=1453,x=39.2,y=85.2,opt=true}}},
  {t="Stormwind", lv=36, g={{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","MAGE","WARLOCK","DRUID"}}},{"a",6141,n2="Brother Crowley, Cathedral of Light",m=1453,x=52.6,y=43.2,ml=34}}},
  {t="Count Remington Ridgewell", lv=36, w={{k="group",q=543}}, g={{"a",543,m=1453,x=76.9,y=47.8,ml=30}}},
  {t="Stormwind", lv=36, g={{"a",538,n2="Milton Sheaf, the Royal Library in the keep",m=1453,x=77.1,y=30.2,opt=true,ml=20}}},
  {t="Tram to Ironforge", lv=36, g={{"g",0,txt="Tram to Ironforge",m=1453,x=69.6,y=30.2}}},
  {t="Fly to Southshore", lv=36, g={{"g",0,txt="Ironforge flight master",m=1455,x=55.9,y=47.9},{"z",0,txt="Fly to Southshore",at="Southshore"}}},
  {t="Southshore", lv=36, g={{"a",500,m=1424,x=49.5,y=58.7,ml=30}}},
  {t="Shadowy Assassin", lv=36, n="A Shadowy Assassin lurks stealthed on the edge of Southshore, and few players find him. If you spot him, kill him and read the contract he carries: Magistrate Henry Maleb takes it. Don't wait for him: the rest of this step doesn't need him.", g={{"b",0,txt="Set your hearthstone at Southshore",m=1424,x=51.2,y=58.9,at="Southshore"},{"i",0,txt="Kill Shadowy Assassin",n2="Shadowy Assassin, if you spot him",m=1424,x=50.1,y=57.9,opt=true},{"h",3668,txt="Get Assassin's Contract",m=1424,x=50.1,y=57.9,n=1,opt=true},{"a",522,opt=true,ml=30},{"t",522,n2="Magistrate Henry Maleb, inside",m=1424,x=48.1,y=59.1},{"a",523,m=1424,x=48.1,y=59.1,opt=true,ml=30},{"t",525,m=1424,x=48.1,y=59.1},{"a",537,m=1424,x=48.1,y=59.1,ml=30}}},
  {t="Southshore", lv=36, g={{"t",538,m=1424,x=50.6,y=57.1,opt=true},{"a",540,m=1424,x=50.6,y=57.1,opt=true,ml=20}}},
  {t="Arathi Highlands", lv=36, g={{"g",0,txt="Refuge Pointe",m=1417,x=45.8,y=47.6}}},
  {t="Refuge Pointe", lv=36, n="Follow the road east out of Hillsbrad over Thoradin's Wall to Refuge Pointe.", g={{"fp",16,txt="Get the Refuge Pointe flight path (Cedrik Prose)",m=1417,x=45.7,y=46.1},{"t",634,n2="Captain Nials: Rhag Garmason's plea, from 01-hillsbrad-foothills",m=1417,x=45.8,y=47.6},{"a",681,m=1417,x=45.8,y=47.6,ml=30},{"t",690,m=1417,x=46.6,y=47},{"a",691,m=1417,x=46.2,y=47.8,ml=30}}},
  {t="Northfold Manor", lv=36, n="The Syndicate hold the farm north-west of Refuge Pointe.\nCareful: Syndicate Highwaymen are level 30-31 and can cast Sneak while out of combat, so they are often stealthed and hard to spot.", g={{"o",681,i=1,txt="Kill Syndicate Highwayman x10",m=1417,x=34.7,y=31.7},{"o",681,i=2,txt="Kill Syndicate Mercenary x6",m=1417,x=33.7,y=29.8}}},
  {t="Hay Weevil", lv=36, n="Hay Weevils crawl about the north end of Northfold Manor's farm: catch one with the tool from Amaryllis Webb's Entomology Starter Kit.", w={{k="onquest",q={93176}}}, g={{"h",213568,txt="Get Hay Weevil Specimen",m=1417,x=31.3,y=27.2,n=1}}},
  {t="Shards of Myzrael", lv=36, n="East from Northfold Manor across the north of the Highlands; the shards glitter on the hill by the Circle of East Binding, north of Go'Shek Farm.", g={{"t",635,n2="Only if Gluggle gave you the pendant in Stranglethorn",m=1417,x=62.5,y=33.7,opt=true},{"a",642,m=1417,x=62.5,y=33.7,ml=30}}},
  {t="Drywhisker Gorge: kill these as you meet them", lv=36, n="The Drywhisker kobolds dig in the gorge east of Hammerfall (Horde); skirt the town to the north. They drop the Motes of Myzrael, not Krazek's ore. Lesser Bloodstone Deposits need Mining 75: mine four ore, buy them at the Auction House, or ask a miner friend. The ore goal is optional; continue with Myzrael if you cannot get it. Careful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them.", g={{"o",627,i=1,txt="Lesser Bloodstone Ore x4",m=1417,x=82.8,y=33.5,opt=true},{"o",642,i=1,txt="Mote of Myzrael x12",n2="Mote of Myzrael from Drywhisker Kobold, Drywhisker Surveyor and Drywhisker Digger, by this stop",m=1417,x=83.1,y=33}}},
  {t="Iridescent Shards", lv=36, n="The shards lie at the far end of Drywhisker Gorge.", g={{"t",642,n2="Below ground",m=1417,x=84.3,y=30.9},{"a",651,m=1417,x=84.3,y=30.9,ml=30}}},
  {t="Stones of Binding", lv=36, n="Each key lies at one of the Highlands' standing-stone circles: east of the shards, near Refuge Pointe and in the west. The Stone of Inner Binding stands west of Refuge Pointe.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East.", g={{"o",651,i=2,txt="Cresting Key",n2="Cresting Key: Stone of East Binding",m=1417,x=66.7,y=29.7}}},
  {t="Witherbark Village", lv=36, n="South from the Stone of East Binding, past Go'Shek Farm, to Witherbark Village in the hills: the Witch Doctors stand among the huts and the Shadow Hunters guard the far end of the valley. Every troll can drop a tusk.", g={{"o",691,i=1,txt="Witherbark Tusk x10",m=1417,x=71.4,y=59},{"o",691,i=2,txt="Witherbark Medicine Pouch x4",m=1417,x=71.6,y=61.8},{"o",691,i=3,txt="Shadow Hunter Knife",n2="Shadow Hunter Knife; below ground",m=1417,x=69.9,y=78.8}}},
  {t="Quae", lv=36, n="North-west out of the Witherbark valley; Quae and Kinelory camp in the hills just north of Go'Shek Farm.", g={{"t",659,m=1417,x=60.2,y=53.9},{"a",658,m=1417,x=60.2,y=53.9,ml=30}}},
  {t="Forsaken Courier", lv=36, n="The courier walks the road from Go'Shek Farm west across the Highlands, as far as about 24,45, and back, with two guards: the arrow follows the road west until you meet him. Pull them off the road.", g={{"o",658,i=1,txt="Sealed Folder",m=1417,x=61.3,y=59.4}}},
  {t="Circle of Outer Binding", lv=36, g={{"o",651,i=3,txt="Thundering Key",n2="Thundering Key: Stone of Outer Binding",m=1417,x=52,y=50.7}}},
  {t="Quae and Kinelory", lv=36, g={{"t",658,m=1417,x=60.2,y=53.9},{"a",657,m=1417,x=60.2,y=53.9,ml=30},{"t",657,m=1417,x=60.2,y=53.9},{"a",660,m=1417,x=60.2,y=53.9,ml=30}}},
  {t="Kinelory's errand", lv=36, n="Stay with Kinelory while she sneaks into Go'Shek Farm and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. Kinelory follows them and can pull more mobs, so kill or slow runners fast.", g={{"g",0,txt="Go here",m=1417,x=60.1,y=53.8},{"c",660,txt="Protect Kinelory"}}},
  {t="Quae", lv=36, g={{"t",660,m=1417,x=60.2,y=53.9},{"a",661,n2="For Phin Odelic in Southshore",m=1417,x=60.2,y=53.9,ml=30}}},
  {t="Refuge Pointe", lv=36, n="West along the road to Refuge Pointe, on the way to the Stone of West Binding.", g={{"t",681,m=1417,x=45.8,y=47.6},{"t",691,m=1417,x=46.2,y=47.8},{"a",693,n2="Skuerto: Kor'gresh's cave comes after Faldir's Cove",m=1417,x=46.6,y=47,ml=30},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Circle of West Binding", lv=36, g={{"o",651,i=1,txt="Burning Key",n2="Burning Key: Stone of West Binding",m=1417,x=25.5,y=30.1},{"t",651,m=1417,x=36.2,y=57.4}}},
  {t="Faldir's Cove", lv=36, n="South along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it.", g={{"a",663,m=1417,x=31.8,y=82.7,ml=35},{"t",663,m=1417,x=32.3,y=81.4},{"a",662,m=1417,x=32.8,y=81.5,ml=35},{"a",664,m=1417,x=34,y=80.8,ml=35},{"a",665,m=1417,x=33.9,y=80.5,ml=35}}},
  {t="Phizzlethorpe", lv=36, n="Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming.", g={{"g",0,txt="Go here",m=1417,x=33.9,y=80.6},{"c",665,txt="Defend Professor Phizzlethorpe"}}},
  {t="Doctor Draxlegauge", lv=36, g={{"t",665,m=1417,x=33.9,y=80.5},{"a",666,m=1417,x=33.9,y=80.5,ml=35}}},
  {t="The Drowned Reef: kill these as you meet them", lv=36, n="The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay.", g={{"o",664,i=1,txt="Kill Daggerspine Raider x10",n2="Daggerspine Raider, underwater",m=1417,x=25.4,y=85.2},{"o",666,i=1,txt="Elven Gem x10",n2="Elven Gem; underwater",m=1417,x=25,y=86},{"o",664,i=2,txt="Kill Daggerspine Sorceress x3",n2="Daggerspine Sorceress, underwater",m=1417,x=23.8,y=84.8},{"o",662,i=2,txt="Maiden's Folly Log",n2="Maiden's Folly Log; underwater",m=1417,x=23.4,y=85.1},{"o",662,i=1,txt="Maiden's Folly Charts",n2="Maiden's Folly Charts; underwater",m=1417,x=23.1,y=84.5},{"o",662,i=4,txt="Spirit of Silverpine Log",n2="Spirit of Silverpine Log; underwater",m=1417,x=20.6,y=85.1},{"o",662,i=3,txt="Spirit of Silverpine Charts",n2="Spirit of Silverpine Charts; underwater",m=1417,x=20.5,y=85.6}}},
  {t="Faldir's Cove", lv=36, g={{"t",662,m=1417,x=32.8,y=81.5},{"t",664,m=1417,x=34,y=80.8},{"t",666,m=1417,x=33.9,y=80.5},{"a",668,m=1417,x=33.9,y=80.5,ml=35},{"t",668,m=1417,x=32.3,y=81.4},{"a",669,n2="For Fleet Master Seahorn in Booty Bay: keep it",m=1417,x=32.3,y=81.4,ml=35}}},
  {t="Kor'gresh Coldrage", lv=36, n="East from Faldir's Cove through the southern hills: Kor'gresh, an ogre mage, holds the cave at the southern end of the Witherbark valley.", g={{"o",693,i=1,txt="Trelane's Wand of Invocation",n2="Trelane's Wand of Invocation; below ground",m=1417,x=54.8,y=81.9}}},
  {t="Foggy MacKreel", lv=36, n="South-west from Kor'gresh's cave to the Thandol Span: Foggy MacKreel stands on a broken section of the bridge; jump down to him from its north end. MacKreel's Moonshine must reach Brewmeister Bilger in Southshore within 15 minutes: go straight back to Refuge Pointe and fly to Southshore.", g={{"a",647,m=1417,x=43.2,y=92.6,ml=28}}},
  {t="Skuerto", lv=36, g={{"t",693,m=1417,x=46.6,y=47}}},
  {t="Fly to Southshore", lv=36, g={{"g",0,txt="Refuge Pointe flight master",m=1417,x=45.8,y=46.1},{"z",0,txt="Fly to Southshore",at="Southshore"}}},
  {t="Brewmeister Bilger", lv=36, n="Off the flight, straight to the Southshore inn.", g={{"t",647,n2="Brewmeister Bilger, below ground",m=1424,x=52.1,y=58.7}}},
  {t="Alterac Mountains", lv=36, g={{"g",0,txt="Gavin's Naze",m=1416,x=45,y=77.2}}},
  {t="Gavin's Naze", lv=36, n="Follow the road north out of Southshore into the mountains. Mountain lions roam the slopes; the Syndicate in Strahnbrad wear the signet rings. Baron Vardus (40) turns up in one spot at a time: the cellar of Strahnbrad's inn, or one of the Syndicate tent camps in the uplands north and north-west of the village.", g={{"o",564,i=2,txt="Kill Hulking Mountain Lion x10",m=1416,x=44.2,y=76.7},{"o",564,i=1,txt="Kill Mountain Lion x8",m=1416,x=32.1,y=82.8}}},
  {t="Ruins of Alterac: kill these as you meet them", lv=36, n="The tomes lie in the ruined keep west of Strahnbrad; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and carry the tomes too: pull one at a time, or group up.", g={{"o",540,i=1,txt="Recovered Tome x5",n2="Recovered Tome: Crushridge ogres",m=1416,x=44.9,y=60.2},{"o",540,i=2,txt="Worn Leather Book",n2="Worn Leather Book: the Weathered Bookcase; inside",m=1416,x=38.4,y=46.4}}},
  {t="Ruins of Alterac: kill these as you meet them", lv=36, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Grel'borg the Miser is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nGrel'borg walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path.", w={{k="group",q=543}}, g={{"o",543,i=1,txt="Perenolde Tiara",m=1416,x=35.6,y=54.4,grp=true}}},
  {t="Strahnbrad: kill these as you meet them", lv=36, n="Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: About three stealthed Syndicate mobs are inside Nagaz's house. Nagaz does not join when they are pulled, and a ranged attack through the doorway brings him out by himself.", g={{"o",512,i=1,txt="Alterac Signet Ring x7",m=1416,x=38.3,y=22.5},{"o",537,i=1,txt="Kill Argus Shadow Mage x4",m=1416,x=47.8,y=17.4},{"o",523,i=1,txt="Head of Baron Vardus",m=1416,x=47.8,y=17.1}}},
  {t="Crushridge ogres", lv=36, n="The Crushridge ogres hold the hills north of Strahnbrad. Farther north, a worn wooden chest holds the Ensorcelled Parchment; Nagaz of the Dark Council stands right by it.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and drop the knucklebones too: pull one at a time, or group up.", g={{"o",500,i=1,txt="Dirty Knucklebones x9",m=1416,x=45.2,y=29.4},{"h",3706,txt="Get Ensorcelled Parchment",n2="Inside",m=1416,x=39.2,y=14.7,n=1},{"a",551,ml=30},{"o",537,i=2,txt="Head of Nagaz",m=1416,x=39.2,y=14.3}}},
  {t="Silverpine Forest", lv=36, g={{"g",0,txt="Dalaran",m=1421,x=68.6,y=45.2}}},
  {t="Dalaran", lv=36, n="South-west to the Kirin Tor camp on the lake shore west of Dalaran, just over the border into Silverpine Forest: the Image of Archmage Modera stands there. Archmage Ansirem stands south-east of it, by the dome.", g={{"t",92432,m=1421,x=68.6,y=45.2},{"t",602,m=1416,x=14.2,y=59.7},{"a",603,n2="For Catelyn the Blade in Booty Bay: keep it",m=1416,x=14.2,y=59.7,ml=32}}},
  {t="Hillsbrad Foothills", lv=36, g={{"g",0,txt="Southshore",m=1424,x=48.1,y=59.1}}},
  {t="Southshore", lv=36, g={{"t",537,n2="Magistrate Henry Maleb, inside",m=1424,x=48.1,y=59.1},{"t",512,m=1424,x=48.1,y=59.1},{"t",523,m=1424,x=48.1,y=59.1},{"t",500,m=1424,x=49.5,y=58.7},{"t",661,m=1424,x=50.4,y=59},{"t",540,m=1424,x=50.6,y=57.1,opt=true},{"a",542,n2="For Milton Sheaf in Stormwind: keep it",m=1424,x=50.6,y=57.1,opt=true,ml=20},{"t",551,n2="Loremaster Dibbs: the parchment",m=1424,x=50.6,y=57.1},{"a",554,m=1424,x=50.6,y=57.1,ml=28},{"t",564,m=1424,x=52.4,y=56}}},
  {t="Bartolo Ginsetti", lv=36, n="Bartolo stands between the flight master and the inn; Micha Yance beside him sells Fine Thread if you have none.", w={{k="complete",q=565}}, g={{"h",2321,txt="Buy Fine Thread (Micha Yance)",n2="Fine Thread, from Micha Yance",m=1424,x=48.9,y=55,n=1,opt=true},{"t",565,m=1424,x=49.4,y=55.5}}},
  {t="Ironforge", lv=36, g={{"z",0,txt="Fly to Ironforge",n2="Darla Harris, Southshore",at="Ironforge"}}},
  {t="Ironforge", lv=36, w={{k="onquest",q={554}}}, g={{"t",554,n2="Prospector Stormpike, Hall of Explorers",m=1455,x=74.6,y=11.7}}},
  {t="Ironforge", lv=36, g={{"a",707,n2="Prospector Stormpike, Hall of Explorers: for Prospector Ironband in Loch Modan, next",m=1455,x=74.6,y=11.7,ml=30},{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}}}},
  {t="To Thelsamar", lv=36, g={{"g",0,txt="Thelsamar",m=1432,x=37.1,y=49.4}}},
  {t="Thelsamar", lv=36, n="From Ironforge take the tunnel east through Dun Morogh into Loch Modan and follow the road to Thelsamar.", g={{"fp",8,txt="Get the Thelsamar flight path (Thorgrum Borrelson)",m=1432,x=33.9,y=51},{"b",0,txt="Set your hearthstone at Stoutlager Inn",m=1432,x=35.5,y=48.4,at="Stoutlager Inn"},{"a",2500,n2="Ghak Healtouch, below ground",m=1432,x=37.1,y=49.4,ml=36}}},
  {t="Prospector Ironband", lv=36, n="South-east along the loch to the dig site.", g={{"t",707,m=1432,x=65.9,y=65.6},{"a",738,m=1432,x=65.9,y=65.6,ml=30}}},
} end)

R:Segment({id="alliance/30-40/06-badlands",title="Badlands & Desolace",faction="Alliance",min=38,max=39,zone=1418,zoneName="Badlands",next="alliance/40-50/01-stranglethorn-vale"}, function() return {
  {t="Into Badlands", lv=38, g={{"g",0,txt="Into Badlands",m=1418,x=49.4,y=8}}},
  {t="Badlands", lv=38, g={{"g",0,txt="Hammertoe's Digsite",m=1418,x=53.4,y=43.4}}},
  {t="Hammertoe's Digsite", lv=38, n="Head back west to the road and follow it south out of Loch Modan through the pass into the Badlands. Prospector Ryedol and Sigrun Ironhew camp side by side at the dig.", g={{"a",719,m=1418,x=53.4,y=43.4,ml=35},{"a",718,m=1418,x=53.8,y=43.3,ml=35}}},
  {t="Hammertoe's Digsite: kill these as you meet them", lv=38, n="The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it.", g={{"a",720,m=1418,x=53,y=33.9,ml=35},{"o",2500,i=2,txt="Crag Coyote Fang x10",m=1418,x=50.2,y=35.2},{"o",719,i=1,txt="Ryedol's Lucky Pick",m=1418,x=51.5,y=34.3},{"o",2500,i=1,txt="Buzzard Gizzard x5",m=1418,x=48.9,y=27.4}}},
  {t="The excavation crate", lv=38, n="Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres.", g={{"o",718,i=1,txt="Supply Crate",m=1418,x=66.6,y=22}}},
  {t="Hammertoe's Digsite", lv=38, g={{"i",0,txt="Ryedol's next errand goes into Uldaman: skip it."},{"t",718,m=1418,x=53.8,y=43.3},{"a",733,m=1418,x=53.8,y=43.3,ml=35},{"t",720,m=1418,x=53.4,y=43.4},{"t",719,m=1418,x=53.4,y=43.4}}},
  {t="Valley of Fangs", lv=38, n="Martek and Rigglefuzz camp together in the Valley of Fangs, in the middle of the Badlands.", g={{"t",1106,m=1418,x=42.2,y=52.7},{"a",1108,m=1418,x=42.2,y=52.7,ml=28},{"a",703,m=1418,x=42.4,y=52.9,ml=33},{"a",705,n2="The clams lie on Stranglethorn's north-west coast, in the next guide: keep it",m=1418,x=42.4,y=52.9,ml=30}}},
  {t="Agmond's End", lv=38, n="The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south.", g={{"t",738,m=1418,x=50.9,y=62.4}}},
  {t="Agmond's End: kill these as you meet them", lv=38, n="The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; Murdaloc, Agmond's killer, walks among the Bonesnappers.\nCareful: Dustbelcher Lords are level 44-45. They use Battle Shout and Demoralizing Shout, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of Kargath.", g={{"o",733,i=1,txt="Scrap Metal x7",m=1418,x=62,y=70.2},{"o",703,i=1,txt="Buzzard Wing x4",m=1418,x=58,y=73.8},{"o",2500,i=1,txt="Buzzard Gizzard x5",m=1418,x=60.8,y=39.6},{"a",739,m=1418,x=50.9,y=62.4,ml=30},{"i",0,txt="Murdaloc himself (42) walks among the Bonesnappers: leave him for the later Badlands guide at 43, and kill the Bonesnappers for this quest now."},{"o",1108,i=1,txt="Indurium Flake x10",m=1418,x=50.9,y=64.4},{"o",739,i=2,txt="Kill Stonevault Bonesnapper x12",m=1418,x=50.9,y=64.4},{"a",709,m=1418,x=51.4,y=76.9,ml=30}}},
  {t="Lotwil Veriatus", lv=38, n="Head west into the Dustbowl; Lotwil works by his machines in the middle of it.", g={{"a",710,m=1418,x=25.9,y=44.9,ml=35}}},
  {t="Lesser Rock Elementals", lv=38, n="The Lesser Rock Elementals wander the Dustbowl west of Lotwil; every rock elemental can drop Ghak's Rock Elemental Shards.", g={{"o",710,i=1,txt="Small Stone Shard x10",m=1418,x=23.5,y=45.5},{"o",2500,i=3,txt="Rock Elemental Shard x5",m=1418,x=23.5,y=45.5}}},
  {t="Lotwil Veriatus", lv=38, g={{"t",710,m=1418,x=25.9,y=44.9},{"a",711,m=1418,x=25.9,y=44.9,ml=35}}},
  {t="The Ancient Chest", lv=38, n="Head north-east to the dwarven ruins in the north of the Badlands; the chest sits among the Shadowforge dwarves. Ambassador Infernus nearby is elite: give him room.", g={{"o",709,i=1,txt="Tablet of Ryun'eh",n2="Tablet of Ryun'eh; below ground",m=1418,x=39.3,y=18.8}}},
  {t="Valley of Fangs", lv=38, n="Head south down the road: Martek and Rigglefuzz camp in the Valley of Fangs, on the way to Agmond's End.", g={{"t",1108,m=1418,x=42.2,y=52.7},{"a",1137,n2="For Fizzle Brassbolts at the Mirage Raceway: the Tanaris guide passes him at 45, keep it",m=1418,x=42.2,y=52.7,ml=28},{"t",703,m=1418,x=42.4,y=52.9}}},
  {t="Theldurin the Lost", lv=38, n="Head south to Agmond's End.", g={{"t",709,m=1418,x=51.4,y=76.9},{"a",727,n2="for Gerrig Bonegrip in Ironforge: keep it",m=1418,x=51.4,y=76.9,ml=30}}},
  {t="Rock Elementals", lv=38, n="The Rock Elementals roam south-east of Lotwil; Giant Buzzards and Elder Crag Coyotes share the plain to their west.", g={{"o",711,i=1,txt="Large Stone Slab x3",m=1418,x=46.1,y=77.6}}},
  {t="Lotwil Veriatus", lv=38, n="Lotwil's last test is optional: five Bracers of Rock Binding, which only the Greater Rock Elementals (42-44) in the south-western gulches drop, about one kill in five, well above your level. Take it only if you can handle them one at a time; otherwise hand in the slabs and move on.", g={{"t",711,m=1418,x=25.9,y=44.9},{"a",712,m=1418,x=25.9,y=44.9,opt=true,ml=35}}},
  {t="Bracers of Rock Binding", lv=38, n="South-west into the gulches: only the Greater Rock Elementals there drop the bracers.", w={{k="onquest",q={712}}}, g={{"o",712,i=1,txt="Bracers of Rock Binding x5",m=1418,x=6.7,y=73.8}}},
  {t="Lotwil Veriatus", lv=38, w={{k="complete",q=712}}, g={{"t",712,m=1418,x=25.9,y=44.9}}},
  {t="Lucien Tosselwrench", lv=38, n="Lucien Tosselwrench, beside Lotwil, trades for Patterned Bronze Bracers, a blacksmith's craft: this step shows only when you carry a pair.", w={{k="has",n=1,item=2868}}, g={{"a",716,n2="Lucien Tosselwrench, beside Lotwil",m=1418,x=25.8,y=44.2,ml=35},{"t",716,m=1418,x=25.8,y=44.2}}},
  {t="To Stoutlager Inn", lv=38, g={{"g",0,txt="Stoutlager Inn",m=1432,x=35.5,y=48.4}}},
  {t="Thelsamar", lv=38, g={{"t",2500,n2="Ghak Healtouch, in the inn; below ground",m=1432,x=37.1,y=49.4}}},
  {t="Fly to Menethil Harbor", lv=38, g={{"g",0,txt="Thelsamar flight master",m=1432,x=33.9,y=50.8},{"z",0,txt="Fly to Menethil Harbor",at="Menethil Harbor"}}},
  {t="Boat to Theramore", lv=38, g={{"g",0,txt="Boat to Theramore",m=1437,x=5.1,y=63.6}}},
  {t="Theramore flight master", lv=38, n="Off the boat, walk up the pier to Baldruc, the flight master by the gate of Foothold Citadel.", g={{"g",0,txt="Theramore flight master",m=1445,x=67.5,y=51.3}}},
  {t="Nijel's Point", lv=38, g={{"z",0,txt="Fly to Nijel's Point",at="Nijel's Point"},{"b",0,txt="Set your hearthstone at Nijel's Point",m=1443,x=66.3,y=6.5,at="Nijel's Point"},{"t",6141,m=1443,x=66.5,y=7.9},{"a",261,m=1443,x=66.5,y=7.9,ml=34},{"a",1466,m=1443,x=66.2,y=9.6,ml=30},{"a",1454,n2="Kreldig Ungor, if 30-40/02 didn't take it: the wreck lies below Azore's tower",m=1443,x=66.2,y=9.6,ml=30},{"a",93224,m=1443,x=66.7,y=10.9,ml=30}}},
  {t="Bibbly F'utzbuckle", lv=38, n="Follow the road south to Kormek's Hut.", g={{"a",5501,m=1443,x=62.3,y=39,ml=33}}},
  {t="Kodo Graveyard", lv=38, n="Hornizz stands at the edge of the Kodo Graveyard, south-west of Kormek's Hut; Kodo Bones lie among the skeletons.", g={{"o",5501,i=1,txt="Kodo Bone x10",m=1443,x=53.9,y=58.1},{"a",6134,m=1443,x=47.8,y=61.8,ml=34}}},
  {t="Flesh Picker", lv=38, n="A Flesh Picker crawls about the Kodo Graveyard: catch one with the tool from Amaryllis Webb's Entomology Starter Kit.", w={{k="onquest",q={93176}}}, g={{"h",213567,txt="Get Flesh Picker Specimen",m=1443,x=48.1,y=57.1,n=1}}},
  {t="Maraudine centaurs", lv=38, n="The Maraudine centaurs hold the Valley of Spears west of the graveyard; every kind drops the totems.", g={{"o",93224,i=1,txt="Carved Centaur Totem x5",m=1443,x=39.7,y=61.4}}},
  {t="Melizza Brimbuzzle", lv=38, n="Melizza is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help.", g={{"a",6132,m=1443,x=34,y=53.5,ml=34},{"c",6132,txt="Melizza Brimbuzzle escorted to safety",n2="escort Melizza back toward the graveyard",m=1443,x=40.1,y=61.6}}},
  {t="Mannoroc Coven", lv=38, n="The demons gather at the Mannoroc Coven in southern Desolace: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit.\nCareful: Most of the mobs here walk patrol routes, so you can easily pull extra mobs.", g={{"o",1466,i=2,txt="Nether Wing x10",m=1443,x=50.4,y=71.5},{"o",1466,i=3,txt="Doomwarder Blood x10",m=1443,x=51.4,y=81.8}}},
  {t="The Valley of Bones", lv=38, n="Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the Crate of Ghost Magnets to draw the Magrami Spectres.", g={{"o",261,i=1,txt="Kill Undead Ravager x30",m=1443,x=58.3,y=90.2},{"o",6134,i=1,txt="Use Crate of Ghost Magnets",m=1443,x=63.5,y=91.6},{"o",6134,i=1,txt="Ghost-o-plasm x8",m=1443,x=64.2,y=91.6}}},
  {t="Mannoroc Coven", lv=38, g={{"o",1466,i=1,txt="Felhound Brain x10",m=1443,x=53.9,y=84.6}}},
  {t="Hornizz Brimbuzzle", lv=38, g={{"t",6132,m=1443,x=47.8,y=61.8},{"t",6134,m=1443,x=47.8,y=61.8}}},
  {t="Azore Aldamort", lv=38, n="Follow the road west across the north of Desolace to the ruins of Ethel Rethor. Azore's tower stands on the hill there, on the way to the wreck.", g={{"t",5741,m=1443,x=38.9,y=27.2},{"a",6027,m=1443,x=38.9,y=27.2,ml=30}}},
  {t="Karnitol's Chest", lv=38, n="The wrecked ship's chest lies just south-west of Azore's tower.", g={{"t",1454,m=1443,x=36.1,y=30.4},{"a",1455,m=1443,x=36.1,y=30.4,ml=30}}},
  {t="Claim Rackmore's Treasure!", lv=38, n="Rackmore's Log lies beside Karnitol's Chest. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next.", g={{"a",6161,m=1443,x=36.1,y=30.4,ml=30},{"o",6161,i=1,txt="Rackmore's Silver Key",n2="Underwater",m=1443,x=34.7,y=33.5}}},
  {t="Sar'theris Strand: kill these as you meet them", lv=38, n="The Slitherblade naga hold the north-west coast north of Azore's tower; Karnitol's satchel lies on the sea floor off it, and any naga can drop Rackmore's golden key. Swim out to Ranazjar Isle off the far northern tip and use the Gem of the Serpent on the Serpent Statue: Lord Kragaru (38) rises; kill him for the Book of the Ancients.", g={{"o",1456,i=1,txt="Karnitol's Satchel",n2="Underwater",m=1443,x=33.2,y=10.5},{"o",6161,i=2,txt="Rackmore's Golden Key",n2="Rackmore's Golden Key, from the Slitherblade naga",m=1443,x=30,y=12.2},{"o",6027,i=1,txt="Use Gem of the Serpent",n2="Gem of the Serpent, on the Serpent Statue",m=1443,x=28.2,y=6.7},{"o",6027,i=1,txt="Book of the Ancients",m=1443,x=28.2,y=6.7}}},
  {t="Rackmore's Chest", lv=38, n="Rackmore's chest lies just south-east of the Serpent Statue.", g={{"t",6161,m=1443,x=30,y=8.7}}},
  {t="Azore Aldamort", lv=38, g={{"t",6027,m=1443,x=38.9,y=27.2}}},
  {t="Kormek's Hut", lv=38, g={{"t",5501,m=1443,x=62.3,y=39}}},
  {t="Nijel's Point", lv=38, n="Follow the road north to Nijel's Point: Captain Pentigast stands at its south end, Kreldig Ungor in the middle, Brother Anton to the north.", g={{"t",93224,m=1443,x=66.7,y=10.9},{"t",1466,m=1443,x=66.2,y=9.6},{"t",1455,m=1443,x=66.2,y=9.6},{"t",1456,m=1443,x=66.2,y=9.6},{"a",1457,n2="for Roetten Stonehammer in Ironforge: keep it",m=1443,x=66.2,y=9.6,ml=30},{"a",1467,n2="for Roetten Stonehammer in Ironforge: keep it",m=1443,x=66.2,y=9.6,ml=30},{"t",261,m=1443,x=66.5,y=7.9},{"a",1052,n2="for Raleigh the Devout in Southshore: keep it",m=1443,x=66.5,y=7.9,ml=34}}},
  {t="Fly to Theramore", lv=38, n="The next guide starts in Theramore.", g={{"z",0,txt="Fly to Theramore",at="Theramore"}}},
} end)

R:Segment({id="alliance/40-50/01-stranglethorn-vale",title="Stranglethorn Vale, Dustwallow Marsh & Swamp of Sorrows",faction="Alliance",min=40,max=43,zone=1434,zoneName="Stranglethorn Vale",next="alliance/40-50/02-badlands"}, function() return {
  {t="Theramore", lv=40, n="Morgan Stern stands near the inn; Helenia Olden, a trade supplier a few steps south, sells the spices Jarl wants.", g={{"b",0,txt="Set your hearthstone at Theramore Isle",m=1445,x=66.6,y=45.2,at="Theramore Isle"},{"t",1260,n2="Morgan Stern, inside",m=1445,x=66.3,y=45.5},{"a",1204,m=1445,x=66.3,y=45.5,ml=33},{"a",1265,n2="Commander Samaul, on the top floor of Foothold Citadel",m=1445,x=68,y=48.7,ml=28},{"h",3713,txt="Buy Soothing Spices x3 (Helenia Olden)",n2="Soothing Spices, for \"Swamp Eye\" Jarl",m=1445,x=66.4,y=51.5,n=3}}},
  {t="Sentry Point", lv=40, n="Follow the road north-west out of Theramore to the watchtower at Sentry Point. Mudrock Burrowers roam the marsh around it.\nArchmage Tervosh waits at the foot of the tower: once you have looked around, hand the quest in to him there, not in Theramore.", g={{"c",1265,txt="Sentry Point explored",m=1445,x=59.9,y=40.9},{"t",1265,n2="Archmage Tervosh, at the tower",m=1445,x=59.7,y=41.2},{"a",1266,m=1445,x=59.7,y=41.2,ml=28},{"o",1204,i=1,txt="Forked Mudrock Tongue x8",m=1445,x=59.2,y=42.4}}},
  {t="Swamplight Manor", lv=40, n="Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house. Jarl wants three Soothing Spices: if you passed Helenia Olden, buy them from her in Theramore first.", g={{"a",1219,m=1445,x=55.4,y=25.9,ml=30},{"a",1218,m=1445,x=55.4,y=26.3,ml=30},{"t",1218,n2="with the spices from Theramore",m=1445,x=55.4,y=26.3},{"a",1206,m=1445,x=55.4,y=26.3,ml=30}}},
  {t="\"Stinky\" Ignatz", lv=40, n="Stinky waits west of the manor, in the marsh below North Point Tower. Lead him to his Bogbean leaves and keep the swamp creatures off him.", g={{"a",1222,m=1445,x=46.9,y=17.5,ml=30},{"c",1222,txt="Help Stinky find Bogbean Leaves",m=1445,x=48.9,y=24.6}}},
  {t="North Point Tower", lv=40, n="Private Hendel holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders.\nArchmage Tervosh and Lady Jaina Proudmoore wait beside the tower: once he yields, hand in to both on the spot.", g={{"t",1266,m=1445,x=45.2,y=24.6},{"a",1324,m=1445,x=45.2,y=24.6,ml=28},{"c",1324,txt="Private Hendel"},{"t",1324,m=1445,x=45.2,y=24.4},{"t",1267,m=1445,x=45.2,y=24.3}}},
  {t="Darkmist Cavern", lv=40, n="The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them.", g={{"o",1206,i=1,txt="Unpopped Darkmist Eye x40",m=1445,x=35.7,y=21.1}}},
  {t="Mudcrush Durtfeet", lv=40, n="Ride south to the giant's hut in the middle of the marsh.", g={{"a",1177,m=1445,x=35.1,y=38.3,ml=32}}},
  {t="The Shady Rest Inn", lv=40, n="The burned inn stands on the road west, toward the Barrens; the guard's badge lies in the ashes.", g={{"a",1252,m=1445,x=29.8,y=48.2,ml=30}}},
  {t="Theramore", lv=40, n="Follow the road east back to Theramore. The officers are in Foothold Citadel.", g={{"t",1219,m=1445,x=65,y=47},{"a",1220,m=1445,x=65,y=47,ml=30},{"t",1252,n2="On the top floor",m=1445,x=68.2,y=48.6},{"a",1259,m=1445,x=68.2,y=48.6,ml=30},{"t",1259,n2="Adjutant Tesoran, on the top floor",m=1445,x=68,y=48.1},{"a",1285,m=1445,x=68,y=48.1,ml=30},{"t",1285,m=1445,x=68.2,y=48.6},{"t",1220,m=1445,x=68.2,y=48.6},{"a",1286,m=1445,x=68.2,y=48.6,ml=30},{"t",1222,n2="Morgan Stern, inside",m=1445,x=66.3,y=45.5},{"t",1204,m=1445,x=66.3,y=45.5},{"a",1258,n2="Morgan Stern: the crawlers are on the Swamp of Sorrows shore, keep it",m=1445,x=66.3,y=45.5,ml=33}}},
  {t="Mirefin murlocs", lv=40, n="The Mirefin murlocs crowd the north coast past Swamplight Manor.", g={{"o",1177,i=1,txt="Mirefin Head x12",m=1445,x=64.4,y=29}}},
