  {t="The Barrens", lv=40, w={{k="onquest",q={1718}}}, f={c={"WARRIOR"}}, g={{"g",0,txt="Klannoc Macleod",m=1413,x=68.6,y=49.2}}},
  {t="The Affray", lv=40, n="On the ride north to Ratchet, Fray Island lies off the Merchant Coast south of the town: wade over the sand bar shallows. Klannoc Macleod sends four challengers and then Big Will (level 33) at you, one at a time.", f={c={"WARRIOR"}}, g={{"t",1718,m=1413,x=68.6,y=49.2},{"a",1719,m=1413,x=68.6,y=49.2,ml=30},{"c",1719,txt="Big Will; Step on the grate to begin the Affray",n2="Defeat the challengers and Big Will"},{"t",1719,n2="Klannoc Macleod: Berserker Stance",m=1413,x=68.6,y=49.2},{"i",0,txt="Klannoc offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."}}},
  {t="Foothold Citadel", lv=40, n="The boat leaves from Theramore: report to Captain Garran Vimes on the top floor of Foothold Citadel on the way to the docks.", w={{k="level",op=">=",n=40}}, f={r={"Human"}}, g={{"t",1287,n2="Captain Garran Vimes, on the top floor",m=1445,x=68.2,y=48.6},{"a",1288,m=1445,x=68.2,y=48.6,ml=30},{"t",1288,n2="Lady Jaina Proudmoore, on the top floor",m=1445,x=66.3,y=49}}},
