  {t="Elwynn Forest", lv=40, w={{k="level",op=">=",n=40}}, f={r={"Human"}}, g={{"g",0,txt="Eastvale Logging Camp",m=1429,x=84.6,y=64.5}}},
  {t="Riding at 40", lv=40, n="At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Randal Hunter teaches Humans at Eastvale Logging Camp in eastern Elwynn Forest, beside Katie Hunter's horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour.", w={{k="level",op=">=",n=40}}, f={r={"Human"}}, g={{"tr",0,txt="Train with Randal Hunter",m=1429,x=84.3,y=64.9,opt=true},{"i",0,txt="Sell and repair at Katie Hunter",n2="Katie Hunter: other colours, 20g",m=1429,x=84.2,y=65.5,opt=true}}},
  {t="Riding at 40", lv=40, n="At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Skyborne learn it from Genn Fairweather, the stablemaster and riding trainer at the Fairweather Stables in Valanaar on Zephras Isle, who also sells the Galestriders: the skyboat to the isle leaves the north side of Dalaran about every five minutes. Collectibles, Mounts · Level 40 lists the Galestriders.", w={{k="level",op=">=",n=40}}, f={r={"Skyborne"}}, g={{"i",0,txt="Riding and Galestriders: Genn Fairweather, at the Fairweather Stables in Valanaar on Zephras Isle."},{"i",0,txt="Skyboat to Zephras Isle: the north side of Dalaran, about every five minutes."}}},
