  {t="Bloodsail camp", lv=40, n="Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks.", g={{"t",595,m=1434,x=27.3,y=69.5},{"a",597,m=1434,x=27.3,y=69.5,ml=37},{"o",610,i=1,txt="Catelyn's Blade",m=1434,x=27.4,y=69.4}}},
