  {t="Ruins of Solarsal", lv=43, n="Walk south along the island to the naga ruins; the gazebo stands among them.", g={{"t",2866,m=1444,x=26.3,y=52.3},{"a",2867,m=1444,x=26.3,y=52.3,ml=40}}},
  {t="Feathermoon Stronghold", lv=43, g={{"t",2867,m=1444,x=30.3,y=46.2},{"a",3130,m=1444,x=30.3,y=46.2,ml=40},{"t",3130,m=1444,x=30.4,y=46.2},{"a",2869,m=1444,x=30.4,y=46.2,ml=40}}},
  {t="Hatecrest naga", lv=43, n="Back to the Ruins of Solarsal. Every Hatecrest naga there can drop scales.", g={{"o",2869,i=1,txt="Hatecrest Naga Scale x10",m=1444,x=28.8,y=50.8}}},
  {t="Feathermoon Stronghold", lv=43, g={{"t",2869,m=1444,x=30.4,y=46.2},{"a",2870,m=1444,x=30.4,y=46.2,ml=40},{"i",0,txt="Lord Shalzaru waits for the end of the mainland loop."}}},
  {t="Boat to The Forgotten Coast", lv=43, g={{"g",0,txt="Boat to The Forgotten Coast",m=1444,x=31,y=39.8}}},
  {t="Feralas", lv=43, g={{"g",0,txt="The courier's boat",m=1444,x=45.4,y=65}}},
  {t="The courier's boat", lv=43, n="Take the boat to the Forgotten Coast and follow the shore south to the wrecked row boat on the beach.", g={{"t",4125,m=1444,x=45.4,y=65},{"a",4127,m=1444,x=45.4,y=65,ml=40}}},
  {t="Gordunni ogres", lv=43, n="Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north.", g={{"o",2982,i=2,txt="Kill Gordunni Shaman x8",m=1444,x=58.4,y=67.5},{"o",2982,i=3,txt="Kill Gordunni Brute x8",m=1444,x=58.6,y=64.9},{"o",2982,i=1,txt="Kill Gordunni Warlock x8",m=1444,x=58.9,y=64.2}}},
  {t="Feral Scar Vale", lv=43, n="Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; Bloodroar the Stalker (level 48) prowls the middle.", g={{"o",2821,i=1,txt="Thick Yeti Hide x10",m=1444,x=55.9,y=58.8},{"o",1452,i=3,txt="Groddoc Liver x3",m=1444,x=57.5,y=56.5}}},
  {t="Isle of Dread", lv=43, n="The Isle of Dread is the island just south of Sardor Isle: swim over. Hatecrest Serpent Guards and Sorceresses hold it; Lord Shalzaru (level 47) waits in the cave at its south end. Pull his guards first.", g={{"o",2870,i=1,txt="Mysterious Relic",n2="Mysterious Relic; below ground",m=1444,x=28.5,y=70.5}}},
  {t="Feathermoon Stronghold", lv=43, n="Coming from the south: Latronicus and Vestia first, then Angelas beside Ginro's building, then the stairs. Ginro Hearthkindle stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Pratt is by the flight master, on the way out.", g={{"t",2870,m=1444,x=30.4,y=46.2},{"a",2871,m=1444,x=30.4,y=46.2,ml=40},{"t",2871,m=1444,x=30.1,y=45.1},{"t",2982,m=1444,x=31.8,y=45.6},{"t",4127,m=1444,x=31.9,y=45.1},{"a",4129,m=1444,x=31.9,y=45.1,ml=40},{"t",4129,n2="Quintis Jonespyre, upstairs",m=1444,x=32.5,y=43.8},{"a",4130,m=1444,x=32.5,y=43.8,ml=40},{"t",4130,m=1444,x=31.9,y=45.1},{"a",4131,m=1444,x=31.9,y=45.1,ml=40},{"t",2821,m=1444,x=30.6,y=42.7},{"a",7733,m=1444,x=30.6,y=42.7,ml=40}}},
  {t="Fly to Thalanaar", lv=43, g={{"g",0,txt="Feathermoon flight master",m=1444,x=30.3,y=43.3},{"z",0,txt="Fly to Thalanaar",at="Thalanaar"}}},
  {t="Feralas", lv=43, g={{"g",0,txt="Grimtotem camp",m=1444,x=65.9,y=45.7}}},
  {t="Grimtotem camp", lv=43, n="From Thalanaar ride west along the road to the Grimtotem camp north of it. Kindal Moonweaver waits outside it; free the Sprite Darters from the pen in the middle and keep Kindal and at least six of them alive.", g={{"a",2969,m=1444,x=65.9,y=45.6,ml=38},{"c",2969,txt="Save at least 6 Sprite Darters from capture"},{"t",2969,m=1444,x=65.9,y=45.6},{"a",2970,m=1444,x=66,y=45.6,ml=38}}},
  {t="Grimtotem tauren", lv=43, g={{"o",2970,i=1,txt="Kill Grimtotem Naturalist x12",m=1444,x=66.8,y=46.2},{"o",2970,i=2,txt="Kill Grimtotem Raider x10",m=1444,x=66.6,y=46.2},{"o",2970,i=3,txt="Kill Grimtotem Shaman x6",m=1444,x=66.6,y=46.4}}},
  {t="Jer'kai Moonweaver", lv=43, g={{"t",2970,m=1444,x=66,y=45.6},{"a",2972,n2="for Tyrande in Darnassus: the route takes you there at 47",m=1444,x=66,y=45.6,ml=38}}},
  {t="The Writhing Deep", lv=43, n="Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to Thalanaar. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out.", g={{"t",4131,m=1444,x=73.3,y=56.3},{"a",4135,m=1444,x=73.3,y=56.3,ml=40},{"h",11463,txt="Get Undelivered Parcel",n2="Undelivered Parcel, from the backpacks",m=1444,x=73.3,y=56.3,n=1},{"a",4281,ml=40},{"t",4135,n2="Zukk'ash Pod, inside",m=1444,x=72.1,y=63.7},{"a",4265,m=1444,x=72.1,y=63.7,ml=40},{"c",4265,txt="Free Raschal."}}},
  {t="High Wilderness: kill these as you meet them", lv=44, n="Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide, and about one in thirty a Pristine Yeti Hide, which Pratt pays for too.\nZorbin's quests on the coast need level 45: grind the yetis here until level 44.5, so the kills also bring Pratt's hides. Or, with a group, run the Zul'Farrak dungeon instead.", g={{"o",1452,i=2,txt="Ironfur Liver x3",m=1444,x=53.2,y=47.3},{"o",7733,i=1,txt="Rage Scar Yeti Hide x10",m=1444,x=54.9,y=32.9},{"l",44,txt="Reach level 44 (50% in): grind Rage Scar Yeti",n2="grind on Rage Scar Yeti",m=1444,x=54.8,y=33,fr=0.5}}},
  {t="Rage Scar Hold", lv=44, n="No Pristine Yeti Hide yet? Keep killing the Rage Scar yetis until one drops, then right-click it.", g={{"h",18969,txt="Get Pristine Yeti Hide",m=1444,x=54.8,y=33,n=1},{"a",7735,ml=40}}},
  {t="Feathermoon Stronghold", lv=44, n="Ginro Hearthkindle stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", g={{"t",4265,m=1444,x=31.9,y=45.1},{"a",4266,m=1444,x=31.9,y=45.1,ml=40},{"t",4266,m=1444,x=30.3,y=46.2},{"a",4267,m=1444,x=30.3,y=46.2,ml=40}}},
  {t="Feathermoon Stronghold", lv=44, g={{"i",0,txt="Shandris then asks you to carry news to Darnassus: skip it, Gadgetzan sends you there instead."},{"t",7733,m=1444,x=30.6,y=42.7},{"t",7735,m=1444,x=30.6,y=42.7}}},
  {t="Boat to The Forgotten Coast", lv=44, g={{"g",0,txt="Boat to The Forgotten Coast",m=1444,x=31,y=39.8}}},
  {t="Grind to 45", lv=45, n="Ride east into Feral Scar Vale. Zorbin's quests on the coast need level 45. Or, with a group, run the Zul'Farrak dungeon or the Uldaman dungeon instead.", g={{"l",45,txt="Reach level 45: grind Feral Scar Yeti",n2="grind on Feral Scar Yeti at Feral Scar Vale, Feralas",m=1444,x=52.3,y=57.9}}},
  {t="Zorbin Fandazzle", lv=45, n="Ride back to the Forgotten Coast; the goblin stands by the dock.", g={{"a",7003,m=1444,x=44.8,y=43.4,ml=45},{"a",7721,m=1444,x=44.8,y=43.4,ml=45}}},
  {t="The Forgotten Coast: kill these as you meet them", lv=45, n="Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with Zorbin's Ultra-Shrinker and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf.", g={{"o",7721,i=1,txt="Water Elemental Core x10",m=1444,x=45,y=46.3},{"o",7003,i=1,txt="Miniaturization Residue x15",m=1444,x=44.3,y=46.6},{"o",7003,i=1,txt="Use Zorbin's Ultra-Shrinker",m=1444,x=44.3,y=46.6}}},
  {t="Zorbin Fandazzle", lv=45, g={{"t",7003,m=1444,x=44.8,y=43.4},{"t",7721,m=1444,x=44.8,y=43.4},{"i",0,txt="Zorbin's refills are level 55: skip them."},{"i",0,txt="The Tanaris guide starts with the trip east, past Thalanaar."}}},
  {t="Thalanaar", lv=45, n="Ride north-east to the night elf outpost on the Thousand Needles border.", w={{k="onquest",q={4281}}}, g={{"t",4281,n2="Falfindel Waywarder walks around Thalanaar: look inside the circle on the map",m=1444,x=89.6,y=46.6}}},
} end)

R:Segment({id="alliance/40-50/04-tanaris",title="Tanaris",faction="Alliance",min=45,max=47,zone=1446,zoneName="Tanaris",next="alliance/40-50/05-the-hinterlands"}, function() return {
  {t="Thousand Needles", lv=45, g={{"g",0,txt="Mirage Raceway",m=1441,x=78.1,y=77.1}}},
  {t="Mirage Raceway", lv=45, n="The Mirage Raceway lies on the Shimmering Flats in south-east Thousand Needles: Fizzle Brassbolts is in the gnomes' camp beside the track, Zamek by the goblin camp.", g={{"t",2769,m=1441,x=78.1,y=77.1},{"t",1137,n2="Fizzle Brassbolts: News for Fizzle, from Martek in the Badlands",m=1441,x=78.1,y=77.1}}},
  {t="Tanaris", lv=45, g={{"g",0,txt="Gadgetzan",m=1446,x=51.6,y=26.8}}},
  {t="Gadgetzan", lv=45, n="Ride south-east off the Shimmering Flats into Tanaris. Gadgetzan is just inside the border.", g={{"t",2864,n2="Tran'rek, north side of town",m=1446,x=51.6,y=26.8},{"a",3362,m=1446,x=51.6,y=26.8,ml=45},{"a",992,m=1446,x=50.2,y=27.5,ml=38},{"fp",39,txt="Get the Gadgetzan flight path (Bera Stonehammer)",m=1446,x=51,y=29.3},{"a",2605,m=1446,x=51.8,y=28.7,ml=44},{"a",1690,n2="Chief Engineer Bilgewhizzle, by the water tower",m=1446,x=52.5,y=28.5,ml=40},{"a",1707,n2="Spigot Operator Luglunket, next to him",m=1446,x=52.5,y=28.4,ml=40},{"b",0,txt="Set your hearthstone at Gadgetzan",m=1446,x=52.5,y=27.9,at="Gadgetzan"},{"a",5863,m=1446,x=52.8,y=27.4,ml=44},{"a",3022,n2="Curgle Cranklehop: his crate goes to Rut'theran Village, later",m=1446,x=52.4,y=26.9,ml=42}}},
  {t="Steamwheedle Port", lv=45, n="Ride east across the dunes to the goblin harbour on the north-east coast.", g={{"a",8365,m=1446,x=66.6,y=22.3,ml=40},{"a",2875,n2="The Wanted poster beside him",m=1446,x=66.8,y=22.3,ml=40},{"a",2781,n2="The same poster: Caliph comes much later, after Gadgetzan",m=1446,x=66.8,y=22.3,ml=39},{"a",8366,n2="Security Chief Bilgewhizzle, inside",m=1446,x=67.1,y=23.9,ml=40},{"t",2872,n2="Stoley, in the port's tavern; inside",m=1446,x=67.1,y=24},{"a",2873,m=1446,x=67.1,y=24,ml=40}}},
  {t="Noonshade Ruins: kill these as you meet them", lv=45, n="Ride back west toward Gadgetzan. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen.", g={{"o",1690,i=2,txt="Kill Wastewander Thief x10",m=1446,x=63.9,y=29.1},{"o",1707,i=1,txt="Wastewander Water Pouch x5",m=1446,x=63.9,y=29.1},{"o",1690,i=1,txt="Kill Wastewander Bandit x10",m=1446,x=63.8,y=29.1}}},
  {t="Gadgetzan", lv=45, g={{"t",1707,m=1446,x=52.5,y=28.4},{"t",1690,m=1446,x=52.5,y=28.5},{"a",1691,m=1446,x=52.5,y=28.5,ml=40}}},
  {t="Waterspring Field", lv=45, n="The tougher Wastewander rogues, shadow mages and assassins camp south-east of Gadgetzan, south of the bandits. Leave Caliph Scorpidsting in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp.", g={{"o",1691,i=3,txt="Kill Wastewander Shadow Mage x10",m=1446,x=58.9,y=35.9},{"h",8483,txt="Get Wastewander Water Pouch x5",m=1446,x=58.9,y=35.9,n=5},{"o",1691,i=1,txt="Kill Wastewander Rogue x8",m=1446,x=58.6,y=36.7},{"o",1691,i=2,txt="Kill Wastewander Assassin x6",m=1446,x=58.8,y=36.4}}},
  {t="Lost Rigger Cove: kill these as you meet them", lv=45, n="Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. Andre Firebeard stands on the far side; Stoley's stolen cargo lies in the camp.\nCareful: Two or three pirates stand with Andre, and many more pirates from the town join the fight once it starts.", g={{"o",8366,i=1,txt="Kill Southsea Pirate x10",m=1446,x=70.5,y=43},{"o",8365,i=1,txt="Southsea Pirate Hat x20",m=1446,x=70.5,y=43},{"o",8366,i=2,txt="Kill Southsea Freebooter x10",m=1446,x=71,y=43.1},{"o",8366,i=4,txt="Kill Southsea Swashbuckler x10",m=1446,x=72.2,y=46.6},{"o",2873,i=1,txt="Stoley's Shipment",n2="Stoley's Shipment; upstairs",m=1446,x=72.1,y=46.7},{"o",8366,i=3,txt="Kill Southsea Dock Worker x10",m=1446,x=72.9,y=47.8},{"o",2875,i=1,txt="Firebeard's Head",m=1446,x=73.4,y=47.1}}},
  {t="Steamwheedle Port", lv=45, g={{"t",2873,n2="Stoley, inside",m=1446,x=67.1,y=24},{"a",2874,n2="\"Sea Wolf\" MacKinley in Booty Bay: the route takes you there at the end of the Hinterlands guide, keep it",m=1446,x=67.1,y=24,ml=40},{"t",2875,n2="Security Chief Bilgewhizzle, inside",m=1446,x=67.1,y=23.9},{"t",8366,m=1446,x=67.1,y=23.9},{"t",8365,m=1446,x=66.6,y=22.3}}},
  {t="Noonshade Ruins", lv=45, n="Careful: Thieves cast Disarm. Rogues stay hidden with Sneak. Assassins use Execute when your health is at 20% or lower.", g={{"h",8483,txt="Get Wastewander Water Pouch x5",m=1446,x=63.9,y=29.1,n=5}}},
  {t="Gadgetzan", lv=45, g={{"t",1878,m=1446,x=52.5,y=28.4},{"t",1691,m=1446,x=52.5,y=28.5}}},
  {t="The pool by Sandsorrow Watch", lv=45, n="Ride north-west to the Sandfury troll camp at Sandsorrow Watch. Use the Untapped Dowsing Widget at the edge of its pool; the trolls stand close, so pull the nearest first.", g={{"o",992,i=1,txt="Pool by Sandsorrow Watch",n2="Gives the Tapped Dowsing Widget",m=1446,x=39.9,y=28.4}}},
  {t="Gadgetzan", lv=45, g={{"t",992,m=1446,x=50.2,y=27.5},{"a",82,m=1446,x=50.2,y=27.5,ml=39}}},
  {t="The Broken Pillar", lv=45, n="Ride south to the dig camp at the Broken Pillar. Marvon hands you a detector helm: wear it to see the Gahz'ridian mounds, which lie thick in the sand around the camp and south-west toward the ogres.", g={{"a",3161,m=1446,x=52.7,y=45.9,ml=43},{"o",3161,i=1,txt="Gahz'ridian Ornament x30",m=1446,x=52.3,y=45.3},{"t",3161,m=1446,x=52.7,y=45.9}}},
  {t="Rhapsody's Kalimdor Kocktail", lv=45, g={{"o",1452,i=1,txt="Roc Gizzard x3",m=1446,x=43.5,y=40.6}}},
  {t="The Noxious Lair", lv=45, n="Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast Silithid Swarm both in and out of combat, which brings small adds that interrupt you.", g={{"o",82,i=1,txt="Centipaar Insect Parts x5",m=1446,x=36.1,y=39.5}}},
  {t="Dunemaul Compound", lv=47, n="Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; Gor'marok the Ravager (49) stands in the middle with guards around him: clear them first.", g={{"o",5863,i=1,txt="Kill Dunemaul Brute x10",m=1446,x=39.3,y=51.2},{"o",5863,i=2,txt="Kill Dunemaul Enforcer x10",m=1446,x=39.9,y=50.9},{"o",5863,i=3,txt="Kill Gor'marok the Ravager",n2="Gor'marok the Ravager, below ground",m=1446,x=41.5,y=57.8},{"l",47,txt="Reach level 47 (6% in): grind Dunemaul Brute",n2="grind on Dunemaul Brute",m=1446,x=41.4,y=56.7,fr=0.06}}},
  {t="Thistleshrub Valley: kill these as you meet them", lv=47, n="Ride south into Thistleshrub Valley. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs.", g={{"o",2605,i=1,txt="Laden Dew Gland",m=1446,x=31.2,y=64.7},{"o",3362,i=2,txt="Kill Thistleshrub Rootshaper x8",m=1446,x=31,y=65.3},{"o",3362,i=1,txt="Kill Gnarled Thistleshrub x8",m=1446,x=31.2,y=65.5}}},
  {t="Tooga's escort", lv=47, n="The little turtle Tooga hides at the north end of the valley. Lead him home to his wife Torta, by the water just east of Steamwheedle Port: he walks slowly and the desert's beasts go for him, so keep him alive.", g={{"a",1560,m=1446,x=30,y=65,ml=40},{"c",1560,txt="Torta"},{"t",1560,m=1446,x=66.6,y=25.7}}},
  {t="Gadgetzan", lv=47, n="Ride back west to Gadgetzan: Andi Lynn stands on the east side of town, where you come in.", g={{"t",5863,m=1446,x=52.8,y=27.4},{"t",2605,m=1446,x=51.8,y=28.7},{"a",2606,m=1446,x=51.8,y=28.7,ml=44},{"t",3362,m=1446,x=51.6,y=26.8},{"t",2606,m=1446,x=51.1,y=26.9},{"a",2641,m=1446,x=51.1,y=26.9,ml=44},{"t",82,n2="Alchemist Pestlezugg, inside",m=1446,x=50.9,y=27},{"a",10,m=1446,x=50.2,y=27.5,ml=39}}},
  {t="Caliph Scorpidsting", lv=47, n="Ride south-east to Waterspring Field. Caliph stands in the middle of the southern Wastewander camp: clear around him first.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them.", g={{"o",2781,i=1,txt="Caliph Scorpidsting's Head",m=1446,x=61.8,y=38.2}}},
  {t="The Gaping Chasm", lv=47, n="Ride south past the Broken Pillar to the Gaping Chasm, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds.", g={{"o",10,i=1,txt="Scrimshank's Surveying Gear",n2="Scrimshank's Surveying Gear; below ground",m=1446,x=56,y=71.2}}},
  {t="Gadgetzan", lv=47, g={{"t",2781,m=1446,x=52.5,y=28.5},{"t",10,m=1446,x=50.2,y=27.5},{"a",110,m=1446,x=50.2,y=27.5,ml=39},{"t",110,n2="Alchemist Pestlezugg, inside",m=1446,x=50.9,y=27},{"a",113,m=1446,x=50.9,y=27,ml=39},{"t",113,m=1446,x=50.2,y=27.5},{"a",162,n2="for Darnassus: the route takes you there at 47",m=1446,x=50.2,y=27.5,ml=39}}},
  {t="Fly to Theramore", lv=47, g={{"g",0,txt="Gadgetzan flight master",m=1446,x=51,y=29.3},{"z",0,txt="Fly to Theramore",at="Theramore"}}},
  {t="Boat to Menethil Harbor", lv=47, g={{"g",0,txt="Boat to Menethil Harbor",m=1445,x=71.6,y=56.4}}},
  {t="Fly to Aerie Peak", lv=47, g={{"g",0,txt="Menethil Harbor flight master",m=1437,x=9.5,y=59.7},{"z",0,txt="Fly to Aerie Peak",at="Aerie Peak"}}},
  {t="Aerie Peak", lv=47, g={{"a",2989,n2="Gryphon Master Talonaxe, beside the flight master",m=1425,x=9.8,y=44.5,ml=40},{"a",2877,n2="Fraggar Thundermantle, inside",m=1425,x=14.8,y=44.6,ml=40}}},
  {t="The Hinterlands", lv=47, g={{"g",0,txt="Rhapsody Shindigger",m=1425,x=26.9,y=48.6}}},
  {t="Rhapsody Shindigger", lv=47, g={{"t",1452,m=1425,x=26.9,y=48.6},{"a",1469,m=1425,x=26.9,y=48.6,ml=38}}},
  {t="Sprinkle's Secret Ingredient", lv=47, g={{"o",2641,i=1,txt="Violet Tragan",n2="Underwater",m=1425,x=41,y=59.8}}},
} end)

R:Segment({id="alliance/40-50/05-the-hinterlands",title="The Hinterlands, Blasted Lands & Loch Modan",faction="Alliance",min=47,max=48,zone=1425,zoneName="The Hinterlands",next="alliance/40-50/06-searing-gorge"}, function() return {
  {t="The Altar of Zul", lv=47, n="Ride south-east to the Altar of Zul, the stepped Vilebranch temple in the south of the Hinterlands, and climb to the top. Qiaga and Morta'gya the Keeper (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including Qiaga the Keeper and Morta'gya the Keeper, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group.", w={{k="onquest",q={2989}}}, g={{"g",0,txt="Go here",m=1425,x=49,y=68.7},{"c",2989,txt="Search the Altar of Zul",m=1425,x=49,y=68.7}}},
  {t="Skulk Rock", lv=47, n="Ride north to Skulk Rock in the middle of the Hinterlands. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth.", g={{"o",2877,i=1,txt="Kill Green Sludge x10",m=1425,x=48.9,y=55.4},{"o",2877,i=2,txt="Kill Jade Ooze x10",m=1425,x=49.4,y=53.1}}},
  {t="Aerie Peak", lv=47, g={{"t",2881,n2="Inside",m=1425,x=14.8,y=44.6,opt=true},{"t",2877,m=1425,x=14.8,y=44.6},{"t",2989,n2="Gryphon Master Talonaxe, inside",m=1425,x=9.8,y=44.5},{"a",2990,n2="for Thadius Grimshade at Nethergarde Keep, later",m=1425,x=9.8,y=44.5,ml=40}}},
