  {t="Morgan's Vigil flight master", lv=47, g={{"g",0,txt="Morgan's Vigil flight master",m=1428,x=84.4,y=68.3},{"fp",71,txt="Get the Morgan's Vigil flight path (Borgus Stoutarm)",m=1428,x=84.3,y=68.3}}},
  {t="Fly to Thelsamar", lv=47, g={{"g",0,txt="Morgan's Vigil flight master",m=1428,x=84.4,y=68.3},{"z",0,txt="Fly to Thelsamar",at="Thelsamar"}}},
  {t="Thelsamar", lv=47, n="Set your hearth here: the Searing Gorge guide starts from Thelsamar.", g={{"b",0,txt="Set your hearthstone at Stoutlager Inn",m=1432,x=35.5,y=48.4,at="Stoutlager Inn"}}},
  {t="Fly to Menethil Harbor", lv=47, g={{"g",0,txt="Thelsamar flight master",m=1432,x=33.9,y=50.8},{"z",0,txt="Fly to Menethil Harbor",at="Menethil Harbor"}}},
  {t="Boat to Auberdine", lv=47, g={{"g",0,txt="Boat to Auberdine",m=1437,x=4.7,y=57}}},
