  {t="Rut'theran Village", lv=47, n="Daryn Lightwind stands upstairs, above Erelas Ambersky: go up inside, the arrow cannot tell the floors apart.", g={{"fp",27,txt="Get the Rut'theran Village flight path (Vesprystus)",m=1438,x=58.4,y=94},{"t",2939,m=1438,x=55.4,y=92.2},{"i",0,txt="Daryn's next errand goes to Tanaris: skip it."},{"t",3022,m=1438,x=55.5,y=92},{"a",3661,n2="Erelas Ambersky: keep it, the feathers come at the end of the Burning Steppes guide",m=1438,x=55.5,y=92,ml=42},{"a",2940,n2="the book on her table",m=1438,x=55.2,y=91.5,ml=42},{"t",2940,m=1438,x=55.4,y=92.2},{"a",2941,m=1438,x=55.4,y=92.2,ml=42}}},
  {t="Portal to Darnassus", lv=47, g={{"g",0,txt="Portal to Darnassus",m=1438,x=55.9,y=89.3}}},
  {t="Temple of the Moon", lv=47, n="Step through the portal into Darnassus. The Temple of the Moon is in the south of the city.", g={{"t",2972,m=1457,x=39.1,y=81.6},{"t",4267,m=1457,x=41.8,y=85.6},{"t",162,n2="Gracina Spiritmight, beside her",m=1457,x=41.8,y=85.6}}},
