  {t="Darkshire", lv=47, g={{"a",1395,m=1431,x=75.8,y=46.2,ml=40}}},
  {t="Blasted Lands", lv=47, g={{"g",0,txt="Bloodmage Drazial",m=1419,x=50.6,y=14.2}}},
  {t="The bloodmages", lv=47, n="The bloodmages' camp is the first stop beside the road into the Blasted Lands, north-west of Nethergarde Keep.", g={{"a",2581,m=1419,x=50.5,y=14.2,ml=45},{"a",2583,m=1419,x=50.5,y=14.2,ml=45},{"a",2585,m=1419,x=50.5,y=14.2,ml=45},{"a",2601,m=1419,x=50.6,y=14.3,ml=45},{"a",2603,m=1419,x=50.6,y=14.3,ml=45}}},
  {t="Nethergarde Keep", lv=47, n="Ride on east along the road to the keep first: the Crate of Power Stones expires an hour after Darkshire, and the bloodmages' beasts take longer than that.", g={{"t",2990,n2="Thadius Grimshade, at the top of the keep",m=1419,x=66.9,y=19.5},{"i",0,txt="Thadius' next task, Nekrum's Medallion, is a Zul'Farrak quest: skip it."},{"t",1364,n2="Watcher Mahar Ba, upstairs",m=1419,x=67.7,y=19.2},{"fp",45,txt="Get the Nethergarde Keep flight path (Alexandra Constantine)",m=1419,x=65.5,y=24.3},{"t",1395,m=1419,x=66.5,y=21.4},{"t",1425,m=1419,x=66.5,y=21.4}}},
  {t="Blasted Lands: kill these as you meet them", lv=47, n="Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. Black Slayer vultures circle over all of it. Pull one at a time.\nAshmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52.\nCareful: Scorpok Stingers use Venom Sting; Clack the Reaver adds Knockdown.", g={{"o",2585,i=2,txt="Vulture Gizzard x2",m=1419,x=62.4,y=26.6},{"o",2601,i=2,txt="Vulture Gizzard x2",m=1419,x=62.4,y=26.6},{"o",2603,i=1,txt="Vulture Gizzard x10",m=1419,x=62.4,y=26.6},{"o",2581,i=2,txt="Blasted Boar Lung x2",m=1419,x=62.3,y=26.7},{"o",2583,i=1,txt="Blasted Boar Lung x3",m=1419,x=62.3,y=26.7},{"o",2585,i=3,txt="Blasted Boar Lung",m=1419,x=62.3,y=26.7},{"o",2601,i=1,txt="Basilisk Brain x10",m=1419,x=61.8,y=26.2},{"o",2583,i=3,txt="Basilisk Brain",m=1419,x=61.8,y=26.2},{"o",2581,i=1,txt="Snickerfang Jowl x3",m=1419,x=61.5,y=35.1},{"o",2603,i=2,txt="Snickerfang Jowl x2",m=1419,x=61.5,y=35.1},{"o",2581,i=3,txt="Scorpok Pincer",m=1419,x=60.9,y=35.4},{"o",2583,i=2,txt="Scorpok Pincer x2",m=1419,x=60.9,y=35.4},{"o",2585,i=1,txt="Scorpok Pincer x3",m=1419,x=60.9,y=35.4}}},
  {t="The bloodmages", lv=47, g={{"t",2601,m=1419,x=50.6,y=14.3},{"t",2603,m=1419,x=50.6,y=14.3},{"t",2581,m=1419,x=50.5,y=14.2},{"t",2583,m=1419,x=50.5,y=14.2},{"t",2585,m=1419,x=50.5,y=14.2},{"i",0,txt="The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."}}},
  {t="Fly to Booty Bay", lv=47, g={{"g",0,txt="Nethergarde Keep flight master",m=1419,x=65.5,y=24.4},{"z",0,txt="Fly to Booty Bay",at="Booty Bay"}}},
  {t="Booty Bay", lv=47, g={{"t",2874,n2="\"Sea Wolf\" MacKinley, on the top floor",m=1434,x=27.8,y=77.1},{"a",608,n2="Fleet Master Seahorn, top floor",m=1434,x=27.2,y=77,ml=37}}},
  {t="The Bloodsail captains", lv=47, n="The three Bloodsail ships lie at anchor off the coast just south of Booty Bay: Captain Stillwater (45) and Captain Keelhaul (46) on the nearer decks, Fleet Master Firallon (48) on the flagship, each with a crew of 42-45 pirates. Swim out, clear each deck from the edge and pull one at a time.", g={{"o",608,i=1,txt="Kill Captain Stillwater",m=1434,x=32.9,y=88.2},{"o",608,i=2,txt="Kill Captain Keelhaul",m=1434,x=29.3,y=88.3},{"o",608,i=3,txt="Kill Fleet Master Firallon",m=1434,x=30.6,y=90.6}}},
  {t="Booty Bay", lv=47, g={{"t",608,n2="Fleet Master Seahorn, top floor",m=1434,x=27.2,y=77}}},
  {t="Monogrammed Sash", lv=47, n="These are elite mobs: grouping up is encouraged, look for people to do it with. The Monogrammed Sash needs a group of 2. Skip it if you are alone: the route has you grind the XP back.", w={{k="group",q=8552}}, g={{"h",3985,txt="Get Monogrammed Sash",m=1434,x=23.3,y=72.1,n=1,grp=true},{"a",8552,ml=35}}},
  {t="Captain Hecklebury Smotts", lv=47, w={{k="group",q=8552}}, g={{"t",8552,m=1434,x=26.7,y=73.6},{"a",8553,m=1434,x=26.7,y=73.6,ml=35}}},
  {t="Sprogger", lv=47, w={{k="group",q=8552}}, g={{"t",8553,m=1434,x=26.7,y=73.6}}},
  {t="Sprogger", lv=47, w={{k="group",q=8554}}, g={{"a",8554,m=1434,x=26.7,y=73.6,ml=35}}},
  {t="Facing Negolash", lv=47, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Negolash (level 52 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.", w={{k="group",q=8554}}, g={{"o",8554,i=1,txt="Smotts' Cutlass",m=1434,x=32.5,y=81.6,grp=true}}},
  {t="Captain Hecklebury Smotts", lv=47, w={{k="group",q=8554}}, g={{"t",8554,m=1434,x=26.7,y=73.6}}},
} end)

R:Segment({id="alliance/40-50/06-searing-gorge",title="Searing Gorge",faction="Alliance",min=48,max=49,zone=1427,zoneName="Searing Gorge",next="alliance/40-50/07-un-goro-crater"}, function() return {
  {t="To Stoutlager Inn", lv=48, g={{"g",0,txt="Stoutlager Inn",m=1432,x=35.5,y=48.4}}},
  {t="Into Searing Gorge", lv=48, g={{"g",0,txt="Into Searing Gorge",m=1427,x=76.6,y=56.7}}},
  {t="Searing Gorge", lv=48, g={{"g",0,txt="The Grimesilt outhouse",m=1427,x=65.6,y=62.2}}},
  {t="The Grimesilt outhouse", lv=48, n="From Thelsamar ride south into the Badlands, then west past the Horde town of Kargath (give it room) and up the trail into Searing Gorge: the Grimesilt Dig Site is just inside, in the south-east. The prisoner in the wooden outhouse wants 15 Silk Cloth and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one.", g={{"a",4449,m=1427,x=65.6,y=62.2,ml=43}}},
  {t="The Grimesilt outhouse", lv=48, g={{"o",4449,i=1,txt="Kill Dark Iron Geologist x8",m=1427,x=63.9,y=60.4},{"o",4449,i=2,txt="Silk Cloth x15",m=1427,x=63.9,y=60.4},{"t",4449,m=1427,x=65.6,y=62.2},{"i",0,txt="The prisoner's next task, Ledger from Tanaris, sends you to the Swamp of Sorrows and Dustwallow Marsh: skip it."}}},
  {t="Level 48.27", lv=48, n="If you skipped The Monogrammed Sash or Facing Negolash, grind here to level 48.27 to stay on the route's plan. Or, with a group, run the Maraudon dungeon or the Zul'Farrak dungeon instead.", w={{k="level",op="<",n=48,frac=0.27}}, g={{"g",0,txt="Dark Iron Geologist",m=1427,x=63.3,y=60.6},{"l",48,txt="Reach level 48 (27% in): grind Dark Iron Geologist",n2="grind on Dark Iron Geologist",m=1427,x=63.1,y=61.3,fr=0.27}}},
  {t="Dorius Stonetender", lv=48, n="Dorius stands by the road beside the Grimesilt Dig Site. Escort him north-east to Dustfire Valley and keep him alive; when it is over, read the Singed Letter he leaves on the road.", g={{"a",3367,m=1427,x=63.9,y=61,ml=40},{"c",3367,txt="Dorius Escort"},{"t",3367,m=1427,x=74.5,y=19.3},{"a",3368,n2="For Curator Thorius in Ironforge, at the end of this guide",m=1427,x=74.5,y=19.3,ml=40}}},
  {t="Thorium Point", lv=48, n="Ride west along the north of the Gorge to Thorium Point, the scaffolded camp on the north-west rim.", g={{"fp",74,txt="Get the Thorium Point flight path (Lanie Reed)",m=1427,x=37.9,y=30.9},{"a",7722,m=1427,x=38.8,y=28.5,ml=45},{"a",7727,m=1427,x=38.6,y=27.8,ml=45},{"a",7724,m=1427,x=38.6,y=27.8,ml=45},{"a",7723,m=1427,x=38.6,y=27.8,ml=45},{"a",7729,m=1427,x=37.6,y=26.5,ml=45},{"a",7728,n2="The Wanted/Missing/Lost & Found board",m=1427,x=37.6,y=26.5,ml=45}}},
  {t="Thorium Point", lv=48, w={{k="group",q=7701}}, g={{"a",7701,m=1427,x=37.6,y=26.5,ml=45}}},
  {t="Zamael Lunthistle", lv=48, n="The night elf stands alone west of Thorium Point. Hear his story.", g={{"a",3377,m=1427,x=29.6,y=26.3,ml=40}}},
  {t="Prayer to Elune", lv=48, g={{"o",3377,i=1,txt="Talk to Zamael Lunthistle",m=1427,x=29.6,y=26.3}}},
  {t="Zamael Lunthistle", lv=48, g={{"t",3377,m=1427,x=29.6,y=26.3}}},
  {t="Greater Lava Spiders", lv=48, n="The spiders roam the plateaus and lava pools south of Zamael, on the way to Velarok.", g={{"o",7724,i=1,txt="Kill Greater Lava Spider x20",m=1427,x=27.1,y=37.3}}},
  {t="Velarok Windblade", lv=48, n="Velarok stands on the rim of the Cauldron, south of Thorium Point. Listen to his story.", g={{"a",3441,m=1427,x=39.1,y=39,ml=40}}},
  {t="Divine Retribution", lv=48, g={{"o",3441,i=1,txt="Talk to Velarok Windblade",m=1427,x=39.1,y=39}}},
  {t="Velarok Windblade", lv=48, g={{"t",3441,m=1427,x=39.1,y=39},{"a",3442,m=1427,x=39.1,y=39,ml=40}}},
  {t="Golems and elementals", lv=48, n="Heavy War Golems patrol the floor of the Cauldron below Velarok; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts.", g={{"o",3442,i=1,txt="Heart of Flame x4",m=1427,x=38.7,y=41.4},{"o",3442,i=2,txt="Golem Oil x4",m=1427,x=38.7,y=41.4},{"o",7723,i=1,txt="Kill Heavy War Golem x20",m=1427,x=39.9,y=44.2}}},
  {t="Velarok Windblade", lv=48, g={{"t",3442,m=1427,x=39.1,y=39},{"a",3443,m=1427,x=39.1,y=39,ml=40}}},
  {t="Dark Iron dwarves: kill these as you meet them", lv=48, n="Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a Thorium Plated Dagger. The Steamsmiths work at the furnaces in the middle (the Smithing Tuyere), the Lookouts stand on the southern ridges (the Spyglass). Any Dark Iron may drop the Grimesilt Outhouse Key: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee.", g={{"o",7729,i=1,txt="Kill Dark Iron Taskmaster x15",m=1427,x=37.5,y=39.6},{"o",7729,i=2,txt="Kill Dark Iron Slaver x15",m=1427,x=38.4,y=38},{"o",3443,i=1,txt="Thorium Plated Dagger x8",m=1427,x=38.4,y=38},{"o",7728,i=2,txt="Lookout's Spyglass",m=1427,x=33.7,y=51.9},{"h",11818,txt="Get Grimesilt Outhouse Key",m=1427,x=33.7,y=51.9,n=1,opt=true},{"a",4451,opt=true,ml=43},{"o",7728,i=1,txt="Smithing Tuyere",m=1427,x=37.7,y=49.6}}},
  {t="Velarok Windblade", lv=48, g={{"t",3443,m=1427,x=39.1,y=39}}},
  {t="Thorium Point", lv=48, g={{"t",7729,m=1427,x=39,y=27.5},{"t",7728,m=1427,x=39,y=27.5},{"t",7723,m=1427,x=38.6,y=27.8},{"t",7724,m=1427,x=38.6,y=27.8}}},
  {t="Searing Gorge: kill these as you meet them", lv=48, n="The Slag Pit opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of Overseer Maltorius and his elite guards deep inside.", g={{"o",7722,i=1,txt="Secret Plans: Fiery Flux",n2="Secret Plans: Fiery Flux; below ground",m=1427,x=40.5,y=35.7},{"o",7727,i=1,txt="Kill Incendosaur x20",m=1427,x=43.4,y=28.3}}},
  {t="Searing Gorge: kill these as you meet them", lv=48, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Overseer Maltorius is a level 50 elite: most classes solo it at level 52, but you may need help. Skip it if you are alone: the route has you grind the XP back.", w={{k="group",q=7701}}, g={{"o",7701,i=1,txt="Head of Overseer Maltorius",m=1427,x=40.8,y=35.9,grp=true}}},
  {t="Lookout Captain Lolo Longstriker", lv=48, w={{k="group",q=7701}}, g={{"t",7701,m=1427,x=37.7,y=26.6}}},
  {t="Level 48.66", lv=48, n="If you skipped WANTED: Overseer Maltorius, grind here to level 48.66 to stay on the route's plan. Or, with a group, run the Maraudon dungeon or the Zul'Farrak dungeon instead.", w={{k="group",neg=true,q=7701},{k="level",op="<",n=48,frac=0.66}}, g={{"g",0,txt="Incendosaur",m=1427,x=46,y=22},{"l",48,txt="Reach level 48 (66% in): grind Incendosaur",n2="grind on Incendosaur",m=1427,x=45.1,y=21.5,fr=0.66}}},
  {t="Velarok Windblade", lv=48, w={{k="group",q=3452}}, g={{"a",3452,m=1427,x=39.1,y=39,ml=40}}},
  {t="The Flame's Casing", lv=48, n="These are elite mobs: grouping up is encouraged, look for people to do it with. Twilight Dark Shaman (level 50 elite) needs a group of 3. Skip it if you are alone: the route has you grind the XP back.", w={{k="group",q=3452}}, g={{"o",3452,i=1,txt="Symbol of Ragnaros",m=1427,x=23.5,y=36.5,grp=true}}},
  {t="Velarok Windblade", lv=48, w={{k="group",q=3452}}, g={{"t",3452,m=1427,x=39.1,y=39},{"a",3453,m=1427,x=39.1,y=39,ml=40}}},
  {t="The Torch of Retribution", lv=48, n="Listen to Velarok's story once more.", w={{k="onquest",q={3453}}}, g={{"o",3453,i=1,txt="Talk to Velarok Windblade",m=1427,x=39.1,y=39}}},
