  {t="Level 48.98", lv=48, n="If you skipped The Flame's Casing, grind here to level 48.98 to stay on the route's plan. Or, with a group, run the Maraudon dungeon or the Zul'Farrak dungeon instead.", w={{k="group",neg=true,q=3452},{k="level",op="<",n=48,frac=0.98}}, g={{"g",0,txt="Dark Iron Slaver",m=1427,x=39.2,y=38.9},{"l",48,txt="Reach level 48 (98% in): grind Dark Iron Slaver",n2="grind on Dark Iron Slaver",m=1427,x=39.1,y=37.9,fr=0.98}}},
