  {t="Marshal's Refuge", lv=49, n="Ride west back to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and Un'Goro Dirt Pile you pass from here on.", g={{"a",4503,n2="Shizzle, at the refuge entrance",m=1449,x=44.2,y=11.6,ml=49},{"a",4141,m=1449,x=42.9,y=9.6,ml=47},{"a",3882,m=1449,x=43.5,y=7.4,ml=49},{"a",3883,m=1449,x=43.9,y=7.2,ml=48},{"a",3881,m=1449,x=44,y=7.1,ml=48},{"fp",79,txt="Get the Marshal's Refuge flight path (Gryfe)",m=1449,x=45.2,y=5.8},{"t",3884,m=1449,x=44,y=7.1,opt=true},{"t",3845,n2="Linken, at the back of the refuge",m=1449,x=44.7,y=8.1},{"a",3908,n2="Ends with Donova Snowden in Winterspring: keep it",m=1449,x=44.7,y=8.1,ml=47},{"a",4284,n2="J.D. Collie, at the back of the cave; below ground",m=1449,x=41.9,y=2.7,ml=47}}},
  {t="Fire Plume Ridge and the eastern jungle", lv=49, n="Ride south to Fire Plume Ridge in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around Fire Plume Ridge: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's Crate of Foodstuffs sits at an abandoned camp in the eastern jungle.", g={{"o",4141,i=1,txt="Bloodpetal x15",m=1449,x=46.4,y=22.2},{"o",4503,i=1,txt="Webbed Diemetradon Scale x8",m=1449,x=46.2,y=24.7}}},
  {t="Lakkari Tar Pits", lv=49, g={{"o",4284,i=4,txt="Blue Power Crystal x7",m=1449,x=39.7,y=26.8},{"o",4284,i=3,txt="Green Power Crystal x7",m=1449,x=39.7,y=26.8},{"o",4284,i=1,txt="Red Power Crystal x7",m=1449,x=39.7,y=26.8},{"o",4284,i=2,txt="Yellow Power Crystal x7",m=1449,x=39.7,y=26.8}}},
  {t="Marshal's Refuge", lv=49, g={{"t",4284,n2="J.D. Collie, below ground",m=1449,x=41.9,y=2.7},{"a",4285,m=1449,x=41.9,y=2.7,ml=47},{"a",4287,m=1449,x=41.9,y=2.7,ml=47},{"a",4288,m=1449,x=41.9,y=2.7,ml=47},{"t",4141,m=1449,x=42.9,y=9.6},{"a",4142,n2="For Gregan Brewspewer in Feralas: keep it",m=1449,x=42.9,y=9.6,ml=47}}},
  {t="Northern Pylon", lv=49, n="The pylon stands on the slope east of the refuge. Pterrordax circle the slopes around it: they count for Spraggle and drop Shizzle's scales.", g={{"g",0,txt="Northern Crystal Pylon",m=1449,x=56.5,y=12.5},{"o",4285,i=1,txt="Northern Crystal Pylon",m=1449,x=56.5,y=12.5},{"o",4503,i=2,txt="Webbed Pterrordax Scale x8",m=1449,x=56.4,y=11.4},{"o",4503,i=1,txt="Webbed Diemetradon Scale x8",m=1449,x=50.8,y=19.9}}},
  {t="A-Me 01", lv=49, n="Ride east to Ironstone Plateau, where the robot stands among the gorillas. Stay out of the deep cave there.", g={{"t",4243,n2="Below ground",m=1449,x=67.7,y=16.8}}},
  {t="Level 49.51", lv=49, n="Top up here to level 49.51 before the hand-ins at Marshal's Refuge: they take you to level 50. Or, with a group, run the Maraudon dungeon instead.", w={{k="level",op="<",n=49,frac=0.51}}, g={{"g",0,txt="Pterrordax",m=1449,x=57,y=10.2},{"l",49,txt="Reach level 49 (51% in): grind Pterrordax",n2="grind on Pterrordax",m=1449,x=57.2,y=10.2,fr=0.51}}},
  {t="Crate of Foodstuffs", lv=49, n="Ride south down the east side. Young Diemetradons graze the eastern jungle and Fledgling Pterrordax fly near the eastern cliffs; both drop Shizzle's scales. The crate sits at the abandoned camp in the eastern jungle.", g={{"o",3881,i=1,txt="Crate of Foodstuffs",m=1449,x=68.5,y=36.5},{"o",4503,i=1,txt="Webbed Diemetradon Scale x8",m=1449,x=65.4,y=35.3}}},
  {t="Eastern Pylon", lv=49, n="The pylon stands on the eastern cliffs.", g={{"g",0,txt="Eastern Crystal Pylon",m=1449,x=77.2,y=50},{"o",4287,i=1,txt="Eastern Crystal Pylon",m=1449,x=77.2,y=50}}},
  {t="The Gorishi hive", lv=49, n="Ride south-west past Torwa: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop Un'Goro Soil; Pterrordax nest on the southern cliffs if you still need kills.\nCareful: Gorishi silithids are level 51-54 and cast Silithid Pox or Tunneler Acid in melee; Gorishi Workers have a 50% chance to call for help within 25 yd once they fall below 45% health.", g={{"o",3883,i=1,txt="Use Unused Scraping Vial",m=1449,x=48.7,y=85.3},{"o",3883,i=1,txt="Hive Wall Sample",m=1449,x=48.7,y=85.3},{"o",3764,i=1,txt="Un'Goro Soil x20",m=1449,x=48.4,y=85.2},{"l",49,txt="Reach level 49 (60% in): grind Frenzied Pterrordax",n2="grind on Frenzied Pterrordax",m=1449,x=40.2,y=76.2,fr=0.6}}},
  {t="Bones and equipment", lv=49, n="Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's Research Equipment lies in the south-west jungle.", g={{"o",3881,i=2,txt="Research Equipment",m=1449,x=38.5,y=66.1},{"o",3882,i=1,txt="Dinosaur Bone x8",m=1449,x=36.3,y=65.2},{"o",4503,i=1,txt="Webbed Diemetradon Scale x8",m=1449,x=35.6,y=61.1},{"l",49,txt="Reach level 49 (79% in): grind Elder Diemetradon",n2="grind on Elder Diemetradon",m=1449,x=35.6,y=61.1,fr=0.79}}},
  {t="Western Pylon", lv=49, n="The pylon stands on the western cliffs. Frenzied Pterrordax fly over the whole west side.", g={{"g",0,txt="Western Crystal Pylon",m=1449,x=23.9,y=59.2},{"o",4288,i=1,txt="Western Crystal Pylon",m=1449,x=23.9,y=59.2}}},
  {t="Marshal's Refuge", lv=50, n="Ride north along the western jungle back to the refuge.", g={{"t",4503,n2="Shizzle, at the refuge's entrance",m=1449,x=44.2,y=11.6},{"t",3882,m=1449,x=43.5,y=7.4},{"t",3883,m=1449,x=43.9,y=7.2},{"t",3881,m=1449,x=44,y=7.1},{"t",4285,n2="J.D. Collie, below ground",m=1449,x=41.9,y=2.7},{"t",4287,m=1449,x=41.9,y=2.7},{"t",4288,m=1449,x=41.9,y=2.7},{"a",4321,m=1449,x=41.9,y=2.7,ml=47},{"t",4321,m=1449,x=41.9,y=2.7},{"l",50,txt="Reach level 50",f={c={"PRIEST","MAGE"}}}}},
  {t="Fly to Astranaar", lv=50, n="The Ironforge quests were taken at the end of the Searing Gorge guide: fly straight on to Ashenvale for Azshara.", f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","SHAMAN","WARLOCK","DRUID"}}, g={{"g",0,txt="Marshal's Refuge flight master",m=1449,x=45.3,y=6},{"z",0,txt="Fly to Astranaar",at="Astranaar"}}},
  {t="To Stoutlager Inn", lv=50, f={c={"PRIEST","MAGE"}}, g={{"g",0,txt="Stoutlager Inn",m=1432,x=35.5,y=48.4}}},
  {t="Fly to Ironforge", lv=50, f={c={"PRIEST","MAGE"}}, g={{"g",0,txt="Thelsamar flight master",m=1432,x=33.9,y=50.8},{"z",0,txt="Fly to Ironforge",at="Ironforge"}}},
  {t="Mystic Ward", lv=50, f={c={"PRIEST","MAGE"}}, g={{"a",8254,n2="High Priest Rohan: for Ogtinc in Azshara, keep it",m=1455,x=24.7,y=8.2,f={c={"PRIEST"}},ml=50},{"a",8250,n2="Dink, the mage trainer: for Sanath Lim-yo in Azshara, keep it",m=1455,x=27.2,y=8.6,f={c={"MAGE"}},ml=50},{"tr",0,txt="Visit your class trainer"}}},
  {t="Fly to Menethil Harbor", lv=50, f={c={"PRIEST","MAGE"}}, g={{"g",0,txt="Ironforge flight master",m=1455,x=55.9,y=47.9},{"z",0,txt="Fly to Menethil Harbor",at="Menethil Harbor"}}},
  {t="Boat to Auberdine", lv=50, f={c={"PRIEST","MAGE"}}, g={{"g",0,txt="Boat to Auberdine",m=1437,x=4.5,y=56.7}}},
  {t="Fly to Astranaar", lv=50, f={c={"PRIEST","MAGE"}}, g={{"g",0,txt="Auberdine flight master",m=1439,x=36.4,y=45.6},{"z",0,txt="Fly to Astranaar",at="Astranaar"}}},
  {t="Level 50.4", lv=50, n="Top up here to level 50.4 before the hand-ins at Talrendis Point: they take you to level 51. Or, with a group, run the Maraudon dungeon or the Sunken Temple dungeon instead.", w={{k="level",op="<",n=50,frac=0.4}}, g={{"g",0,txt="Highborne Apparition",m=1447,x=17,y=69.4},{"l",50,txt="Reach level 50 (40% in): grind Highborne Apparition",n2="grind on Highborne Apparition",m=1447,x=16.6,y=69.4,fr=0.4}}},
