  {t="Sanath Lim-yo", lv=50, n="Sanath Lim-yo wants two Undamaged Hippogryph Feathers from the Thunderhead hippogryphs around his camp, the ones you top up on here: about one in three carries one.", g={{"a",3381,m=1447,x=28.1,y=50.1,ml=45},{"o",3381,i=1,txt="Undamaged Hippogryph Feather x2",m=1447,x=21.1,y=54.2},{"t",3381,m=1447,x=28.1,y=50.1},{"l",50,txt="Reach level 50 (56% in): grind Thunderhead Hippogryph",n2="grind on Thunderhead Hippogryph",m=1447,x=21.1,y=54.2,fr=0.56}}},
