  {t="Level 52", lv=52, n="Top up here to level 52 on the ogres of Dreadmaul Rock, on the way to Flame Crest: the hand-ins there take you to level 53. Or, with a group, run the Sunken Temple dungeon or the Maraudon dungeon instead.", w={{k="level",op="<",n=52}}, g={{"g",0,txt="Firegut Ogre Mage",m=1428,x=78.7,y=44.7},{"l",52,txt="Reach level 52: grind Firegut Ogre Mage",n2="grind on Firegut Ogre Mage",m=1428,x=79,y=44}}},
