  {t="Fallen Hero of the Horde", lv=52, n="Listen to his tale, then ride back south to Kum'isha.", g={{"t",2783,m=1435,x=34.3,y=66.1},{"a",2801,m=1435,x=34.3,y=66.1,ml=45},{"o",2801,i=1,txt="Talk to Fallen Hero of the Horde",m=1435,x=34.3,y=66.1},{"t",2801,m=1435,x=34.3,y=66.1}}},
