  {t="The Emerald Sanctuary", lv=53, n="Ride north out of Astranaar into Felwood to the Emerald Sanctuary, the druids' camp by the road.", g={{"a",4101,n2="Arathandris Silversky, in the ruins just east of Grazle",m=1448,x=54.1,y=86.8,ml=48},{"a",4421,n2="Eridan Bluewind, inside",m=1448,x=51.4,y=81.5,ml=49},{"a",5156,m=1448,x=50.9,y=81.6,ml=48},{"a",5155,m=1448,x=51.2,y=82.1,ml=48}}},
  {t="Grazle", lv=53, n="Grazle the furbolg stands by the road just south of the Emerald Sanctuary.", g={{"a",8460,m=1448,x=50.9,y=85,ml=45}}},
  {t="Deadwood Village", lv=53, n="The Deadwood furbolgs live in the village just south-west of Grazle; keep the Deadwood Headdress Feathers they drop.", g={{"o",8460,i=1,txt="Kill Deadwood Warrior x6",m=1448,x=49.7,y=88.2},{"o",8460,i=3,txt="Kill Deadwood Gardener x6",m=1448,x=48.8,y=88.9},{"o",8460,i=2,txt="Kill Deadwood Pathfinder x6",m=1448,x=48.3,y=89.5}}},
  {t="Level 52.58", lv=53, n="If you skipped The Horn of the Beast or The Super Snapper FX, grind here to level 52.58 to stay on the route's plan. Or, with a group, run the Sunken Temple dungeon or the Maraudon dungeon instead.", w={{k="level",op="<",n=52,frac=0.58}}, g={{"g",0,txt="Deadwood Warrior",m=1448,x=48.7,y=92.1},{"l",52,txt="Reach level 52 (58% in): grind Deadwood Warrior",n2="grind on Deadwood Warrior",m=1448,x=48.7,y=91.9,fr=0.58}}},
  {t="Grazle", lv=53, g={{"t",8460,m=1448,x=50.9,y=85},{"a",8462,n2="Nafien waits at the north end of Felwood",m=1448,x=50.9,y=85,ml=45},{"t",8466,m=1448,x=50.9,y=85,opt=true}}},
  {t="Level 52.69", lv=53, n="Top up here to level 52.69 before the hand-ins at Jaedenar: they take you to level 53. Or, with a group, run the Sunken Temple dungeon or the Maraudon dungeon instead.", w={{k="level",op="<",n=52,frac=0.69}}, g={{"g",0,txt="Deadwood Pathfinder",m=1448,x=46.3,y=89.4},{"l",52,txt="Reach level 52 (69% in): grind Deadwood Pathfinder",n2="grind on Deadwood Pathfinder",m=1448,x=46.4,y=88.9,fr=0.69}}},
  {t="Jadefire Glen", lv=53, n="The Jadefire satyrs hold the glen west of the road, with Xavathras at its back.\nCareful: Jadefire Shadowstalkers (level 51-52) use Sneak and Slowing Poison and are stealthed, so they often join fights uninvited.\nCursed Oozes slide about the glen's streams: kill them and use Laris's Empty Ooze Jar on their remains.", g={{"o",4421,i=1,txt="Kill Jadefire Felsworn x11",m=1448,x=44,y=88.9},{"o",4512,i=1,txt="Filled Cursed Ooze Jar x6",m=1448,x=40.4,y=72.5},{"l",52,txt="Reach level 52 (74% in): grind Jadefire Felsworn",n2="grind on Jadefire Felsworn",m=1448,x=37.8,y=69.5,fr=0.74}}},
  {t="Ruins of Constellas", lv=53, g={{"o",4421,i=2,txt="Kill Jadefire Shadowstalker x9",m=1448,x=37.7,y=69.3},{"o",4421,i=3,txt="Kill Jadefire Rogue x9",m=1448,x=38.1,y=69.5},{"o",4421,i=4,txt="Kill Xavathras",m=1448,x=32.2,y=67.1}}},
  {t="Jaedenar", lv=53, n="Jaedenar is the ruined temple north of the glen.", g={{"o",5155,i=1,txt="Kill Jaedenar Hound x4",m=1448,x=34.5,y=60.1},{"o",5155,i=2,txt="Kill Jaedenar Guardian x4",m=1448,x=35,y=59.4},{"o",5155,i=3,txt="Kill Jaedenar Adept x6",m=1448,x=34.5,y=59.7},{"o",5155,i=4,txt="Kill Jaedenar Cultist x6",m=1448,x=34.9,y=60.3},{"o",4512,i=2,txt="Filled Tainted Ooze Jar x6",n2="Filled Tainted Ooze Jar: Tainted Oozes slide about Jaedenar's fel pools",m=1448,x=40.3,y=58.9},{"l",52,txt="Reach level 52 (87% in): grind Jaedenar Hound",n2="grind on Jaedenar Hound",m=1448,x=39.1,y=59.2,fr=0.87}}},
  {t="Level 52.9", lv=53, n="Top up here to level 52.9 before the hand-ins at Emerald Sanctuary: they take you to level 53. Or, with a group, run the Sunken Temple dungeon or the Maraudon dungeon instead.", w={{k="level",op="<",n=52,frac=0.9}}, g={{"g",0,txt="Jaedenar Hound",m=1448,x=38.3,y=61.7},{"l",52,txt="Reach level 52 (90% in): grind Jaedenar Hound",n2="grind on Jaedenar Hound",m=1448,x=38.5,y=61.4,fr=0.9}}},
  {t="The Emerald Sanctuary", lv=53, g={{"t",5155,m=1448,x=51.2,y=82.1},{"a",5157,m=1448,x=51.2,y=82.1,ml=48},{"t",4421,n2="Eridan Bluewind, inside",m=1448,x=51.4,y=81.5},{"a",4906,m=1448,x=51.4,y=81.5,ml=49}}},
  {t="Shatter Scar Vale", lv=53, n="Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them.", g={{"g",0,txt="First crater",m=1448,x=41.6,y=43},{"g",0,txt="Second crater",m=1448,x=40.4,y=41.2},{"g",0,txt="Third crater",m=1448,x=42.2,y=40.3},{"c",5156,txt="Entropic Beast; Entropic Horror; Explore the craters in Shatter Scar Vale"},{"o",5156,i=1,txt="Kill Entropic Beast x2",m=1448,x=41.7,y=40.1},{"o",5156,i=2,txt="Kill Entropic Horror x2",m=1448,x=41.7,y=40.1}}},
  {t="Irontree Woods", lv=53, n="The Warpwood treants of Irontree Woods, east of Jadefire Run, carry the Blood Amber.", g={{"o",4101,i=1,txt="Blood Amber x15",n2="Below ground",m=1448,x=55,y=19.6}}},
  {t="Nafien", lv=53, n="Follow the road north to the cave mouth of Timbermaw Hold; Nafien guards it.", g={{"t",8462,m=1448,x=64.8,y=8.1},{"a",8461,m=1448,x=64.8,y=8.1,ml=45}}},
  {t="Felpaw Village", lv=53, n="The Deadwood furbolgs of Felpaw Village fill the hills west of the cave. Keep killing them until one drops a Deadwood Ritual Totem, about one kill in thirty, then right-click it: Kernda in Timbermaw Hold takes it once the Timbermaw are Neutral to you, now if they already are, or when the last guide passes the cave again at 58.\nCareful: Den Watchers are level 53-54; they call nearby allies within 25 yd once below 50% health and run off for help below 15%.", g={{"o",8461,i=1,txt="Kill Deadwood Den Watcher x6",m=1448,x=63.7,y=6},{"o",8461,i=2,txt="Kill Deadwood Avenger x6",m=1448,x=63,y=7.3},{"o",8461,i=3,txt="Kill Deadwood Shaman x6",m=1448,x=62.7,y=7.1},{"h",20741,txt="Get Deadwood Ritual Totem",m=1448,x=62.7,y=7.1,n=1},{"a",8470,ml=45}}},
  {t="Nafien", lv=53, g={{"t",8461,m=1448,x=64.8,y=8.1},{"a",8465,n2="Salfa stands at the Winterspring end of the tunnel: keep it",m=1448,x=64.8,y=8.1,ml=45}}},
  {t="Nafien", lv=53, w={{k="has",n=5,item=21377}}, g={{"t",8467,m=1448,x=64.8,y=8.1}}},
  {t="Timbermaw Hold", lv=53, n="Step into the cave: Kernda stands just inside.", g={{"t",8470,n2="Kernda: the Timbermaw speak to you only from Neutral; walks around here: look inside the circle on the map",m=1448,x=65.5,y=3.5,opt=true}}},
  {t="Jadefire Run: kill these as you meet them", lv=53, n="Jadefire Run is the satyr valley in the north-west, with Xavaric at its far end. He drops the Flute of Xavaric; every Jadefire satyr can drop Jadefire Felbind.", g={{"h",11668,txt="Get Flute of Xavaric",m=1448,x=39.1,y=22.4,n=1},{"a",939,ml=49},{"o",939,i=1,txt="Jadefire Felbind x5",m=1448,x=40.2,y=85.2},{"o",4906,i=3,txt="Kill Jadefire Trickster x8",m=1448,x=41,y=20.2},{"o",4906,i=2,txt="Kill Jadefire Betrayer x8",m=1448,x=41.6,y=19.6},{"o",4906,i=1,txt="Kill Jadefire Hellcaller x8",m=1448,x=41,y=18.9},{"o",4906,i=4,txt="Kill Xavaric",m=1448,x=39.1,y=22.4}}},
  {t="Jaedenar again", lv=53, n="Use the Empty Canteen at the corrupted moonwell in the middle of Jaedenar.", g={{"o",5157,i=1,txt="Use Empty Canteen",m=1448,x=35.2,y=59.8},{"o",5157,i=1,txt="Corrupt Moonwell Water",m=1448,x=35.2,y=59.8}}},
  {t="The Emerald Sanctuary", lv=53, n="Ride south-east from Jaedenar to the Emerald Sanctuary, the druids' camp by the road in southern Felwood.", g={{"t",5156,m=1448,x=50.9,y=81.6}}},
  {t="The Emerald Sanctuary", lv=53, g={{"t",939,m=1448,x=51.4,y=81.5},{"a",4441,n2="The vial is filled in Darnassus: keep it; inside",m=1448,x=51.4,y=81.5,ml=49},{"t",4906,m=1448,x=51.4,y=81.5},{"t",5157,m=1448,x=51.2,y=82.1},{"a",5158,n2="Ends in the Barrens: keep it",m=1448,x=51.2,y=82.1,ml=48},{"t",4101,m=1448,x=54.1,y=86.8}}},
} end)

R:Segment({id="alliance/50-60/03-winterspring",title="Winterspring & Eastern Plaguelands",faction="Alliance",min=53,max=56,zone=1452,zoneName="Winterspring",next="alliance/50-60/04-western-plaguelands"}, function() return {
  {t="Into Winterspring", lv=53, g={{"g",0,txt="Into Winterspring",m=1452,x=28,y=34.6}}},
  {t="Salfa", lv=53, n="Salfa stands right at the Winterspring exit of Timbermaw Hold's tunnel, where you come out.", g={{"t",8465,m=1452,x=27.7,y=34.5},{"a",8464,m=1452,x=27.7,y=34.5,ml=45}}},
  {t="Winterspring", lv=53, g={{"g",0,txt="Everlook",m=1452,x=61.3,y=39}}},
  {t="Everlook's inn", lv=53, n="Your Hearthstone is not set at Thelsamar (the Hinterlands guide binds there at 47, and this guide leaves Winterspring through it): bind at Everlook instead, for the trips back to town.", w={{k="bound",neg=true,name="Stoutlager Inn",area=2101}}, g={{"b",0,txt="Set your hearthstone at Everlook",m=1452,x=61.4,y=38.8,at="Everlook"}}},
  {t="Everlook", lv=53, g={{"fp",52,txt="Get the Everlook flight path (Maethrya)",m=1452,x=62.3,y=36.6},{"a",5601,n2="Jessica Redpath: keep it for Darrowshire; inside",m=1452,x=61.3,y=39,ml=50},{"a",6028,n2="Gregor Greystone: keep both for the Plaguelands; inside",m=1452,x=61.4,y=39,ml=50},{"a",6030,m=1452,x=61.4,y=39,ml=50},{"t",4808,m=1452,x=61.6,y=38.6},{"a",4809,m=1452,x=61.6,y=38.6,ml=50},{"a",6603,n2="Meggi Peppinrocker walks around Everlook: look inside the circle on the map",m=1452,x=60.7,y=38.2,ml=52},{"a",3783,m=1452,x=60.9,y=37.6,ml=52},{"o",978,i=1,txt="Moontouched Feather x10",n2="Moontouched Feather, 110 yd north",m=1452,x=63.4,y=38.4}}},
  {t="Wynd Nightchaser", lv=53, g={{"a",5244,m=1452,x=52,y=30.4,ml=53},{"t",5244,m=1452,x=52.1,y=30.4},{"a",5245,m=1452,x=52.1,y=30.4,ml=53}}},
  {t="Ice Thistle Hills: kill these as you meet them", lv=53, n="Ice Thistle yetis live in the hills south of Winterfall Village, Chillwind Chimaeras in the valley toward Everlook.", g={{"o",3783,i=1,txt="Thick Yeti Fur x10",m=1452,x=52.4,y=32.4},{"o",4809,i=1,txt="Uncracked Chillwind Horn x8",m=1452,x=53.2,y=37.7}}},
  {t="The Ruins of Kel'Theril", lv=53, n="The ruins lie around the frozen lake south of Starfall Village. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam.", g={{"o",5245,i=1,txt="First Relic Fragment",m=1452,x=55.1,y=43},{"o",5245,i=3,txt="Third Relic Fragment",m=1452,x=53.3,y=43.4},{"o",5245,i=4,txt="Fourth Relic Fragment",m=1452,x=52.4,y=41.5},{"o",5245,i=2,txt="Second Relic Fragment",m=1452,x=50.9,y=41.7},{"o",978,i=1,txt="Moontouched Feather x10",m=1452,x=49.5,y=40.8}}},
  {t="Donova Snowden", lv=53, n="Follow the road west to Donova's camp beside the hot springs.", g={{"t",3908,m=1452,x=31.3,y=45.2},{"a",3909,n2="Keep it: Gregan in Feralas brews the elixir later",m=1452,x=31.3,y=45.2,ml=47},{"t",6603,m=1452,x=31.3,y=45.2},{"a",5082,m=1452,x=31.3,y=45.2,ml=52}}},
  {t="Frostfire Hot Springs: kill these as you meet them", lv=54, n="The western Winterfall camp sits in the hills between Salfa and Donova. Any furbolg here can drop an Empty Firewater Flask (about one in ten: it comes within the kills these quests need) and a Winterfall Ritual Totem (about one in thirty: it comes within the top-ups): right-click whichever drops. Keep the Runecloth the furbolgs drop for Meilosh.\nThe rest of Winterspring's work is level 55-58: stay on this camp until level 54, so your first kills also count for Donova and Salfa. Or, with a group, run the Blackrock Depths dungeon instead.", g={{"h",12771,txt="Get Empty Firewater Flask",m=1452,x=32.4,y=37.6,n=1},{"a",5083,ml=52},{"o",5082,i=1,txt="Kill Winterfall Pathfinder x8",m=1452,x=32.4,y=37.1},{"o",5082,i=2,txt="Kill Winterfall Den Watcher x8",m=1452,x=30.5,y=36.9},{"o",5082,i=3,txt="Kill Winterfall Totemic x8",m=1452,x=30,y=36.2},{"o",8464,i=2,txt="Kill Winterfall Den Watcher x8",m=1452,x=30.3,y=36.3},{"l",54,txt="Reach level 54: grind Winterfall Pathfinder",n2="grind on Winterfall Pathfinder",m=1452,x=30.1,y=35.6}}},
  {t="Donova Snowden", lv=54, g={{"t",5082,m=1452,x=31.3,y=45.2},{"t",5083,m=1452,x=31.3,y=45.2},{"a",5084,n2="The Deadwood cauldron in Felwood: keep it",m=1452,x=31.3,y=45.2,ml=52}}},
  {t="Level 55.05", lv=55, n="Top up here to level 55.05 before the hand-ins at Everlook: they take you to level 56. Grind the Winterfall furbolgs camped by Frostfire Hot Springs (Pathfinders, Totemics, Den Watchers): killing them raises your Timbermaw reputation, which the quests here and the walk through Timbermaw Hold need, one of them drops the Winterfall Ritual Totem, and they fill your bags with the thirty Runecloth Meilosh asks for. Or, with a group, run the Blackrock Depths dungeon or the Blackrock Spire dungeon (Lower) instead.", w={{k="level",op="<",n=55,frac=0.05}}, g={{"g",0,txt="Winterfall Pathfinder",m=1452,x=31.4,y=36},{"l",55,txt="Reach level 55 (5% in): grind Winterfall Pathfinder",n2="grind on Winterfall Pathfinder",m=1452,x=31.4,y=36.3,fr=0.05}}},
  {t="Winterfall Ritual Totem", lv=55, n="Any Winterfall furbolg can drop the totem, about one kill in thirty: if the top-up did not bring one, keep killing them here until it drops, then right-click it.", g={{"g",0,txt="Winterfall Pathfinder",m=1452,x=31.4,y=36},{"h",20742,txt="Get Winterfall Ritual Totem",m=1452,x=31.4,y=36.3,n=1},{"a",8471,n2="For Kernda in Timbermaw Hold: keep it",ml=50}}},
  {t="Everlook", lv=55, g={{"t",4809,m=1452,x=61.6,y=38.6},{"t",3783,m=1452,x=60.9,y=37.6},{"a",977,m=1452,x=60.9,y=37.6,ml=52}}},
  {t="Winterfall Village", lv=55, n="The Winterfall furbolg village lies east of Everlook: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. High Chief Winterfall in the cave at the back is elite: stay out.", g={{"o",8464,i=1,txt="Kill Winterfall Shaman x8",m=1452,x=67.4,y=35.2},{"o",8464,i=2,txt="Kill Winterfall Den Watcher x8",m=1452,x=67.5,y=35.9},{"o",8464,i=3,txt="Kill Winterfall Ursa x8",m=1452,x=68.1,y=36.9}}},
  {t="Pristine Yeti Horns", lv=55, n="Back to the hills: only the Ice Thistle Matriarchs and Patriarchs carry the horns.", g={{"o",977,i=1,txt="Pristine Yeti Horn x2",m=1452,x=70.5,y=37.6}}},
  {t="Everlook", lv=55, g={{"t",977,m=1452,x=60.9,y=37.6},{"a",5163,m=1452,x=60.9,y=37.6,ml=52},{"i",0,txt="Use Umi's Mechanical Yeti",n2="On Legacki, by the inn",m=1452,x=61.5,y=38.6},{"o",5163,i=1,txt="Scare Legacki with Umi's Mechanical Yeti",n2="Legacki: Sprinkle and Quixxil come later",m=1452,x=61.5,y=38.6}}},
  {t="To Stoutlager Inn", lv=55, n="Your Hearthstone is still set at Thelsamar: from there the gryphon to Chillwind Camp is about ten minutes quicker than Everlook's flight to Theramore and the boat.", w={{k="bound",name="Stoutlager Inn",area=2101}}, g={{"g",0,txt="Stoutlager Inn",m=1432,x=35.5,y=48.4}}},
  {t="Fly to Chillwind Camp", lv=55, w={{k="bound",name="Stoutlager Inn",area=2101}}, g={{"g",0,txt="Thelsamar flight master",m=1432,x=33.9,y=50.8},{"z",0,txt="Fly to Chillwind Camp",at="Chillwind Camp"}}},
  {t="Fly to Theramore", lv=55, w={{k="bound",neg=true,name="Stoutlager Inn",area=2101}}, g={{"g",0,txt="Everlook flight master",m=1452,x=62.3,y=36.6},{"z",0,txt="Fly to Theramore",at="Theramore"}}},
  {t="Boat to Menethil Harbor", lv=55, w={{k="bound",neg=true,name="Stoutlager Inn",area=2101}}, g={{"g",0,txt="Boat to Menethil Harbor",m=1445,x=71.6,y=56.4}}},
  {t="Fly to Chillwind Camp", lv=55, w={{k="bound",neg=true,name="Stoutlager Inn",area=2101}}, g={{"g",0,txt="Menethil Harbor flight master",m=1437,x=9.5,y=59.7},{"z",0,txt="Fly to Chillwind Camp",at="Chillwind Camp"}}},
  {t="Chillwind Camp", lv=55, n="Pureheart, Dumah, Valorfist and MacDonnell stand around the middle of the camp, by the flight master.", g={{"t",6028,m=1422,x=43,y=83.5},{"a",5903,n2="Nathaniel Dumah: the termites come later, in Terrordale",m=1422,x=43.4,y=84.8,ml=48},{"a",5097,n2="Commander Ashlam Valorfist: the watchtowers are in Andorhal, keep it",m=1422,x=42.7,y=84,ml=50},{"a",5219,n2="High Priestess MacDonnell: the cauldron is at Dalson's Tears, keep it",m=1422,x=43,y=84.5,ml=50}}},
  {t="Mulgris Deepriver", lv=55, n="Mulgris stands by the farm at the Writhing Haunt, on the road east to the Eastern Plaguelands.", g={{"a",4984,n2="Inside",m=1422,x=53.7,y=64.7,ml=51}}},
  {t="Into Eastern Plaguelands", lv=55, g={{"g",0,txt="Into Eastern Plaguelands",m=1423,x=6.3,y=55.8}}},
  {t="Eastern Plaguelands", lv=55, g={{"g",0,txt="Pamela Redpath",m=1423,x=31.1,y=78}}},
  {t="Pamela Redpath", lv=55, n="Follow the southern road east into the Eastern Plaguelands; the ruins of Darrowshire lie south of it. Pamela's ghost plays by the ruined house at the south end.", g={{"t",5601,m=1423,x=31.1,y=78},{"a",5149,m=1423,x=31.1,y=78,ml=50}}},
  {t="Pamela's doll", lv=55, n="The three pieces of the doll lie in the ruined houses of Darrowshire; picking one up can call out ghosts. Combine them into the doll.", g={{"g",0,txt="Go here",m=1423,x=31.1,y=78},{"h",12886,txt="Get Pamela's Doll's Head",n2="Pamela's Doll's Head; inside",m=1423,x=32.6,y=79.6,n=1,opt=true},{"h",12887,txt="Get Pamela's Doll's Left Side",m=1423,x=32.7,y=79.1,n=1,opt=true},{"h",12888,txt="Get Pamela's Doll's Right Side",n2="Pamela's Doll's Right Side; inside",m=1423,x=33.1,y=79.7,n=1,opt=true},{"c",5149,txt="Pamela's Doll"}}},
  {t="Pamela Redpath", lv=55, g={{"t",5149,m=1423,x=31.1,y=78},{"a",5152,n2="Auntie Marlene, in the Western Plaguelands: keep it",m=1423,x=31.1,y=78,ml=50},{"a",5241,m=1423,x=31.1,y=78,ml=50}}},
  {t="Light's Hope Chapel", lv=55, n="Follow the road east across the zone to the chapel.", g={{"fp",67,txt="Get the Light's Hope Chapel flight path (Khaelyn Steelwing)",m=1423,x=71.8,y=49.6},{"b",0,txt="Set your hearthstone at Light's Hope Chapel",m=1423,x=71.8,y=48.5,at="Light's Hope Chapel"},{"t",5241,m=1423,x=71.7,y=50},{"a",5211,m=1423,x=71.7,y=50,ml=50},{"t",6030,m=1423,x=71.6,y=50.1},{"t",5503,m=1423,x=71.6,y=50.1},{"a",6021,n2="Caretaker Alen: Zaeldarr is a level 54 elite",m=1423,x=69.9,y=53.7,opt=true,ml=50}}},
  {t="Corin's Crossing", lv=55, n="The Scourge around Corin's Crossing, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it.\nCareful: Eye of Naxxramas goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min.", g={{"o",5211,i=1,txt="Free Darrowshire Spirits: talk to them x15",m=1423,x=69.6,y=46.8},{"h",12840,txt="Get Minion's Scourgestone x20",m=1423,x=68.8,y=55.8,n=20},{"h",12841,txt="Get Invader's Scourgestone x10",m=1423,x=69.8,y=47.2,n=10}}},
  {t="The Undercroft", lv=55, n="Zaeldarr is elite: grouping up is advised. He waits at the bottom of the Undercroft, the crypt in the south-west of the zone.", g={{"o",6021,i=1,txt="Zaeldarr's Head",n2="Zaeldarr's Head; below ground",m=1423,x=23.1,y=72.6,opt=true}}},
  {t="Light's Hope Chapel", lv=55, g={{"t",5211,m=1423,x=71.7,y=50},{"t",5509,m=1423,x=71.6,y=50.1},{"t",5510,m=1423,x=71.6,y=50.1},{"t",6021,m=1423,x=69.9,y=53.7,opt=true},{"i",0,txt="The next guide starts here and flies to Chillwind Camp."}}},
