R:Segment({id="alliance/50-60/04-western-plaguelands",title="Western Plaguelands, Eastern Plaguelands, Feralas, Un'Goro Crater & Silithus",faction="Alliance",min=56,max=58,zone=1422,zoneName="Western Plaguelands",next="alliance/50-60/05-silithus"}, function() return {
  {t="Chillwind Camp", lv=56, g={{"z",0,txt="Fly to Chillwind Camp",at="Chillwind Camp"}}},
  {t="Argent Officer Pureheart", lv=56, n="No Argent Dawn Commission yet (Light's Hope gives it on the Winterspring guide's way through)? Pureheart gives you one here: the scourgestone quests need it.", w={{k="turnedin",neg=true,q=5503}}, g={{"t",5401,m=1422,x=43,y=83.5}}},
  {t="Sorrow Hill: kill these as you meet them", lv=56, n="Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones.\nCareful: These undead notice you from far away, and other undead nearby join the fight when one is pulled.\nCareful: The Eye of Naxxramas (3 spawns, 15 min respawn) turns invisible when out of combat and calls in Rockwing Gargoyles once a fight starts.", g={{"h",12840,txt="Get Minion's Scourgestone x20",m=1422,x=47.4,y=84.3,n=20}}},
  {t="Marlene Redpath", lv=56, n="Marlene's farmhouse stands on the hill east of the camp; Joseph Redpath's monument is just north of it.", g={{"t",5152,n2="Upstairs",m=1422,x=49.2,y=78.6},{"a",5153,m=1422,x=49.2,y=78.6,ml=50},{"o",5153,i=1,txt="Joseph's Wedding Ring",n2="Joseph's Wedding Ring, at the monument",m=1422,x=49.7,y=76.8}}},
  {t="Dalson's Tears", lv=56, n="Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and Farmer Dalson waits in the outhouse with the cabinet key.", g={{"t",5058,m=1422,x=47.8,y=50.7}}},
  {t="The Writhing Haunt: kill these as you meet them", lv=56, g={{"h",12841,txt="Get Invader's Scourgestone x10",m=1422,x=46.1,y=52.6,n=10},{"o",4984,i=1,txt="Kill Diseased Wolf x8",m=1422,x=44.9,y=49.5}}},
  {t="Dalson's Tears", lv=56, g={{"h",12738,txt="Get Dalson Outhouse Key",m=1422,x=47.7,y=49.9,n=1},{"t",5059,m=1422,x=48.1,y=49.6},{"h",12739,txt="Get Dalson Cabinet Key",m=1422,x=48.2,y=49.7,n=1},{"t",5060,n2="Locked Cabinet, in the farmhouse; inside",m=1422,x=47.4,y=49.6}}},
