  {t="The Andorhal watchtowers", lv=56, n="Use the Beacon Torch at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp.", g={{"o",5097,i=1,txt="Use Beacon Torch",m=1422,x=40,y=71.6},{"o",5097,i=1,txt="Mark Andorhal Tower One with the Beacon Torch",m=1422,x=40,y=71.6},{"o",5097,i=2,txt="Mark Andorhal Tower Two with the Beacon Torch",m=1422,x=42.3,y=66.2}}},
