  {t="Dalson's Tears cauldron", lv=56, n="The cauldron sits at Dalson's Tears, north-east of Felstone; its Cauldron Lord stands beside it.", g={{"o",5219,i=1,txt="Dalson's Tears Cauldron Key",m=1422,x=46.1,y=52.6},{"t",5219,m=1422,x=46.2,y=51.9},{"a",5220,m=1422,x=46.2,y=51.9,ml=50}}},
