  {t="The Scarlet Crusade", lv=56, n="The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward Hearthglen.", g={{"o",6004,i=3,txt="Kill Scarlet Mage x2",m=1422,x=52.8,y=36.6},{"o",6004,i=2,txt="Kill Scarlet Hunter x2",m=1422,x=52.2,y=44},{"o",6004,i=1,txt="Kill Scarlet Medic x2",m=1422,x=51.8,y=44.8},{"o",6004,i=4,txt="Kill Scarlet Knight x2",m=1422,x=50.2,y=42.2}}},
