  {t="Hearthglen overlook", lv=56, n="Climb the hill west of Hearthglen to look down on the town.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby.", g={{"g",0,txt="Go here",m=1422,x=45.8,y=18.3},{"c",6025,txt="Overlook Hearthglen from a high vantage point",m=1422,x=45.8,y=18.3}}},
