  {t="Eastern Plaguelands: kill these as you meet them", lv=56, n="Ride west to Terrordale. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the Empty Termite Jar at the big termite mounds and kill the Frenzied Plaguehounds further north.", g={{"o",5543,i=1,txt="Kill Plaguebat x30",m=1423,x=47.8,y=64.4},{"o",5542,i=1,txt="Kill Plaguehound Runt x20",m=1423,x=46.4,y=64.6}}},
  {t="Augustus the Touched", lv=56, n="Ride north to Terrordale. Augustus lives in the ruined hut, and his receipt book lies in the ruined inn nearby.", g={{"a",6164,n2="Inside",m=1423,x=11.4,y=26.4,ml=50}}},
