  {t="Gregan Brewspewer", lv=56, n="Gregan's camp lies north of the Twin Colossals. He brews the Videre Elixir from an Evoroot: take his errand for one.", g={{"t",4142,m=1444,x=45.1,y=25.6}}},
  {t="Rockbiter", lv=56, n="The giant Rockbiter sits just north-west of Gregan's camp.", g={{"a",2844,m=1444,x=42.4,y=22,ml=44}}},
  {t="Evoroot", lv=56, n="The Evoroot grows inside a ruined building north of Rockbiter: climb in through the break in its wall from the ledge beside it.", g={{"h",11242,txt="Get Evoroot",m=1444,x=44.5,y=10.2,n=1}}},
  {t="Shay Leafrunner", lv=56, n="Ride west into the Ravenwind Ruins: Shay hides in the small round building at the back. Open the chest beside her for Shay's Bell: it lasts 15 minutes, like the quest.", g={{"t",2844,m=1444,x=38.2,y=10.3},{"a",2845,m=1444,x=38.2,y=10.3,ml=44},{"o",2845,i=1,txt="Shay's Bell",m=1444,x=38.2,y=10.3}}},
  {t="Wandering Shay", lv=56, n="Lead Shay back to Rockbiter at walking pace: she wanders off, so ring the bell to call her back (not in combat), and clear the harpies on the way before she reaches them.", g={{"c",2845,txt="Shay's Bell; Take Shay Leafrunner to Rockbiter's camp",m=1444,x=42.3,y=21.9},{"t",2845,m=1444,x=42.4,y=22}}},
  {t="Gregan Brewspewer", lv=56, n="Back to Gregan's camp, just south-east of Rockbiter: the Evoroot buys three Videre Elixirs. Keep them: Donova takes one, and Gaeriyan in Gadgetzan shows himself only to someone who has drunk one.", g={{"t",4041,m=1444,x=45.1,y=25.6},{"o",3909,i=1,txt="Videre Elixir",m=1444,x=45.1,y=25.6}}},
  {t="Feralas", lv=56, g={{"g",0,txt="Thalanaar",m=1444,x=89.5,y=45.9}}},
  {t="Fly to Theramore", lv=56, g={{"g",0,txt="Thalanaar flight master",m=1444,x=89.5,y=45.9},{"z",0,txt="Fly to Theramore",at="Theramore"}}},
  {t="The Barrens", lv=56, g={{"g",0,txt="Ratchet",m=1413,x=65.8,y=43.8}}},
  {t="Ratchet", lv=56, n="From Theramore, ride west into the Barrens and north up the coast to Ratchet.", g={{"t",5158,n2="Islen Waterseer, on the coast north of town",m=1413,x=65.8,y=43.8},{"a",5159,n2="For Felwood: keep it",m=1413,x=65.8,y=43.8,ml=48},{"fp",80,txt="Get the Ratchet flight path (Bragok)",m=1413,x=63.1,y=37.2},{"b",0,txt="Set your hearthstone at Ratchet",m=1413,x=62,y=39.4,at="Ratchet"},{"a",4502,n2="Liv Rizzlefix: keep it for Un'Goro; inside",m=1413,x=62.5,y=38.7,ml=49}}},
  {t="Fly to Everlook", lv=56, g={{"g",0,txt="Ratchet flight master",m=1413,x=63.1,y=37.1},{"z",0,txt="Fly to Everlook",at="Everlook"}}},
  {t="Winterspring", lv=56, g={{"g",0,txt="Donova Snowden",m=1452,x=31.3,y=45.2}}},
  {t="Donova Snowden", lv=56, n="Ride west along the road to the hot springs.", g={{"t",3909,m=1452,x=31.3,y=45.2},{"a",3912,n2="Gaeriyan in Gadgetzan: keep it",m=1452,x=31.3,y=45.2,ml=47}}},
  {t="Moonglade", lv=56, g={{"g",0,txt="Rabine Saturna",m=1450,x=51.7,y=45.1}}},
  {t="Rabine Saturna", lv=56, n="Walk into Timbermaw Hold and take the Moonglade branch of the tunnel to Nighthaven.", g={{"t",6762,m=1450,x=51.7,y=45.1},{"a",5527,m=1450,x=51.7,y=45.1,ml=56},{"a",1124,n2="For Silithus: keep it",m=1450,x=51.7,y=45.1,ml=54}}},
  {t="Fly to Gadgetzan", lv=56, g={{"g",0,txt="Ratchet flight master",m=1413,x=63.1,y=37.1},{"z",0,txt="Fly to Gadgetzan",at="Gadgetzan"}}},
  {t="Gadgetzan", lv=56, g={{"t",4493,n2="Alchemist Pestlezugg, inside",m=1446,x=50.9,y=27},{"a",4496,m=1446,x=50.9,y=27,ml=50},{"o",5163,i=2,txt="Use Umi's Mechanical Yeti",n2="On Sprinkle",m=1446,x=51.1,y=26.9},{"o",5163,i=2,txt="Scare Sprinkle with Umi's Mechanical Yeti",m=1446,x=51.1,y=26.9},{"t",5538,m=1446,x=51.5,y=28.8},{"a",5801,n2="For Chillwind Camp: keep it",m=1446,x=51.5,y=28.8,ml=55},{"a",4504,n2="Tran'rek, north side of town: the tar is in Un'Goro, keep it",m=1446,x=51.6,y=26.8,ml=48}}},
  {t="Gaeriyan", lv=56, n="Gaeriyan is a ghost at the graveyard just east of town: drink a Videre Elixir there, which kills you, release your spirit and talk to him as a ghost. Then run back to your body to come back to life: the gravestone stands nearby.", g={{"t",3912,m=1446,x=53.9,y=23.3},{"a",3913,m=1446,x=53.9,y=23.3,ml=47},{"t",3913,m=1446,x=53.8,y=29.1},{"a",3914,m=1446,x=53.8,y=29.1,ml=47}}},
  {t="Broken Pillar", lv=56, n="Ride south-west to Marvon Rivetseeker's camp at the Broken Pillar.", g={{"t",3445,m=1446,x=52.7,y=45.9},{"a",3444,n2="The Stone Circle is in Ratchet",m=1446,x=52.7,y=45.9,ml=46}}},
  {t="Tanaris", lv=56, g={{"g",0,txt="Gadgetzan",m=1446,x=51,y=29.3}}},
  {t="Fly to Marshal's Refuge", lv=56, g={{"g",0,txt="Gadgetzan flight master",m=1446,x=51,y=29.3},{"z",0,txt="Fly to Marshal's Refuge",at="Marshal's Refuge"}}},
  {t="Linken", lv=56, n="Fly from Gadgetzan to Marshal's Refuge. Linken stands at the back of the refuge; J.D. Collie is in the cave behind him.\nSpraggle's friend Ringo has gone missing.", g={{"t",3914,m=1449,x=44.7,y=8.1},{"a",3941,m=1449,x=44.7,y=8.1,ml=47},{"t",3941,n2="J.D. Collie, below ground",m=1449,x=41.9,y=2.7},{"a",3942,n2="For Felwood: keep it",m=1449,x=41.9,y=2.7,ml=47},{"a",4492,m=1449,x=43.6,y=8.5,ml=50},{"a",4501,n2="The wooden sign beside Spraggle Frock",m=1449,x=43.5,y=8.4,ml=49}}},
  {t="Into Silithus", lv=56, g={{"g",0,txt="Into Silithus",m=1451,x=81.5,y=19.5}}},
  {t="Layo Starstrike", lv=56, n="Ride out of the crater's north-western pass into Silithus: Layo Starstrike stands at Valor's Rest, where the pass comes out.", g={{"t",1124,m=1451,x=81.9,y=18.9},{"a",1125,m=1451,x=81.9,y=18.9,ml=54}}},
  {t="Silithus", lv=56, g={{"g",0,txt="Cenarion Hold",m=1451,x=51.6,y=38.6}}},
  {t="Cenarion Hold", lv=56, n="Ride on west to Cenarion Hold. Beetix Ficklespragg stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", g={{"fp",73,txt="Get the Cenarion Hold flight path (Cloud Skydancer)",m=1451,x=50.6,y=34.5},{"a",9415,n2="Rifleman Torrig, at the Alliance tents",m=1451,x=50.7,y=34.7,ml=1},{"a",8277,m=1451,x=51.6,y=38.6,ml=54},{"a",8280,m=1451,x=51.1,y=38.3,ml=54},{"a",8284,m=1451,x=49.7,y=37.5,ml=54}}},
  {t="Silithus: kill these as you meet them", lv=56, n="Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around.", g={{"o",8280,i=1,txt="Kill Dredge Striker x15",m=1451,x=51.4,y=32},{"o",8277,i=2,txt="Sand Skitterer Fang x8",m=1451,x=51,y=30.3},{"o",8277,i=1,txt="Stonelash Scorpid Stinger x8",m=1451,x=56.1,y=30.2}}},
  {t="Level 56.89", lv=56, n="If you skipped The Super Snapper FX, grind here to level 56.89 to stay on the route's plan. Or, with a group, run the Blackrock Depths dungeon or the Blackrock Spire dungeon (Lower) instead.", w={{k="group",neg=true,q=2944},{k="level",op="<",n=56,frac=0.89}}, g={{"g",0,txt="Dredge Striker",m=1451,x=54.9,y=31.2},{"l",56,txt="Reach level 56 (89% in): grind Dredge Striker",n2="grind on Dredge Striker",m=1451,x=54.1,y=28.1,fr=0.89}}},
  {t="Cenarion Hold", lv=57, n="Ride back to Cenarion Hold. Beetix Ficklespragg stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", g={{"t",8277,m=1451,x=51.6,y=38.6},{"a",8278,m=1451,x=51.6,y=38.6,ml=54},{"t",8280,m=1451,x=51.1,y=38.3},{"a",8281,m=1451,x=51.1,y=38.3,ml=54},{"a",8318,m=1451,x=48.6,y=37.8,ml=57}}},
  {t="Silithus: kill these as you meet them", lv=57, n="Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands.", g={{"o",8278,i=2,txt="Stonelash Pincer Stinger x3",m=1451,x=43.4,y=45},{"o",8281,i=1,txt="Kill Dredge Crusher x20",n2="Dredge Crusher walks around here: look inside the circle on the map",m=1451,x=44.2,y=48.2},{"o",8278,i=3,txt="Rock Stalker Fang x3",m=1451,x=40.4,y=66.7},{"o",8278,i=1,txt="Stonelash Flayer Stinger x3",m=1451,x=41.2,y=69.7}}},
  {t="Southwind Village", lv=57, n="The tortured druids and sentinels haunt the ruined village south-west of Layo.", g={{"o",1125,i=1,txt="Kill Tortured Druid x8",m=1451,x=59.9,y=56.6},{"o",1125,i=2,txt="Kill Tortured Sentinel x8",m=1451,x=60.1,y=55.7}}},
  {t="Layo Starstrike", lv=57, g={{"t",1125,m=1451,x=81.9,y=18.9},{"a",1126,m=1451,x=81.9,y=18.9,ml=54}}},
  {t="The Hive'Ashi tower", lv=57, n="Ride back south-west to the Hive'Ashi tower in Southwind Village; climb it and kill the ambushers that rise for the encrusted object.", g={{"o",1126,i=1,txt="Encrusted Silithid Object",m=1451,x=60.2,y=52.4}}},
  {t="Layo Starstrike", lv=57, g={{"t",1126,m=1451,x=81.9,y=18.9},{"a",6844,n2="Umber in Moonglade: keep it",m=1451,x=81.9,y=18.9,ml=54}}},
  {t="Un'Goro Crater", lv=57, g={{"g",0,txt="Krakle",m=1449,x=33.2,y=48.4}}},
  {t="Krakle", lv=57, n="Coming in from Silithus, Golakka Hot Springs is just inside the crater: Krakle the goblin sits by the water.", g={{"a",974,m=1449,x=30.9,y=50.4,ml=51}}},
  {t="Un'Goro Crater: kill these as you meet them", lv=57, g={{"o",4501,i=2,txt="Kill Frenzied Pterrordax x15",m=1449,x=30.8,y=46},{"o",4501,i=1,txt="Kill Pterrordax x10",m=1449,x=42.8,y=85.4}}},
  {t="Krakle's Thermometer", lv=57, n="Ride east to Fire Plume Ridge, climb it and use Krakle's Thermometer at the lava vents near the top.", g={{"o",974,i=1,txt="Fire Plume Ridge Hot Spot",m=1449,x=49.7,y=45.6}}},
  {t="Krakle", lv=57, g={{"t",974,m=1449,x=30.9,y=50.4},{"a",980,n2="Ends with Donova Snowden in Winterspring: keep it",m=1449,x=30.9,y=50.4,ml=51}}},
  {t="Northern Pylon", lv=57, g={{"o",4501,i=1,txt="Kill Pterrordax x10",m=1449,x=42.8,y=85.4}}},
  {t="Ironstone Plateau: kill these as you meet them", lv=57, n="The gorillas live on Ironstone Plateau, just east of the pylon: take the pelts for Torwa Pathfinder now, while you are up here. Stay out of the deepest cave: U'cha is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds.", w={{k="onquest",q={4289}}}, g={{"o",4289,i=1,txt="Un'Goro Gorilla Pelt x2",n2="Un'Goro Gorilla Pelt; below ground",m=1449,x=62.6,y=19.7},{"o",4289,i=2,txt="Un'Goro Stomper Pelt x2",n2="Un'Goro Stomper Pelt; below ground",m=1449,x=62.6,y=19.7},{"o",4289,i=3,txt="Un'Goro Thunderer Pelt x2",n2="Un'Goro Thunderer Pelt; below ground",m=1449,x=62.6,y=19.7}}},
  {t="Marshal's Refuge", lv=57, g={{"t",4501,m=1449,x=43.6,y=8.5}}},
  {t="Lakkari Tar Pits: kill these as you meet them", lv=57, n="The Tar Beasts and Tar Lords wallow in the Lakkari Tar Pits, south of the refuge on the way down into the crater.", g={{"o",4504,i=1,txt="Super Sticky Tar x12",m=1449,x=45.7,y=15.5}}},
  {t="The crater", lv=57, n="Tar Beasts wallow in the Lakkari Tar Pits; the fire elementals of Fire Plume Ridge in the middle carry the ash; the Gorishi wasps of the Slithering Scar in the south carry the gland. Every creature in the crater can drop Un'Goro Soil.\nCareful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd.", g={{"o",4496,i=1,txt="Gorishi Scent Gland",m=1449,x=45.5,y=72.3}}},
  {t="Torwa Pathfinder", lv=57, n="Torwa camps at the foot of the ramp into the crater.", g={{"t",4291,m=1449,x=71.6,y=76},{"a",4292,m=1449,x=71.6,y=76,ml=48},{"a",4289,n2="The pelts come from the gorillas on Ironstone Plateau",m=1449,x=71.6,y=76,ml=47}}},
  {t="Torwa Pathfinder", lv=57, w={{k="complete",q=4289}}, g={{"t",4289,m=1449,x=71.6,y=76},{"a",4301,m=1449,x=71.6,y=76,ml=50}}},
  {t="Ironstone Plateau: kill these as you meet them", lv=57, n="The gorillas live on Ironstone Plateau, east of Marshal's Refuge. Keep their pelts for Torwa Pathfinder. Stay out of the deepest cave: U'cha is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds.", w={{k="onquest",q={4289}}}, g={{"o",4289,i=1,txt="Un'Goro Gorilla Pelt x2",n2="Un'Goro Gorilla Pelt; below ground",m=1449,x=62.6,y=19.7},{"o",4289,i=2,txt="Un'Goro Stomper Pelt x2",n2="Un'Goro Stomper Pelt; below ground",m=1449,x=62.6,y=19.7},{"o",4289,i=3,txt="Un'Goro Thunderer Pelt x2",n2="Un'Goro Thunderer Pelt; below ground",m=1449,x=62.6,y=19.7}}},
  {t="Torwa Pathfinder", lv=57, w={{k="onquest",q={4289}}}, g={{"t",4289,m=1449,x=71.6,y=76},{"a",4301,m=1449,x=71.6,y=76,ml=50}}},
  {t="U'cha", lv=57, n="Ride north along the east side to the gorilla plateau. U'cha, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first.", g={{"o",4301,i=1,txt="U'cha's Pelt",n2="Below ground",m=1449,x=68.1,y=12.6}}},
  {t="Lar'korwi", lv=57, n="Lar'korwi's lair lies in the jungle north of Torwa, below the eastern cliffs: use Torwa's Pouch there. Lar'korwi is level 56: start at full health.", g={{"o",4292,i=1,txt="Lar'korwi's Head",m=1449,x=79.7,y=49.8}}},
  {t="Torwa Pathfinder", lv=57, n="Cross the south of the crater to Torwa by the ramp.", w={{k="onquest",q={4301,4292}}}, g={{"t",4301,m=1449,x=71.6,y=76},{"t",4292,m=1449,x=71.6,y=76}}},
  {t="The Marshlands: kill these as you meet them", lv=57, g={{"o",4496,i=2,txt="Un'Goro Soil x5",m=1449,x=70.7,y=65.8},{"o",4502,i=1,txt="Un'Goro Ash x9",m=1449,x=55.5,y=57.9}}},
  {t="Ringo", lv=57, n="Ringo sits on the south-east slope of Fire Plume Ridge, in the middle of the crater.", g={{"t",4492,n2="Below ground",m=1449,x=51.9,y=49.9},{"a",4491,m=1449,x=51.9,y=49.9,ml=50}}},
  {t="Escort Ringo", lv=57, n="Lead Ringo north to Marshal's Refuge. When he faints, use Spraggle's Canteen on him to wake him.", g={{"g",0,txt="Go here",m=1449,x=43.7,y=8.3},{"c",4491,txt="Escort Ringo to Spraggle Frock at Marshal's Refuge"}}},
  {t="Spraggle Frock", lv=57, g={{"t",4491,m=1449,x=43.6,y=8.5}}},
} end)

