  {t="Stormwind Keep", lv=58, g={{"a",6182,m=1453,x=80.2,y=38.4,ml=56},{"t",6182,n2="Master Mathias Shaw, in SI:7",m=1453,x=78.3,y=70.7},{"a",6183,m=1453,x=78.3,y=70.7,ml=56},{"t",6183,m=1453,x=78.3,y=70.7},{"a",6184,n2="Flint Shadowmore at Chillwind Camp: keep it",m=1453,x=78.3,y=70.7,ml=56}}},
  {t="Tram to Ironforge", lv=58, g={{"g",0,txt="Tram to Ironforge",m=1453,x=69.6,y=30.2}}},
