  {t="Fly to Light's Hope Chapel", lv=58, g={{"g",0,txt="Ironforge flight master",m=1455,x=55.9,y=47.9},{"z",0,txt="Fly to Light's Hope Chapel",at="Light's Hope Chapel"}}},
