  {t="Scourge Champions", lv=58, n="Scourge Champions (59) roam the Noxious Glade, north of Light's Hope Chapel. Pass Carlin's Mystic Crystal over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time.", g={{"i",0,txt="Kill Scourge Champion",m=1423,x=66.6,y=43.1,opt=true},{"o",5206,i=1,txt="Resonating Skull x5",n2="Resonating Skull, from the Scourge Champions",m=1423,x=71.7,y=35.8}}},
  {t="Light's Hope Chapel", lv=58, g={{"t",5206,m=1423,x=71.7,y=50},{"a",5941,n2="Chromie in Andorhal: keep it",m=1423,x=71.7,y=50,ml=50}}},
  {t="Infiltrator Hameya", lv=58, n="Ride north to the Plaguewood's north-eastern edge.\nCareful: The trolls along the path to Zul'Mashar are level 57-59. They run away at low health and call for help, so they often bring adds with them.", g={{"o",6024,i=1,txt="Hameya's Key",m=1423,x=62,y=11.1}}},
  {t="The Undercroft", lv=58, n="Ride south-west to the Undercroft. The mound of dirt lies inside. Mercutio Filthgorger is elite: grouping up is advised.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot.", g={{"t",6024,m=1423,x=23.6,y=73.8},{"o",5781,i=1,txt="Taelan's Hammer",n2="Taelan's Hammer, from Mercutio Filthgorger",m=1423,x=23.9,y=74.2,opt=true}}},
} end)

