  {t="The Emerald Sanctuary", lv=58, n="From Talrendis Point ride into Felwood: the Emerald Sanctuary is the druids' camp on the road just past the Ashenvale border.", g={{"t",5159,m=1448,x=51.2,y=82.1},{"a",5165,m=1448,x=51.2,y=82.1,ml=48},{"t",4441,m=1448,x=51.4,y=81.5},{"a",4442,n2="Inside",m=1448,x=51.4,y=81.5,ml=49},{"t",4442,n2="Wait a moment for Eridan",m=1448,x=51.4,y=81.5},{"t",3942,m=1448,x=51.4,y=81.5},{"a",4084,m=1448,x=51.4,y=81.5,ml=47}}},
  {t="Shadow Hold braziers", lv=58, n="Shadow Hold is the cave at the back of Jaedenar, west of the road. Use the Purified Moonwell Water on the four braziers inside. Kill the Angerclaw bears and Felpaw wolves you pass for the Silvery Claws.\nCareful: Shadow Council mobs of level 53-55 fill the cave and often come in large linked groups, many with stuns. A group of 2-3 players is recommended.\nThe Jaedenar Darkweavers, Warlocks and Enforcers in here drop a Blood Red Key, about one kill in thirty: keep killing them until it drops. It opens the cell of Arko'narin, the night elf held in the cave.", g={{"o",4084,i=1,txt="Silvery Claws x11",n2="Angerclaw bears and Felpaw wolves",m=1448,x=51.4,y=80.6},{"o",5165,i=2,txt="Brazier of Malice",n2="Brazier of Malice, below ground",m=1448,x=37.7,y=52.7},{"o",5165,i=3,txt="Brazier of Suffering",n2="Brazier of Suffering, below ground",m=1448,x=36.7,y=53.3},{"o",5165,i=1,txt="Brazier of Pain",n2="Brazier of Pain, below ground",m=1448,x=36.3,y=56.3},{"o",5165,i=4,txt="Brazier of Hatred",n2="Brazier of Hatred, below ground",m=1448,x=36.5,y=55.2},{"h",13140,txt="Get Blood Red Key",m=1448,x=36.6,y=55.1,n=1},{"a",5202,ml=49},{"t",5202,n2="Captured Arko'narin, in her cell; below ground",m=1448,x=36.2,y=55.5},{"a",5203,m=1448,x=36.2,y=55.5,ml=49}}},
  {t="Arko'narin", lv=58, n="Lead her out of Shadow Hold and keep her alive until she is outside the cave: clear the way back first.", w={{k="onquest",q={5203}}}, g={{"g",0,txt="Go here",m=1448,x=35.4,y=59.1},{"c",5203,txt="Protect Arko'narin out of Shadow Hold"}}},
