  {t="Irontree Woods", lv=58, n="Follow the road north to Irontree Woods. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north.", g={{"o",4084,i=1,txt="Silvery Claws x11",m=1448,x=51.4,y=80.6},{"o",4084,i=2,txt="Irontree Heart",n2="Irontree Stompers",m=1448,x=48.5,y=29.8}}},
  {t="Arei", lv=58, n="Arei waits in Irontree Woods. Escort her out of the woods and keep her alive.\nCareful: Three Toxic Horrors ambush you soon after the escort starts.", g={{"a",4261,m=1448,x=49.6,y=29.6,ml=49},{"c",4261,txt="Help Arei get to Safety"}}},
  {t="Felpaw Village", lv=58, n="Ride north to the Deadwood furbolgs' village by the Timbermaw Hold cave mouth.", g={{"t",5084,m=1448,x=60.2,y=5.8},{"a",5085,n2="Mystery Goo: Donova Snowden in Winterspring, keep it",m=1448,x=60.2,y=5.8,ml=52}}},
  {t="A Final Blow", lv=58, n="Back into Shadow Hold: Moora and Salia guard Shadow Lord Fel'dan in its deepest chamber. The succubus Rakaiah waits on the way, with Trey Lightforge's remains beside her.\nCareful: The three bosses fight as a group. Kill the nearby mobs first so you don't pull extra enemies.", g={{"o",5204,i=1,txt="Kill Rakaiah",n2="Rakaiah, below ground",m=1448,x=38.3,y=50.5},{"t",5204,n2="Remains of Trey Lightforge, below ground",m=1448,x=38.5,y=50.4},{"a",5385,m=1448,x=38.5,y=50.4,ml=49},{"o",5242,i=1,txt="Kill Moora",n2="Moora, below ground",m=1448,x=38.8,y=46.9},{"o",5242,i=2,txt="Kill Salia",n2="Salia, below ground",m=1448,x=38.8,y=46.7},{"o",5242,i=3,txt="Shadow Lord Fel'dan's Head",n2="Shadow Lord Fel'dan; below ground",m=1448,x=38.8,y=46.8}}},
  {t="The Emerald Sanctuary", lv=58, n="Ride back south along the road to the Sanctuary.", g={{"t",4084,n2="Eridan Bluewind, inside",m=1448,x=51.4,y=81.5},{"a",4005,n2="Keep the Book of Aquor, the claws and the heart he hands back",m=1448,x=51.4,y=81.5,ml=47},{"t",5242,m=1448,x=51.2,y=82.1},{"t",5385,m=1448,x=51.4,y=82}}},
