  {t="Aquementas", lv=58, n="Ride east into the hills. Use the Book of Aquor to summon Aquementas, then defeat him for the totem.", g={{"o",4005,i=1,txt="Silver Totem of Aquementas",m=1446,x=70.4,y=49.9}}},
