  {t="The Slithering Scar", lv=58, n="Take the road west down into the crater and ride to the Slithering Scar, the silithid cave in the south. The Gorishi Hive Queen waits in its deepest chamber.", g={{"o",4507,i=1,txt="Use Gorishi Queen Lure",m=1449,x=43.5,y=81},{"o",4507,i=1,txt="Gorishi Queen Brain",m=1449,x=43.9,y=81.4}}},
  {t="Fire Plume Ridge", lv=58, n="Climb Fire Plume Ridge in the middle of the crater and use the Skeleton Key Mold by the lava lake at the top, with two Thorium Bars in your bags. Fill Laris's Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge.", g={{"o",4513,i=1,txt="Filled Pure Sample Jar x10",n2="Use the jars on slain oozes",m=1449,x=37.6,y=81.5},{"o",5801,i=1,txt="Use Skeleton Key Mold",m=1449,x=48.9,y=47},{"o",5801,i=1,txt="Unfinished Skeleton Key",m=1449,x=48.9,y=47}}},
  {t="Marshal's Refuge", lv=58, n="Ride north to Marshal's Refuge. Use Umi's Mechanical Yeti beside Quixxil.", g={{"t",4005,n2="J.D. Collie, below ground",m=1449,x=41.9,y=2.7},{"a",3961,m=1449,x=41.9,y=2.7,ml=47},{"t",3961,n2="Linken, at the back of the refuge",m=1449,x=44.7,y=8.1},{"o",5163,i=3,txt="Scare Quixxil with Umi's Mechanical Yeti",m=1449,x=43.7,y=9.4}}},
