  {t="Hive'Ashi: kill these as you meet them", lv=58, n="The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an Encrypted Twilight Text: keep twenty, ten for Bor Wildmane and ten for Hermit Ortell later.", g={{"o",8318,i=1,txt="Encrypted Twilight Text x10",n2="Twilight's Hammer cultists",m=1451,x=41.8,y=44.1},{"o",8284,i=1,txt="Twilight Tablet Fragment x8",n2="Twilight Tablet Fragments",m=1451,x=28.5,y=27.2},{"h",20404,txt="Get Encrypted Twilight Text x20",n2="Ten more for True Believers",m=1451,x=28.4,y=31,n=20,opt=true}}},
  {t="Hive'Zora", lv=58, n="Marshal Bluewall camps outside Hive'Zora, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp.\nCareful: You lose the Silithyst if you mount, stealth, use Divine Shield, Feign Death or Vanish. Blink and Power Word: Shield do not drop it.", g={{"t",9415,m=1451,x=33.3,y=51.1},{"a",9419,m=1451,x=33.3,y=51.1,ml=1},{"c",9419,txt="Silithus Dust Turnin Quest Doodad"},{"t",9419,m=1451,x=33.3,y=51.1}}},
