  {t="Southwind Village", lv=58, n="Ride east to the ruins of Southwind Village. The Dusty Reliquary lies among the ruined buildings, watched by Tortured Sentinels.", g={{"o",5527,i=1,txt="Reliquary of Purity",n2="Dusty Reliquary; inside",m=1451,x=63.2,y=55.4}}},
