  {t="Bronzebeard's Encampment", lv=58, n="Ride south-west to the dwarves' camp near the southern mountains and question Frankal Stonebridge and Rutgar Glyphshaper. Noggle's satchel lies in the sand just south-east of the camp.", g={{"o",8282,i=1,txt="Noggle's Satchel",m=1451,x=44.6,y=91.4},{"o",8304,i=1,txt="Talk to Frankal Stonebridge",m=1451,x=40.8,y=88.9},{"o",8304,i=2,txt="Talk to Rutgar Glyphshaper",m=1451,x=41.3,y=88.5}}},
