  {t="Ironforge", lv=58, n="Take the Deeprun Tram to Ironforge. Bubulo Acerbus and Mistina Steelshield each take sixty Wool, sixty Silk and sixty Mageweave, then sixty Runecloth: hand in what you carry (or buy at the Auction House), skip the rest.", g={{"t",4513,m=1455,x=75.8,y=23.4},{"h",2592,txt="Get Wool Cloth x60",n2="Wool Cloth, from your bags",m=1455,x=24.2,y=74.7,n=60,opt=true},{"h",4306,txt="Get Silk Cloth x60",n2="Silk Cloth, from your bags",m=1455,x=24.2,y=74.7,n=60,opt=true},{"h",4338,txt="Get Mageweave Cloth x60",n2="Mageweave Cloth, from your bags",m=1455,x=24.2,y=74.7,n=60,opt=true},{"t",7807,m=1455,x=74.1,y=48.2,opt=true},{"t",7808,m=1455,x=74.1,y=48.2,opt=true},{"t",7809,m=1455,x=74.1,y=48.2,opt=true},{"h",14047,txt="Get Runecloth x60",n2="Runecloth, from your bags",m=1455,x=24.2,y=74.7,n=60,opt=true},{"t",7811,m=1455,x=74.1,y=48.2,opt=true},{"h",2592,txt="Get Wool Cloth x60",n2="Wool Cloth, from your bags",m=1455,x=24.2,y=74.7,n=60,opt=true},{"h",4306,txt="Get Silk Cloth x60",n2="Silk Cloth, from your bags",m=1455,x=24.2,y=74.7,n=60,opt=true},{"h",4338,txt="Get Mageweave Cloth x60",n2="Mageweave Cloth, from your bags",m=1455,x=24.2,y=74.7,n=60,opt=true},{"t",7802,m=1455,x=43.2,y=31.6,opt=true},{"t",7803,m=1455,x=43.2,y=31.6,opt=true},{"t",7804,m=1455,x=43.2,y=31.6,opt=true},{"h",14047,txt="Get Runecloth x60",n2="Runecloth, from your bags",m=1455,x=24.2,y=74.7,n=60,opt=true},{"t",7805,m=1455,x=43.2,y=31.6,opt=true},{"tr",0,txt="Visit your class trainer",n2="Stormwind has no shaman trainer",f={c={"SHAMAN"}}}}},
