  {t="Chillwind Camp", lv=58, g={{"t",5801,m=1422,x=42.7,y=83.8},{"a",5803,n2="Araj the Summoner is a level 61 elite",m=1422,x=42.7,y=83.8,opt=true,ml=55},{"t",6184,m=1422,x=43.6,y=84.5},{"a",6185,n2="Flint Shadowmore: the agents' remains lie at the Marris Stead in the Eastern Plaguelands",m=1422,x=43.6,y=84.5,ml=56},{"t",5903,m=1422,x=43.4,y=84.8},{"a",5904,m=1422,x=43.4,y=84.8,ml=48}}},
  {t="Andorhal", lv=58, n="Chromie waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. Araj the Summoner guards his phylactery in the middle of the town.", g={{"o",5803,i=1,txt="Araj's Scarab",n2="Araj is elite: grouping up is advised.",m=1422,x=45.3,y=69.2,opt=true},{"t",5941,n2="Chromie, upstairs",m=1422,x=39.5,y=66.8}}},
  {t="Felstone Field", lv=58, n="Janice's ghost wanders by the farmhouse of Felstone Field, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves.", g={{"t",5050,n2="Upstairs",m=1422,x=38.4,y=54},{"i",0,txt="Kill Jabbering Ghoul",m=1422,x=38.4,y=55.4,opt=true},{"a",5051,m=1422,x=38.4,y=54,ml=50},{"c",5051,txt="Good Luck Charm"},{"t",5051,m=1422,x=38.4,y=54}}},
  {t="Northridge Lumber Camp", lv=58, n="Ride north up the road to the lumber mill and set the termite barrel down in the middle of it.", g={{"t",5904,m=1422,x=48.3,y=32},{"a",6389,m=1422,x=48.3,y=32,ml=48}}},
  {t="Tirion Fordring (optional)", lv=58, n="Tirion lives in a small hut on the border river, north-east of the lumber camp. Hand in Of Forgotten Memories if you finished it.", g={{"t",5781,m=1423,x=5.2,y=35.6,opt=true},{"a",5845,m=1423,x=5.2,y=35.6,ml=52}}},
  {t="Eastern Plaguelands", lv=58, w={{k="onquest",q={5845}}}, g={{"g",0,txt="The lake for Of Lost Honor",m=1423,x=62.5,y=26.8}}},
  {t="Of Lost Honor", lv=58, g={{"o",5845,i=1,txt="Symbol of Lost Honor",n2="Underwater",m=1423,x=62.5,y=26.8}}},
  {t="Tirion Fordring", lv=58, g={{"t",5845,m=1423,x=5.2,y=35.6,opt=true},{"a",5846,m=1423,x=5.2,y=35.6,ml=52}}},
  {t="Egan", lv=58, n="Cross the river east of Tirion's hut into Terrordale: Egan stands by Augustus' ruined hut.", g={{"t",5281,m=1423,x=11.4,y=26.6}}},
  {t="The Marris Stead", lv=58, n="Ride south to the Marris Stead, the farm north-west of Darrowshire. The three agents' remains are bone outlines on the ground: one by the road south of the farm, one on the hill east of the house, one on the mound in front of it. Coming close enough to see the Blightcaller in front of the house completes the scouting.\nCareful: Nathanos Blightcaller (level 62 elite) and his elite hounds stand in front of the house: take the remains on the mound from the side and do not pull him. You don't have to fight him.", g={{"o",6185,i=1,txt="SI:7 Insignia (Rutger)",m=1423,x=24.3,y=68.1},{"o",6185,i=3,txt="SI:7 Insignia (Turyen)",m=1423,x=24.3,y=63.6},{"o",6185,i=2,txt="SI:7 Insignia (Fredo)",m=1423,x=22.8,y=63.7},{"c",6185,txt="SI:7 Insignia (Rutger); SI:7 Insignia (Fredo); SI:7 Insignia (Turyen); The Blightcaller Uncovered"}}},
  {t="Artist Renfray", lv=58, w={{k="onquest",q={5846}}}, g={{"g",0,txt="Artist Renfray",m=1422,x=65.8,y=75.4},{"t",5846,n2="Inside",m=1422,x=65.8,y=75.4}}},
  {t="Scholomance (optional)", lv=58, n="Running Scholomance (Caer Darrow, south-east Western Plaguelands) or Stratholme instead of grinding gets you there faster in a group. Skip this step to grind solo.", g={{"i",0,txt="Scholomance fits levels 58 to 60; The Key to Scholomance is handed in at Chillwind Camp below."}}},
  {t="Level 59.93", lv=59, n="Cross the river east of Tirion into Terrordale. The Terrordale Spirits haunt the woods there. Top up here to level 59.93 before the hand-ins at Chillwind Camp: they take you to level 60. Or, with a group, run the Scholomance dungeon or the Stratholme dungeon instead.", g={{"l",59,txt="Reach level 59 (93% in): grind Terrordale Spirit",n2="grind on Terrordale Spirit at Terrordale, Eastern Plaguelands",m=1423,x=11.6,y=21.4,fr=0.93}}},
  {t="Western Plaguelands", lv=59, g={{"g",0,txt="Chillwind Camp",m=1422,x=43.4,y=84.8}}},
  {t="Chillwind Camp", lv=59, n="Ride back south-west to Chillwind Camp.", g={{"t",6389,m=1422,x=43.4,y=84.8},{"t",6185,m=1422,x=43.6,y=84.5},{"i",0,txt="Flint's next task goes to Stormwind: you are level 60 now, skip it."},{"t",5803,m=1422,x=42.7,y=83.8,opt=true},{"t",5505,m=1422,x=42.7,y=83.8,opt=true}}},
} end)

