  {t="Camping 101: Mining", lv=5, w={{k="skill",n=1,name="Mining",skillLine=186},{k="knows",neg=true,spell=1230161}}, g={{"a",96046,n2="Eric Brighthammer: for Yarr Hammerstone at Steelgrill's Depot",m=1426,x=46.7,y=53.9,ml=4}}},
  {t="Camping 101: Engineering", lv=5, w={{k="skill",n=1,name="Engineering",skillLine=202},{k="knows",neg=true,spell=1230656}}, g={{"a",96058,n2="Eric Brighthammer: for Bronk Guzzlegear at Steelgrill's Depot",m=1426,x=46.7,y=53.9,ml=4}}},
  {t="Tognus Flintfire", lv=5, w={{k="onquest",q={96044}}}, g={{"c",96044,txt="Tognus Flintfire",n2="talk to the trainer",m=1426,x=45.3,y=51.9},{"t",96044,n2="Tognus Flintfire, below ground",m=1426,x=45.3,y=51.9}}},
  {t="Kharanos", lv=5, n="Tharek works the forge west of the distillery.\nThen go in: Tannok, the innkeeper, Maxan and Ragnar. Gremlock's Cooking lesson waits for the return with the ribs, when the copper is there for it.", g={{"a",98321,n2="Tognus Flintfire, below ground",m=1426,x=45.3,y=51.9,ml=4},{"a",400,m=1426,x=46,y=51.7,ml=2},{"a",384,m=1426,x=46.8,y=52.4,ml=5},{"t",2160,n2="Tannok Frosthammer, inside",m=1426,x=47.2,y=52.2},{"a",99158,n2="Maxan Anvol, upstairs",m=1426,x=47.3,y=52.2,ml=5},{"t",5626,n2="Maxan Anvol, upstairs",m=1426,x=47.3,y=52.2,f={c={"PRIEST"}}},{"a",5625,n2="Maxan Anvol: heal Mountaineer Dolf south of Kharanos",m=1426,x=47.3,y=52.2,f={c={"PRIEST"}},ml=5},{"tr",0,txt="Visit your class trainer",n2="Last: some classes' trainers stand outside"}}},
