  {t="Misty Pine Refuge: kill these as you meet them", lv=10, n="The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for Rime's Wrath.\nFinish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short.", g={{"o",99162,i=2,txt="Sunhammer's Rifle",m=1426,x=59.9,y=50.1},{"o",99162,i=3,txt="Coalbeard's Rifle",m=1426,x=52.1,y=44},{"o",99162,i=1,txt="Stoneanvil's Rifle",m=1426,x=53.2,y=58.8},{"o",99160,i=1,txt="Kill Minor Ice Elemental x10",n2="Minor Ice Elemental, around the small lake",m=1426,x=56.4,y=44.7}}},
  {t="Father Gavin", lv=10, lb="q99160", g={{"t",99162,m=1426,x=57.7,y=44.9},{"t",99160,m=1426,x=57.7,y=44.9},{"a",99161,m=1426,x=57.7,y=44.9,ml=5}}},
  {t="Avala's Core", lv=10, n="Avala's Core is by the frozen lake, among the ice elementals.", g={{"o",99161,i=1,txt="Avala's Core",m=1426,x=58.3,y=42.1}}},
  {t="Father Gavin", lv=10, g={{"t",99161,m=1426,x=57.7,y=44.9}}},
  {t="Dun Morogh", lv=10, f={c={"HUNTER"}}, g={{"g",0,txt="Kharanos",m=1426,x=45.8,y=53}}},
  {t="Taming the Beast", lv=10, n="Each of Grif Wildheart's quests hands you a Taming Rod: use it on the beast he names, then bring the rod back to him at the Kharanos smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of Kharanos.", f={c={"HUNTER"}}, g={{"o",6064,i=1,txt="Tame Large Crag Boar",n2="Large Crag Boar: tame it with the Taming Rod",m=1426,x=49.2,y=54.8},{"t",6064,m=1426,x=45.8,y=53},{"a",6084,m=1426,x=45.8,y=53,ml=10},{"o",6084,i=1,txt="Tame Snow Leopard",n2="Snow Leopard: tame it with the Taming Rod",m=1426,x=48.3,y=56.5},{"t",6084,m=1426,x=45.8,y=53},{"a",6085,m=1426,x=45.8,y=53,ml=10},{"o",6085,i=1,txt="Tame Ice Claw Bear",n2="Ice Claw Bear: tame it with the Taming Rod",m=1426,x=50.3,y=53.8},{"t",6085,n2="Tame Beast",m=1426,x=45.8,y=53},{"a",6086,n2="Belia Thundergranite in Ironforge takes it",m=1426,x=45.8,y=53,ml=10}}},
