  {t="Gol'Bolar Quarry", lv=10, n="The quarry lies just east of Farsen's ridge.", g={{"a",433,n2="Senator Mehr Stonehallow, in the quarry",m=1426,x=68.7,y=56,ml=6},{"a",95217,n2="Frast Dokner: blacksmiths only",m=1426,x=69,y=55.9,opt=true,ml=7},{"a",432,m=1426,x=69.1,y=56.3,ml=5}}},
  {t="The quarry troggs", lv=10, n="Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the Empty Powder Keg.", g={{"o",432,i=1,txt="Kill Rockjaw Skullthumper x6",m=1426,x=69.7,y=57.1},{"o",433,i=1,txt="Kill Rockjaw Bonesnapper x10",m=1426,x=70.7,y=56.6},{"h",268548,txt="Get Empty Powder Keg",m=1426,x=70.7,y=56.6,n=1,opt=true},{"a",95213,opt=true,ml=7}}},
