  {t="Braldir Ashmantle", lv=10, n="Go through the tunnel into Loch Modan. Just past it, a path marked by stones climbs the hills on the right of the road north to Braldir's camp.", f={c={"SHAMAN"}}, g={{"t",94465,m=1432,x=32.2,y=66},{"a",94466,m=1432,x=32.2,y=66,ml=10}}},
  {t="Fire Tar and the Reagent Pouch", lv=10, n="Stonesplinter Seers (level 13) stand among the troggs in the south of Stonesplinter Valley, south of Braldir; Tunnel Rat Geomancers (level 12) work the Silver Stream Mine at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time.", f={c={"SHAMAN"}}, g={{"o",94466,i=2,txt="Reagent Pouch",n2="Reagent Pouch: Stonesplinter Seers",m=1432,x=36.8,y=77.8},{"o",94466,i=1,txt="Fire Tar",n2="Fire Tar: Tunnel Rat Geomancers",m=1432,x=35.5,y=27.9}}},
  {t="The Fire Spirit Stone", lv=10, n="Braldir gives you the Fire Sapta. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the Minor Manifestation of Fire, then place its Glowing Ember in the Brazier of the Dormant Flame, atop the Shrine of Eternal Flame.", f={c={"SHAMAN"}}, g={{"t",94466,m=1432,x=32.2,y=66},{"a",94467,m=1432,x=32.2,y=66,ml=10},{"o",94467,i=1,txt="Use Fire Sapta",n2="Fire Sapta, beside the Spirit Stone",m=1432,x=31.9,y=64.5},{"o",94467,i=1,txt="Glowing Ember",n2="Glowing Ember: Minor Manifestation of Fire",m=1432,x=31.9,y=64.5},{"t",94467,m=1432,x=31.9,y=64.5},{"a",94468,m=1432,x=31.9,y=64.5,ml=10}}},
  {t="Back to Bruegs Kindleborn", lv=10, n="Back through the tunnel to Bruegs' cave above the farm.", f={c={"SHAMAN"}}, g={{"t",94468,n2="Bruegs Kindleborn: Searing Totem, your Fire Totem and the Totem of Charged Flames",m=1426,x=87.9,y=44.8}}},
  {t="North Gate Outpost", lv=10, n="Pilot Hammerfoot waits at the North Gate Outpost, north of the South Gate; the dwarven corpse lies up the pass to the west of him.", g={{"a",419,m=1426,x=83.9,y=39.2,ml=8},{"t",419,m=1426,x=79.7,y=36.2},{"a",417,m=1426,x=79.7,y=36.2,ml=8},{"o",417,i=1,txt="Mangy Claw",n2="Mangy Claw: Mangeclaw",m=1426,x=78.3,y=37.8},{"t",417,m=1426,x=83.9,y=39.2}}},
  {t="The tunnel post", lv=10, n="East through the South Gate tunnel into Loch Modan. Mountaineer Cobbleflint and Captain Rugelfuss stand at the dwarven post just past it.", g={{"a",224,m=1432,x=22.1,y=73.1,ml=10},{"a",267,m=1432,x=23.2,y=73.7,ml=10}}},
  {t="Stonesplinter troggs", lv=10, n="North of the post, west of the road: the Stonesplinter troggs and scouts camp in the hills. Both drop the Trogg Stone Teeth.", g={{"o",224,i=1,txt="Kill Stonesplinter Trogg x10",m=1432,x=29.6,y=72.5},{"o",224,i=2,txt="Kill Stonesplinter Scout x10",m=1432,x=29.6,y=72.9},{"o",267,i=1,txt="Trogg Stone Tooth x8",m=1432,x=29.6,y=72.9}}},
  {t="Back to the tunnel post", lv=10, g={{"t",224,m=1432,x=22.1,y=73.1},{"t",267,m=1432,x=23.2,y=73.7}}},
  {t="Thelsamar", lv=10, n="North up the road to Thelsamar. Mountaineer Kadrell walks the road through town, Vidra Hearthstove stands outside the Stoutlager Inn, Brock Stoneseeker on the east side of town; Thorgrum Borrelson keeps the gryphons.", g={{"t",414,m=1432,x=33.8,y=48.3},{"a",416,m=1432,x=33.8,y=48.3,ml=10},{"a",1339,m=1432,x=33.8,y=48.3,ml=9},{"a",418,m=1432,x=34.8,y=49.3,ml=7},{"a",6387,m=1432,x=37,y=47.8,ml=10},{"t",6387,n2="Thorgrum Borrelson, the gryphon master",m=1432,x=33.9,y=51},{"a",6391,n2="Thorgrum: for Golnir Bouldertoe in Ironforge",m=1432,x=33.9,y=51,ml=10},{"fp",8,txt="Get the Thelsamar flight path (Thorgrum Borrelson)",m=1432,x=33.9,y=51}}},
  {t="The west hills and the Algaz Station", lv=10, n="North through the hills west of the road to Mountaineer Stormpike at the Algaz Station. The Tunnel Rat kobolds dig in the hills on the way; Elder Black Bears, Mountain Boars and Forest Lurkers roam the same ground.", g={{"o",416,i=1,txt="Tunnel Rat Ear x12",n2="Tunnel Rat Ear: Tunnel Rat kobolds",m=1432,x=27.4,y=44.6},{"o",418,i=1,txt="Boar Intestines x3",n2="Boar Intestines: Mountain Boars",m=1432,x=29.9,y=46.8},{"o",418,i=2,txt="Bear Meat x3",n2="Bear Meat: Elder Black Bears",m=1432,x=29.4,y=40.3},{"o",418,i=3,txt="Spider Ichor x3",n2="Spider Ichor: Forest Lurkers",m=1432,x=31.1,y=41.6},{"t",1339,m=1432,x=24.8,y=18.4},{"a",307,m=1432,x=24.8,y=18.4,ml=9},{"a",1338,n2="Furen Longbeard in Stormwind takes it",m=1432,x=24.8,y=18.4,ml=9}}},
  {t="Silver Stream Mine", lv=10, n="East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats.", g={{"o",307,i=1,txt="Miners' Gear x4",n2="Miners' Gear, from the crates",m=1432,x=34.9,y=23.4}}},
  {t="Back to the Algaz Station", lv=10, g={{"t",307,m=1432,x=24.8,y=18.4}}},
  {t="Thelsamar", lv=10, n="South down the road to Thelsamar, finishing the ears, meat and ichor on the way. Mountaineer Kadrell walks the road through town.", g={{"t",416,m=1432,x=33.8,y=48.3},{"t",418,m=1432,x=34.8,y=49.3},{"z",0,txt="Fly to Ironforge",at="Ironforge"}}},
  {t="Golnir Bouldertoe", lv=10, n="The gryphons land in the Great Forge: Golnir Bouldertoe works at its north end, and Gryth Thurden keeps the gryphons where you landed.", g={{"t",6391,n2="Golnir Bouldertoe, in the Great Forge",m=1455,x=51.5,y=26.3},{"a",6388,m=1455,x=51.5,y=26.3,ml=10},{"t",6388,n2="Gryth Thurden, the gryphon master where you landed",m=1455,x=55.5,y=47.7},{"fp",6,txt="Get the Ironforge flight path (Gryth Thurden)",m=1455,x=55.5,y=47.7}}},
  {t="Tinker Town", lv=10, n="East from the Great Forge into Tinker Town: the Misplaced Packages lie by its mailbox. From here the guide goes once round the city: north to the Forlorn Cavern, west to the Mystic Ward, south through the Commons to the High Seat, east through the Military Ward and back to Tinker Town for the tram.", g={{"a",97263,n2="Misplaced Packages, by the mailbox in Tinker Town",m=1455,x=72.3,y=48.6,opt=true,ml=1}}},
  {t="The Forlorn Cavern", lv=10, n="North of the Great Forge: Eldrun Stormbreaker, the shaman trainer, stands at the south end of the Forlorn Cavern, the rogue and warlock trainers and Lago Blackwrench just north of him.", g={{"t",97263,m=1455,x=47.1,y=13.8,opt=true},{"a",1715,n2="Lago Blackwrench: Gakin the Darkbinder in Stormwind takes it",m=1455,x=47.6,y=9.3,f={c={"WARLOCK"}},ml=10},{"tr",0,txt="Visit your class trainer",f={c={"ROGUE","SHAMAN","WARLOCK"}}}}},
  {t="The Tome of Divinity", lv=12, n="West from the Forlorn Cavern into the Mystic Ward: Brandur Ironhammer, Tiza Battleforge and Muiredon Battleforge are in the Hall of Mysteries, Tiza and Muiredon on its upper floor: the stairs up start just north-east of Brandur. John Turner, a beggar, wanders the city. He asks for ten Linen Cloth: the troggs and trolls of Dun Morogh drop it, and the Auction House sells it.", f={c={"PALADIN"}}, g={{"l",12,txt="Reach level 12",f={c={"PALADIN"}}},{"a",2999,m=1455,x=23.1,y=6.1,ml=12},{"t",2999,m=1455,x=27.6,y=12.2},{"a",1646,n2="From the Tome of Divinity she gives you",ml=12},{"t",1646,m=1455,x=27.6,y=12.2},{"a",1647,m=1455,x=27.6,y=12.2,ml=12},{"t",1647,m=1455,x=23.3,y=61.9},{"a",1648,m=1455,x=23.3,y=61.9,ml=12},{"o",1648,i=1,txt="Linen Cloth x10",m=1432,x=34.6,y=27.1},{"t",1648,m=1455,x=23.3,y=61.9},{"a",1778,m=1455,x=23.3,y=61.9,ml=12},{"t",1778,m=1455,x=27.6,y=12.2},{"a",1779,m=1455,x=27.6,y=12.2,ml=12},{"t",1779,m=1455,x=23.5,y=8.3},{"a",1783,m=1455,x=23.5,y=8.3,ml=12},{"o",1783,i=1,txt="Use Symbol of Life",n2="Use the Symbol of Life on Narm Faulk",m=1426,x=78.3,y=58.1,f={c={"PALADIN"}}},{"t",1783,m=1426,x=78.3,y=58.1,f={c={"PALADIN"}}}}},
  {t="Narm Faulk", lv=12, n="Head back out of Ironforge and east along the road to Helm's Bed Lake. Narm Faulk lies dead by its shore: use the Symbol of Life on him. The Dark Iron Spies sneaking around the lake carry the script.", f={c={"PALADIN"}}, g={{"l",12,txt="Reach level 12",f={c={"PALADIN"}}},{"a",1784,m=1426,x=78.3,y=58.1,ml=12},{"o",1784,i=1,txt="Dark Iron Script",n2="Dark Iron Script: Dark Iron Spies",m=1426,x=77.4,y=59.3}}},
  {t="Muiredon Battleforge", lv=12, f={c={"PALADIN"}}, g={{"t",1784,m=1455,x=23.5,y=8.3}}},
  {t="Muiredon Battleforge", lv=12, f={c={"PALADIN"}}, g={{"l",12,txt="Reach level 12",f={c={"PALADIN"}}},{"a",1785,m=1455,x=23.5,y=8.3,ml=12},{"t",1785,n2="Tiza Battleforge: Redemption",m=1455,x=27.6,y=12.2}}},
  {t="The Mystic Ward", lv=12, n="The paladin, priest and mage trainers are in the Hall of Mysteries, in the Mystic Ward.", f={c={"PALADIN","PRIEST","MAGE"}}, g={{"t",5637,n2="High Priest Rohan: Desperate Prayer",m=1455,x=24.7,y=8.2,f={c={"PRIEST"},r={"Dwarf"}}},{"tr",0,txt="Visit your class trainer",f={c={"PALADIN","PRIEST","MAGE"}}}}},
  {t="The High Seat", lv=12, n="South through the Commons: Senator Barin Redstone stands in the High Seat with King Magni.", g={{"t",291,n2="Senator Barin Redstone, in the High Seat with King Magni",m=1455,x=39.5,y=57.5}}},
  {t="Buliwyf Stonehand", lv=12, n="While you're here: learn Two-Handed Axes from Buliwyf Stonehand (Military Ward, 10 silver); two-handers level a Paladin fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Axes",skillLine=172}}, f={c={"PALADIN"}}, g={{"tr",0,txt="Train with Buliwyf Stonehand",m=1455,x=61.2,y=89.5}}},
  {t="The Military Ward", lv=12, n="East to the Military Ward: the warrior trainers and Buliwyf Stonehand in the Hall of Arms, the hunter trainers beside it.", f={c={"WARRIOR","HUNTER"}}, g={{"t",6086,n2="Belia Thundergranite: Beast Training",m=1455,x=70.9,y=85.8,f={c={"HUNTER"}}},{"tr",0,txt="Visit your class trainer",f={c={"WARRIOR","HUNTER"}}}}},
  {t="Buliwyf Stonehand", lv=12, n="While you're here: learn Two-Handed Axes from Buliwyf Stonehand (Military Ward, 10 silver); two-handers level a Warrior fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Axes",skillLine=172}}, f={c={"WARRIOR"}}, g={{"tr",0,txt="Train with Buliwyf Stonehand",m=1455,x=61.2,y=89.5}}},
  {t="Buliwyf Stonehand", lv=12, n="While you're here: learn Two-Handed Maces from Buliwyf Stonehand (Military Ward, 10 silver); two-handers level a Warrior fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Maces",skillLine=160}}, f={c={"WARRIOR"}}, g={{"tr",0,txt="Train with Buliwyf Stonehand",m=1455,x=61.2,y=89.5}}},
  {t="Druid trainer", lv=12, f={c={"DRUID"}}, g={{"tr",0,txt="Visit your class trainer",n2="Theridran in Stormwind City; Dun Morogh has no druid trainer",f={c={"DRUID"}}}}},
  {t="The Deeprun Tram", lv=12, n="East back into Tinker Town: the Deeprun Tram leaves from its east end. Ride it to Stormwind.", g={{"g",0,txt="Deeprun Tram",m=1455,x=78,y=51.4}}},
  {t="Tram to Stormwind", lv=12, n="On the Ironforge platform of the Deeprun Tram, Monty asks for help with the rats: use his Rat Catcher's Flute on the Deeprun Rats around the platform, hand them in, then take his letter to his brother Nipsy at the Stormwind end.", g={{"a",6661,n2="Monty, on the Ironforge platform",m=1455,x=78,y=51.4,ml=10},{"o",6661,i=1,txt="Catch Deeprun Rat x5",n2="Deeprun Rat: use the Rat Catcher's Flute",m=1455,x=78,y=51.4},{"t",6661,m=1455,x=78,y=51.4},{"a",6662,m=1455,x=78,y=51.4,ml=10}}},
  {t="Nipsy", lv=12, n="Ride the tram to Stormwind: Nipsy waits on the Stormwind platform. Furen Longbeard stands in the Dwarven District, just outside the tram.", g={{"t",6662,n2="Nipsy, on the Stormwind platform",m=1453,x=69.6,y=30.2},{"t",1338,m=1453,x=64.6,y=37.2}}},
  {t="Baros Alexston", lv=12, n="From the Dwarven District south-west to Cathedral Square: Baros Alexston's compass is in his old house in Westfall, on the way. The flight master and the Trade District are south of the square.", g={{"a",399,m=1453,x=57.7,y=47.9,ml=10}}},
  {t="Stormwind flight master", lv=12, g={{"g",0,txt="Stormwind flight master",m=1453,x=71,y=73},{"fp",2,txt="Get the Stormwind flight path (Dungar Longdrink)",m=1453,x=71.3,y=72.2}}},
  {t="Woo Ping", lv=12, n="While you're here: learn Two-Handed Swords from Woo Ping (Trade District, 10 silver); two-handers level a Paladin fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Swords",skillLine=55}}, f={c={"PALADIN"}}, g={{"tr",0,txt="Train with Woo Ping",m=1453,x=63.9,y=69.1}}},
  {t="Woo Ping", lv=12, n="While you're here: learn Staves from Woo Ping (Trade District, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Staves",skillLine=136}}, f={c={"HUNTER"}}, g={{"tr",0,txt="Train with Woo Ping",m=1453,x=63.9,y=69.1}}},
  {t="Woo Ping", lv=12, n="While you're here: learn Swords from Woo Ping (Trade District, 10 silver); a sword in the main hand levels a Rogue steadily.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Swords",skillLine=43}}, f={c={"ROGUE"}}, g={{"tr",0,txt="Train with Woo Ping",m=1453,x=63.9,y=69.1}}},
  {t="Defensive Stance", lv=12, n="Ilsa Corbin trains warriors in Old Town, near Osric's shop; the tram from Ironforge arrives in the Dwarven District, north of it. Harry Burlguard and Bartleby stand together by the Pig and Whistle Tavern there. Bartleby fights you for his mug. If Ilsa doesn't offer A Warrior's Training, go straight to Harry: he gives Bartleby the Drunk without it.", f={c={"WARRIOR"}}, g={{"a",1638,m=1453,x=80.4,y=59.8,ml=10},{"t",1638,m=1453,x=77.1,y=53.3},{"a",1639,m=1453,x=77.1,y=53.3,ml=10},{"t",1639,m=1453,x=76.8,y=52.5},{"a",1640,m=1453,x=76.8,y=52.5,ml=10},{"o",1640,i=1,txt="Kill Bartleby",n2="Beat Bartleby",m=1453,x=76.8,y=52.5},{"t",1640,m=1453,x=76.8,y=52.5},{"a",1665,m=1453,x=76.8,y=52.5,ml=10},{"t",1665,n2="Harry Burlguard: Defensive Stance",m=1453,x=77.1,y=53.3}}},
  {t="Woo Ping", lv=12, n="While you're here: learn Two-Handed Swords from Woo Ping (Trade District, 10 silver); two-handers level a Warrior fastest.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Two-Handed Swords",skillLine=55}}, f={c={"WARRIOR"}}, g={{"tr",0,txt="Train with Woo Ping",m=1453,x=63.9,y=69.1}}},
  {t="Woo Ping", lv=12, n="While you're here: learn Staves from Woo Ping (Trade District, 10 silver); a staff carries more spell stats than a one-hander while you level.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Staves",skillLine=136}}, f={c={"PRIEST"},r={"Dwarf"}}, g={{"tr",0,txt="Train with Woo Ping",m=1453,x=63.9,y=69.1}}},
  {t="Gakin the Darkbinder", lv=12, n="Gakin the Darkbinder waits in the cellar of the Slaughtered Lamb, in the Mage Quarter.", f={c={"WARLOCK"}}, g={{"t",1715,m=1453,x=39.2,y=85.2},{"a",1688,m=1453,x=39.2,y=85.2,ml=10}}},
  {t="Woo Ping", lv=12, n="While you're here: learn Staves from Woo Ping (Trade District, 10 silver); a staff carries more spell stats than a one-hander while you level.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Staves",skillLine=136}}, f={c={"WARLOCK"}}, g={{"tr",0,txt="Train with Woo Ping",m=1453,x=63.9,y=69.1}}},
  {t="Surena Caledon", lv=12, n="Leave Stormwind by the main gate, go south to Goldshire and east along the road to the Brackwell Pumpkin Patch. Surena Caledon (level 9) stands by its farmhouse.", f={c={"WARLOCK"}}, g={{"o",1688,i=1,txt="Surena's Choker",n2="Surena's Choker: Surena Caledon",m=1429,x=71,y=80.8}}},
  {t="The Binding", lv=12, n="Back to Gakin. Use the Bloodstone Choker at the summoning circle in the Slaughtered Lamb's cellar and defeat the voidwalker it calls. Goldshire and east Elwynn are next, then Westfall.", f={c={"WARLOCK"}}, g={{"t",1688,m=1453,x=39.2,y=85.2},{"a",1689,m=1453,x=39.2,y=85.2,ml=10},{"c",1689,txt="Summoned Voidwalker",n2="Subdue the voidwalker"},{"t",1689,n2="Summon Voidwalker",m=1453,x=39.2,y=85.2}}},
  {t="Goldshire", lv=12, n="Leave Stormwind by the main gate and follow the road south to Goldshire: east Elwynn comes before Westfall.", g={{"g",0,txt="Goldshire",m=1429,x=42.1,y=65.9}}},
} end)

R:Segment({id="alliance/gnome/01-dun-morogh",title="Dun Morogh",faction="Alliance",races={"Gnome"},min=1,max=14,zone=1426,zoneName="Dun Morogh",next="alliance/02-westfall"}, function() return {
  {t="Sten Stoutarm", lv=1, n="You start in front of Anvilmar, the stone hall at the north end of the valley. Sten Stoutarm waits outside the door.", g={{"a",179,m=1426,x=29.9,y=71.2,ml=1}}},
  {t="Young wolves", lv=1, n="Ragged Young Wolves roam the snow just south of Anvilmar.", g={{"o",179,i=1,txt="Tough Wolf Meat x8",m=1426,x=30.8,y=73}}},
  {t="Anvilmar", lv=1, g={{"t",179,m=1426,x=29.9,y=71.2},{"a",233,m=1426,x=29.9,y=71.2,ml=1},{"a",3112,n2="Sten Stoutarm: Simple Memorandum",m=1426,x=29.9,y=71.2,f={c={"WARRIOR"},r={"Gnome"}},ml=1},{"a",3113,n2="Sten Stoutarm: Encrypted Memorandum",m=1426,x=29.9,y=71.2,f={c={"ROGUE"},r={"Gnome"}},ml=1},{"a",98574,n2="Sten Stoutarm: Hallowed Memorandum",m=1426,x=29.9,y=71.2,f={c={"PRIEST"},r={"Gnome"}},ml=1},{"a",3114,n2="Sten Stoutarm: Glyphic Memorandum",m=1426,x=29.9,y=71.2,f={c={"MAGE"}},ml=1},{"a",3115,n2="Sten Stoutarm: Tainted Memorandum",m=1426,x=29.9,y=71.2,f={c={"WARLOCK"}},ml=1},{"a",170,n2="Balir Frosthammer, next to Sten",m=1426,x=29.7,y=71.2,ml=1},{"t",3112,n2="Thran Khorman, the warrior trainer",m=1426,x=28.8,y=67.2,f={c={"WARRIOR"},r={"Gnome"}}},{"t",3113,n2="Solm Hargrin, the rogue trainer",m=1426,x=28.4,y=67.5,f={c={"ROGUE"},r={"Gnome"}}},{"t",98574,n2="Branstock Khalder, the priest trainer",m=1426,x=28.6,y=66.4,f={c={"PRIEST"},r={"Gnome"}}},{"t",3114,n2="Marryk Nurribit, the mage trainer, inside Anvilmar",m=1426,x=28.7,y=66.4,f={c={"MAGE"}}},{"t",3115,n2="Alamar Grimm, inside Anvilmar",m=1426,x=28.6,y=66.1,f={c={"WARLOCK"}}},{"tr",0,txt="Visit your class trainer",n2="Inside Anvilmar"},{"a",1599,n2="Alamar Grimm, inside Anvilmar",m=1426,x=28.6,y=66.1,f={c={"WARLOCK"}},ml=1}}},
  {t="The troggs", lv=1, n="Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of Anvilmar.", g={{"o",170,i=1,txt="Kill Rockjaw Trogg x6",m=1426,x=24.3,y=71},{"o",170,i=2,txt="Kill Burly Rockjaw Trogg x6",m=1426,x=24.8,y=72.4}}},
  {t="Back to Anvilmar", lv=3, g={{"t",170,m=1426,x=29.7,y=71.2},{"a",3361,n2="Felix Whindlebolt, by the door of Anvilmar; inside",m=1426,x=28.6,y=67.6,ml=3}}},
  {t="Talin Keeneye", lv=3, n="Talin's camp is at the west end of the valley. Felix's Box lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass.", g={{"t",233,m=1426,x=22.6,y=71.4},{"a",183,m=1426,x=22.6,y=71.4,ml=1},{"a",234,m=1426,x=22.6,y=71.4,ml=1}}},
  {t="The boars", lv=3, n="Small Crag Boars graze around Talin's camp and along the west side of the valley.", g={{"o",183,i=1,txt="Kill Small Crag Boar x12",m=1426,x=22.7,y=72.4}}},
  {t="Talin Keeneye", lv=3, g={{"t",183,m=1426,x=22.6,y=71.4}}},
  {t="Grelin Whitebeard", lv=3, n="Grelin and Nori Pridedrift camp at the south-west edge of the valley, below the troll cave.", g={{"t",234,m=1426,x=25.1,y=75.7},{"a",182,m=1426,x=25.1,y=75.7,ml=1}}},
  {t="Coldridge Valley: kill these as you meet them", lv=3, n="Frostmane Troll Whelps fill the slopes south and east of Grelin's camp.", g={{"o",182,i=1,txt="Kill Frostmane Troll Whelp x14",m=1426,x=25.9,y=78.3},{"o",3361,i=3,txt="Felix's Bucket of Bolts",m=1426,x=26.3,y=79.3},{"o",3361,i=2,txt="Felix's Chest",m=1426,x=22.8,y=80},{"o",3361,i=1,txt="Felix's Box",m=1426,x=20.9,y=76.1},{"o",1599,i=1,txt="Feather Charm x3",n2="Feather Charms, from the Frostmane Novices",m=1426,x=29.1,y=81.2,f={c={"WARLOCK"}}}}},
  {t="Grelin Whitebeard", lv=4, g={{"t",182,m=1426,x=25.1,y=75.7},{"a",218,m=1426,x=25.1,y=75.7,ml=1},{"a",3364,n2="Nori Pridedrift: timed, five minutes to reach Durnan in Anvilmar",m=1426,x=25,y=76,ml=4}}},
  {t="Anvilmar", lv=4, n="The Scalding Mornbrew lasts five minutes: go straight north to Durnan Furcutter inside Anvilmar.", g={{"t",3364,n2="Durnan Furcutter, inside Anvilmar; below ground",m=1426,x=28.8,y=66.4},{"a",3365,m=1426,x=28.8,y=66.4,ml=4},{"tr",0,txt="Visit your class trainer",n2="Level 4 spells, before Gozwin's camp"},{"t",1599,n2="Alamar Grimm: Summon Imp",m=1426,x=28.6,y=66.1,f={c={"WARLOCK"}}},{"a",94373,n2="Teo Hammerstorm, inside Anvilmar",m=1426,x=28.8,y=66.2,f={c={"SHAMAN"}},ml=4},{"t",3361,n2="Felix Whindlebolt, at the door on the way out; inside",m=1426,x=28.6,y=67.6}}},
  {t="Grund and Gozwin", lv=4, n="Grund Drokda stands by Felix at the door of Anvilmar. Gozwin's camp is in the hills just north-west; the Snow Leopard Prowler prowls around it.", g={{"a",97277,n2="Grund Drokda, inside",m=1426,x=28.6,y=67.6,ml=4},{"o",97277,i=1,txt="Gozwin's Mechanic's Log",n2="Gozwin's Mechanic's Log, in the camp",m=1426,x=27.3,y=62.9},{"o",97277,i=2,txt="Kill Snow Leopard Prowler",m=1426,x=27.4,y=62.9},{"t",97277,m=1426,x=28.6,y=67.4},{"g",0,txt="The troll cave",m=1426,x=26.9,y=80}}},
  {t="Grik'nir the Cold", lv=4, n="Grik'nir the Cold is inside the troll cave east of Grelin's camp, not on the hill above it: go in at the mouth and follow the tunnel to the back.", g={{"o",218,i=1,txt="Grelin Whitebeard's Journal",n2="Grelin Whitebeard's Journal; below ground",m=1426,x=30.5,y=80.2}}},
  {t="Grelin Whitebeard", lv=4, g={{"t",3365,n2="Nori Pridedrift, next to him",m=1426,x=25,y=76},{"o",94373,i=1,txt="Iceclaw Bear Pendant x2",n2="Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp",m=1426,x=25.9,y=78.3,f={c={"SHAMAN"}}},{"t",218,m=1426,x=25.1,y=75.7},{"a",282,m=1426,x=25.1,y=75.7,ml=1}}},
  {t="Branstock Khalder", lv=5, n="Anvilmar is on the way north from Grelin's camp to the tunnel: Branstock Khalder, the priest trainer inside, sends priests of level 5 to Maxan Anvol in Kharanos.", f={c={"PRIEST"}}, g={{"a",5626,n2="Branstock Khalder, inside Anvilmar",m=1426,x=28.6,y=66.4,ml=5}}},
  {t="Call of Earth", lv=5, n="Back to Teo Hammerstorm in Anvilmar. He gives you the Earth Sapta: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the Minor Manifestation of Earth, then bring its Rough Quartz back to Teo.", f={c={"SHAMAN"}}, g={{"t",94373,m=1426,x=28.8,y=66.2},{"a",94374,m=1426,x=28.8,y=66.2,ml=4},{"i",0,txt="Use Earth Sapta",n2="Earth Sapta, beside the Spirit Stone",m=1426,x=25,y=62.4},{"t",94374,m=1426,x=24.8,y=61.8},{"a",94375,m=1426,x=24.8,y=61.8,ml=4},{"t",94375,n2="Teo Hammerstorm: Stoneskin Totem and your Earth Totem",m=1426,x=28.8,y=66.2}}},
  {t="The tunnel", lv=5, n="Mountaineer Thalos guards the tunnel out of the valley, east of Anvilmar; Hands Springsprocket stands beside him at its mouth.", g={{"t",282,m=1426,x=33.5,y=71.8},{"a",420,m=1426,x=33.5,y=71.8,ml=1},{"a",96628,m=1426,x=33.5,y=71.8,ml=4},{"a",2160,m=1426,x=33.9,y=72.2,ml=1}}},
  {t="The Great Outdoors", lv=5, n="Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with Tognus Flintfire and First Aid with Thamner Pol in Kharanos, mining and engineering at Steelgrill's Depot.", g={{"t",96628,n2="Eric Brighthammer: The Adventurer",m=1426,x=46.7,y=53.9},{"a",96608,m=1426,x=46.7,y=53.9,ml=4},{"c",96608,txt="Sit near the campfire (Optional); Gain the Boosted Rest buff"},{"t",96608,m=1426,x=46.7,y=53.9},{"a",96629,m=1426,x=46.7,y=53.9,ml=4}}},
  {t="Camping 101: Blacksmithing", lv=5, w={{k="skill",n=1,name="Blacksmithing",skillLine=164},{k="knows",neg=true,spell=1230171}}, g={{"a",96044,n2="Eric Brighthammer: for Tognus Flintfire, in the cellar west of the distillery",m=1426,x=46.7,y=53.9,ml=4}}},
  {t="Camping 101: First Aid", lv=5, w={{k="skill",n=1,name="First Aid",skillLine=129},{k="knows",neg=true,spell=1230117}}, g={{"a",96047,n2="Eric Brighthammer: for Thamner Pol in the Thunderbrew Distillery",m=1426,x=46.7,y=53.9,ml=4}}},
  {t="Camping 101: Mining", lv=5, w={{k="skill",n=1,name="Mining",skillLine=186},{k="knows",neg=true,spell=1230161}}, g={{"a",96046,n2="Eric Brighthammer: for Yarr Hammerstone at Steelgrill's Depot",m=1426,x=46.7,y=53.9,ml=4}}},
  {t="Camping 101: Engineering", lv=5, w={{k="skill",n=1,name="Engineering",skillLine=202},{k="knows",neg=true,spell=1230656}}, g={{"a",96058,n2="Eric Brighthammer: for Bronk Guzzlegear at Steelgrill's Depot",m=1426,x=46.7,y=53.9,ml=4}}},
  {t="Kharanos", lv=5, n="Follow the road through the tunnel and north-east to Kharanos. Start outside: Senir and Eric's campfire are in front of the Thunderbrew Distillery.\nTharek works the forge west of the distillery.\nThen go in: Tannok, the innkeeper, Maxan and Ragnar. Gremlock's Cooking lesson waits for the return with the ribs, when the copper is there for it.", g={{"t",420,m=1426,x=46.7,y=53.8},{"a",98322,m=1426,x=46.7,y=53.8,ml=4},{"a",98321,n2="Tognus Flintfire, below ground",m=1426,x=45.3,y=51.9,ml=4},{"a",400,m=1426,x=46,y=51.7,ml=2},{"a",384,m=1426,x=46.8,y=52.4,ml=5},{"t",2160,n2="Tannok Frosthammer, inside",m=1426,x=47.2,y=52.2},{"a",99158,n2="Maxan Anvol, upstairs",m=1426,x=47.3,y=52.2,ml=5},{"t",5626,n2="Maxan Anvol, upstairs",m=1426,x=47.3,y=52.2,f={c={"PRIEST"}}},{"a",5625,n2="Maxan Anvol: heal Mountaineer Dolf south of Kharanos",m=1426,x=47.3,y=52.2,f={c={"PRIEST"}},ml=5},{"tr",0,txt="Visit your class trainer",n2="Last: some classes' trainers stand outside"}}},
