  {t="Tognus Flintfire", lv=5, w={{k="onquest",q={96044}}}, g={{"c",96044,txt="Tognus Flintfire",n2="talk to the trainer",m=1426,x=45.3,y=51.9},{"t",96044,n2="Tognus Flintfire, in the cellar west of the distillery",m=1426,x=45.3,y=51.9}}},
  {t="Steelgrill's Depot", lv=5, n="Follow the road north-east from Kharanos to the depot below the Ironforge road.", g={{"a",317,m=1426,x=49.4,y=48.4,ml=2},{"a",313,m=1426,x=49.6,y=48.6,ml=4},{"t",400,m=1426,x=50.4,y=49.1},{"a",5541,n2="Loslor Rudge, beside him",m=1426,x=50.1,y=49.4,ml=5}}},
