  {t="Rumbleshot's Ammo", lv=5, n="The Ammo Crate sits next to Mountaineer Gretchen, south of the Grizzled Den.", g={{"o",5541,i=1,txt="Rumbleshot's Ammo",n2="Rumbleshot's Ammo: the Ammo Crate",m=1426,x=44.1,y=57}}},
  {t="Mountaineer Gretchen", lv=5, n="Gretchen camps just outside the Grizzled Den, the wendigo cave south-west of Kharanos.", g={{"t",98322,m=1426,x=44.1,y=57.1},{"a",98319,m=1426,x=44.1,y=57.1,ml=4},{"g",0,txt="The Grizzled Den",m=1426,x=42.6,y=54.7}}},
  {t="The Grizzled Den", lv=5, n="Flintfire's shipments lie on the cave floor, and Mountaineer Cornelius is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this.", g={{"o",98321,i=1,txt="Flintfire's Shipment x8",m=1426,x=41.8,y=52.8},{"o",313,i=1,txt="Wendigo Mane x8",m=1426,x=41.9,y=52.7},{"g",0,txt="Mountaineer Cornelius",m=1426,x=42.9,y=49.6},{"c",98319,txt="Mountaineer Cornelius found"}}},
  {t="Mountaineer Gretchen", lv=5, g={{"t",98319,m=1426,x=44.1,y=57.1},{"a",98323,m=1426,x=44.1,y=57.1,ml=4}}},
  {t="Rumbleshot's Ammo", lv=5, n="Hegnar Rumbleshot camps south-west of it, by the road to Coldridge.", g={{"t",5541,m=1426,x=40.7,y=65.1}}},
  {t="Dun Morogh: kill these as you meet them", lv=5, n="Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to Kharanos and the depot: kill them on the walk back.", g={{"o",317,i=2,txt="Thick Bear Fur x2",m=1426,x=41.9,y=66.8},{"o",384,i=1,txt="Crag Boar Rib x6",m=1426,x=42.4,y=65.4},{"o",317,i=1,txt="Chunk of Boar Meat x4",m=1426,x=42.4,y=65.4}}},
  {t="Mountaineer Dolf", lv=5, n="Mountaineer Dolf kneels wounded on the ridge between two low walls just south of Kharanos, across the road from the hunter pet trainer, on the walk back from Rumbleshot's camp. Cast Lesser Heal (Rank 2) on him, then Power Word: Fortitude: Rank 1 of Lesser Heal does not count.", f={c={"PRIEST"}}, g={{"o",5625,i=1,txt="Heal and fortify Mountaineer Dolf",m=1426,x=45.8,y=54.6}}},
  {t="Kharanos", lv=7, n="Senir stands by Eric's campfire in front of the Thunderbrew Distillery; Tognus Flintfire is in the cellar west of it.", g={{"t",98323,m=1426,x=46.7,y=53.8},{"a",287,m=1426,x=46.7,y=53.8,ml=7},{"t",98321,n2="Tognus Flintfire, below ground",m=1426,x=45.3,y=51.9}}},
  {t="Thunderbrew Distillery", lv=7, n="Kill the Crag Boars on the way: their ribs drop before you have Ragnar's quest and count toward it. Back in the distillery: Gremlock Pilsnor teaches Cooking, then the ribs go to Ragnar.", g={{"h",2894,txt="Buy Rhapsody Malt (Innkeeper Belm)",n2="Rhapsody Malt, from Innkeeper Belm; upstairs",m=1426,x=47.4,y=52.5,n=1},{"tr",0,txt="Learn Cooking from Gremlock Pilsnor",n2="Gremlock Pilsnor: Camping 101 asks you to learn it; below ground",m=1426,x=47.7,y=52.3},{"c",96629,txt="Gremlock Pilsnor",m=1426,x=47.7,y=52.3},{"t",96629,m=1426,x=47.7,y=52.3},{"t",384,m=1426,x=46.8,y=52.4},{"t",5625,n2="Maxan Anvol, upstairs: Friar's Robes of the Light",m=1426,x=47.3,y=52.2,f={c={"PRIEST"}}},{"b",0,txt="Set your hearthstone at Thunderbrew Distillery",n2="Upstairs",m=1426,x=47.4,y=52.5,at="Thunderbrew Distillery"}}},
  {t="Kharanos and the depot", lv=7, n="The pilots stand at the depot; Razzle Sprysprocket is on the road back west, north of Kharanos.", g={{"t",317,m=1426,x=49.4,y=48.4},{"a",318,m=1426,x=49.4,y=48.4,ml=2},{"t",313,n2="Pilot Stonegear, beside him",m=1426,x=49.6,y=48.6},{"a",412,n2="Razzle Sprysprocket, on the way back; below ground",m=1426,x=45.9,y=49.4,ml=7}}},
  {t="Brewnall Village", lv=7, n="Brewnall Village sits on the lake west of Kharanos. Gretta Ganter's dock is the first stop; Rejold and Marleth Barleybrew are in the village beyond it.", g={{"a",98326,n2="Gretta Ganter, on the dock",m=1426,x=31.5,y=44.6,ml=5},{"a",310,m=1426,x=30.2,y=45.5,ml=2},{"t",318,m=1426,x=30.2,y=45.7},{"a",315,m=1426,x=30.2,y=45.7,ml=5},{"a",319,m=1426,x=30.2,y=45.7,ml=2},{"o",319,i=1,txt="Kill Ice Claw Bear x6",n2="Ice Claw Bear, on the way to the Hold",m=1426,x=30.2,y=42.3,opt=true},{"o",319,i=2,txt="Kill Elder Crag Boar x8",n2="Elder Crag Boar, on the way",m=1426,x=28,y=42.7,opt=true},{"o",319,i=3,txt="Kill Snow Leopard x8",n2="Snow Leopard, on the way",m=1426,x=28.1,y=45,opt=true},{"g",0,txt="Frostmane Hold",m=1426,x=25.1,y=50.9}}},
  {t="Frostmane Hold", lv=7, n="Frostmane Hold is the troll cave in the hills south-west of Brewnall Village. Ice Claw Bears, Elder Crag Boars and Snow Leopards you kill on the way count for Rejold. Kill Headhunters at its mouth and walk through to its far end.", g={{"o",287,i=1,txt="Kill Frostmane Headhunter x5",n2="Frostmane Headhunter, below ground",m=1426,x=25.5,y=50.9},{"g",0,txt="Frostmane Hold",m=1426,x=21.3,y=54.2},{"c",287,txt="Frostmane Headhunter; Fully explore Frostmane Hold"}}},
  {t="Gnomeregan: kill these as you meet them", lv=7, n="Leper Gnomes around Brewnall and the Gnomeregan road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake.", g={{"o",412,i=1,txt="Restabilization Cog x8",n2="Restabilization Cog: Leper Gnomes",m=1426,x=24.7,y=44.6},{"o",412,i=2,txt="Gyromechanic Gear x8",n2="Gyromechanic Gear: Leper Gnomes",m=1426,x=24.7,y=44.6},{"o",319,i=1,txt="Kill Ice Claw Bear x6",m=1426,x=25.5,y=46.4},{"o",319,i=2,txt="Kill Elder Crag Boar x8",m=1426,x=27.7,y=47.4},{"o",319,i=3,txt="Kill Snow Leopard x8",m=1426,x=28.1,y=45}}},
  {t="Rejold Barleybrew", lv=7, g={{"t",319,m=1426,x=30.2,y=45.7},{"a",320,m=1426,x=30.2,y=45.7,ml=2}}},
  {t="Frosthowl", lv=7, g={{"g",0,txt="The Grizzled Den",m=1426,x=42.6,y=54.7},{"o",98326,i=1,txt="Sack of Fish",m=1426,x=39.3,y=48.8}}},
  {t="Kharanos", lv=7, n="Jarven Thunderbrew guards the Thunder Ale barrels in the distillery basement. Buy a Thunder Ale from Innkeeper Belm, click the guarded barrel, then hand the ale to Jarven from his quest window (there is no quest to accept); after that, the unguarded barrel takes the Barleybrew Scalder.", g={{"t",287,m=1426,x=46.7,y=53.8},{"a",291,n2="Senir Whitebeard: Senator Barin Redstone in Ironforge takes it",m=1426,x=46.7,y=53.8,ml=1},{"h",2686,txt="Buy Thunder Ale (Innkeeper Belm)",n2="Thunder Ale, from Innkeeper Belm in the distillery; upstairs",m=1426,x=47.4,y=52.5,n=1},{"t",403,n2="The Guarded Thunder Ale Barrel in the basement",m=1426,x=47.7,y=52.7},{"t",308,n2="Jarven Thunderbrew, beside the barrel; below ground",m=1426,x=47.6,y=52.7},{"t",310,n2="The Unguarded Thunder Ale Barrel in the distillery; below ground",m=1426,x=47.7,y=52.7},{"a",311,m=1426,x=47.7,y=52.7,ml=2},{"tr",0,txt="Visit your class trainer"},{"t",412,n2="Razzle Sprysprocket, below ground",m=1426,x=45.9,y=49.4}}},
  {t="Shimmerweed", lv=7, n="The Shimmerweed grows in baskets up on Shimmer Ridge, the snowy slope north of the road between Kharanos and Brewnall: climb from the road west of Kharanos. The Frostmane Seers camped on the ridge drop it too.", g={{"o",315,i=1,txt="Shimmerweed x6",m=1426,x=42.1,y=45.5}}},
  {t="Brewnall Village", lv=8, g={{"t",315,m=1426,x=30.2,y=45.7},{"a",413,m=1426,x=30.2,y=45.7,ml=8},{"t",311,m=1426,x=30.2,y=45.5},{"t",98326,m=1426,x=31.5,y=44.6}}},
  {t="Tundra MacGrann", lv=8, n="Tundra MacGrann camps in Chill Breeze Valley, south of the road back east from Brewnall to Kharanos. His meats are in the locker in Old Icebeard's cave, east of his camp. Old Icebeard is an elite yeti: wait out of sight until he wanders off on his patrol, then take the meats and leave before he comes back. You don't need to fight him.", g={{"a",312,m=1426,x=34.6,y=51.6,ml=7},{"o",312,i=1,txt="MacGrann's Dried Meats",n2="MacGrann's Dried Meats: the meat locker; below ground",m=1426,x=38.5,y=53.9},{"t",312,m=1426,x=34.6,y=51.6}}},
  {t="Kharanos", lv=10, n="Back east through Kharanos: the class quests here wait for level 10.", g={{"l",10,txt="Reach level 10",f={c={"HUNTER"}}},{"l",10,txt="Reach level 10",f={c={"SHAMAN"}}},{"a",94449,n2="Ingrid Dunwald: Bruegs Kindleborn by the South Gate takes it",m=1426,x=28.8,y=66.2,f={c={"SHAMAN"}},ml=10},{"l",10,txt="Reach level 10",f={c={"PRIEST"}}},{"a",94824,n2="Maxan Anvol: High Priestess Mims in Ironforge takes it",m=1426,x=47.3,y=52.2,f={c={"PRIEST"},r={"Gnome"}},ml=10}}},
  {t="Steelgrill's Depot", lv=10, n="Follow the road north-east from Kharanos to the depot: the whole east of Dun Morogh is one sweep from here.", g={{"t",320,m=1426,x=49.4,y=48.4},{"a",96408,m=1426,x=50.4,y=49.1,ml=9}}},
  {t="Misty Pine Refuge", lv=10, n="Follow the road east past the depot to Misty Pine Refuge.", g={{"t",99158,m=1426,x=57.7,y=44.9},{"a",99159,m=1426,x=57.7,y=44.9,ml=5}}},
  {t="Firewood", lv=10, n="The firewood lies in the snow around the frozen lake by the refuge.", g={{"o",99159,i=1,txt="Mostly Dry Firewood x14",m=1426,x=57.4,y=46.4}}},
  {t="Father Gavin", lv=10, g={{"t",99159,m=1426,x=57.7,y=44.9},{"a",99160,m=1426,x=57.7,y=44.9,ml=5},{"a",99162,m=1426,x=57.7,y=44.9,ml=5}}},
  {t="Minor Ice Elemental on the way", lv=10, al=true, g={{"o",99160,i=1,txt="Kill Minor Ice Elemental x10",n2="Minor Ice Elemental along the way to Father Gavin",m=1426,x=57.6,y=45.1,opt=true}}},
  {t="Misty Pine Refuge: kill these as you meet them", lv=10, n="The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for Rime's Wrath.\nFinish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short.", g={{"o",99162,i=2,txt="Sunhammer's Rifle",m=1426,x=59.9,y=50.1},{"o",99162,i=3,txt="Coalbeard's Rifle",m=1426,x=52.1,y=44},{"o",99162,i=1,txt="Stoneanvil's Rifle",m=1426,x=53.2,y=58.8},{"o",99160,i=1,txt="Kill Minor Ice Elemental x10",n2="Minor Ice Elemental, around the small lake",m=1426,x=56.4,y=44.7}}},
  {t="Father Gavin", lv=10, lb="q99160", g={{"t",99162,m=1426,x=57.7,y=44.9},{"t",99160,m=1426,x=57.7,y=44.9},{"a",99161,m=1426,x=57.7,y=44.9,ml=5}}},
  {t="Avala's Core", lv=10, n="Avala's Core is by the frozen lake, among the ice elementals.", g={{"o",99161,i=1,txt="Avala's Core",m=1426,x=58.3,y=42.1}}},
  {t="Father Gavin", lv=10, g={{"t",99161,m=1426,x=57.7,y=44.9}}},
