  {t="The moonwell", lv=3, n="The moonwell sits north of Aldrassil.", g={{"o",921,i=1,txt="Use Crystal Phial",m=1438,x=60,y=33},{"o",921,i=1,txt="Filled Crystal Phial",n2="Use the Crystal Phial at the moonwell",m=1438,x=60,y=33}}},
  {t="Tenaron Stormgrip", lv=5, n="Back to the top of Aldrassil. The Lost Journal lies beside him.", g={{"t",921,n2="Upstairs",m=1438,x=59.1,y=39.5},{"a",928,m=1438,x=59.1,y=39.5,ml=1},{"a",96630,n2="Lost Journal, upstairs",m=1438,x=59.1,y=39.5,ml=4},{"a",5622,n2="Shanda, the priest trainer, on the second level of Aldrassil on the way down: Laurna Morninglight in Dolanaar takes it",m=1438,x=59.2,y=40.4,f={c={"PRIEST"}},ml=5}}},
  {t="Iverron's Antidote", lv=5, n="Take the antidote from Dirania Silvershine at the foot of Aldrassil only now, on the way down: it lasts five minutes. Iverron waits north-west, by the cave: go straight on to him.", g={{"a",3522,m=1438,x=60.9,y=42,ml=2},{"t",3522,m=1438,x=54.6,y=33}}},
  {t="Porthannius", lv=5, n="Leave Shadowglen by the path south-east of Aldrassil: Porthannius stands beside it, where it goes down towards the road to Dolanaar.", g={{"a",2159,m=1438,x=61.2,y=47.6,ml=1}}},
  {t="Zenn Foulhoof", lv=5, n="Follow the road south-west out of Shadowglen. Zenn sits beside it just east of Dolanaar.", g={{"a",488,m=1438,x=60.4,y=56.2,ml=4}}},
  {t="Dolanaar", lv=5, g={{"t",96630,n2="Lyreena Duskblade, by the campfire",m=1438,x=57.6,y=56.6},{"a",96606,m=1438,x=57.6,y=56.6,ml=4}}},
  {t="The Great Outdoors", lv=5, n="With a profession learned, Lyreena also offers its Camping 101, which its trainer takes: alchemy and herbalism beside Zarrin, First Aid with Byancie in the inn, skinning and leatherworking at the Maneweavers' camp on the road west.", g={{"c",96606,txt="Sit near the campfire (Optional); Gain the Boosted Rest buff",n2="/sit by Lyreena's campfire until you get Boosted Rest",m=1438,x=57.7,y=56.7},{"t",96606,m=1438,x=57.6,y=56.6},{"a",96634,m=1438,x=57.6,y=56.6,ml=4}}},
