  {t="Dolanaar", lv=5, n="Moon Priestess Amara patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her.", g={{"a",487,n2="Moon Priestess Amara, on the road west of the village",m=1438,x=52.9,y=57.2,ml=5}}},
  {t="Teldrassil: kill these as you meet them", lv=5, n="Nightsabers, Strigid Owls and Webwood Lurkers roam all around Dolanaar and along the road east; the lurkers also drop the recipe's spider legs. The moonwell is at the west edge of Starbreeze Village.", g={{"o",488,i=1,txt="Nightsaber Fang x3",m=1438,x=52.9,y=58.5},{"o",87288,i=1,txt="Soft Nightsaber Pelt x6",n2="Nightsabers",m=1438,x=52.9,y=58.5},{"o",488,i=2,txt="Strigid Owl Feather x3",m=1438,x=52.2,y=59.3},{"o",488,i=3,txt="Webwood Spider Silk x3",m=1438,x=51.8,y=58.5},{"o",4161,i=1,txt="Small Spider Leg x7",n2="Webwood Lurkers",m=1438,x=51.8,y=58.5}}},
  {t="Zenn Foulhoof", lv=5, n="Zenn sits by the road just east of Dolanaar, between Dolanaar and Starbreeze Village.", g={{"t",488,m=1438,x=60.4,y=56.2}}},
  {t="Starbreeze Village", lv=5, n="Gaerolas Talvethren stands upstairs in a house in the village, east of the moonwell: go up inside, the arrow cannot tell the floors apart. Tallonkai's Dresser is in the house on the hill at the east end of the village.", g={{"o",929,i=1,txt="Use Jade Phial",m=1438,x=63.4,y=58.1},{"o",929,i=1,txt="Filled Jade Phial",n2="Use the Jade Phial at the moonwell",m=1438,x=63.4,y=58.1},{"t",475,m=1438,x=66.3,y=58.5},{"a",476,m=1438,x=66.3,y=58.5,ml=4},{"o",2438,i=1,txt="Emerald Dreamcatcher",n2="Tallonkai's Dresser; inside",m=1438,x=68,y=59.6}}},
  {t="Lake Al'Ameth", lv=5, n="South-west of Starbreeze, south of Zenn. Denalan tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the Timberling Sprouts grow among them.", g={{"t",997,m=1438,x=60.9,y=68.5},{"a",918,m=1438,x=60.9,y=68.5,ml=4},{"a",919,m=1438,x=60.9,y=68.5,ml=4},{"o",918,i=1,txt="Timberling Seed x8",m=1438,x=61.5,y=69.3},{"o",919,i=1,txt="Timberling Sprout x12",m=1438,x=61.2,y=69.9},{"t",918,m=1438,x=60.9,y=68.5},{"a",922,n2="Denalan: Rellian Greenspyre in Darnassus takes it",m=1438,x=60.9,y=68.5,ml=4},{"t",919,m=1438,x=60.9,y=68.5}}},
  {t="Sentinel Shaya", lv=5, n="Sentinel Shaya kneels wounded on the rocks at the north edge of Lake Al'Ameth, on the walk back to Dolanaar, with no quest mark over her. Cast Lesser Heal (Rank 2) on her, then Power Word: Fortitude: Rank 1 of Lesser Heal does not count. She runs off once both land and is back in about 5 minutes.", f={c={"PRIEST"}}, g={{"o",5621,i=1,txt="Heal and fortify Sentinel Shaya",m=1438,x=57.2,y=63.5}}},
  {t="Dolanaar", lv=5, g={{"t",4161,m=1438,x=57.1,y=61.3},{"t",929,m=1438,x=56.1,y=61.7},{"a",933,m=1438,x=56.1,y=61.7,ml=1},{"a",489,m=1438,x=56,y=59.5,ml=4},{"t",87288,n2="Aldia, upstairs",m=1438,x=55.5,y=57.1},{"t",2438,n2="Tallonkai Swiftroot, upstairs",m=1438,x=55.6,y=57},{"a",2459,m=1438,x=55.6,y=57,ml=1},{"t",476,m=1438,x=56,y=57.3},{"a",483,m=1438,x=56,y=57.3,ml=4},{"tr",0,txt="Visit your class trainer"},{"t",5621,n2="Laurna Morninglight: Moon Robes of Elune",m=1438,x=55.6,y=56.8,f={c={"PRIEST"}}}}},
  {t="Fel Rock's mouth", lv=5, g={{"g",0,txt="Fel Rock",m=1438,x=54.6,y=52.1}}},
  {t="Fel Rock", lv=5, n="Lord Melenas waits inside the cave, at the bottom or up on the ledge; keep to the right.", g={{"o",932,i=1,txt="Melenas' Head",n2="Lord Melenas; below ground",m=1438,x=52.8,y=50.2}}},
  {t="The road to Darnassus", lv=5, n="Gnarlpine Ambushers hide along the road west of Fel Rock.", g={{"o",487,i=1,txt="Kill Gnarlpine Ambusher x6",m=1438,x=48.3,y=53.5}}},
  {t="Radnaal Maneweaver", lv=5, w={{k="onquest",q={97949}}}, g={{"c",97949,txt="Radnaal Maneweaver",n2="talk to the trainer",m=1438,x=42.1,y=50},{"t",97949,n2="Radnaal Maneweaver, camped beside the road before Shayla",m=1438,x=42.1,y=50}}},
  {t="Nadyia Maneweaver", lv=5, w={{k="onquest",q={97946}}}, g={{"c",97946,txt="Nadyia Maneweaver",n2="talk to the trainer",m=1438,x=41.9,y=49.4},{"t",97946,n2="Nadyia Maneweaver, beside Radnaal",m=1438,x=41.9,y=49.4}}},
  {t="Sentinel Shayla Nightbreeze", lv=5, n="West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and Gnarlpine Hold's all count.", g={{"a",490,m=1438,x=42.2,y=51.3,ml=5}}},
  {t="Darnassus", lv=5, n="Into the city through the gate. Rellian Greenspyre is just south of the Cenarion Enclave at the north end, Sister Aquinne in the west, Priestess A'moora and Sentinel Dalia Sunblade in the Temple of the Moon at the south end. On the way back out, use Dalia's Lunar Pendant at the bank and at the city gate; the other two owls wait for your last visit.", g={{"t",922,m=1457,x=38.2,y=21.6},{"a",923,m=1457,x=38.2,y=21.6,ml=4},{"t",98391,m=1457,x=28.9,y=45.8},{"a",2519,m=1457,x=28.9,y=45.8,ml=5},{"t",2519,n2="Priestess A'moora, in the Temple of the Moon",m=1457,x=36.6,y=85.9},{"a",2518,m=1457,x=36.6,y=85.9,ml=5},{"a",98067,n2="Sentinel Dalia Sunblade, beside her",m=1457,x=39.6,y=89.5,ml=1},{"o",98067,i=2,txt="Use Lunar Pendant",n2="Lunar Pendant: the bank, on the way out",m=1457,x=41,y=43.5},{"o",98067,i=4,txt="Use Lunar Pendant",n2="the city gate",m=1457,x=89.1,y=34.8}}},
  {t="Ban'ethil Barrow Den's entrance", lv=5, g={{"g",0,txt="Ban'ethil Barrow Den",m=1438,x=44.3,y=57.9}}},
  {t="Ban'ethil Barrow Den", lv=5, n="The barrow is south of the road. Sentinel Lynessa Duskblossom is held inside, Oben Rageclaw sleeps in its depths, and the four relic chests sit in the lower rooms. Its furbolgs drop Shayla's fangs.", g={{"o",490,i=1,txt="Gnarlpine Fang x15",n2="Gnarlpine Fang: any Gnarlpine furbolg",m=1438,x=44.4,y=58.5},{"o",483,i=1,txt="Raven Claw Talisman",n2="Below ground",m=1438,x=45.6,y=57.4},{"a",2541,n2="Oben Rageclaw, below ground",m=1438,x=44.9,y=61.6,ml=3},{"o",483,i=2,txt="Black Feather Quill",n2="Below ground",m=1438,x=43.7,y=61.2},{"o",483,i=3,txt="Sapphire of Sky",n2="Below ground",m=1438,x=44.7,y=62.4},{"o",483,i=4,txt="Rune of Nesting",n2="Below ground",m=1438,x=44.4,y=60.7},{"o",2541,i=1,txt="Shaman Voodoo Charm",n2="Gnarlpine Shamans",m=1438,x=44.5,y=60.5},{"t",2541,m=1438,x=44.9,y=61.6},{"a",2561,m=1438,x=44.9,y=61.6,ml=3},{"o",2561,i=1,txt="Kill Rageclaw",n2="Rageclaw, in the den; walks around Ban'ethil Hollow: look inside the circle on the map",m=1438,x=45.5,y=58.6},{"o",2561,i=1,txt="Use Voodoo Charm",m=1438,x=45.5,y=58.6},{"t",2561,m=1438,x=44.9,y=61.6}}},
  {t="Escaping Ban'ethil", lv=5, n="Escort Sentinel Lynessa Duskblossom out of the barrow; Sentinel Kyra Starsong in Dolanaar takes the report.", g={{"a",99053,m=1438,x=44.7,y=58.9,ml=4},{"g",0,txt="Ban'ethil Hollow, outside the barrow",n2="Walk Lynessa out and keep her alive",m=1438,x=46.4,y=57.3},{"c",99053,txt="Escort Lynessa Duskblossom out of Ban'ethil"}}},
  {t="The Pools of Arlithrien", lv=5, n="South-west of the barrow. The moonwell sits by the pools.", g={{"o",933,i=1,txt="Use Tourmaline Phial",m=1438,x=42.4,y=67.1},{"o",933,i=1,txt="Filled Tourmaline Phial",n2="Use the Tourmaline Phial at the moonwell",m=1438,x=42.4,y=67.1}}},
  {t="Gnarlpine Hold", lv=5, n="South of the pools. The Strange Fruited Plant grows by the Hold; the furbolgs around it drop the rest of the fangs.", g={{"a",930,m=1438,x=42.6,y=76.2,ml=4},{"o",490,i=1,txt="Gnarlpine Fang x15",n2="Gnarlpine Fang: any Gnarlpine furbolg",m=1438,x=41.3,y=77}}},
  {t="Dolanaar", lv=5, n="Moon Priestess Amara patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her.", g={{"t",487,m=1438,x=52.9,y=57.2},{"t",932,n2="Tallonkai Swiftroot, upstairs",m=1438,x=55.6,y=57},{"t",483,m=1438,x=56,y=57.3},{"a",486,m=1438,x=56,y=57.3,ml=4},{"t",99053,m=1438,x=56,y=59.5},{"t",933,m=1438,x=56.1,y=61.7},{"a",7383,m=1438,x=56.1,y=61.7,ml=1}}},
  {t="Seek Redemption!", lv=5, n="Fel Cones lie under the trees all around Dolanaar and Zenn: pick them up on the road east and hand them to Zenn on the way to Ferocitas.", g={{"o",489,i=1,txt="Fel Cone x3",m=1438,x=61.6,y=53.4},{"t",489,m=1438,x=60.4,y=56.2}}},
  {t="Ferocitas the Dream Eater", lv=5, n="Gnarlpine Mystics and Ferocitas camp north-east of Starbreeze Village. Ferocitas drops the Gnarlpine Necklace: open it for the jewel.\nCareful: Ferocitas waits near the camp fire with mystics around him, so pulling him without adds is hard.", g={{"o",2459,i=1,txt="Kill Gnarlpine Mystic x7",m=1438,x=68.3,y=52.2},{"h",8049,txt="Get Gnarlpine Necklace",n2="Gnarlpine Necklace, from Ferocitas",m=1438,x=69.4,y=53.4,n=1},{"o",2459,i=2,txt="Tallonkai's Jewel",m=1438,x=69.4,y=53.4}}},
  {t="Dolanaar", lv=5, n="The road west to the Oracle Glade runs through Dolanaar: hand Tallonkai the jewel on the way.", g={{"t",2459,n2="Tallonkai Swiftroot, upstairs",m=1438,x=55.6,y=57},{"a",98403,n2="Tallonkai Swiftroot: Twisted Hatred's Befouled Webwoods and the elite Xethorr's moss, on the walk to the Oracle Glade",m=1438,x=55.6,y=57,opt=true,ml=4}}},
  {t="Befouled Webwoods", lv=5, n="North-west of Dolanaar, on the way to the Oracle Glade, Befouled Webwoods creep through the woods; Xethorr the Wicked prowls at their east edge and carries the Mature Fel Moss.\nXethorr the Wicked is elite (level 12): grouping up is advised. Clear the webwoods around him first and pull him on his own.", w={{k="group",q=98403},{k="onquest",q={98403}}}, g={{"o",98403,i=1,txt="Kill Befouled Webwood x8",m=1438,x=49.7,y=53},{"o",98403,i=2,txt="Mature Fel Moss",n2="Mature Fel Moss: Xethorr the Wicked",m=1438,x=51.4,y=45.5,grp=true}}},
  {t="The Wellspring River", lv=5, n="West from the webwoods to the Wellspring River, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors.", g={{"o",923,i=1,txt="Mossy Tumor x5",n2="Mossy Tumor: timberlings",m=1438,x=43.9,y=42.7}}},
  {t="The Oracle Glade", lv=6, n="The moonwell is in the middle of the glade. The Strange Fronded Plant grows at its north end.", g={{"a",937,n2="Sentinel Arynia Cloudsbreak, by the moonwell",m=1438,x=38.3,y=34.4,ml=6},{"o",7383,i=1,txt="Use Amethyst Phial",m=1438,x=38.4,y=34.1},{"o",7383,i=1,txt="Filled Amethyst Phial",n2="Use the Amethyst Phial at the moonwell",m=1438,x=38.4,y=34.1},{"t",99046,m=1438,x=37.5,y=36.8},{"a",99047,m=1438,x=37.5,y=36.8,ml=4}}},
  {t="Bloodfeather harpies", lv=7, n="The Bloodfeather harpies nest on the slopes west and north of the glade. Mist, an injured sabercat, lies by the glade's west wall among them: lead her back to Sentinel Arynia at the moonwell before her time runs out.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them.", g={{"o",937,i=1,txt="Bloodfeather Belt x6",m=1438,x=37.3,y=37.8},{"a",938,n2="Mist, by the west wall",m=1438,x=31.5,y=31.6,ml=7},{"c",938,txt="Lead Mist safely to Sentinel Arynia Cloudsbreak",n2="Lead Mist to the moonwell",m=1438,x=38.3,y=34.4}}},
  {t="Sentinel Arynia Cloudsbreak", lv=7, n="Back to the moonwell.", g={{"t",937,m=1438,x=38.3,y=34.4},{"t",938,m=1438,x=38.3,y=34.4},{"a",98392,m=1438,x=38.3,y=34.4,ml=6}}},
  {t="The named harpies", lv=7, n="Hatescreech and Windmistress Gaedress fly just west of the moonwell, Witchmother Arysa further north.", g={{"o",98392,i=1,txt="Hatescreech's Amulet",m=1438,x=35,y=39.3},{"o",98392,i=2,txt="Windmistress Gaedress' Amulet",m=1438,x=33.2,y=36.1},{"o",98392,i=3,txt="Witchmother Arysa's Amulet",m=1438,x=34.2,y=27.9}}},
  {t="Lady Sathrah", lv=7, n="The Strange Fronded Plant grows at the glade's north end, on the way: then north of Witchmother Arysa, along the island's northern edge by Wellspring Lake, Lady Sathrah, a level 12 spider, lurks.", g={{"a",931,m=1438,x=34.6,y=28.8,ml=4},{"o",2518,i=1,txt="Silvery Spinnerets",n2="Silvery Spinnerets: Lady Sathrah",m=1438,x=39.4,y=25.4}}},
  {t="Sentinel Arynia again", lv=7, g={{"t",98392,m=1438,x=38.3,y=34.4},{"a",98398,m=1438,x=38.3,y=34.4,ml=6},{"t",98398,n2="Oracle Tree Bark, just west of the moonwell",m=1438,x=37,y=34},{"a",940,n2="the same Oracle Tree Bark: Fandral in Darnassus takes it",m=1438,x=37,y=34,ml=6}}},
  {t="Sentinel Shayla Nightbreeze", lv=7, n="South from the glade toward Ursal: Shayla walks the road west of Dolanaar, from where the path down from the glade meets it south-west to the bend at about 38,54 and back.", g={{"t",490,m=1438,x=42.2,y=51.3}}},
  {t="Ursal the Mauler", lv=7, n="Walk south along the west side of the island. Ursal prowls the far south, below the Pools of Arlithrien.\nCareful: Gnarlpine of roughly level 9-12 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal.", g={{"o",486,i=1,txt="Kill Ursal the Mauler",m=1438,x=38.8,y=79.8}}},
  {t="Dolanaar", lv=10, n="North-east from Ursal's den, back to Dolanaar.", g={{"t",99047,n2="Byancie, inside",m=1438,x=55.3,y=56.8},{"a",99050,m=1438,x=55.3,y=56.8,ml=4},{"h",3371,txt="Buy Empty Vial (Narret Shadowgrove)",n2="Empty Vial from Narret Shadowgrove, beside Byancie",m=1438,x=55.3,y=57.1,n=1},{"a",5629,n2="Laurna Morninglight: Priestess Alathea in Darnassus takes it",m=1438,x=55.6,y=56.8,f={c={"PRIEST"}},ml=10},{"t",486,m=1438,x=56,y=57.3},{"tr",0,txt="Visit your class trainer"},{"h",159,txt="Buy Refreshing Spring Water (Innkeeper Keldamyr)",n2="Refreshing Spring Water from Innkeeper Keldamyr, for Byancie",m=1438,x=55.6,y=59.8,n=1},{"a",6063,m=1438,x=56.7,y=59.5,f={c={"HUNTER"}},ml=10},{"t",7383,m=1438,x=56.1,y=61.7},{"a",935,n2="Fandral in Darnassus takes it",m=1438,x=56.1,y=61.7,ml=1},{"a",5925,n2="Kal: Mathrengyl Bearwalker in Darnassus takes it",m=1438,x=56,y=61.6,f={c={"DRUID"}},ml=10},{"a",1684,n2="Kyra Windblade, the warrior trainer: Elanaria in Darnassus takes it",m=1438,x=56.2,y=59.2,f={c={"WARRIOR"}},ml=10}}},
  {t="Tallonkai Swiftroot", lv=10, n="Back upstairs to Tallonkai Swiftroot with the webwoods done and Xethorr's moss.", w={{k="complete",q=98403}}, g={{"t",98403,n2="Tallonkai Swiftroot, upstairs",m=1438,x=55.6,y=57}}},
  {t="Lake Al'Ameth", lv=10, n="South-east of Dolanaar, to Denalan. Lasher Sproutlings wander around him on the shore.", g={{"t",930,m=1438,x=60.9,y=68.5},{"t",931,m=1438,x=60.9,y=68.5},{"t",2399,m=1438,x=60.8,y=68.6},{"o",99050,i=1,txt="Dewy Lasher Frond x6",m=1438,x=62.1,y=68.8}}},
  {t="Dolanaar again", lv=10, n="Byancie takes a Refreshing Spring Water with the fronds and the vial: if you drank yours, buy another from Innkeeper Keldamyr in this inn before you hand in.", g={{"t",99050,n2="Byancie, inside",m=1438,x=55.3,y=56.8},{"a",99073,m=1438,x=55.3,y=56.8,ml=4}}},
  {t="Taming the Beast", lv=10, n="Each of Dazalar's quests hands you a Taming Rod: use it on the beast he names, then bring the rod back to him in Dolanaar. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it.", f={c={"HUNTER"}}, g={{"o",6063,i=1,txt="Tame Webwood Lurker",n2="Webwood Lurker: tame it with the Taming Rod",m=1438,x=58.2,y=55.8},{"t",6063,m=1438,x=56.7,y=59.5},{"a",6101,m=1438,x=56.7,y=59.5,ml=10},{"o",6101,i=1,txt="Tame Nightsaber Stalker",n2="Nightsaber Stalker: tame it with the Taming Rod",m=1438,x=55.8,y=72.3},{"t",6101,m=1438,x=56.7,y=59.5},{"a",6102,m=1438,x=56.7,y=59.5,ml=10},{"o",6102,i=1,txt="Tame Strigid Screecher",n2="Strigid Screecher: tame it with the Taming Rod",m=1438,x=64.2,y=67.2},{"t",6102,n2="Tame Beast",m=1438,x=56.7,y=59.5},{"a",6103,n2="Jocaste in Darnassus takes it",m=1438,x=56.7,y=59.5,ml=10}}},
  {t="Sentinel Eralya Leafshadow", lv=10, n="Take the road north-west from Dolanaar again; she still lies beside it, on the way to Darnassus.", g={{"t",99073,m=1438,x=37.5,y=36.8}}},
  {t="Into Darnassus", lv=10, f={c={"WARRIOR"}}, g={{"a",6344,n2="Mydrannul, on the Craftsmen's Terrace just inside the city",m=1457,x=70.7,y=45.4,ml=10}}},
  {t="Darnassus", lv=10, f={c={"WARRIOR"}}, g={{"g",0,txt="Elanaria",m=1457,x=57.3,y=34.6}}},
  {t="Elanaria", lv=10, n="Elanaria stands on the Warrior's Terrace, just inside the city.", f={c={"WARRIOR"}}, g={{"t",1684,m=1457,x=57.3,y=34.6},{"a",1683,m=1457,x=57.3,y=34.6,ml=10}}},
  {t="Vorlus Vilehoof", lv=10, n="Back out of the city gate and east along the road: Vorlus Vilehoof stands south of it, by Ban'ethil Hollow. Bring his horn back to Elanaria.", f={c={"WARRIOR"}}, g={{"o",1683,i=1,txt="Horn of Vorlus",m=1438,x=47.2,y=63.6}}},
  {t="Back to Darnassus", lv=10, f={c={"WARRIOR"}}, g={{"g",0,txt="Elanaria",m=1457,x=70.7,y=45.4}}},
  {t="Darnassus", lv=10, n="Follow the road west into Darnassus and use the Lunar Pendant at the inn on the Craftsmen's Terrace and at the tunnel mouth below Cenarion Hold for the last two owls. Mydrannul stands on the Craftsmen's Terrace just inside the city. Arch Druid Fandral Staghelm is in the Cenarion Enclave at the north end of the city, Rellian Greenspyre just south of it; Lariia, Tyrande Whisperwind, Priestess A'moora and Sentinel Dalia Sunblade are in the Temple of the Moon at the south end.", g={{"t",1683,n2="Elanaria, on the Warrior's Terrace: Defensive Stance",m=1457,x=57.3,y=34.6,f={c={"WARRIOR"}}},{"a",6344,m=1457,x=70.7,y=45.4,f={c={"PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK","DRUID"}},ml=10},{"o",98067,i=3,txt="Use Lunar Pendant",n2="Lunar Pendant: the inn on the Craftsmen's Terrace",m=1457,x=66.5,y=15.3}}},
  {t="Cenarion Enclave", lv=10, g={{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6}}},
  {t="Darnassus", lv=10, g={{"t",935,n2="Arch Druid Fandral Staghelm, in the Cenarion Enclave",m=1457,x=34.8,y=9.3},{"t",940,m=1457,x=34.8,y=9.3},{"a",952,m=1457,x=34.8,y=9.3,ml=6}}},
  {t="Cenarion Enclave", lv=10, g={{"a",98046,m=1457,x=34.8,y=9.3,ml=1},{"t",6103,n2="Jocaste, in the Cenarion Enclave: Beast Training",m=1457,x=40.4,y=8.6,f={c={"HUNTER"}}}}},
  {t="Cenarion Enclave", lv=10, f={c={"DRUID"}}, g={{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6}}},
  {t="Cenarion Enclave", lv=10, g={{"t",5925,n2="Mathrengyl Bearwalker, in the Cenarion Enclave",m=1457,x=35.4,y=8.4,f={c={"DRUID"}}},{"a",5921,m=1457,x=35.4,y=8.4,f={c={"DRUID"}},ml=10},{"o",98067,i=1,txt="Use Lunar Pendant",n2="the tunnel mouth below Cenarion Hold, on the way south",m=1457,x=33.4,y=16.8},{"t",923,m=1457,x=38.2,y=21.6},{"t",98046,n2="Lariia, in the Temple of the Moon",m=1457,x=40.4,y=88.7},{"a",98065,m=1457,x=40.4,y=88.7,ml=1},{"t",98065,n2="Tyrande Whisperwind, above Lariia",m=1457,x=39.1,y=81.6},{"t",2518,m=1457,x=36.6,y=85.9},{"a",2520,m=1457,x=36.6,y=85.9,ml=5},{"o",2520,i=1,txt="Use Sathrah's Sacrifice",n2="Sathrah's Sacrifice, standing in the temple's central fountain",m=1457,x=39.2,y=85.6},{"t",2520,m=1457,x=36.6,y=85.9},{"t",98067,m=1457,x=39.6,y=89.5},{"t",5629,n2="Priestess Alathea, in the Temple of the Moon: Starshards",m=1457,x=39.5,y=81.2,f={c={"PRIEST"}}}}},
  {t="Ilyenia Moonfire", lv=10, n="While you're here: learn Staves from Ilyenia Moonfire (Warrior's Terrace, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Staves",skillLine=136}}, f={c={"HUNTER"}}, g={{"tr",0,txt="Train with Ilyenia Moonfire",m=1457,x=57.6,y=46.7}}},
  {t="Ilyenia Moonfire", lv=10, n="While you're here: learn Staves from Ilyenia Moonfire (Warrior's Terrace, 10 silver); a staff carries more spell stats than a one-hander while you level.", w={{k="money",op=">=",n=1000},{k="skill",neg=true,n=1,name="Staves",skillLine=136}}, f={c={"PRIEST"}}, g={{"tr",0,txt="Train with Ilyenia Moonfire",m=1457,x=57.6,y=46.7}}},
  {t="Portal to Teldrassil", lv=10, g={{"g",0,txt="Portal to Teldrassil",m=1457,x=29.1,y=41.2}}},
  {t="Rut'theran Village", lv=10, n="Take the portal down to Rut'theran Village. Nessa stands on the dock, Vesprystus by the hippogryphs. Once you have Flight to Auberdine, talk to Vesprystus again and choose the flight to Auberdine: it is free and lands beside Laird. If the flight map opens instead, close it and talk to him again holding Shift.", g={{"t",6344,m=1438,x=56.3,y=92.4},{"a",6341,m=1438,x=56.3,y=92.4,ml=10},{"fp",27,txt="Get the Rut'theran Village flight path (Vesprystus)",m=1438,x=58.4,y=94},{"t",6341,m=1438,x=58.4,y=94},{"a",6342,m=1438,x=58.4,y=94,ml=10},{"z",0,txt="Fly to Auberdine",n2="talk to Vesprystus again: free with Flight to Auberdine",at="Auberdine"}}},
  {t="Auberdine", lv=11, n="Learn the flight path from Caylais Moonfeather where you land. Laird's fish stall is just north of her, by the docks.\nThe boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street.", g={{"t",6342,m=1439,x=36.8,y=44.3},{"a",6343,n2="Return to Nessa",m=1439,x=36.8,y=44.3,ml=10},{"a",3524,m=1439,x=36.6,y=45.6,ml=11},{"a",98025,n2="The WANTED poster outside the inn",m=1439,x=37.2,y=44.2,ml=10},{"a",983,n2="Wizbang Cranktoggle, upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart",m=1439,x=37,y=44.1,ml=7},{"fp",26,txt="Get the Auberdine flight path (Caylais Moonfeather)",m=1439,x=36.3,y=45.6}}},
  {t="Return to Nessa", lv=11, n="Fly back to Rut'theran Village from Caylais Moonfeather, hand Laird's Response to Nessa on the dock, then fly back to Auberdine.", f={c={"WARRIOR","PALADIN","HUNTER","ROGUE","PRIEST","SHAMAN","MAGE","WARLOCK"}}, g={{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village"},{"t",6343,m=1438,x=56.3,y=92.4},{"z",0,txt="Fly to Auberdine",at="Auberdine"}}},
  {t="The Long Wash", lv=11, n="Tide Crawlers scuttle along the shore below the village; Buzzbox 827 stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The Beached Sea Creature lies on the shore just south of the village.", g={{"o",3524,i=1,txt="Sea Creature Bones",m=1439,x=36.4,y=50.9},{"o",983,i=1,txt="Crawler Leg x6",n2="Crawler Legs: the Tide Crawlers",m=1439,x=35.6,y=47.1},{"t",983,m=1439,x=36.6,y=46.3}}},
  {t="Auberdine", lv=11, g={{"t",3524,m=1439,x=36.6,y=45.6},{"a",4681,m=1439,x=36.6,y=45.6,ml=11},{"a",954,n2="Thundris Windweaver, north end of the village",m=1439,x=37.4,y=40.1,ml=7},{"a",958,m=1439,x=37.4,y=40.1,ml=9},{"a",984,m=1439,x=39.4,y=43.5,ml=10},{"a",2118,m=1439,x=38.8,y=43.4,ml=10}}},
  {t="Gubber Blump", lv=11, n="Fishers only: Gubber Blump stands on the pier. His Darkshore Grouper is fished from the pier itself.", w={{k="skill",n=1,name="Fishing",skillLine=356}}, g={{"a",1141,n2="Gubber Blump, on the pier",m=1439,x=36.1,y=44.9,opt=true,ml=10}}},
  {t="Moonglade", lv=11, n="Cast Teleport: Moonglade. Dendrite Starblaze is in Nighthaven; the Great Bear Spirit sits in the woods to the north-west. Then Silva Fil'naveth in Nighthaven flies Druids straight to Rut'theran Village, no flight path needed. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", f={c={"DRUID"}}, g={{"t",5921,m=1450,x=56.2,y=30.6},{"a",5929,m=1450,x=56.2,y=30.6,ml=10},{"c",5929,txt="Seek out the Great Bear Spirit and learn what it has to share with you about the nature of the bear.",n2="Speak with the Great Bear Spirit",m=1450,x=39.1,y=27.5},{"t",5929,m=1450,x=56.2,y=30.6},{"a",5931,m=1450,x=56.2,y=30.6,ml=10},{"fp",49,txt="Get the Moonglade flight path (Sindrayl)",m=1450,x=48.1,y=67.3},{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village"}}},
  {t="Back to Darnassus", lv=11, n="Nessa stands on the Rut'theran dock where you land. Then take the portal up to Mathrengyl in the Cenarion Enclave.", f={c={"DRUID"}}, g={{"t",6343,m=1438,x=56.3,y=92.4}}},
  {t="Cenarion Enclave", lv=11, f={c={"DRUID"}}, g={{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6}}},
  {t="Back to Darnassus", lv=11, f={c={"DRUID"}}, g={{"t",5931,m=1457,x=35.4,y=8.4},{"a",6001,m=1457,x=35.4,y=8.4,ml=10}}},
  {t="The Moonkin Stone", lv=11, n="Go back down to Rut'theran Village and fly to Auberdine. The Moonkin Stone stands in the hills just east of the village: use the Cenarion Moondust there, defeat Lunaclaw and speak to the Lunaclaw Spirit.", f={c={"DRUID"}}, g={{"z",0,txt="Fly to Auberdine",at="Auberdine"},{"i",0,txt="Use Cenarion Moondust",m=1439,x=43.5,y=46},{"c",6001,txt="Lunaclaw Spirit"}}},
  {t="Body and Heart", lv=11, n="Fly to Rut'theran Village once more and take the portal up to Mathrengyl, then fly back to Auberdine.", f={c={"DRUID"}}, g={{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village"},{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6},{"t",6001,n2="Mathrengyl Bearwalker: Bear Form",m=1457,x=35.4,y=8.4},{"z",0,txt="Fly to Auberdine",at="Auberdine"}}},
} end)

R:Segment({id="alliance/nightelf/02-darkshore",title="Darkshore",faction="Alliance",races={"NightElf"},min=12,max=14,zone=1439,zoneName="Darkshore",next="alliance/02-westfall"}, function() return {
  {t="Auberdine", lv=12, n="The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street.", f={r={"Human","Dwarf","Gnome","Skyborne"}}, g={{"a",3524,m=1439,x=36.6,y=45.6,ml=11},{"a",98025,n2="The WANTED poster outside the inn",m=1439,x=37.2,y=44.2,ml=10}}},
  {t="The beach", lv=12, n="Tide Crawlers scuttle along the shore below the village; Buzzbox 827 stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The Beached Sea Creature lies on the shore just south of the village.", f={r={"Human","Dwarf","Gnome","Skyborne"}}, g={{"o",3524,i=1,txt="Sea Creature Bones",m=1439,x=36.4,y=50.9}}},
  {t="Auberdine", lv=12, f={r={"Human","Dwarf","Gnome","Skyborne"}}, g={{"a",954,n2="Thundris Windweaver, north end of the village",m=1439,x=37.4,y=40.1,ml=7},{"a",958,m=1439,x=37.4,y=40.1,ml=9},{"a",984,m=1439,x=39.4,y=43.5,ml=10},{"a",2118,m=1439,x=38.8,y=43.4,ml=10},{"a",4811,m=1439,x=37.7,y=43.4,ml=12}}},
  {t="Auberdine", lv=12, n="The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street. Wizbang Cranktoggle stands upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart.", g={{"b",0,txt="Set your hearthstone at Auberdine",m=1439,x=37,y=44.1,at="Auberdine"},{"a",983,n2="Wizbang Cranktoggle, upstairs in the inn",m=1439,x=37,y=44.1,ml=7},{"a",4811,m=1439,x=37.7,y=43.4,f={r={"NightElf"}},ml=12},{"t",1141,m=1439,x=36.1,y=44.9,opt=true}}},
  {t="The skeletal turtle", lv=12, g={{"o",4681,i=1,txt="Sea Turtle Remains",n2="Sea Turtle Remains, on the beach west of the docks; underwater",m=1439,x=31.8,y=46.3},{"t",4681,m=1439,x=36.6,y=45.6}}},
  {t="Bears and the Blackwood camp", lv=12, n="Rabid Thistle Bears roam the hills south of Auberdine: use Tharnariun's Hope on one to capture it. Then walk up to the furbolg camp just east of them: nothing to kill yet.", g={{"c",2118,txt="Rabid Thistle Bear",n2="the Rabid Thistle Bears nearest Tharnariun",m=1439,x=38.2,y=52.6},{"c",984,txt="Find a corrupt furbolg camp",m=1439,x=39.9,y=53.9}}},
  {t="Ameth'Aran", lv=12, n="Sentinel Tysha Moonblade stands at the north edge of the ruins. Cursed, Writhing and Wailing Highborne haunt them; Anaya Dawnrunner's ghost walks among them, Jai'vhanel the owl circles east of them. The two tablets lie in the ruins; a Beached Sea Turtle lies on the shore west of them.", g={{"a",4722,m=1439,x=37.1,y=62.2,ml=11},{"a",953,m=1439,x=40.3,y=59.7,ml=9},{"o",958,i=1,txt="Highborne Relic x7",n2="Highborne Relics",m=1439,x=41.6,y=59.6},{"o",98025,i=1,txt="Feather of Jai'vhanel",m=1439,x=43.4,y=58.7},{"o",953,i=1,txt="The Lay of Ameth'Aran",n2="Read the Lay of Ameth'Aran",m=1439,x=43.3,y=58.7},{"o",953,i=2,txt="The Fall of Ameth'Aran",n2="Read the Fall of Ameth'Aran",m=1439,x=42.6,y=63.1},{"t",953,m=1439,x=40.3,y=59.7}}},
  {t="The red crystal", lv=12, n="Climb the eastern mountains east of Ameth'Aran; the Mysterious Red Crystal sits on a ledge.", g={{"o",4811,i=1,txt="Mysterious Red Crystal",m=1439,x=47.3,y=48.7},{"c",4811,txt="Mysterious Red Crystal; Locate the large, red crystal on Darkshore's eastern mountain range"}}},
  {t="Bashal'Aran", lv=12, n="North along the hills. Asterion waits in the ruins of Bashal'Aran; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. Buzzbox 411 stands by the road west of the ruins; a Beached Sea Creature lies on the shore on the way to him.", g={{"t",954,m=1439,x=44.2,y=36.3},{"a",955,m=1439,x=44.2,y=36.3,ml=7},{"o",955,i=1,txt="Grell Earring x8",n2="Grell Earrings",m=1439,x=44.6,y=36.6},{"t",955,m=1439,x=44.2,y=36.3},{"a",956,m=1439,x=44.2,y=36.3,ml=7},{"o",956,i=1,txt="Ancient Moonstone Seal",n2="Ancient Moonstone Seal: Deth'ryll Satyrs",m=1439,x=45.5,y=36.5},{"t",956,m=1439,x=44.2,y=36.3},{"a",957,m=1439,x=44.2,y=36.3,ml=7},{"a",4723,m=1439,x=41.9,y=31.5,ml=11}}},
  {t="Auberdine", lv=12, g={{"t",958,m=1439,x=37.4,y=40.1},{"t",984,m=1439,x=39.4,y=43.5},{"a",985,m=1439,x=39.4,y=43.5,ml=10}}},
  {t="Auberdine", lv=12, g={{"t",2118,m=1439,x=38.8,y=43.4},{"t",4811,m=1439,x=37.7,y=43.4},{"a",4812,m=1439,x=37.7,y=43.4,ml=12},{"t",98025,m=1439,x=37.7,y=43.4},{"t",4722,m=1439,x=36.6,y=45.6},{"t",4723,m=1439,x=36.6,y=45.6},{"o",4812,i=1,txt="Use Empty Water Tube",m=1439,x=37.8,y=44},{"o",4812,i=1,txt="Moonwell Water Tube",n2="Fill the tube at the moonwell in the village",m=1439,x=37.8,y=44},{"i",0,txt="Sell and repair",opt=true}}},
  {t="Blackwood furbolgs", lv=12, n="Blackwood Pathfinders and Windtalkers hold the camp south-east of Auberdine.", g={{"o",985,i=1,txt="Kill Blackwood Pathfinder x8",m=1439,x=39.3,y=52.2},{"o",985,i=2,txt="Kill Blackwood Windtalker x5",m=1439,x=39.1,y=52.6}}},
  {t="The southern beaches", lv=12, n="Follow the coast south past Ameth'Aran: one Beached Sea Creature lies on the shore west of the Grove, another further south near Remtravel's Excavation. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level.", g={{"a",4728,m=1439,x=36,y=70.9,ml=12}}},
  {t="Ameth'Aran", lv=12, n="Back north to Ameth'Aran: the flame burns in the south of the ruins.", g={{"o",957,i=1,txt="Ancient Flame",m=1439,x=42.4,y=61.8}}},
  {t="The red crystal", lv=12, n="Back north-east into the mountains to the crystal.", g={{"t",4812,m=1439,x=47.3,y=48.7},{"a",4813,m=1439,x=47.3,y=48.7,ml=12}}},
  {t="Bashal'Aran", lv=12, n="North along the hills to Asterion, then west down to Auberdine.", g={{"t",957,m=1439,x=44.2,y=36.3}}},
