  {t="Boat to Stormwind Harbor", lv=12, f={r={"NightElf"}}, g={{"g",0,txt="Boat to Stormwind Harbor",m=1439,x=30.8,y=40.9}}},
  {t="Manifest Clerk Philmor", lv=12, n="Off the boat, Manifest Clerk Philmor stands on the harbor: his shipment goes to Elaine Trias' cheese shop in the Trade District, beside the flight master.", f={r={"NightElf"}}, g={{"a",97220,m=1453,x=30.5,y=28.8,ml=9}}},
  {t="Stormwind flight master", lv=12, f={r={"NightElf"}}, g={{"g",0,txt="Stormwind flight master",m=1453,x=71,y=73},{"fp",2,txt="Get the Stormwind flight path (Dungar Longdrink)",m=1453,x=71.3,y=72.2,f={r={"NightElf"}}},{"t",97220,n2="Elaine Trias, in her cheese shop",m=1453,x=66.6,y=73.4},{"a",97222,m=1453,x=66.6,y=73.4,ml=9},{"o",97222,i=1,txt="Gatehouse Door",n2="Up the stairs in her shop: leave the shipment at the Gatehouse Door",m=1453,x=66.5,y=74.8},{"t",97222,m=1453,x=66.6,y=73.4}}},
