R:Segment({id="alliance/skyborne/01-zephras-isle",title="Zephras Isle",faction="Alliance",races={"Skyborne"},min=1,max=14,zone=2521,zoneName="Zephras Isle",next="alliance/02-westfall"}, function() return {
  {t="Thendal Grove", lv=1, n="You wake in Thendal Grove. Ailee Farheart stands beside you; Rorian the Dayseeker is a few steps west, Elatrell Featherlight by the south edge of the grove.", g={{"a",92460,m=2521,x=42.8,y=23.4,ml=1},{"t",92460,m=2521,x=42,y=23.5},{"a",92461,m=2521,x=42,y=23.5,ml=1},{"a",92462,m=2521,x=43.4,y=24.8,ml=1}}},
  {t="Thendal Grove: kill these as you meet them", lv=1, n="Juvenile Vuldren and Pesky Cirrusflies roam the meadow just south-east of the grove.", g={{"o",92461,i=1,txt="Kill Juvenile Vuldren x8",m=2521,x=43.5,y=25.4},{"o",92462,i=1,txt="Kill Pesky Cirrusfly x8",m=2521,x=43.6,y=26.9}}},
  {t="Back to Thendal Grove", lv=2, n="Halaan Hawk-Eye and Myriaal Mistwake stand at the top of the watchtower, a few steps north-east of Elatrell.", g={{"a",94414,m=2521,x=43.8,y=24.1,ml=2},{"c",94414,txt="Halaan Hawk-Eye",n2="Listen to Halaan",m=2521,x=43.8,y=24.1},{"t",94414,m=2521,x=43.8,y=24.1},{"a",92474,m=2521,x=43.7,y=24.1,ml=2}}},
  {t="Rorian the Dayseeker", lv=2, n="Jump off the top of the watchtower and use Walk on Air to float down to Rorian, west of the tower.", g={{"t",92461,m=2521,x=42,y=23.5},{"t",92474,m=2521,x=42,y=23.5},{"a",92532,n2="Rorian the Dayseeker: the Crumpled Note",m=2521,x=42,y=23.5,f={c={"WARRIOR"}},ml=2},{"a",92482,n2="Rorian the Dayseeker: a note from your trainer",m=2521,x=42,y=23.5,f={c={"HUNTER"}},ml=2},{"a",92483,n2="Rorian the Dayseeker: read the Simple Note",m=2521,x=42,y=23.5,f={c={"ROGUE"}},ml=2},{"a",92481,n2="Rorian the Dayseeker: A Student of the Arcane",m=2521,x=42,y=23.5,f={c={"MAGE"}},ml=2},{"a",92485,n2="Rorian: A Student of Nature",m=2521,x=42,y=23.5,f={c={"DRUID"}},ml=2},{"a",92464,m=2521,x=42,y=23.5,ml=2},{"a",92597,m=2521,x=43.3,y=24.9,ml=2},{"t",92462,m=2521,x=43.4,y=24.8},{"a",92463,m=2521,x=43.4,y=24.8,ml=2},{"t",92532,n2="Blademaster Ren, in the watchtower",m=2521,x=43.6,y=24.1,f={c={"WARRIOR"}}},{"t",92482,m=2521,x=42.5,y=23.8,f={c={"HUNTER"}}},{"t",92483,n2="Akeri Duskblade, in the watchtower",m=2521,x=43.7,y=24.4,f={c={"ROGUE"}}},{"t",92481,n2="Dorii Brightwhisper, the mage trainer: read the Glowing Recall Crystal first",m=2521,x=41.5,y=23.7,f={c={"MAGE"}}},{"t",92485,n2="Xyton Silverwind, the druid trainer, on the ground floor of the tree behind Rorian",m=2521,x=41.7,y=23.3,f={c={"DRUID"}}},{"tr",0,txt="Visit your class trainer",n2="The class trainers stand together in the grove"},{"a",93552,m=2521,x=43.4,y=24,ml=2}}},
  {t="Raw Windstones and the Cirrusfly Queen", lv=2, n="The Raw Windstones glitter on the ground just south of the grove. The Cirrusfly Queen hovers over the meadow further east, on the way to Yala.", g={{"o",93552,i=1,txt="Windstone Cluster x15",m=2521,x=43.5,y=23.9}}},
  {t="Thendal Grove turn-ins", lv=2, g={{"t",93552,m=2521,x=43.4,y=24}}},
  {t="Yala Windwatcher", lv=3, n="Yala Windwatcher keeps watch east of the grove. The Roiling Winds and Al'Aketh Converts gather just north of her; the Ley Line rises further north: cast your Read Leyline racial ability at it.", g={{"o",92597,i=1,txt="Cast Read Leyline at the Ley Line",m=2521,x=46.3,y=17.9},{"t",92464,m=2521,x=47.2,y=22},{"a",92465,m=2521,x=47.2,y=22,ml=2},{"o",92465,i=1,txt="Kill Al'Aketh Convert x7",m=2521,x=47.1,y=21.8},{"o",92465,i=2,txt="Kill Roiling Winds x6",m=2521,x=47.7,y=21.6},{"t",92465,m=2521,x=47.2,y=22},{"a",92469,m=2521,x=47.2,y=22,ml=3}}},
