  {t="Thendal Grove: kill these as you meet them", lv=4, n="The Ursera Scavengers den west of the grove, with Urs'anah, the matriarch, at the back of the den; Scrawny Ursera prowl the woods between the den and the grove.", g={{"o",92470,i=1,txt="Kill Ursera Scavenger x8",n2="Below ground",m=2521,x=39.5,y=26.9},{"o",92470,i=2,txt="Head of Urs'anah",n2="Head of Urs'anah; below ground",m=2521,x=35.6,y=26.1},{"o",92473,i=1,txt="Scrawny Ursera Claw x6",m=2521,x=41.4,y=26.4}}},
