  {t="Shen'dar Village", lv=4, n="Follow the road south to Shen'dar Village. Raan Wildwind camps by the fire west of the village; Constable Aonda and Rathiril Sunlance stand in its middle.", g={{"t",92472,m=2521,x=45.7,y=45.5},{"a",93461,m=2521,x=45.7,y=45.5,ml=4},{"a",92596,m=2521,x=45,y=46.4,ml=4},{"o",92596,i=1,txt="Talk to Rathiril Sunlance",m=2521,x=45,y=46.3},{"t",92596,m=2521,x=45,y=46.4},{"a",94413,m=2521,x=45,y=46.4,ml=4},{"o",93461,i=1,txt="Talk to Rathiril Sunlance",m=2521,x=45,y=46.4},{"o",93461,i=2,txt="Talk to Coriella Calmbreeze",m=2521,x=43,y=43.3},{"t",96638,m=2521,x=41.7,y=44.8}}},
